window.__D("text/zohar-chadash/c006",{"p":[[9514013962,"<p>וְאִי תֵימָא, הָא כַּד סָלְקָא לְאִתְחַבְּרָא, כְּדֵין הִיא שְׁמָא שְׁלִים ידו\"ד, וְלָא יַתִּיר, אָן הוּא רָזָא דֵּאלֹהִים. אֶלָּא כַּד הֲוֵי שְׁמָא בִּשְׁלִימוּ, כְּדֵין אִתְכְּלִילַת עֵילָא וְתַתָּא, עֵילָא בִּשְׁמָא דַיהו\"ה. לְתַתָּא בִּשְׁמָא דֵּאלֹהִים. וּכְדֵין אִשְׁתְּלֵימַת בְּכוֹלָּא.</p>"],[9514013963,"<p>כְתִיב, (מלכים א ב) וְהַמֶּלֶךְ שְׁלֹמֹה בָּרוּךְ. אַמַּאי אִיקְּרֵי הָכֵי. אֶלָּא וְהַמֶּלֶךְ שְׁלמֹה, מַלְכָּא דִּשְׁלָמָה דִּילֵיהּ. דְּהָא בְּכַמָּה אַתְרֵי כְּתִיב הַמֶּלֶךְ סְתָם, וְלָא כְּתִיב הַמֶּלֶךְ שְׁלֹמֹה. אֶלָּא הַמֶּלֶךְ סְתָם, עַל בֵּית דָּוִד קָאָמַר. הַמֶּלֶךְ שְׁלֹמֹה, עַל מַלְכָּא דִּשְׁלָמָא דִילֵיהּ קָאֲמַר.</p>"],[9514013964,"<p>בָּרוּךָ, דְּהָא כְּדֵין נְבִיעוּ דְּבִרְכָאן לָא הֲווֹ פָּסְקִין עֵילָּא וְתַתָּא. בָּרוּךְ, דְּכָל בִּרְכָאן נָבְעִין מִתַּמָּן, לְאִתְבָּרְכָא כָּל עָלְמִין, וְכָל אַתְוָון אִתְנַהֲרִין, כָּלְהוֹ בְּחִבּוּרָא חָדָא, בִּשְׁלִימוּ חַד.</p>"],[9514013965,"<p>וּכְדֵין, יָרְתָא שְׁמָא דָא, אָת בַּתְרָאָה דְּבִשְׁמָא קַדִּישָׁא, לְאִתְקְרֵי אוּף הָכֵי בָּרוּךְ. דִּכְתִיב, (מלכים א ה) בָּרוּךְ ה' אֱלֹהֵי כו' דָּוִד אָבִי.</p>"],[9514013966,"<p>דְּכַד אִתְקְרֵי בָּרוּךְ, כְּדֵין כּוֹלָּא אִיהוּ שְׁמָא שְׁלִים כִּדְקָא יָאוֹת, וְכָל עָלְמִין אִתְבָּרְכָאן מִגּוֹ מְקוֹרָא דְחַיֵּי. וּשְׁמָא דָא, אִיהִי עֵילָא וְתַתָּא. לְזִמְנִין לְעֵילָא, לְזִמְנִין לְתַתָּא. זַכָּאִין אַתּוּן עַמָּא קַדִּישָׁא, דְּרָזִין קַדִּישִׁין עִילָּאִין אִתְגַּלְּיָין לְכוֹ.</p>"],[9514013967,"<p>כַד מִתְחַבְּרָן אַתְוָון דִּשְׁמָא קַדִּישָׁא, כְּדֵין ו' נָחֵית לְאַמְשָׁכָא ה', מִתַּתָּא לְעֵילָא, לְמֶהֱוֵי חִיבּוּרָא חָדָא, וּכְדֵין אַתְוָון דְּאַלְפָא בֵיתָא נָחֲתִין וְסָלְקִין. א' נָחֲתָא לְגַבֵּי ת', לְאַמְשָׁכָא לָהּ לְגַבֵּיהּ, לְאִתְחַבְּרָא אִלֵּין גּוֹ אִלֵּין. ב' סָלְקָא לְגַבֵּי ש', מִתַּתָּא לְעֵילָא, דְּהָא אִתְמַשְּׁכַת מִתַּתָּא, וּבַעְיָא לְאִתְעַטְרָא בְּבַעֲלָהּ.</p>"],[9514013968,"<p>רָזָא דְּאָת ו, דְּבָעֵי לְאֹקְמָא לְכַלָּה, בְּאִלֵּין שִׁירִין דְּאִיהִי אִתְעָרַת מִתַּתָּא, כַּד אִיהִי מִתְקַשֶּׁטֶת. וְיָהֵיב לָהּ יָדָא לְאַמְשָׁכָא לָהּ לְגַבֵּיהּ, וְאַתְוָון חָדָאן דָּא לְגַבֵּי דָא. בְּשַׁעֲתָא דְאִיהִי אֲמָרַת לְגַבֵּיהּ מָשְׁכֵנִי, כְּדֵין א' דְּאִיהוּ ו', נָחֵית לְגַבֵּי ת', לְאַמְשָׁכָא לָהּ לְגַבֵּיהּ.</p>"],[9514013969,"<p>וּבְשַׁעֲתָא דְּאִיהִי אֲמָרַת אַחֲרֶיךָ נָרוּצָה, סָלְקָא ב', וּמְרַהֲטָא בָּתַר ש', דְּאִיהוּ ו'. וּכְדֵין עַיְילָא אִיהִי גוֹ חַדְרֵי מַלְכָּא, דְּאִינוּן תְּלַת נְקוּדִין, וַחֲדָרִין, וְאַכְּסַדְּרִין לְגוֹ חֲדָרִין, דָּא אִיהוּ אוֹת ש', תְּלַת נְקוּדִין, וְאַכְּסַדְרִין לְגוֹ.</p>"],[9514013970,"<p>וּבְשַׁעֲתָא דַּאֲמַרְתְּ נָגִילָה וְנִשְׂמְחָה בָךְ, אַתְיָא ג' לְאִתְדַּבָּקָא בְּאָת ר', דְּהָא כְּדֵין חֶדְוָוא וְרַעֲוָא בְּעֶשְׂרִין וּתְרֵין אַתְוָון, דְּאִשְׁתַּלִּימוּ בְּאָת ג'. וְאָת ר אִתְפָּרְעָא לְגַבֵּיהּ, לְנַטְלָא מִנֵּיהּ בְּלָא כִיסּוּפָא כְּלַל. וְאִיהוּ לְאִתְדַּבָּקָא בָּהּ, וְלַאֲרָקָא בָּהּ בְּרַעֲוָא.</p>"],[9514013971,"<p>בְּשַׁעֲתָא דְּאִיהִי אֲמָרַת נַזְכִּירָה דּוֹדֶיךָ מִיָּיִן, אִידַכָּרַת דְּהָא עָרְלָה אַתְיָיא גּוֹ אִינוּן אוּכְלוּסִין, לְעַרְבָּבָא חֶדְוָהָא, בְּגִין לְמֵיטַל חוּלָקָא בְּחֶדְוָוא דְּקוּדְשָׁא. וְכַד אִיהִי חָמַת לֵיהּ, דְּאָחִיד מְסָאֲבָא בְּשִׁיפּוּלֵי מַקְדְּשָׁא, כְּדֵין אִיהִי אַזְעֵירַת גַּרְמָהּ, בְּגִין לְמֵיהַב לֵיהּ תַּמְצִית דָּחִיק וְסָתִים, כְּמָה דִּנְבִיעַ מִגּוֹ אַבְנָא. וּכְדֵין ד' יָהֵיב לְאָת ק', וְאָת ק' אִתְפַּשַּׁט בְּחֶדְוָוא, לְנַטְלָא חוּלָקָא מִגּוֹ מַקְדְּשָׁא.</p>"],[9514013972,"<p>וְעַל דְּכַלָּה דָא קַדִּישָׁא אִיהִי, לִמְסָאֲבוּ לֵית לָהּ לְמֵיהַב, עֲבֵידַת גַרְמָהּ ד', כְּמַאן דְּלָא נָטֵיל בְּגַוָּוהּ כָּל כָּךְ, וְאִיהִי מִסְכֵּנָא, וְהָכֵי אִצְטְרִיךְ. וְסִימָנֵיךְ, ב (בראשית מ״ב:א׳) וַיֹּאמֶר יַעֲקֹב לְבָנָיו לָמָּה תִּתְרָאוּ. דְּאַתּוּן בְּשָׂבְעָא וּבְעוֹתְרָא, הָא חַיָּיבֵי אַרְעָא גַּבַּיְיכוּ, אַחֲזוּ גַּרְמַיְיכוּ מִסְכֵּנִין וְכָפִינִין. וְעַל דָּא אַחְזִיאַת גַרְמָהּ בְּחֶדְוָה, ד'.</p>"],[9514013973,"<p>כַד חָמַת, חַיָּיבָא דָּא אָת ק', דְּאִתְפַּשְּׁטָא כְּנָחָשׁ דְּפָשֵׁיט זְנָבֵיהּ, וְאַתְקֵיף לֵיהּ בְּחֶדְוָא, לְיָנְקָא מִן מַקְדְּשָׁא, דִּכְדֵין אִיהוּ אִזְדַּמַּן לְעַרְבָּבָא חֶדְוָוה, בְּכָל אֲתַר דְּחָמֵי לָהּ.</p>"],[9514013974,"<p>וְעַל דָּא, בְּכָל אֲתַר דְּחֶדְוָא, אִית לְאַסְגָּאָה חֵילִין, בְּדִיל דְּלָא יָכֵיל לְקַטְרְגָא. וְכָל בְּכָל אֲתַר דְּאֶבְלָא, אִית לְאַסְגָּאָה חֵילִין, דְּהָא אִיהוּ תַּמָּן, דְּלָא יָךָ אָת חַד מֵאִינוּן מֵישָׁרִים. כְּדֵין נָפְקַת אָת תַּקִּיף זְנָבָא פָּשֵׁיט לְתַתָּא, חַמְשִׁין אַמִין. כְּגַוְונָא דְּהַהוּא אֲתַר, דְּהָמָן אִזְדַּקַּף בֵּיהּ, וְדָא אִיהִי אָת ץ'. כֵּיוָן דְּזָקֵיף הַאי נָחָשׁ עֵינוֹי, וַחֲמָא לְהַאי זְקָפָא דְּאָתֵי, כְּדֵין אִתְפְּרַשׁ מִגּוֹ מַקְדְּשָׁא, וְעָרֵיק.</p>"],[9514013975,"<p>וְכַלָּה נָפְקַת לְגַבֵּיהּ דִּרְחִימָה, וְאִתְעֲבָרַת מֵאָת ד', וְעַיְילָא בְּאָת ה', וְנָפְקַת לְגַבֵּיהּ, וְחֶדְוָה אִשְׁתְּלֵים מִכָּל סִטְרִין, בְּלָא קִטְרוּגָא אָחֳרָא, וּבְלָא עִרְבּוּבְיָא.</p>"],[9514013976,"<p>הָכָא אִית לְאִסְתַּכָּלָא, בְּשַׁעֲתָא דַּאֲמָרַת מָשְׁכֵנִי, אִיהוּ א', וְאִיהִי ת'. וּבְשַׁעֲתָא דַּאֲמָרַת אַחֲרֶיךָ נָרוּצָה, אִיהִי ב', וְאִיהוּ ש'. וּבְשַׁעֲתָא דַּאֲמָרַת נָגִילָה וְנִשְׂמְחָה בָךְ, אִיהוּ ג', וְאִיהִי ר'. וּבְשַׁעֲתָא דְּאַתְיָא נָחָשׁ, כַּד אָמְרָה נַזְכִּירָה דוֹדֶיךָ מִיָּיִן, אִיהִי ד', וְהַהוּא מְקַטְרְגָא ק'. כָּל דָּא, אַמַּאי מִתְחַלְפֵי אַתְוָון מֵאֲתַר לַאֲתַר, אִיהוּ אִתְחַלַּף בְּאַתְוָון אָחֳרָנִין, וְאִיהִי אִתְחַלְּפַת בְּאַתְוָון אָחֳרָנִין.</p>"],[9514013977,"<p>אֶלָּא, בְּשַׁעֲתָא דַּאֲמָרַת מָשְׁכֵנִי, לֵית אָת דְּאַמְשֵׁיךְ לָהּ, בַּר דָּא א. דְּאִיהִי אָת דְּנָהֲרָא בְּסִטְרָא דְּאוֹר קַדְמָאָה, רָזָא דְּיָמִינָא, דְּהָא יָמִינָא מְקָרֵב תָּדִיר, וְאַתְקֵיף בָּהּ, לְאַמְשָׁכָא לָהּ לְעֵילָא. וּבְגִין כָּךְ אִיהוּ א', וְאִיהִי ת', דְּאִיהִי מִתְקַשְּׁטָא בְּכָל סִטְרִין, בְּגִין לְסָלְקָא לְעֵילָא, מְשַׁבַּחַת וּמְהַדְּרַת לְאִתְעָרָא לְעֵילָא.</p>"],[9514013978,"<p>וּבְשַׁעֲתָא דַּאֲמָרַת אַחֲרֶיךָ נָרוּצָה, הָא כָּל אִינוּן אוּכְלוּסִין פְּנִימָאן דִּילָהּ, דְּאִינוּן גּוּפָא, נָטְלָה לְגַבָּהּ, וְאִיהִי בֵּיתָא לְקַבְּלָא אוּכְלוּסָהָא, וּלְעָאֳלָא לוֹן לְגַבֵּי מַלְכָּא. כְּמָה דְאַתְּ אָמֵר, (תהלים מה) בְּתוּלוֹת אַחֲרֶיהָ רְעוּתֶיהָ וְגו'. וְעַל דָּא אִיהִי ב'. וְאִיהוּ אִתְעַטַר בְּשי\"ן, וּפָתַח הֵיכָלִין דְּאִינוּן חַדְרֵי מַלְכָּא, לְקַבְּלָא לָהּ וּלְאַעֳלָא לָהּ לְגַבַּיְיהוּ.</p>"],[9514013979,"<p>וּבְשַׁעֲתָא דַּאֲמָרַת נָגִילָה וְנִשְׂמְחָה בָךְ, הָא חֶדְוָא דְצַדִּיקַיָיא, דְאִזְדַּמַּן לְמֶחֱדֵי לָהּ. וְעַל דָּא אִיהוּ ג', וְאִיהִי ר', אִתְתַּקָּנַת אִיהִי בִּלְחוֹדָהָא, וְאִתְפָּרְעָא לְגַבֵּיהּ, לְנַטְלָא חֶדְוָוה דְהַהוּא אֲתַר, כְּאִתְּתָא דְּאִתְפָּרְעָא לְאִשְׁתַּמְּשָׁא בְּבַעֲלָהּ.</p>"],[9514013980,"<p>וּבְשַׁעֲתָא דַּאֲמָרַת נַזְכִּירָה דּוֹדֶיךָ מִיָּיִן, אִתְקְרֵיב הַהוּא מְקַטְרְגָא, וְכֵיוָן דְּחָמַת לֵיהּ, אִתְעֲבִידַת מִסְכֵּנָא, בְּרָזָא דְאָת ד', בְּגִין דְּלָא יִסְתָּאַב מַקְדְּשָׁא. וְהַהוּא מְקַטְרְגָא פָּשִׁיט זְנָבֵיהּ בְּחֵידוּ, לְקַבְּלָא מֵעִינּוּגֵי דְחֶדְוָא, וְעַל דָּא ק'.</p>"],[9514013981,"<p>עַד דַּאֲמָרַת מֵשָׁרִים, וְאִתְגַּלְיָיא ץ', וְהַהוּא מְקַטְרְגָא עָרַק. וְאִיהִי אַתְיָיא וּמִתְעַבְרָא מֵאָת ד', וְעָיְילַת בְּאָת ה'. וּכְדֵין אִתְגַּלְּיָין מֵשָׁרִים. ה\"ץ, הָא מֵשָׁרִים. ו\"ף, הָא מֵשָׁרִים.</p>"],[9514013982,"<p>וְעַל דָּא, מִתְחַלְּפֵי אַתְוָון, מֵאֲתַר לַאֲתַר, וּמִדַּרְגָּא לְדַרְגָּא, וְכוֹלָּא בְּרָזָא דְּאַתְוָון דְּאוֹרַיְיתָא. זַכָּאִין עַמָּא קַדִּישָׁא, דְּאִינוּן מִתְדַּבְּקֵי בְּמַלְכָּא עִילָּאָה, וְכוֹלָּא אִתְתַּקַּן בְּגִינַיְיהוּ.</p>"],[9514013983,"<p>חָדֵי רַבִּי שִׁמְעוֹן, אֲמַר לֵיהּ אֵלִיָּהוּ, ר', אַפְתַּח פּוּמָךְ, וִינַהֲרוּן מִילָךְ קַמֵּי עַתִּיק יוֹמִין. פְּתַח רַבִּי שִׁמְעוֹן וַאֲמַר, אִי נִיחָא קַמֵי דְמַר דְּאֶשְׁאַל מִינֵּיהּ חַד שְׁאֵילְתָּא. אֲמַר לֵיהּ, ר', קוּטְרָא דְהוּרְמְנוּתָא בִּגְלִיפִין טְהִירִין מַהוּ.</p>"],[9514013984,"<p>אָמַר לֵיהּ, הֲדָא הוּא דִכְתִיב, (שיר השירים א׳:ד׳) מָשְׁכֵנִי אַחֲרֶיךָ נָרוּצָה. דְּהָא בַּאֲתַר דְּהוּרְמְנוּתָא דְמַלְכָּא עִילָּאָה אָזֵיל, תַּמָּן אָזְלֵי כּוּלְהוֹ וְאִתְמַשְׁכָן אֲבַתְרֵיהּ. הַשְׁתָּא ר', אֵימָא מִילָיךְ וּסְדַר זַיְינָךְ.</p>"],[9514013985,"<p>פָּתַח וְאָמַר, מָשְׁכֵנִי אַחֲרֶיךָ נָרוּצָה הֱבִיאַנִי הַמֶּלֶךְ חֲדָרָיו. כְּתִיב, (תהילים ס״ג:א׳) מִזְמוֹר לְדָוִד בִּהְיוֹתוֹ בְּמִדְבַּר יְהוּדָה. תָּא חֲזֵי. דָּוִד מַלְכָּא, קוּדְשָׁא בְּרִיךְ הוּא אִתְרְעֵי בֵיהּ יַתִּיר מִכָּל מַלְכִין דְּעָלְמָא, כְּמָה דְאִתְּמָר, (מלכים א ח׳:ט״ז) וָאֶבְחַר בְּדָוִד לִהְיוֹת עַל עַמִּי יִשְׂרָאֵל. מַאי טַעְמָא.</p>"],[9514013986,"<p>בְּגִין דְּדָוִד, מִן יוֹמָא דְּהֲוָה אָזֵיל בָּתַר עָאנָא בְּמַדְבְּרָא, הֲוָה מִסְתַּכֵּל הָתָם בְּמַדְבְּרָא עוֹבַד אוּמָנוּתָא דְּקוּדְשָׁא בְּרִיךְ הוּא, וַהֲוָה מְשַׁבַּח וַאֲמַר, (תהילים ח׳:ד׳) כִּי אֶרְאֶה שָׁמֶךָ מַעֲשֵׂה אֶצְבְּעוֹתֶיךָ וְגו'.</p>"],[9514013987,"<p>מַאי טַעְמָא, בְּגִין דְּהָא בְּלֵילְיָא, כָּל בְּנֵי עָלְמָא שָׁכְבֵי נַיְימִין עַל עַרְסַיְיהוּ, וְאִיהוּ הֲוָה יָתֵיב בְּמַדְבְּרָא, וַהֲוָה אִסְתַּכֵּל בִּשְׁמַיָא, בְּסִיהֲרָא וְכוֹכְבַיָא וּבְמַזָּלֵי, וּבְעוֹבָדֵי דִשְׁמַיָא, וַהֲוָה אֲמַר כִּי אֶרְאֶה שָׁמֶיךָ וְגו'. וּכְתִיב (שם) ה' אֲדוֹנֵנוּ מָה אַדִּיר שִׁמְךָ וְגו'. וְתָדִיר הֲוָה דָחֵיל, וּמְשַׁבֵּחַ וּמְרוֹמֵם לְקוּדְשָׁא בְּרִיךְ הוּא.</p>"],[9514013988,"<p>לְבָתַר הֲוָה עָרִיק מִקַּמֵּי חֲמוֹי, וּבְכָל עָאקוֹ דְּהֲוָה לֵיהּ, הֲוָה מְשַׁבֵּחַ וּמַצְלֵי קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא. וְהַשְׁתָּא בִּהְיוֹתוֹ בְּמִדְבַּר יְהוּדָה, דְּהֲוָה שָׁאוּל מַלְכָּא רָדֵיף בַּתְרֵיהּ, הֲוָה אֲמַר שִׁירָה. דִּכְתִיב, ט (שם ג) מִזְמוֹר לְדָוִד בִּהְיוֹתוֹ בְּמִדְבַּר יְהוּדָה, בַּאֲתַר דְּהֲוָה רָדְפִין אֲבַתְרֵיהּ.</p>"],[9514013989,"<p>וּמַה אֲמַר, (תהילים ס״ג:ב׳) אֱלֹהִים אֵלִי אַתָּה אֲשַׁחֲרֶךָּ וְגו'. אֱלֹהִים, אֵלִי, אַתָּה, תְּלַת שְׁמָהָן אִינוּן. אֱלֹהִים, דָּא אִיהוּ דַרְגָּא דִילֵיהּ, כִּתְרָא דְמַלְכוּתָא. אֵלִי, דָּא רֵישָׁא, דְּכִתְרָא דָא דְקַיְימָא עֲלֵיהּ, וְאִיהוּ חַד עַמּוּדָא דְּכָל עָלְמָא עֲלֵיהּ קָיְימָא. דִּכְתִיב, (משלי י׳:כ״ה) וְצַדִּיק יְסוֹד עוֹלָם. אַתָּה, דָּא יְמִינָא עִילָּאָה. דִּכְתִיב, (תהילים ק״י:ד׳) אַתָּה כֹהֵן לְעוֹלָם. וְעַל דָּא, תְּלַת דַּרְגִּין הָכָא, אֱלֹהִי\"ם, אֵלִ\"י, אַתָּ\"ה. אֲשַׁחֲרֶךָּ, וַאֲבַקֵּר לְגַבָּךְ בְּכָל יוֹמָא תָּדִיר.</p>"],[9514013990,"<p>(שם סג) צָמְאָה לְךָ נַפְשִׁי, כְּמַאן דְּצָחֵי לְמִשְׁתֵּי, אוּף הָכֵי אֲנָא, צָחֵי נַפְשִׁי לְגַבָּךְ, תְּאִיבָא לְגַבָּךְ בִּשְׂרָא דִילִי, לְמֶהֱוֵי נַפְשָׁא וּבִשְׂרָא דָּבְקָא לְגַבָּךְ. בְּאֶרֶץ צִיָּה וְעָיֵף בְּלִי מָיִם, מַאי בְּלִי מָיִם. דְּלֵית תַּמָּן נְהִירוּ דְאוֹרַיְיתָא, נְהִירוּ דִּנְהוֹרָא עִילָּאָה.</p>"],[9514013991,"<p>(שם) כֵּן בַּקֹּדֶשׁ חֲזִיתִיךָ, מַאי טַעְמָא. אֶלָא כֵּן בַּקֹּדֶשׁ חֲזִיתִיךָ, אַף עַל גַּב דַּאֲנָא בְּמַדְבְּרָא דָא, בַּאֲתַר דְּאִיהוּ הָכֵי, אֲנָא חָמֵי לָךְ, לְאִתְדַּבְּקָא בָּךְ, וְתָאֵיב אֲבַתְרָךְ לְמֶחֱמֵי עוּזָּךְ וּכְבוֹדָךְ. וְדָא אִיהוּ כְּמָא דִכְתִיב, (שיר השירים א׳:ד׳) מָשְׁכֵנִי אַחֲרֶיךָ נָרוּצָה, בְּזִמְנָא דְּתִמְשְׁכֵנִי אֲבַתְרָךְ, כֹּלָּא נִתְרְעֵי עִמָּךְ.</p>"],[9514013992,"<p>הֱבִיאַנִי הַמֶּלֶךְ חֲדָרָיו, אִלֵין חַדְרֵי דְגִנְתָא דְּעֵדֶן. דְּתָנִינָן, כַּד בָּרָא קוּדְשָׁא בְּרִיךְ הוּא לְאָדָם הָרִאשׁוֹן, מֵעַפְרָא דְבֵי מַקְדְּשָׁא נָטֵיל, וּמִתַּמָּן אִתְבְּרֵי. וּנְפַח בְּאַנְפּוֹי נִשְׁמָתָא דְחַיֵּי, וּמִתַּמָּן פָּתַח לֵיהּ פִּתְחָא דְגַן עֵדֶן, וְעַיִּיל לֵיהּ בְּשִׁבְעִין אִדְרִין הֵיכָלִין קַדִּישִׁין, וַעֲבַד לֵיהּ עֶשֶׂר חוּפּוֹת. כְּגַוְונָא דְאִינוּן חוּפּוֹת דְּזַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְמֶעְבַּד לַצַּדִּיקִים בְּגַּן עֵדֶן. וּמַלְאֲכֵי עִילָּאֵי הֲווֹ מְרַקְדָּן קַמֵּיהּ, וַהֲוָה חָדֵי תַּמָּן. וְתַמָּן אַעֲבַר קַמֵּיהּ קוּדְשָׁא בְּרִיךְ הוּא, כָּל אִינוּן רוּחִין וְנִשְׁמָתִין, דְּזַמִּינִין וּמִתְעַתְּדָן לְמֶהֱוֵי בִּבְנֵי נָשָׁא, דְּיִפְקוּן מִינֵּיהּ.</p>"],[9514013993,"<p>כֵיוָן דְּמָטָא לַמֶּלֶךְ דָּוִד, חֲמָא לֵיהּ דְּלָא הֲוֵי לֵיהּ חַיִּין כְּלָל. אֲמַר קַמֵּיהּ רִבּוֹנוֹ שֶׁל עוֹלָם, מַאן הוּא דְנָא, דְּלָא חָמֵינָא לֵיהּ חַיִּין, עַד דַּאֲמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, דָּוִד מַלְכָּא אִיהוּ. כֵּיוָן דַּחֲמָא אָדָם הָרִאשׁוֹן כָּךְ, יְהֵיב לֵיהּ מִשְּׁנוֹי שִׁבְעִין שְׁנִין, וְאִינוּן ע' שְׁנִין דְּחָיֵי דָּוִד מַלְכָּא. וְכָל שַׁיְיפָא וְשַׁיְיפָא מִכָּל שַׁיְיפוֹי, יְהַב לֵיהּ מִדִּילֵיהּ, וְחָסְרוּ מֵאָדָם קַדְמָאָה שִׁבְעִין שְׁנִין, מֵאִינוּן אֶלֶף שְׁנִין דִּילֵיהּ.</p>"],[9514013994,"<p>כְתִיב, (שם) מָשְׁכֵנִי אַחֲרֶיךָ נָרוּצָה, אַתְוָון דְּרָזָא דִשְׁמָא קַדִּישָׁא, הֲווֹ גְּלִיפִין עֵילָא וְתַתָּא. בְּשַׁעֲתָא דְאִינוּן אַתְוָון בָּלְטִין וְסָלְקִין לְגַבֵּי אַתְוָון אָחֳרָנִין, כָּל אִינוּן מַשִּׁרְיָין קַדִּישִׁין, נָטְלִין בְּמַטְלָנוֹן בְּאֵימָתָא וְכִסּוּפָא. בְּגִין דְּלֵית תַּקִּיפוּ לְעִילָּאֵי.</p>"],[9514013995,"<p>מֵהָכָא, כָּל אִינוּן בְּנֵי עָלְמָא דְּלֵית בְּהוּ כִיסּוּפָא, לֵית לְהוּ חוּלָקָא לְעַלְמָא דְאָתֵי. כָּל אִינוּן תַּקִּיפֵא מִצְחָא דַּהֲוֵי בְּהוּ בְּיִשְׂרָאֵל, כַּד הֲווֹ מִסְתַּכְּלִין בְּאַתְוָון דִּשְׁמָא קַדִּישָׁא, בְּצִיצָא נִזְרָא דְּקוּדְשָׁא דְּכֹהֵן גָּדוֹל, הֲווֹ מְתַבְּרֵי לִבַּיְיהוּ, וּמִסְתַּכְּלֵי בְּעוֹבָדֵיהוֹן, בְּגִין דְּצִיץ עַל אָת הֲוָה קָאִים, דְּכָל מַאן דְּאִסְתַּכַּל בֵּיהּ, הֲוָה מַכְסִיף מֵעוֹבָדוֹי.</p>"],[9514013996,"<p>אַתְוָון דְּרָזָא דִּשְׁמָא קַדִּישָׁא דְידו\"ד, דְּהֲוָה גָּלֵיף עַל צִיצָא, הֲווֹ נָהֲרִין וּבָלְטִין וְנָצְצִין, כָּל מַאן דְּאִסְתַּכַּל בְּהַהוּא נְצִיצוּ, הֲוָה חָמֵי אַתְוָון בָּלְטִין, וְאַנְפּוֹי נָפְלִין מֵאֵימָתָא דְּמָארֵיהּ, וְתָבַר לִבֵּיהּ לְגַבֵּי קוּדְשָׁא בְּרִיךְ הוּא.</p>"],[9514013997,"<p>כְגַוְונָא דָא קְטוֹרֶת, כָּל מַאן דְּאָרַח בְּהַהוּא תְּנָנָא, כַּד סָלֵיק הַהוּא עַמּוּדָא, מֵהַהוּא מַעֲלֶה עָשָׁן, הֲוָה מְבָרֵר לִבֵּיהּ בִּבְרִירוּ וּנְהִירוּ, בְּחֶדְוָוא וּרְעוּתָא, לְמִפְלַח לְמָארֵיהּ, וְאַעֲבַר מִנֵּיהּ זוּהֲמָא וְטִנּוּפָא דְּיֵצֶר הָרָע, וְלָא הֲוָה לֵיהּ אֶלָּא לִבָּא חָדָא, לָקֳבֵל אֲבוֹי דְבִשְׁמַיָא.</p>"],[9514013998,"<p>בְּגִין דִּקְטוֹרֶת תְּבִירוּ דְּיֵצֶר הָרָע אִיהוּ וַדַּאי בְּכָל סִטְרִין. וּכְמָא דְּצִיץ הֲוָה קָאִים עַל נִיסָּא, אוּף הָכֵי קְטוֹרֶת. דְּלֵית לָךְ מִלָּה בְּעָלְמָא, דִּמְתַבַּר לֵיהּ לְסִטְרָא אָחֳרָא, בַּר קְטוֹרֶת.</p>"],[9514013999,"<p>תָּא חֲזֵי, דְּהָא אוֹקְמוּהָ, דִּכְתִיב, (במדבר י״ז:י״א) וַיֹּאמֶר משֶׁה אֶל אַהֲרֹן קַח אֶת הַמַּחְתָּה וְגו', דְּהָא תְּבִירוּ דְּסִטְרָא אָחֳרָא לָאו אִיהוּ אֶלָּא קְטוֹרֶת. בְּגִין דְּהָא לֵית חֶדְוָה וַחֲבִיבוּ קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא כִּקְטוֹרֶת. וְקָיְימָא לְבַטָלָא חָרָשִׁין וּמִילִּין בִּישָׁא מִבֵּיתָא. רֵיחָא וַעֲשָׁנָא דִקְטוֹרֶת, דְּעָבְדֵי בְּנֵי נָשָׁא לְהַהוּא עוֹבָדָא אִיהוּ מְבַטֵל. כָּל שֶׁכֵּן קְטוֹרֶת.</p>"],[9514014000,"<p>מִלָּה דָא אִיהוּ גְּזֵירַת קִיּוּמָא קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, דְּכָל מַאן דְּאִסְתַּכַּל וְקָרֵי בְּכָל יוֹמָא עוֹבָדָא דִקְטוֹרֶת, אִשְׁתְּזֵיב מִכָּל מִלִּין דַּחֲרָשִׁין דְּעָלְמָא, וּמִכָּל פְּגָעִין בִּישִׁין, וּמֵהַרְהוֹרָא בִּישָׁא, וּמִדִּינָא בִּישָׁא, וּמִמּוֹתָנָא. וְלָא יִתְּזַק כָּל הַהוּא יוֹמָא, דְּלָא יָכֵיל סִטְרָא אָחֳרָא לְשַׁלְטָאָה עֲלֵיהּ, וְאִצְטְרִיךְ דִּיכַוֵּין בֵּיהּ.</p>"],[9514014001,"<p>אָמַר רַבִּי שִׁמְעוֹן, אִי בְּנֵי נָשָׁא הֲווֹ יָדְעֵי כַּמָּה עִילָּאָה הוּא עוֹבָדָא דִקְטוֹרֶת קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, הֲווֹ נָטְלֵי כָּל מִלָּה וּמִלָּה מִנֵּיהּ, וְסַלְקֵי לָהּ עֲטָרָא עַל רֵישַׁיְיהוּ, כְּכִתְרָא דְדַהֲבָא. וּמַאן דְּיִשְׁתַּדֵּל בֵּיהּ, לְאִסְתַּכָּלָא בְּעוֹבָדָא דִקְטוֹרֶת, וּלְכַוֵּין בֵּיהּ בְּכָל יוֹמָא, אִית לֵיהּ חוּלָקָא בְּהַאי עָלְמָא וּבְעָלְמָא דְאָתֵי, וִיסַלֵּק מוֹתָנָא מִינֵּיהּ וּמִכָּל עָלְמָא, וְיִשְׁתְּזֵיב מִכָּל דִּינִין דְּהַאי עָלְמָא, וּמִסִּטְרִין בִּישִׁין, וּמְדִינֵי דְּגֵיהִנֹּם, וּמִדִּינָא דְּמַלְכוּ אָחֳרָא.</p>"],[9514014002,"<p>בְּהַהוּא קְטוֹרֶת, כַּד הֲוָה סָלֵיק תְּנָנָא בְּעַמּוּדָא, כַּהֲנָא הֲוָה חָמֵי אַתְוָון דְּרָזָא דִשְׁמָא קַדִּישָׁא פְּרִישָׂן בַּאֲוִירָא, וְסָלְקִין לְעֵילָא בְּהַהוּא עַמּוּדָא. לְבָתַר, כַּמָּה רְתִיכִין קַדִּישִׁין הֲווֹ סָחֲרִין לֵיהּ מִכָּל סִטְרִין, עַד דְּסָלֵיק וְחָדֵי לְמַאן דְּחָדֵי. וּבְהַהוּא קְטוֹרֶת הֲוָה מִתְקַשְּׁרֵי קִשּׁוּרִין עִילָּאִין. וְשַׁיְיפִין נָחֲתִין לְאַמְשָׁכָא לְדַרְגָא דִלְתַתָּא לְעֵילָּא. וּכְדֵין אִיהִי אָמְרַת, מָשְׁכֵנִי אַחֲרֶיךָ נָרוּצָה. בְּגִין דִּקְטוֹרֶת אִיהִי מְקַשֵּׁר קִשְׁרִין עֵילָּא וְתַתָּא.</p>"],[9514014003,"<p>פְּתַח וַאֲמַר, (שמות ל׳:א׳) וְעָשִׂיתָ מִזְבֵּחַ מִקְטַר קְטֹרֶת וְגו'. הַאי קְרָא אִית לְאִסְתַּכָּלָא בֵּיהּ. בְּגִין דִּתְרֵין מִדְבְּחִין הֲווֹ, מִדְבְּחָא דַּעֲלָוָון, וּמִדְבְּחָא דִּקְטוֹרֶת בּוּסְמִין. דָּא לְבַר, וְדָא לְגַאו. הַאי מִדְבְּחָא דִקְטוֹרֶת, אִיהוּ פְּנִימָאָה.</p>"],[9514014004,"<p>אַמַּאי אִיקְּרֵי מִזְבֵּחַ, וְהָא לָא דַּבְּחִין בֵּיהּ דִּבְחִין, וּמִזְבֵּחַ עַל דָּא אִיקְּרֵי. אֶלָּא בְּגִין דְּבַטֵיל וְכָפֵית לְכַמָּה סִטְרִין בִּישִׁין. וְהַהוּא סִטְרָא אָחֳרָא הֲוָה כָּפֵית, כְּעֶגְלָא דְּכָפֵית לְדַבָּחָא, אוּף הָכֵי סִטְרָא אָחֳרָא הֲוָה כָּפֵית, דְּלָא יָכֵיל לְשַׁלְטָאָה, וְלָא לְמֶהֱוֵי מְקַטְרְגָא, וְעַל דָּא אִיקְּרֵי מִזְבֵּחַ.</p>"],[9514014005,"<p>כַד הַהוּא סִטְרָא אָחֳרָא הֲוָה חָמֵי עַמּוּדָא דַעֲשָׁנָא דִּקְטוֹרֶת סָלֵיק, הֲוָה אִתְכַּפְיָיא וְעָרַק, וְלָא יָכֵיל לְקָרְבָא לְמַשְׁכְּנָא. וּבְגִין דָּא אִתְדַּכֵּי, וְלָא אִתְעָרַב אָחֳרָא בְּהַהוּא חֶדְוָוא דִלְעֵילָא, בַּר קוּדְשָׁא בְּרִיךְ הוּא בִּלְחוֹדוֹי.</p>"],[9514014006,"<p>וְלֵית סִטְרָא אָחֳרָא דְּאִתְהַנֵּי מִינֵיהּ, וְלֵית לְסִטְרָא אַחֲרָא בָּהּ חוּלָקָא כְּבִשְׁאָר קוּרְבָּנִין וְעִלַּוָּון. בְּגִין דְּבִשְׁאָר קוּרְבָּנִין, לְכוֹלָּא אִית חוּלָקָא וּקְרִיבוּ בְּהַהוּא קָרְבָּן. בִּקְטוֹרֶת, לָא מִתְקַשֵּׁר וּמִתְקָרֵב בַּר קוּדְשָׁא בְּרִיךְ הוּא בִּלְחוֹדוֹי, וְכָל סִטְרִין בִּישִׁין עָרְקִין, וְסִטְרִין קַדִּישִׁין מִתְקָרְבִין, וּמִתְקַשְּׁרִין שַׁיְיפָא בְּשַׁיְיפָא, דָּא בְּדָא, כָּל חַד וְחַד כִּדְקָא חָזֵי לֵיהּ.</p>"],[9514014007,"<p>וּבְגִין דַּחֲבִיבָא כָּל כַּךְ, לָא קָאִים הַהוּא מִזְבֵּחַ פְּנִימָאָה אֶלָּא לְגוֹ. דְּהַאי אִיהוּ מִזְבֵּחַ דְּבִרְכָאן אִשְׁתַּכָּחוֹ בֵיהּ, וְעַל דָּא סָתִים מֵעֵינָא.</p>"],[9514014008,"<p>מַה כְּתִיב בְּאַהֲרֹן, (במדבר י״ז:י״ג) וַיַּעֲמֹד בֵּין הַמֵּתִים וְגו'. דְּכָפֵית לֵיהּ לְמַלְאַךְ הַמָּוֶת, דְּלָא יָכֵיל לְשַׁלְטָאָה כְּלַל, וְלָא לְמֶעְבַּד דִּינָא. סִימָנָא דָא אִתְמְסַר בִּידָנָא, דִּבְכָל אֲתַר דְּאָמְרֵי בְּכַוָּנָה וּבִרְעוּתָא דְלִבָּא עוֹבָדָא דִקְטוֹרֶת, דְּלָא שָׁלְטָא מוֹתָנָא בְּהַהוּא אֲתַר, וְלָא יִתְּזְקוּ, וְלָא יָכְלִין עוֹבְדֵי גִלּוּלִים וְלָא שְׁאָר דַּרְגִּין אָחֳרָנִין לְאִתְקָרְבָא בַּהֲדַיְיהוּ.</p>"],[9514014009,"<p>מַה כְּתִיב בְּיַעֲקֹב, (בראשית ל׳:מ׳) וַיָּשֶׁת לוֹ עֲדָרִים לְבַדּוֹ. מִכָּאן, דְּבֵירַר פְּסוֹלֶת מִן מַקְדְּשָׁא, וְשַׁוֵּי חוּלָקֵיהּ בִּלְחוֹדוֹי, וְכָל אִינוּן רְתִיכִין דְּאִתְחֲזוֹן לֵיהּ לְרָזָא דִּמְהֵימְנוּתָא קַדִּישָׁא. וְלָא שָׁתָם עַל צֹאן לָבָן, דְּשַׁוֵּי חוּלַק שְׁאָר עַמִּין בִּלְחוֹדַיְיהוּ, דְּלָא יִתְעָרְבוּן בַּהֲדֵי מְהֵימְנוּתָא קַדִּישָׁא. הַצֹּאן הַמְקוּשָּׁרוֹת, אִינוּן דְּמִתְקַשְּׁרֵי בְּקִישּׁוּרָא חָדָא, דְּלָא מִתְעָרְבֵי בַּהֲדֵי שְׁאָר עַמִּין, דְּלָא מִתְקַשְּׁרִין בַּהֲדַיְיהוּ לְעָלְמָא.</p>"],[9514014010,"<p>כְגַוְונָא דָּא קְטוֹרֶת, דְּהָא בְּהַהוּא קְטוֹרֶת, כָּל רְתִיכִין קַדִּישִׁין דְּרָזָא דִמְהֵימְנוּתָא, הֲווֹ מִתְקַשְּׁרָן, וְכָל שַׁיְיפִין עִילָּאִין וְתַתָּאִין, כּוּלְהוּ מִתְקַשְּׁרִין אִלֵּין בְּאִלֵּין. דְּהָא רְתִיכִין קַדִּישִׁין דִּלְתַתָּא, הֲווֹ מִתְקָרְבִין וּמִתְקַשְּׁרִין אִלֵּין בְּאִלֵּין, לְמֶהֱוֵי כּוּלְהוּ בְּיִיחוּדָא חָדָא, לְסַלְקָא בְּיִיחוּדָא כִּדְקָא חָזֵי.</p>"],[9514014011,"<p>וְכָל אִינוּן מַשִּׁרְיָין דִּשְׁאָר עַמִּין, כּוּלְהוּ מִתְבַּדְּרֵי, וּמִתְפַּלְּגֵי דָּא מִן דָּא, וְעַל דָּא אִיקְרוּן יִשְׂרָאֵל גּוֹי אֶחָד, דְּאִינוּן בְּיִיחוּדָא וְקִישּׁוּרָא חָדָא. וְעַל דָּא אִיקְרוּן הַצֹּאן הַמְקוּשָּׁרוֹת, מַה דְּלֵית הָכֵי לִשְׁאָר עַמִּין.</p>"],[9514014012,"<p>קְטוֹרֶת אָסוּר לְאַקְטָרָא בַּר בַּמִּזְבֵּחַ, וְלָא בְמָנָא אָחֳרָא, בַּר בְּמַחְתָּה. הַאי מַאן דְּדִינָא רָדִיף אֲבַתְרֵיהּ, אִצְטְרִיךְ לְהַאי קְטוֹרֶת, וְלַאֲתָבָא לְקַמֵּי מָארֵיהּ, דְּהָא סִיּוּעָא אִיהוּ לְסַלְקָא דִּינִין מֵעֲלֵיהּ.</p>"],[9514014013,"<p>וּבְהַאי וַדַּאי מִסְתַּלְּקִין דִּינִין מֵעֲלֵיהּ, אִי הוּא רָגִיל בְּהַאי, לְאַדְכָּרָא לֵיהּ תְּרֵין זִמְנִין בְּכָל יוֹמָא, בְּצַפְרָא וּבְרַמְשָׁא, דִּכְתִיב (שמות ל) וְהִקְטִיר עָלָיו אַהֲרֹן קְטוֹרֶת סַמִּים בַּבֹּקֶר בַּבֹּקֶר. וּכְתִיב (שם) וּבְהַעֲלוֹת אַהֲרֹן וְגו'. וְדָא אִיהוּ קִיּוּמָא דְּעַלְמָא דִלְתַתָּא, וְקִיּוּמָא דְעַלְמָא דִלְעֵילָא.</p>"],[9514014014,"<p>בְּהַהוּא אֲתַר דְּלָא אִידְכַּר בְּכָל יוֹמָא עוֹבָדָא דִקְטוֹרֶת, דִּינִין דִּלְעֵילָא שַׁרְיָין עֲלֵיהּ, וּמוֹתָנָא סַגִּיאָה בֵּיהּ, וְעַמִּין אָחֳרָנִין שָׁלְטִין עֲלֵיהּ, בְּגִין דִּכְתִיב, (שם) קְטֹרֶת תָּמִיד לִפְנֵי ה' לְדֹרֹתֵיכֶם. תָּדִיר אִיהוּ קָיְימָא לִפְנֵי ה', יַתִּיר מִכָּל פּוּלְחָנִין אָחֳרָנִין.</p>"],[9514014015,"<p>מָשְׁכֵנִי, בְּאַתְוָון דִּשְׁמָא קַדִּישָׁא. כַּד מִתְחַבְּרָן תְּרֵין שְׁמָהָן כַּחֲדָא, דְּאִינוּן שְׁמָא שְׁלִים, יהו\"ה אֱלֹהִים. שְׁמָא קַדְמָאָה, מָשֵׁיךְ לְגַבֵּיהּ שְׁמָא אָחֳרָא.</p>"],[9514014016,"<p>וּמַה דַּאֲמַר אַחֲרֶיךָ נָרוּצָה, וְלָא כְתִיב אָרוּצָה. בְּגִין דִּשְׁמָא דָא דְּאִיקְּרֵי אֱלֹהִי\"ם, כַּמָּה רְתִיכִין, וְכַמָּה בֵּי דִינִין, כּוּלְהוּ כְּלִילָן וּמִתְחַבְּרָן בֵּיהּ. וְעַל דָּא כְּתִיב אַחֲרֶיךָ נָרוּצָה.</p>"],[9514014017,"<p>סַגִּיאִין אִינוּן דִּכְלִילָן בְּהַאי שְׁמָא, וְאִיהוּ כּוֹלָא שְׁמָא חָדָא. דְּכֵיוָן דִּשְׁמָא קַדְמָאָה מָשֵׁיךְ לִשְׁמָא אָחֳרָא, כְּדֵין כֹּלָּא הוּא חִבּוּרָא חָדָא, וְעִילָּאִין וְתַתָּאִין כּוּלְהוּ דַרְגִּין מִתְקַשְּׁרִין הָא בְּהָא, לְמֶהֱוֵי כּוּלְהוּ קִשּׁוּרָא חַד, וְחִיבּוּרָא חַד, וְיִיחוּדָא חַד.</p>"],[9514014018,"<p>(שיר השירים א׳:ד׳) הֱבִיאַנִי הַמֶּלֶךָ חֲדָרָיו, דָּא מַלְכָּא קַדִּישָׁא עִילָּאָה. חֲדָרָיו, אִלֵּין חֲדָרִין עִילָּאִין, וְאִידְרִין קַדִּישִׁין דִּרְתִיכִין עִילָּאִין.</p>"],[9514014019,"<p>חַדְּרָא קַדְמָאָה, אִיהוּ נְהִירוּ דְּנָהֵיר מִסִּטְרָא דְיָמִינָא, נְהִירוּ דְּנָהֵיר מִסְּיָיפֵי עַלְמָא וְעַד סְיָיפֵי עַלְמָא. נְהִירוּ דְּכָל נְהוֹרִין כְּלִילָן בֵּיהּ. נְהִירוּ דְּאַרְבַּע גְּוָונִין, גְּלִיפִין בְּאַרְבַּע סִטְרִין דְּעָלְמָא, וְאִיקְּרֵי אֵל גָּדוֹל. נְהִירוּ דְּנָטֵיל בְּרֵישָׁא, אִדְּרָא וְחַדְּרָא קַדְמָאָה. וְדָא אִיהוּ נְהוֹרָא דְּאִתְאַחֲדָא בְּרֵישָׁא בְּרָזָא דְּאִיקְּרֵי יהו\"ה.</p>"],[9514014020,"<p>חַדְּרָא תִּנְיָינָא, נְהִירוּ דַּחֲשׁוֹכָא, דְּקָא נָפְקָא מִסִּטְרָא דִּנְהִירוּ קַדְמָאָה. וְדָא אִיהוּ נְהִירוּ סוּמְקָא, דְּחָשִׁיךְ. וְדָא אִיהוּ דְּאִתְקְרֵי אֱלֹהִים, דְּבִסְטַר שְׂמָאלָא, לְאִתְקַשְּׁרָא בִּנְהִירוּ קַדְמָאָה.</p>"],[9514014021,"<p>תְּרֵין אִדְּרִין דְּמִתְקַשְּׁרָן וּמִתְחַבְּרָן דָּא בְּדָא. דְּהָא בְּאִלֵּין אִדְּרִין, הַהִיא דִּלְתַתָּא אִתְאַחֲדָא, וְאָעֵיל לָהּ מַלְכָּא עִילָּאָה לְאִלֵּין חֲדָרִין קַדִּישִׁין. וַאֲנָא וְכוּלְהוּ, בְּשַׁעֲתָא דְּאִתְקַשַּׁרְנָא כַּחֲדָא בְּקִישּׁוּרָא חָדָא, נָגִילָה וְנִשְׂמְחָה בָךְ. נָגִילָה וְנִשְׂמְחָה בְּאִינוּן כ\"ב אַתְוָון אַלְפָא בֵיתָא, דְּאִקְּרֵי בָ\"ךְ. כְּמָה דְאַתְּ אָמֵר אֲשֶׁר נִשְׁבַּעְתָּ לָהֶם בָּךְ. בְּךָ יְבָרֵךְ יִשְׂרָאֵל. אב גד הו זח טי כל מנ סע פצ קר שת אִלֵּין אִינוּן עֶשְׂרִים וּתְרֵין אַתְוָון דְּאַלְפָא בֵיתָא, וּמִתְחַלְּפֵי לְעֶשְׂרִין וּתְרֵין אַלְפָא בֵיתוֹת, בְּרָזָא דִּשְׁמָהָן קַדִּישִׁין גְּלִיפִין בִּשְׁמָהָן דִּלְהוֹן, וְאִינוּן אִיקְרוּן ב\"ך.</p>"],[9514014022,"<p>נָגִילָה וְנִשְׂמְחָה בָךְ, בָּךְ וַדַּאי, דְּהָא כָּל אַתְוָון נָטֵיל הַאי קְיָימָא קַדִּישָׁא, רָזָא בָּךְ: אב גד הו זח טי כל מנ סע פצ קר שת.</p>"],[9514014023,"<p>אשב גתד הקו זרח טפי כצל מסן עזר אכתריאל יה צְבָאוֹת יוֹשֵׁב עַל כִּסֵּא רָם וְנִשָּׂא. וְכָל גְּדוּדֵי שָׂרֵי צִבְאוֹת מַעְלָה, מִימִינוֹ חַיִּים מִשְׂמֹאלוֹ מָוֶת. וְהַכִּסֵּא עוֹמֵד עַל אַרְבָּעָה עַמּוּדִים. וְדָא עַמּוּד הַיְמִינִי, בְּד' שַׁלְהוֹבֵי מְלַהֲטָן דְּאַתְוָון.</p>"],[9514014024,"<p>בשא דתג וקה חרז יפט לצכ נסמ עזר יהו, דָּא אִיהוּ רָזָא וְסִתְרָא דְּעַמּוּדָא דְאֶמְצָעִיתָא, מֵאִינוּן אַרְבַּע עַמּוּדִין, דְּהַהוּא כִּסֵּא סַמְכָא עֲלַיְיהוּ, בְּרָזָא דְאַתְוָון דְּאַלְפָא בֵיתָא. וְאִינוּן תְּרֵיסַר בְּכָל עַמּוּדָא וְעַמּוּדָא, לְאִתְקָיְימָא כָּל חַד מִנַּיְיהוּ עַל תְּרֵיסַר עַמּוּדִין סָמְכִין, לְאִתְקָיְימָא כּוּרְסְיָיא עֲלַיְיהוּ.</p>"],[9514014025,"<p>עַמּוּה הַשְּׂמָאלִי, אִיהוּ בְּרָזָא אָחֳרָא, תא\"ש רב\"ק צג\"פ עד\"ס נה\"ם לו\"ך כז\"י טח\"י הו\"י דָּא אִיהוּ רָזָא וְסִתְרָא דְּעַמּוּדָא דִשְׂמָאלָא. וְכוּרְסְיָיא מִתְתַּקְּנָא עֲלַיְיהוּ, בְּרָזָא וְסִתְרָא דִּתְרֵיסַר סָמְכִין.</p>"],[9514014026,"<p>וְהָא תִּשְׁעָה הֲווֹ. אֶלָּא, תְּלַת אַתְוָון מִצְטָרְפִין גּוֹ צֵירוּפָא חָדָא בְּהַאי סִטְרָא, וּבְהַאי סִטְרָא, לִתְלַת תֵּיבִין. סָלְקִין וְנָחֲתִין, וְאִינוּן טְמִירִין בְּרָזָא יה\"ו, גְּלִיפוּ דִּשְׁמָא קַדִּישָׁא מְחַקְּקָא יה\"ו יה\"ו יה\"ו אִלֵּין גְּנִיזִין בְּעַמּוּדָא קַדְמָאָה, דְּאִיהוּ עַמּוּדָא דְּיָמִינָא. יה\"ו יו\"ה הי\"ו, אִלֵּין גְּנִיזִין בְּעַמּוּדָא דִשְׂמָאלָא. לְמֶהֱוֵי כּוּרְסְיָיא שְׁלֵימָא בְּרָזָא דְעֶשְׂרִין וּתְרֵין אַתְוָון דְּאַלְפָא בֵיתָא, דְּהַהוּא קְיָם קַדִּישָׁא כָּנֵישׁ וְנָטֵיל בְּגַוֵּויהּ בְּרָזָא בָּךְ, וְעַל דָּא נָגִילָה וְנִשְׂמְחָה בָךְ.</p>"],[9514014027,"<p>נַזְכִירָה דֹדֶיךָ מִיַּיִן, מִיֵּינָהּ שֶׁל תּוֹרָה. דּוֹדֶיךָ, אִלֵּין ע' מְמַנָּן דְּסָחֲרִין כּוּרְסְיָיא קַדִּישָׁא. וְאִינוּן רַבְרְבִין שָׁלְטִין, וְנָטְלִין דִּינָא מֵהַהוּא יַיִן. וְעַל דָּא כְּתִיב, אַשְׁקֶךָ מִיַּיִן הָרֶקַח. וְאִינוּן דּוֹדִים שִׁבְעִין.</p>"],[9514014028,"<p>וְאִלֵּין אִינוּן: מִיכָאֵל. גַּבְרִיאֵל. רְפָאֵל. נוּרִיאֵל. קְדוּמִיאֵל. מַלְכִּיאֵל. צַדְקִיאֵל. פְּדַאֵל. תּוֹמִיאֵל. חַסְדִּיאֵל. צוּרִיאֵל. רְמָאֵל. יוֹפִיאֵל. סטוריה. גַּזְרִיאֵל. להמיאל. חזקיאל. רהטיאל. קדשיאל. שבניאל. גדהסיאל. ומיאל. קדמיאל. חכמיאל. רמאל. קדשיאל. עניאל. עזריאל. פוריאל. חכמיאל. מבניאל. קניאל. גדיאל. צורטק. עופפיאל. רחמיאל. סנסניה. ודרגזריה. ודרגויה. רססיאל. רומיאל. סניה. טהריאל. עזריאל. גדיה. שמיאל. עינאל. תסוריה. דנאל. צוריה. כסיסיה. עיריאל. סמכיאל. מרוניה. כמניה. ירויאל. טטרוסיה. חוניאל. זכריאל. ועריאל. דטיאל. גדיאל. בראל. אהינאל. אֵין בֵּין כּוּלָּם רק ס\"ה.</p>"],[9514014029,"<p>בִּסְפָרִים אֲחֵרִים כָּתוּב כַּסֵּדֶר הַזֶּה: מִיכָאֵל. גַּבְרִיאֵל. רְפָאֵל. נוֹרִיאֵל. קְדוּמִיאֵל. מַלְכִּיאֵל. צַדְקִיאֵל. פדאל. תומיאל. חסדיאל. צוריאל. רמאל. יופיאל. סטוריאל. גזריאל. ודריאל. להריאל. חזקיאל. רהמיאל. קדשיאל. שבניאל. ברקיאל. אהיאל. חניאל. לעריאל. מלכיאל. שבניאל. רהסיאל. רומיאל. קדומיאל. קדמאל. חכמיאל. רמאל. קדשיאל. עניאל. עזריאל. חכמיאל. מחניאל. קניאל. גדיאל. צורטק. עופפיאל. רחמיאל. סנסניה. ודרגזיה. רססיאל. דומיאל. סניה. טהריאל. יעזריאל. נריה. סמכיאל. עינאל. תסיריה. רנאל. צוריה. פסיסיה. עיריאל. סמכיאל. מרוניה. קנוניה. ירואל. טטרוסיה. חוניאל. זכריאל. ועריאל. דניאל. גדיאל. בריאל. אהניאל.</p>"],[9514014030,"<p>הֵם ע' אִילֵין, אִינוּן דְּסָחֲרִין כּוּרְסְיָיא קַדִּישָׁא, דְּאִקְּרוּן דּוֹדִים. וְנָהֲרִין וְנָצְצִין, מֵאִינוּן דּוֹדִים עִילָּאִין, דְּנָהֲרִין וְנָצְצִין בִּטְמִירוּ וּגְנִיזוּ עִלָּאָה. וַעֲלַיְיהוּ כְּתִיב, (שיר השירים א׳:ב׳) כִּי טוֹבִים דֹּדֶיךָ מִיַּיִן. דּוֹדֶךָ, אִלֵּין כּוּלְהוֹן בִּכְלָלָא חָדָא, תַּתָּאִין מִגּוֹ עִילָּאִין, וְכוּלְהוּ נְהִירִין וּנְצִיצִין מִגּוֹ הַהוּא יַיִן דְּמִנְטְרָא.</p>"],[9514014031,"<p>עִילָּאִין טְמִירִין, אִינוּן אִיקְּרוּן חַיּוֹת טְמִירִין, דְּאִינוּן רָצוֹא וָשׁוֹב. וְאִינוּן נָהֲרִין מִגּוֹ עַלְמָא עִילָּאָה, עַלְמָא דְאָתֵי. וְאִלֵּין תַּתָּאִין, נָהֲרִין וּנְצִיצִין מִגּוֹ הַהוּא נְהִירוּ טָמִיר וְגָנִיז, דְּאִלֵּין נְצִיצִין.</p>"],[9514014032,"<p>וְכָלְהוֹ מִיַּיִן, מֵאִינוּן שִׁבְעִין שְׁמָהָן, דְּאִינוּן נְהִירִין טְמִירִין. דְּהָא אִינוּן שִׁבְעִין דְּסָחֲרִין כּוּרְסְיָא קַדִּישָׁא לְתַתָּא, מֵאִינוּן שִׁבְעִין פְּנִימָאִין נְהִירִין כָּלְהוֹ וְנָצְצֵי. וְדָא הוּא מִיַּיִן, מֵאִינוּן נַהֲרִין עִילָּאִין, יֵינָא דְאוֹרַיְיתָא. וְאִינוּן בּוּצִינִין עִילָּאִין דְּנָהֲרִין אַנְפִּין, וּבוּצִינִין. וְאִינוּן שִׁבְעִין שְׁמָהָן דְּאִתְקְרֵי בְּהוּ קוּדְשָׁא בְּרִיךְ הוּא.</p>"],[9514014033,"<p>בְּרָזָא וְסִתְרָא דְאַלְפָא בֵיתָא, דְּאִינוּן כ\"ב אַתְוָון, אִית מִנַּיְיהוּ עֶשֶׂר עִילָּאִין, א\"ב ג\"ד ה\"ו ז\"ח ט\"י. וּתְרֵיסַר אָחֳרָנִין, דְּמִתְהַפְּכִין לְכַמָּה גְוָונִין, וּמִתְגַּלְגְּלִין בְּאַתְוָון, וּלְעוֹלָם לָא מְשַׁנְיָין. דְּהָא יֵינָא דְאוֹרַיְיתָא מֵהָכָא מִתְפָּרַשׁ. לָא דְּנַפְקָא מֵאִלֵּין אַתְוָון, אֶלָּא מִטְמִירוּ דִלְּהוֹן.</p>"],[9514014034,"<p>בְּגִין דְּאַתְוָון כּוּלְהוּ נָפְקוֹ מִגּוֹ נְקוּדָה עִילָּאָה, טְמִירָא וּסְתִימָא, רָזָא וּכְלָלָא דְאוֹרַיְיתָא, וְלָא הֲווֹ רְשִׁימִין אַתְוָון בֵּיהּ, עַד דְּעָלוּ לְגוֹ הֵיכָלָא טְמִירָא, וְנָפְקוֹ אַתְוָון, וְלַחִים הֲווֹ, וְאִתְקְרִישׁוּ.</p>"],[9514014035,"<p>וּכְדֵין אִתְגְּלֵיף שְׁמָא קַדִּישָׁא בְּרָזָא דְאַתְוָון. בְּגוֹ אַתְוָון דְּאִתְבְּרִיאוּ בְּהוּ שְׁמַיָא וְאַרְעָא. שְׁמָא גְלִיפָא עִילָּאָה בְּרָזָא דְּמ\"ב אַתְוָון.</p>"],[9514014036,"<p>כֵיוָן דְּקָיְימוּ אַתְוָון עַל תִּיקּוּנַיְיהוּ, וְאִתְקַיַּים עַלְמָא. כְּדֵין אִתְתַּקָּנוּ אַתְוָון בְּע\"ב שְׁמָהָן, דְּאִיקְּרוּן יַיִן, שִׁבְעִין שְׁמָהָן דְּאִתְקְרֵי קוּדְשָׁא בְּרִיךְ הוּא בְּהוּ. וְאִלֵּין אִינוּן יַיִ\"ן.</p>"],[9514014037,"<p>וה\"ו. יל\"י. סי\"ט. על\"ם. מה\"ש. לל\"ה. אכ\"א. כה\"ת. הז\"י. אל\"ד. לא\"ו. הה\"ע. יז\"ל. מבְּרִיךְ הוּא. הר\"י. הק\"ם. לא\"ו. כל\"י. לו\"ו. פה\"ל. נל\"ך. יי\"י. מל\"ה. חה\"ו. נת\"ה. הא\"א. יר\"ת. שא\"ה. רי\"י. או\"ם. לכ\"ב. וש\"ר. יחַס וְשָׁלוֹם. לה\"ח. כו\"ק. מנ\"ד. אנ\"י. חע\"ם. רה\"ע. יי\"ז. הה\"ה. מי\"ך. וו\"ל. יל\"ה. סאָמַר לֵיהּ. ער\"י. עש\"ל. מי\"ה. וה\"ו. דנ\"י. הח\"ש. עמ\"ם. ננ\"א. ני\"ת. מבְּרִיךְ הוּא. פו\"י. נמ\"ם. יי\"ל. הר\"ח. מצ\"ר. ומ\"ב. יה\"ה. ענ\"ו. מח\"י. דמ\"ב. מנ\"ק. אי\"ע. חב\"ו. רא\"ה. יב\"ם. הי\"י. מו\"ם.</p>"],[9514014038,"<p>(שיר השירים א׳:ה׳) שְׁחוֹרָה אֲנִי וְנָאוָה, בּוּצִינָא דְּמַעֲרָב, כַּד שָׁלְטָא וְקָיְימָא לְגַבֵּי בּוּצִינָא דְמִזְרָח, דָּא אוּכְמָא, וְדָא חִיוָּורָא. כַּמָּה הוּא יָאֶה, בְּהַהוּא נְהִירוּ חִוָּורָא.</p>"],[9514014039,"<p>נְהִירוּ דְּבוּצִינָא, תְּרֵין נְהוֹרִין מִתְחַבְּרָן כַּחֲדָא. תַּתָּאָה אוּכְמָא, עִילָּאָה חִיוָּורָא. דָּא שָׁלְטָא עַל דָּא, נְהוֹרָא חִיוָּורָא עַל אוּכְמָא. וְעִם כָּל דָּא, כַּמָּה אִיהִי יָאָה.</p>"],[9514014040,"<p>בְּתִיקּוּנָא דִּתְחוֹתָהּ, כַּמָּה תִּיקּוּנִין קָיְימִין תְּחוֹתָהּ, פְּתִילָה וּשְׁרַגָּא וּמִשְׁחָא. וְאִיהִי קָיְימָא בִּרְבוּ עִילָּאָה, יָאָה בְּהַהוּא נְהוֹרָא חִיוָּורָא. כָּךְ בְּנוֹת יְרוּשָׁלַיִם, אִלֵּין תִּקּוּנִין דִּלְתַתָּא, דְּקָיְימִין תְּחוֹתָהּ בְּנוֹי דִילָהּ. כְּאָהֳלֵי קֵדָר כִּירִיעוֹת שְׁלֹמֹה. דָּא אוּכְמָא, וְדָא חִיוָּורָא.</p>"],[9514014041,"<p>שְׁחוֹרָה אֲנִי וְנָאוָה, כְּתִיב (משלי כ״ב:ו׳) חֲנֹךְ לַנַּעַר עַל פִּי דַּרְכּוֹ גַּם כִּי יַזְקִין לֹא יָסוּר מִמֶּנָּהּ. כַּד בְּרָא קוּדְשָׁא בְּרִיךְ הוּא לָאָדָם, בָּרָא לֵיהּ בִּדְיוֹקְנָא עִילָּאָה, אֵבָרוֹי וְשַׁיְיפוֹ כָּלְהוֹ בְּרָזָא עִילָּאָה. נָחֵית לֵיהּ לְאַרְעָא גּוֹ גִּינְתָא דְעֵדֶן, דִּבְרָא קוּדְשָׁא בְּרִיךְ הוּא בְּאַרְעָא בַּאֲתַר טָמִיר וְגָנִיז, דְּאִיהוּ בִּדְיוּקְנָא וְצִיּוּרָא דִלְעֵילָא. דִּכְתִיב, (בראשית ב׳:ט״ו) וַיִּקַּח ה' אֱלֹהִים אֶת הָאָדָם וַיַּנִּחֵהוּ בְגַן עֵדֶן לְעָבְדָהּ וּלְשָׁמְרָהּ. וַיַּנִּחֵהוּ בְגַּן עֵדֶן סְתָם, דְּכוֹלָּא בְּרָזָא חָדָא.</p>"],[9514014042,"<p>וְאִי תֵימָא, בְּגַּן עֵדֶן עִילָּאָה, כַּמָּה תְּחוּמִין, וְכַמָּה שׁוּרִין מִתְתַּחֲמָן סְחוֹר סְחוֹר לֵיהּ, מִכַּמָּה מַשִּׁרְיָין עִילָּאִין וְרוּחִין קַדִּישִׁין, וְהָכָא בְּהַאי גִנְתָא דְעֵדֶן דְּאַרְעָא, לָא מִתְתַּחֲמָא הָכֵי. דְּאִי תֵימָא, הוֹאִיל וְאִיהוּ בִּדְיוֹקְנָא עִילָּאָה, אַתְקֵין לֵיהּ בְּכַמָּה רוּחִין וְנִשְׁמָתִין דְּצַדִּיקַיָּיא. אִי הָכֵי, עַד לָא הֲווֹ צַדִּיקַיָּיא בְּעָלְמָא, לָא הֲוָה בִּדְיוֹקְנָא עִילָּאָה הַאי גִנְתָא דְעֵדֶן דִּלְתַתָּא.</p>"],[9514014043,"<p>אֶלָּא, וַדַּאי בְּדוּגְמָא וּדְיוֹקְנָא עִילָּאָה אִיהוּ מִיּוֹמָא דְאִתְבְּרֵי עָלְמָא. וְעַד לָא אִתְבְּרֵי אָדָם, הֲווֹ כַּמָּה שׁוּרִין תְּחוּמִין דְּמַלְאָכִין עִילָּאִין סָחֲרִין לֵיהּ, דְּלָא הֲוָה בְּלָא נְטִירוּ, בְּגִין דִּבְכָל אִינוּן הֵיכָלִין דְּתַמָּן, אִית שׁוּלְטָנִין נָטְרִין לֵיהּ. עַד דְּאִינוּן רוּחִין אִתְכְּלִילָן לְמֵיתֵי בְּהַאי עָלְמָא, כָּל רוּחִין וְנִשְׁמָתִין דַּהֲווֹ זְמִינִין לַאֲעָלָא בְּהַאי עָלְמָא, כָּלְהוֹ הֲווֹ תַּמָּן עַד לָא אִתְבְּרֵי אָדָם.</p>"],[9514014044,"<p>וְעַד יוֹמָא עַד לָא יֵיתוּן לַאֲעָלָא בְּהַאי עָלְמָא, אִינוּן רוּחִין דְּזַמִּינִין לְאִתְיַיהֲבָא בְּהַאי עָלְמָא, כָּלְהוֹ הֲווֹ תַּמָּן. וְאִלֵּין רוּחִין וְנִשְׁמָתִין סָלְקִין וְנַחֲתִין, נָפְקוֹ מִגַּן עֵדֶן דִּלְעֵילָא, וְנָחֲתֵי בְּגַּן עֵדֶן דִּלְתַתָּא, וּמִתְלַבְּשָׁן תַּמָּן בִּלְבוּשִׁין, כְּגַוְונָא דְּגוּפֵי דְּהַאי עָלְמָא.</p>"],[9514014045,"<p>וְאִתְעַסְּקָן בְּאוֹרַיְיתָא, לְמִנְדַע וּלְאִסְתַּכָּלָא בְּהַהוּא לְבוּשָׁא בִּיקָרָא דְּמָארֵיהוֹן, כָּל חַד וְחַד, כְּמָה דְאִזְדַּמַּן לְמֶהֱוֵי בְּהַאי עָלְמָא.</p>"],[9514014046,"<p>וְהַהוּא דְּתִיקּוּנֵיהּ שַׁפִּיר וְיָאוֹת בְּהַהוּא לְבוּשָׁא, וְאִי אִשְׁתַּדְּלוּתֵיהּ כִּדְקָא יָאוֹת, סָלְקִין לֵיהּ לְעֵילָא לְקַמֵּי מַלְכָּא קַדִּישָׁא, בְּהַאי לְבוּשָׁא כְּגַוְונָא דְּהַאי עָלְמָא, וְקָאִים קַמֵּיהּ, וְחָדֵי בֵּיהּ קוּדְשָׁא בְּרִיךְ הוּא. הֲדָא הוּא דִכְתִיב, (מלכים ב ה׳:ט״ז) חַי ה' אֲשֶׁר עָמַדְתִּי לְפָנָיו. עַד לָא נָפְקֵית לְעָלְמָא.</p>"],[9514014047,"<p>אִית לְבוּשִׁין דְּמִתְלַבְּשִׁין בְּהוֹן רוּחִין, כְּגַוְונָא דְגוּפָא דְּהַאי עָלְמָא. וְאִי הַאי גּוּפָא אִזְדַּמַּן לְמִשְׁבַּק רוּחָא קַדִּישָׁא, וּלְאַסְטָאָה בָּתַר רוּחָא בִּישָׁא, הַהוּא רוּחָא קַדִּישָׁא פָּרַח מִגּוֹ הַהוּא לְבוּשָׁא, וְהַהוּא לְבוּשָׁא אִתְמְשַׁךְ לְבַר מִגַּן עֵדֶן.</p>"],[9514014048,"<p>בְּגִין דִּבְכָל יוֹמָא תִּנְיָינָא וּבְכָל יוֹמָא רְבִיעָאָה, רוּחָא בִּישָׁא דְּאֵשֶׁת זְנוּנִים, אָזְלָא סָחֲרָנֵיהּ דְּגִנְתָּא. וְאִית לְבוּשִׁין דְּאִתְמַשְׁכָן אֲבַתְרֵיהּ דְּהַהוּא רוּחָא בִּישָׁא, וְתֵיאוֹבְתֵּיהּ דְּהַהוּא רוּחָא בִּישָׁא בְּהוּ. וְכֵיוָן דְּרוּחָא קוּדְשָׁא נָחֵית וְאִתְלַבְּשָׁא בֵּיהּ, לָא אִתְיַשְּׁבָא בְּגַוֵּיהּ, וּפָרַח מִנֵּיהּ, וְסָלֵיק לְעֵילָא.</p>"],[9514014049,"<p>וְהַהוּא לְבוּשָׁא, אִתְמְשַׁךְ בָּתַר הַהוּא רוּחָא בִּישָׁא, וּמַפְקֵי לֵיהּ לְבַר, וְיָתְבָא תַּמָּן עַד דְּאָתֵי הַהוּא בַּר נָשׁ, וְאִתְלַבַּשׁ בֵּיהּ, וְנָחֵית לֵיהּ לְגֵיהִנֹּם, וְאִתְדָּן בֵּיהּ בְּכָל יוֹמָא. וְהַהוּא רוּחָא דְקוּדְשָׁא, דְּקָא פָרַח מֵהַהוּא לְבוּשָׁא, סָלֵיק לְעֵילָא, וְאָעֵל בְּחַד אוֹצָר, עַד דְּנָפֵיק מֵהַהוּא חַיָּיבָא בְּרָא, אוֹ זַרְעָא, דְּיֵיחוֹת הַהוּא רוּחָא קַדִּישָׁא, וְאִשְׁתְּלֵים בֵּיהּ כִּדְקָא יָאוֹת. וְהַהוּא חַיָּיבָא אִית לֵיהּ נַיְיחָא לְבָתַר, וּמְצַפְצְפָא וְסָלֵיק, וְאִתְלַבַּשׁ בִּלְבוּשָׁא אָחֳרָא.</p>"],[9514014050,"<p>וְקָאי אֲפִתְחָא דְּגַּן עֵדֶן, וְחָמֵי לְהַהוּא רוּחָא קַדִּישָׁא דְּאִיהוּ שָׁבַק, בְּכַמָּה יְקָר, וּבְכַמָּה נְהִירוּ, וְאַכְסִיף בֵּיהּ. וְכֵן אַשְׁגַּח בְּהַהוּא יְקָר דִּשְּׁאָר צַדִּיקַיָּיא, וְאַכְסִיף וּבְכֵי עַל עוֹבָדוֹי.</p>"],[9514014051,"<p>וְכַד בְּרָא קוּדְשָׁא בְּרִיךְ הוּא לְאָדָם הָרִאשׁוֹן, אָעֵיל לֵיהּ בְּגִנְתָא דְעֵדֶן בְּחַד לְבוּשׁ יְקָר דִּנְהוֹרָא דְּגַּן עֵדֶן, וְאִשְׁתְּלֵים בֵּיהּ בְּרוּחַ וּנְשָׁמָה קַדִּישָׁא, לְמֶהֱוֵי שְׁלִים בְּכוֹלָּא.</p>"],[9514014052,"<p>הוּא וְאִתְּתֵיהּ הָיוּ מְטַיְילִין בְּגַּן עֵדֶן, וּמַלְאֲכֵי עִילָּאֵי סַחֲרָנַיְיהוּ, מְעַנְגֵּי לוֹן בְּכַמָּה עִדּוּנִין וְעִינּוּגִין. פְּתַח לֵיהּ חַד אוֹצָר, וְאַחְמֵי לֵיהּ כָּל אִינוּן דָּרִין בַּתְרָאִין, כָּל דָּרָא וְדָרָא. וֲהֲוָה חָמֵי דְּיוֹקְנִין עִילָּאִין, וּדְיוֹקְנִין תַּתָּאִין, בִּנְהִירוּ דְּאַסְפַּקְלַרְיָא דְּנָהֲרָא עֲלַיְיהוּ.</p>"],[9514014053,"<p>נָחֲתָא אֵשֶׁת זְנוּנִים, וְהַהוּא דְּרָכֵיב וְשַׁלֵּיט עֲלָהּ, הַהוּא חֲסַר לֵב, דְּאַסְטֵי כֹּלָּא. וְחָמוֹ הַהוּא יְקָר עִילָּאָה דְּהֲוָה בֵיהּ אָדָם וְאִתְּתֵיהּ. אִתְתְּקָפַת אֵשֶׁת זְנוּנִים, בְּחֵילָא וְתוֹקְפָא דְּהַהוּא דְּשַׁלֵּיט עֲלָהּ, וּקְרֵיבַת אֵצֶל חַוָּה, וּשְׁרִיאַת לְמִפְתֵּי לָהּ בְּכַמָּה פִּתּוּיִם, וּבְכַמָּה מְתִיקוּ דְּלִישְׁנָא, עַד דְּאִתְפַּתִּיאַת. כְּדֵין, וְאִתְפַּתֵּי לְבָתַר אָדָם, וּפָרְחוּ אִינוּן לְבוּשִׁין מִינֵּיהּ, וּסְלִיקָא נִשְׁמָתָא זָהֲרָא דְּאַסְפַּקְלַרְיָא דִּלְעֵילָא מִינֵּיהּ, וְאִשְׁתָּאַר עָרוֹם מִכֹּלָּא, הוּא וְאִתְּתֵיהּ.</p>"],[9514014054,"<p>כֵיוָן דַּחֲשֵׁיב תְּשׁוּבָה, לְבָתַר דְּאִתְתָּרַךְ מִגַּן עֵדֶן, וְאִתְקַיָּים לְבַר. חָס עֲלֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, וַעֲבַד לֵיהּ לְבוּשִׁין אָחֳרָנִין, כְּגַוְונָא דְּאִצְטְרִיךְ לְאִשְׁתַּמָּשָׁא בְּהַאי עָלְמָא. וּלְבָתַר אִשְׁתַּמַּשׁ לְבַר, וְאוֹלִיד בְּנִין.</p>"],[9514014055,"<p>וְהַהוּא זָהֳרָא דְּנִשְׁמָתָא עִילָּאָה דְּפָרְחָה מִנֵּיהּ, סְלִיקָא לְעֵילָא, וַהֲוַת גְּנִיזָא בְּחַד אוֹצָר, דְּאִיהוּ גּוּף. עַד דְּאוֹלִיד בְּנִין, וּנְפַק חֲנוֹךְ לְעָלְמָא. כֵּיוָן דְּאָתָא חֲנוֹךְ, הַהוּא זָהֳרָא עִילָּאָה נִשְׁמָתָא קַדִּישָׁא נָחֲתַת בֵּיהּ, וַהֲוָה חֲנוֹךְ בְּהַהוּא רְבוּ עִילָּאָה דְּשָׁבַק מִנֵּיהּ אָדָם. הֲדָא הוּא דִכְתִיב, (בראשית ה׳:כ״ב) וַיִּתְהַלֵּךְ חֲנוֹךְ אֶת הָאֱלֹהִים וְגו'.</p>"],[9514014056,"<p>לְבָתַר, אִצְטְרִיךְ לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא לְנַטְלָא לֵיהּ מֵהַאי עָלְמָא, וּלְאִתְכְּלָלָא רוּחָא קַדִּישָׁא, מִתַּתָּא וּמִלְּעֵילָא, וְאִתְכְּלֵיל כּוֹלָּא בְּהַהוּא רוּחָא קַדִּישָׁא. וְהַהוּא רוּחָא קַדִּישָׁא אִתְכְּלֵיל מִתַּתָּא וּמִלְּעֵילָא, לְאִתְמַשְּׁכָא כָּל עַלְמָא זִינָא בָּתַר זִינֵיהּ.</p>"],[9514014057,"<p>כֵיוָן דְּאִתְכְּלֵיל, אִתְעֲבֵיד מְמַנָּא בְּהַאי עַלְמָא וּבְעַלְמָא דִלְעֵילָּא. בְּהַאי עַלְמָא, מִסִּטְרָא דְּהַהוּא כְּלִילוּ דְּאִתְכְּלֵיל מֵהַאי עָלְמָא, וּבְעַלְמָא דִלְעֵילָא, מִסְטַר דְּהַהוּא כְּלִילוּ דְּאִתְכְּלֵל מִלְּעֵילָא.</p>"],[9514014058,"<p>וּבְכָל זִמְנָא וְזִמְנָא דְּצַדִּיקֵי וַחֲסִידֵי אִית בְּעָלְמָא, אִתְחַדֵּשׁ הַהוּא כְּלִילוּ דְּאִתְכְּלֵיל מִתַּתָּא מִסִּטְרָא דַּחֲנוֹךְ, כְּדֵין אִיהוּ נַעַר, בְּרָזָא דְּחַדְתּוּתָא דְּסִיהֲרָא. וְרָזָא דָא, (משלי כ״ב:ו׳) חֲנוֹ\"ךְ לַנַּעַ\"ר עַל פִּי דַרְכּוֹ גַּם כִּי יַזְקִין לֹא יָסוּר מִמֶּנָּהּ. מַאי עַל פִּי דַּרְכּוֹ. עַל פִּי דַּרְכּוֹ דַּחֲנוֹךְ. לְמֵיזַל בְּהַהוּא דֶרֶךְ קְשׁוֹט, בְּאוֹרַח מֵישָׁר וּשְׁלִים.</p>"],[9514014059,"<p>גַּם כִּי יַזְקִין הַהוּא דִּיוּקְנָא דַּחֲנוֹךְ, מֵהַהוּא זִמְנָא דְּאִתְכְּלֵיל בְּהַהוּא קוּדְשָׁא, לָא תֵימָא דְּהָא סִיב מִכַּמָּה יוֹמִין וְאִתְעַדֵּי מֵהַהוּא אֲתַר, לָאו הָכֵי, אֶלָּא בְּכָל זִמְנָא וְזִמְנָא דְּצַדִּיקֵי וַחֲסִידֵי אִית בְּעָלְמָא, הַהוּא כְּלִילוּ דְּהַהוּא סִטְרָא אִתְחַדַּשׁ, וְאִתְחֲזֵי הַהוּא דְיוֹקְנָא מַמָּשׁ נַעַר, וְלָא אִתְעַדֵּי מִתַּמָּן. וּבְגִין הַהוּא כְּלִילוּ, יַרְתֵי תַּתָּאֵי מִטַלָּא דְּשַׁקְיוּ עִילָּאָה, וְנָחֲתָא יְרוּתָא דִרְבוּ קַדִּישָׁא לְעָלְמָא.</p>"],[9514014060,"<p>וְעַל דָּא (שיר השירים א׳:ה׳) שְׁחוֹרָה אֲנִי וְנָאוָה, שְׁחוֹרָה אֲנִי מִסִּטְרָא דִלְתַתָּא, וְנָאוָה אֲנִי מִסִּטְרָא דִּכְלִילוּ דִלְעֵילָא.</p>"],[9514014061,"<p>שְׁחוֹרָה אֲנִי, כַּד חָזֵינָא כַּמָּה חַיָּיבִין דְּמַרְגִּיזִין לְמָארֵי כוֹלָּא, וַאֲנָא זָן לוֹן בְּסִטְרָא דְהַהוּא כְּלִילוּ דִּלְתַתָּא דְּבִי. וְנָאוָה, מִסִּטְרָא דִלְעֵילָּא.</p>"],[9514014062,"<p>בְּנוֹת יְרוּשָׁלַיִם, אַף עַל גַּב דִּירוּשָׁלַיִם וּבֵי מַקְדְּשָׁא כּוֹלָּא חָדָא, בֵּי מַקְדְּשָׁא אִיהוּ יַתִּיר, בְּכַמָּה קִדּוּשִׁין, בְּכַמָּה עִילּוּיִין. בֵּי מַקְדְּשָׁא חַד, וִירוּשָׁלַיִם חַד, וּבֵית קֹדֶשׁ הַקֳּדָשִׁים לְגוֹ מִינַּיְיהוּ, דְּהוּא פְּנִימָאָה מִכּוּלְהוּ.</p>"],[9514014063,"<p>וְהַאי בְּשַׁעֲתָא דְּמַטְרוֹנִיתָא אִתְקַשְׁטַת, וּבַעְיָא לְאְתְקָרְבָא בְּבַעֲלָהּ, וְהִיא אִתְקַשְּׁטָא, אִיהִי אָמְרַת לְאוּכְלוּסֶיהָ, שְׁחוֹרָה אֲנִי, מִסִּטְרָא דִלְתַתָּא. וְנָאוָה, בִּכְלִילוּ דְּסִטְרָא דִּלְעֵילָא יַתִּיר, בְּגִין דִּכְתִיב, (דברים ד׳:ד׳) וְאַתֶּם הַדְּבֵקִים בַּה' אֱלֹהֵיכֶם. יִשְׂרָאֵל דְּבֵקִים בַּה', בְּהַהִיא תִּיקּוּנָא יַתִּיר מִכּוֹלָּא.</p>"],[9514014064,"<p>שְׁחוֹרָה אֲנִי וְנָאוָה, אָמַר לֵיהּ אֵלִיָּהוּ, ר', כָּל אִלֵּין מִלִּין אִינוּן רְשִׁימִין לְעֵילָא עַד לָא תֵיתֵי לְעַלְמָא מִן שְׁמָךְ. וְהַשְׁתָּא בְּחַדְתּוּתָא קָיְימֵי כּוּלְהוּ כְּמִלְקַדְּמִין. וּבְחוֹתָמָא דְגוּשְׁפַּנְקָא דְּמַלְכָּא כּוּלְהוּ סְתִימִין.</p>"],[9514014065,"<p>פָּתַח וְאָמַר, (בראשית א׳:י״ד) וַיֹּאמֶר אֱלֹהִים יְהִי מְאֹרֹת בִּרְקִיעַ הַשָּׁמָיִם, הַאי קְרָא אִתְּמָר. וְחַבְרַיָא אִתְעָרוֹ בֵּיהּ, וְהָכֵי אִיהוּ. אֶלָּא אַמַּאי כְּתִיב דָּא בְּיוֹמָא רְבִיעָאָה, דְּהָא מִיּוֹם שֵׁנִי אִתְחֲזֵי לְמֶהֱוֵי סִיהֲרָא חַסְרָא, דִּבְיוֹם שֵׁנִי אִתְבְּרֵי בֵיהּ גֵּיהִנֹּם, וְהוֹאִיל וְאִתְבְּרֵי בֵיהּ, סִיהֲרָא אִיהִי חֲסֵרָה בְּגִינֵיהּ, אַמַּאי אִיהוּ כְּתִיב בָּרְבִיעִי.</p>"],[9514014066,"<p>תּוּ אִית לְשָׁאֲלָא, אִי גִּרְעוֹנָא דְּסִיהֲרָא אִיהוּ בָּרְבִיעִי, הָא תָּנִינָן, דְּנִישּׂוּאֵי בְּתוּלָה לָאו אִיהוּ אֶלָּא בָּרְבִיעִי, יוֹמָא דְגִרְעוֹנָא דִּבְתוּלַת יִשְׂרָאֵל, לָא אִתְחֲזֵי לְמֶהֱוֵי בְּתוּלָה אָחֳרָא בִּשְׁלִימוּ, דְּהָא לֵית שְׁלִימוּ לְאִתְּתָא אֶלָּא בְּבַעֲלָהּ.</p>"],[9514014067,"<p>אֲבָל בְּיוֹם שֵׁנִי דְּאִתְבְּרֵי בֵיהּ גֵּיהִנֹּם, עַד לָא קָיְימָא בְּקִיּוּמָא. דְּהָא נְפַק מִיּוֹם שֵׁנִי דְּהוּא חשֶׁךְ, וּכְדֵין אִתְבְּרֵי מִנֵּיהּ. דִּכְתִיב, (איוב כ״ח:ג׳) קֵץ שָׂם לַחשֶׁךְ וְגו', וְאָרְחֵיהּ דְּהַהוּא קֵץ, לְכָל תַּכְלִית הוּא חוֹקֵר, אֵימָתַי. לְבָתַר דְּקָיְימָא בְּקִיּוּמָהּ.</p>"],[9514014068,"<p>וְלָא קָיְימַת בְּקִיּוּמָהּ, עַד דַּאַזְעֵירַת סִיהֲרָא בָּרְבִיעִי, דְּהָא סִיהֲרָא רַגְלָא רְבִיעָאָה אִיהוּ בְּכוּרְסְיָיא עִילָּאָה. וּבְגִין דְּאִיהִי יוֹמָא ד' גַּבֵּי ג' קָיְימִין אָחֳרָנִין, אִתְּמָר בִּרְבִיעָאָה עוֹבָדָא דִילָהּ, דְּהָא אַזְעֵירַת גַּרְמָהּ, וְאַחְשֵׁיךְ נְהוֹרָאָהּ. וְעַל דָּא בְּתוּלָה אִית לָהּ קִיּוּמָא בִּרְבִיעָאָה, לְאַחֲזָאָה קִיּוּמָא בְּסִיהֲרָא.</p>"],[9514014069,"<p>וְהַהוּא יוֹמָא דִּבְתוּלָה נִשַּׂאת בָּרְבִיעִי, וְאִית לָהּ קִיּוּמָא לְתַתָּא. כָּרוֹזָא קָיְימָא לְעֵילָא וְקָרֵי, (מיכה ז׳:ח׳) אַל תִּשְׂמְחִי אֹיַבְתִּי לִי כִּי נָפַלְתִּי קָמְתִּי. וְעַל דָּא, בְּיוֹמָא דִנְפִילָה קִימָה מַשְׁמַע, דִּכְתִיב כִּי נָפַלְתִּי קַמְתִּי.</p>"],[9514014070,"<p>וַיֹּאמֶר אֱלֹהִים יְהִי מְאֹרֹת, חָסֵר, בְּגִין דְּאִתְיְהֵיב דּוּכְתָּא לְסִטְרָא אָחֳרָא לְשַׁלְטָאָה. וְחַפְיָא נְהוֹרָא דְסִיהֲרָא, כְּהַאי אֱגוֹזָא, דִּקְלִיפָּה חַפְיָא עַל מוֹחָא בְּכָל סִטְרִין, וְאִתְתַּקְפַת קְלִיפָּא לְבַר, וּכְעָרְלָה עַל בְּרִית. וּבְגִין כָּךְ אִתְחַשְׁכַת נְהוֹרָא דִּלְעֵילָא.</p>"],[9514014071,"<p>וְהִיא אָמְרַת שְׁחוֹרָה אֲנִי וְנָאוָה בְּנוֹת יְרוּשָׁלַיִם, לְגַבֵּי אִינוּן אוּכְלוּסִין דְּלָא הֲווֹ בְּקִשּׁוּטָהָא בְּאִינוּן פְּנִימָאֵי. לִפְנִימָאֵי דְּקַשִּׁיטוּ לָהּ, לָא אָמְרַת הַאי. אֶלָּא כַּד נָפְקַת לְבַר, לְגַבֵּי שְׁאָר אוּכְלוּסִין אָמְרַת הַאי.</p>"],[9514014072,"<p>לִפְנִימָאֵי דְּיָדְעֵי קִישּׁוּטָהָא, וְקַשִּׁיטוּ לָהּ בְּכַמָּה קִישּׁוּטִין עִילָּאִין, הִיא אָמְרַת לוֹן יִשָּׁקֵנִי. כַּמָּה אֲנָא מִתְתַּקְּנַת יָאוֹת, לְקַבֵּל נְשִׁיקִין מִמַּלְכָּא. לְאִינוּן דִּלְבַר דְּלָא יָדְעֵי בְּקִישּׁוּטָהָא, אָמְרַת דְּאִיהִי שְׁחוֹרָה, מִסִּטְרָא דְּתַתָּאֵי, מִסִּטְרָא דִּכְלִילוּ דִּלְתַתָּא, בְּגִין דְּלָא יִשְׁגְּחוּן בְּעֵינָא בִּישָׁא לְקַטְרָגָא לְתַתָּאֵי.</p>"],[9514014073,"<p>דְּהָא לֵית לוֹן קִנְאָה אֶלָּא בְּתַתָּאֵי, כַּד תַּתָּאֵי אִינוּן בְּעִילוּיָא, אִינוּן מְקַנְאָן לוֹן יַתִּיר מִכּוֹלָּא. וְאִי תֵימָא, דְּלֵית בְּהוּ קִנְאָה. בֵּינַיְיהוּ לֵית קִנְאָה, אֲבָל עַל אָחֳרָנִין אִית קִנְאָה.</p>"],[9514014074,"<p>וּבְגִין דְּאִיהִי כְּאִימָּא עַל בְּנָהָא עַל יִשְׂרָאֵל, הַהוּא תִּיקּוּנָא שַׁפִּירָא וְיָאָה מִכּוֹלָא, דְּאִיהוּ מִסִּטְרָא דִּכְלִילוּ דִּלְתַתָּא, דִּבְגִינֵיהּ סָלְקָא לְעֵילָא, מְחַכְדָא לֵיהּ לְגַבֵּי אוּכְלוּסָהָא דִּלְבַר, בְּגִין דְּלָא יְקַנְאוּן וְלָא יְקַטְרְגוּ עֲלַיְיהוּ דְיִשְׂרָאֵל. וּבְגִין כָּךְ, אַל תִּרְאוּנִי שֶׁאֲנִי שְׁחַרְחוֹרֶת, לָא תִסְתַּכְּלוּן בְּהַאי תִּיקּוּנָא, בְּגִין שֶׁאֲנִי שְׁחַרְחוֹרֶת.</p>"],[9514014075,"<p>וּבְכָל תִּיקּוּנִין דִּילָהּ, לֵית תִּיקּוּנָא שַׁפִּירָא וְיָאָה בְּעִילוּיָיא, לְסָלְקָא לְקוּדְשָׁא, בַּר הַהוּא תִּקּוּנָא מִסִּטְרָא דִּכְלִילוּ דִּלְתַתָּא. וְכָל דָּא אֲמָרַת לְגַבֵּיהּ אוּכְלוּסָהָא, וְלָא לְגַבֵּי רְחִימָהּ. וְעַל דָּא אֲמָרַת לוֹן, שְׁחוֹרָה אֲנִי וְנָאוָה.</p>"],[9514014076,"<p>תּוּ. שְׁחוֹרָה אֲנִי מִסִּטְרָא דִלְתַתָּא, וְנָאוָה מִסִּטְרָא דִּילְכוֹן, אַתּוּן בְּנוֹת יְרוּשָׁלַיִם, הָא תִּיקּוּנָא דִילִי בְּכוֹן אִיהִי, דְּאַתּוּן אוּכְלוּסִין קַדִּישִׁין. וּבְגִין כָּךְ לָא תִסְתַּכְּלוּן בְּהַהוּא תִּיקּוּנָא דִסְטַר תַּתָּאֵי.</p>"],[9514014077,"<p>וְכֹלָּא אִיהוּ כְּאִמָּא עַל בְּנִין, דְּכַמָּה מְקַטְרְגִין אִינוּן דְּקָיְימֵי הָתָם, וְאִי יִסְתַּכְּלוּ בְּהַהוּא תִּיקּוּנָא דִּכְלִילוּ דִּלְתַתָּא, כַּמָּה אִיהוּ יָאֶה וְכַמָּה אִיהִי שַׁפִּירָא לְסָלְקָא בֵּיהּ לְעֵילָא, יֵיתוּן לְקַטְרְגָא וּלְאַדְכָּרָא חוֹבֵיהוֹן דְּיִשְׂרָאֵל. וּמְקַטְרְגֵי לְהוֹ, וּמְעַכְּבֵי לָהּ לְסָלְקָא לְעֵילָא, וּלְאִתְחַבְּרָא בְּבַעֲלָהּ.</p>"],[9514014078,"<p>וְעַל דָּא, כְּאָהֳלֵי קֵדָר, מִסִּטְרָא דְּתַתָּאֵי. כִּירִיעוֹת שְׁלֹמֹה, מִסִּטְרָא דִּילְכוֹן. וּבְגִין כָּךְ, אַל תִּרְאוּנִי שֶׁאֲנִי שְׁחַרְחוֹרֶת. לָא תִסְתַּכְּלוּן בִּי כְּלַל, בִּשְׁבִיל אִינוּן תִּיקּוּנֵי דִּילִי, דְּאִינוּן בְּסִטְרָא דְּתַתָּאֵי, דְּהָא בְּגִינֵיהוֹן נָּזֵיף בִּי שִׁמְשָׁא. וְלָאו אִיהוּ בִּלְחוֹדוֹי, אֶלָּא בְּנֵי אִמִּי נִחֲרוּ בִי, אֲבָהָן דְּעָלְמָא, כַּד חָמוֹ קַדְרוּתָא דִּילִי מִסִּטְרָא דְּתַתָּאֵי.</p>"],[9514014079,"<p>וְאִם תֹּאמַר יָאוֹת הוּא לְמֵימַר הָכֵי. אֵין. דְּהָא מִתְּרֵין סִטְרִין יָאוֹת הוּא. חַד, בְּגִין אוֹרַח שְׁלִים, דְּלָא יְקַטְרְגוּן עַל יִשְׂרָאֵל בְּנָהָא. וְחַד, דְּלָא יְעַכְּבוּן עֲלָהּ מִלְּסָלְקָא לְאִתְחַבְּרָא בְּבַעֲלָהּ, וּלְמִנְקַט נַיְיחָא. דְּהָא כֹּלָּא בְּסִיהֲרָא.</p>"],[9514014080,"<p>דִּבְזִמְנָא דְאִיהִי חַפְיָא נְהוֹרָא דְסִיהֲרָא, שִׁמְשָׁא לָא אִתְקְרַב בַּהֲדָהּ. בַּר חוּטָא חָדָא דְּחֶסֶד עִילָּאָה דְּאִתְמְשֵׁיךְ עֲלָהּ, וְהַאי כָּרֵי בְּהַהוּא קְלִיפָּה וְתָבַר חֵילָהּ, וִיהֵיב לָהּ נוֹי וְשַׁפִּירוּ. וְאִיהוּ אָמְרַת, שְׁחוֹרָה אֲנִי מִסִּטְרָא דְעָרְלָה. וְנָאוָה מִסִּטְרָא דְּהַהוּא חוּטָא דְּאִתְמְשַׁךְ עָלַי.</p>"],[9514014081,"<p>תּוּ, שְׁחוֹרָה, מִסִּטְרָא דְחשֶׁךְ עִילָּאָה כַּד אִתְתַּקַּף. כְּמָה דְאַתְּ אָמֵר, (ישעיה ס) כִּי הִנֵּה הַחשֶׁךְ יְכַסֶּה אֶרֶץ. וְנָאוָה, מִסִּטְרָא דְאוֹר קַדְמָאָה. כְּמָה דְאַתְּ אָמֵר, (מיכה ז) כִּי אֵשֵׁב בַּחשֶׁךְ, מִסִּטְרָא דִשְׂמָאלָא. ה' אוֹר לִי, מִסִּטְרָא דְּיָמִינָא.</p>"],[9514014082,"<p>(שה\"ש א) אַל תִּרְאוּנִי שֶׁאֲנִי שְׁחַרְחוֹרֶת. הִיא אָמְרַת לְאוּכְלוּסָהָא, כַּמָּה עִרְבּוּבָא דָּא לְכוֹן, דְּאַל תִּרְאוּנִי, בְּזִמְנָא דְּחַפְיָא עָלַי הַהִיא סִטְרָא, וְלָא תֵיכְלוּן לְאִתְנָהֲרָא מִנִּי, וּלְאִסְתַּכְּלָא בִּנְהוֹרִי כְּלַל.</p>"],[9514014083,"<p>בְּנֵי אִמִּי נִחֲרוּ בִי, דְּהָא אִסְתַּלַּק לְעֵילָא שִׁמְשָׁא אִתְכְּנֵישׁ, וּבְנֵי אִמִּי אִסְתְּלָקוֹ לְעֵילָא, וּבְגִין כָּךְ שָׁלְטָא עָרְלָה, וְאַתּוּן אַל תִּרְאוּנִי, לָא תֵיכְלוּן לְמֶחֱמֵי וּלְאִסְתַּכָּלָא בִּנְהוֹרִי כְּלָל. שָׂמוּנִי נוֹטֵרָה אֶת הַכְּרָמִים, דְּהוֹאִיל וְהָעָרְלָה לְגַבֵּי, וְהִיא יָנְקָא מִמֶּנִּי לְמֵיהַב לְאוּכְלֻסִין דִּילָהּ, וּלְאִינוּן מַשִּׁרְיָין דִּשְּׁאָר עַמִּין. כַּרְמִי שֶׁלִּי לֹא נָטָרְתִּי, אִלֵּין אוּכְלֻסִּין קַדִּישִׁין דִּילִי, דְּלָא יָכֵילְנָא בְּהַהוּא סִטְרָא לְמֵיזַן לוֹן.</p>"],[9514014084,"<p>הַשְׁתָּא אִית לְאִסְתַּכָּלָא. מַאן דְּאִתְעַסֵּק בְּשִׁיר, אֵיךְ אָמַר תַּרְעוֹמִין וְקִנְטוּרִין, בְּשֵׁירוּתָא דְתוּשְׁבַּחְתָּא. אֶלָּא וַדַּאי טַעְמָא קַדְמָאָה אִיהוּ רָזָא דְתוּשְׁבַּחְתָּא, וְכֹלָּא אִיהוּ בִּקְרָא. עַל פּוּמָא דְּאֵלִיָּהוּ אִתְגְּזַר.</p>"],[9514014085,"<p>(שיר השירים א׳:ה׳) שְׁחוֹרָה אֲנִי וְנָאוָה וְגו', כְּתִיב, (תהילים מ״ח:ג׳) יְפֵה נוֹף מְשׂוֹשׂ כָּל הָאָרֶץ וְגו', יְפֵה נוֹף, שַׁפִּירוּ דְּנוֹפָא, דְּאִילָנָא דְחַיֵּי, בְּרָזָא דִּכְלִילוּ דְּכָל אַתְוָון.</p>"],[9514014086,"<p>דְּכַד אַתְוָון מִתְחַקְּקָן, וְאִתְרְשִׁימוּ בְּאִילָנָא דְחַיֵּי, סָלְקָן אַתְוָון כּוּלְהוּ, וְאִתְרַשְׁמוּ בְּחַד אָת, וְאִתְכְּלִילוּ בְּהַהוּא אָת. וְכֵיון דְּאִתְכְּלִילוּ בֵּיהּ, כּוּלְהוּ אַפֵּיק לוֹן לְבָתַר.</p>"],[9514014087,"<p>וְהַהוּא אָת, אִיהוּ שִׁבְחָא דְּכוּלְהוּ. הַאי אָת, לָא עָבִיד רְשִׁימוּ אָחֳרָא, לְבַר מִינָהּ, בְּגִין דְּאִיהִי אִתְכְּלִילַת בְּגַוָּהּ, וְלָא עָבִיד רְשִׁימוּ בַּר טְמִירוּ וּגְנִיזוּ. וּמַאן אִיהִי. אָת י'.</p>"],[9514014088,"<p>דְּאִיהִי נְקוּדָא חָדָא, בְּלָא רְשִׁימוּ אָחֳרָא. כָּל אַתְוָון אִית לוֹן רְשִׁימוּ אָחֳרָא, עַל גַּבֵּי אַתְרֵיהּ דִּכְתִיב תַּמָּן, וְהַהוּא רְשִׁימוּ, אִשְׁתָּאַר בְּחִוָּורוֹ דְּהַהוּא אָת, בַּר י' דְּאִיהִי נְקוּדָה חָדָא, בְּלָא חִוָּורוֹ דַּאֲתַר אָחֳרָא.</p>"],[9514014089,"<p>וְהַאי נְקוּדָה, יָרְתָא כַּלָּה דָּא בְּתִיקוּנָהָא. וְאִיהִי נְקוּדָה חָדָא גּוֹ חֵילָהָא וּמַשִּׁרְיָיאָה, וְאִתְקְרֵי י', נְקוּדָה חָדָא.</p>"],[9514014090,"<p>וְכֵיוָן דְּסָלְקָא בִּשְׁמָא דָא, וְאִתְקְרֵי י', הָא אִתְקַשְׁטַת בְּתִיקּוּנָא עִילָּאָה, וְאָמְרַת שְׁחוֹרָה אֲנִי, לֵית לִי אַתְרָא לְאִתְכְּלָלָא אָחֳרָנִין בְּגַוָּואי בְּזִמְנָא דָא. דְּהָא בִּשְׁמָא דְּי' אִתְקָרֵינָא, לְסָלְקָא לְעֵילָא.</p>"],[9514014091,"<p>וְעַל דָּא, שְׁחוֹרָה אֲנִי וְנָאוָה, כְּתִיקּוּנָא דִלְעֵילָא, רֵישׁ כָּל דַּרְגִּין. בְּהַאי אִתְכְּלֵילְנָא בְּגֵוִוי לְסָלְקָא לְעֵילָא, וְלֵית לִי הַשְׁתָּא אֲתַר פְּשִׁיטוּ אָחֳרָא לְאִתְגַּלְּיָא. הָא אִתְכַּסֵּינָא בְּלָא חֵיזוּ אָחֳרָא, בְּרָזָא דִנְקוּדָה חָדָא, לְסָלְקָא נְקוּדָה לִנְקוּדָה.</p>"],[9514014092,"<p>וּבְגִין דַּאֲנָא שְׁחוֹרָה בְּלָא פְּשִׁיטוּ דַּאֲתַר אָחֳרָא, אַל תִּרְאוּנִי, לֵית לְכוֹ רְשׁוּ לְמֶחֱזֵי לִי כְּלַל, לָא תֵיכְלוּן לְמֶחֱזֵי בִּי, דְּהָא אֲנָא בִּטְמִירוּ וּגְנִיזוּ, בְּרָזָא דְּחַד נְקוּדָה, דְּלָא אִתְיְדַע בָּהּ אֲתַר כְּלָל.</p>"],[9514014093,"<p>דְּכָל אַתְוָון אִית לוֹן דּוּכְתָּא אָחֳרָא בְּחִוָּורוֹ, בַּר י', דְּלֵית לָהּ פְּשִׁיטוּ לְאִתְחֲזָאָה כְּלָל. וְדָא הִיא אַל תִּרְאוּנִי שֶׁאֲנִי שְׁחַרְחוֹרֶת, בְּכָל סִטְרִין לֵית בִּי אֲתַר חִוָּורוֹ, וְדוּכְתָּא אָחֳרָא לְאִתְכְּלָלָא בִּי אָחֳרָנִין. כְּאָהֳלֵי קֵדָר, דִּטְמִירִין גּוֹ טִינָרֵי, וְלָא נָפְקֵי לְבַר. כָּךְ הוּא יוֹנָתִי תַמָּתִי בְּחַגְוֵי הַסֶּלַע, נְקוּדָה גּוֹ אוּכְלוּסָהָא.</p>"],[9514014094,"<p>כִירִיעוֹת שְׁלֹמֹה, יְרִיעוֹת שְׁלמֹה אִינוּן כְּלִילָן כַּחֲדָא בְּאָת חַד, וּבְהַהוּא אָת לָא אִתְחֲזוּן בֵּיהּ כְּלָל. וְאִינוּן שִׁית, וְאִינוּן חָמֵשׁ. וְרָזָא דָא, חֲמֵשׁ הַיְרִיעוֹת תִּהְיֶיןָֹ חוֹבְרוֹת, בְּלָא פֵּירוּדָא כְּלָל. וְחַד דְּכָלֵיל לוֹן, דְּאִיהוּ טָמִיר וְגָנִיז. וְאִיהוּ אָת חַד, דְּלֵית בֵּיהּ חִיוָּרוֹ דַּאֲתַר אָחֳרָא.</p>"],[9514014095,"<p>וְהָא אִיהוּ אָת ו', דְּלֵית בָּהּ אֲתַר לְאִתְחֲזָאָה בָּהּ כְּלָלָא אָחֳרָא, אֶלָּא כֹּלָּא סְתִים בְּגַוֵּיהּ. כָּךְ הַאי נְקוּדָה, הִיא בְּלָא חִוָּורוֹ דַּאֲתַר אָחֳרָא, וְכֹלָּא כָּלֵיל בְּגַוֵּיהּ. וּמַאן כָּלֵיל בְּגַוֵּיהּ. שִׁית סִטְרִין אָחֳרָנִין.</p>"],[9514014096,"<p>כְאָהֳלֵי קֵדָר, דָּא אָת אָחֳרָא, דְּאִית בָּהּ כָּל דַּרְגִּין אָחֳרָנִין, דְּלֵית לָהּ חִוָּורוֹ דַּאֲתַר אָחֳרָא, וְכוֹלָּא כָּלֵיל בְּגַוֵּיהּ, וְדָא אִיהוּ אָת ז'.</p>"],[9514014097,"<p>אָת דָּא, אִיהִי אָהֳלֵי קֵדָר. יְרִיעוֹת שְׁלֹמֹה, דָּא אָת ו'. וְעַל דָּא ז' אִיהוּ, דִּבְנֵי קֵדָר כּוּלְהוּ מַגִּיחֵי קְרָבָא תָּדִיר, מִכָּל שְׁאָר אוּמִין וּזְמִינִין לַאֲגָחָא קְרָבָא בְּסוֹף יוֹמִין, בְּכָל אוּמִין דְּעָלְמָא.</p>"],[9514014098,"<p>וְעַל דָּא, שְׁחוֹרָה אֲנִי, דָּא יוּ\"ד. כְּמָה דְּאִתְּמָר, דְּלֵית בֵּיהּ חִוָּורָא דַּאֲתַר אָחֳרָא, וְכוֹלָּא כָּלֵיל בְּגַוֵּיהּ. כְּאָהֳלֵי קֵדָר, דָּא אָת ז', דְּהָכֵי אִיהוּ, דְּלֵית בֵּיהּ חִוָּורָא דַּאֲתַר אָחֳרָא, וְכוֹלָּא כָּלֵיל בְּגַוֵּיהּ. כִּירִיעוֹת שְׁלֹמֹה, אָת ו', דְּלֵית בֵּיהּ חִוָּורוֹ דַּאֲתַר אָחֳרָא, וְכוֹלָּא כָּלֵיל בְּגַוֵּיהּ.</p>"],[9514014099,"<p>וְעִם כָּל דָּא, אַף עַל גַּב דִּתְרֵין אִלֵּין, אָהֳלֵי קֵדָר וִירִיעוֹת שְׁלמֹה, אִינוּן סְתִימִין, וְלֵית בְּהוּ חִוָּורוֹ אָחֳרָא, לֵית סָתִים וְגָנִיז כְּאָת י'. וּבְגִין כָּךְ, אַל תִּרְאוּנִי, כְּמָא דְאִתְּמָר.</p>"],[9514014100,"<p>וְאִי תֵימָא, אָת ן'. הַאי, נָפְקָא מֵאָת ו', דְּאִתְפְּשַׁט מִכְּלָלוֹ דְּכַר וְנוּקְבָא. וּבְגִין דְּנָפְקַת מֵאָת ו', לָאו אִיהוּ חוּשְׁבְּנָא בְּגַרְמָהּ.</p>"],[9514014101,"<p>וְעַל דָּא, תְּרֵין אִלֵּין, אִינוּן שְׁחוֹרוֹת בְּגַרְמַיְיהוּ, וּכְלָלָא דְּאִינוּן פְּנִימָאִין, קְרֵבִין דִּלְהוֹן. וְלֵית בְּהוּ חִוָּורוֹ דַּאֲתַר אָחֳרָא, לְאִתְחֲזָאָה. אָהֳלֵי קֵדָר וִירִיעוֹת שְׁלֹמֹה, וּבְכָל אַתְוָון, לֵית בְּהוּ כְּאָת י', דְּאִיהִי סָתִים מִכָּל סִטְרוֹי.</p>"],[9514014102,"<p>(תהילים מ״ח:ג׳) יְפֵה נוֹף, דָּא נוֹפָא דְּאִילָנָא דְחַיֵּי, דְּנָפֵיק מֵאָת ו'. וּלְבָתַר אִתְכְּלֵיל בְּאָת י'. כֵּיוָן דַּאֲרֵיק כָּל אִינוּן בִּרְכָאן בְּחִבּוּרָא חָדָא, אִתְכְּלֵיל בְּאָת י', וַהֲוֵי כּוֹלָּא נְקוּדָה חָדָא. וְדָא אִיהוּ מְשׂוֹשׂ כָּל הָאָרֶץ. לְבָתַר דְּאִתְכְּלֵיל בְּהַהוּא נְקוּדָה, כֹּלָּא אִיהוּ הַר צִיּוֹן. כֹּלָּא נְקוּדָה חָדָא אִיהִי.</p>"],[9514014103,"<p>אַף עַל גַּב דְּאִיהִי זְעֵירָא, וְלָא אִתְחֲזִיאַת בָּהּ פְּשִׁיטוּ אָחֳרָא, וְחִוָּורוֹ, לְאִתְכְּלָלָא בָּהּ אָחֳרָנִין, קִרְיַת מֶלֶךְ רַב אִיהִי. וְהַהוּא מֶלֶךְ רַב, עִילָּאָה וְשַׁלִּיטָא בְּכָל אוּכְלֻסִּין דִּילֵיהּ, כּוּלְהוֹן עָאלִין גּוֹ הַאי נְקוּדָה דְּאִיהִי י'.</p>"],[9514014104,"<p>וְהָא אִיהִי (קהלת ט׳:י״ד) עִיר קְטַנָּה וַאֲנָשִׁים בָּהּ מְעַט, דְּלֵית בָּהּ חִוָּורוֹ דַּאֲתַר אָחֳרָא לְאִתְכְּלָלָא וּלְאַעֲלָא אָחֳרָנִין בְּגַוָּוהּ. וּבָא אֵלֶיהָ מֶלֶךְ גָּדוֹל, דָּא אָת ל', דְּאִיהִי מִגְדְּלָא דְּפָרַח בַּאֲוִירָא דַכְיָא דְּאִתְפַּס. בְּגִין דְּאִית אֲוִירָא אָחֳרָא דְּלָא אִתְפַּס כְּלַל, וְלָא יְדִיעַ.</p>"],[9514014105,"<p>הַאי, אַף עַל גַּב דְּאָת דָּא מֶלֶךְ גָּדוֹל עַל כָּל אַתְוָון, עַיִּיל בְּגַוָּוהּ, וְאִיהִי אָת זְעֵירָא שְׁחוֹרָה דְּלֵית בָּהּ חִוָּורוֹ דַּאֲתַר אָחֳרָא. כָּנֵישׁ לֵיהּ בְּגַוָּהּ, וְכָלַל לֵיהּ. וְסָבַב אוֹתָהּ בְּאָת חַד דְּאִיהִי ט'. ט' ל' הֲוַת, וּבְהַהוּא סִיבוּבָא דְּקָא מְסַבַּב סְחוֹר סְחוֹר, אִתְעֲבֵיד בְּעִגּוּלָא ט'.</p>"],[9514014106,"<p>וּבָנָה עָלֶיהָ מְצוֹדִים גְּדוֹלִים, לְאִתָּפְשָׂא מַאן דְּבָעְיָא בִּתְפִיסוּ דִילָהּ. כְּמָה דְאַתְּ אָמֵר, אֲשֶׁר הִיא מְצוֹדִים וַחֲרָמִים. וּבָנָה עָלֶיהָ, עָלֶיהָ וַדַּאי, בְּגִינָהּ, בְּגִין יְקָרָהּ, לְמֵיהַב לָהּ שָׁלְטָנוּתָא עַל בְּנֵי חַיָּיבֵי כַּמָּה מִיתוֹת בֵּית דִּין, כַּמָּה קְנָסִין, כַּמָּה עוֹנָשִׁין, מַאן דְיֵעוֹל לְגַבֵּי הַהוּא נְקוּדָה, קְנָסָא יְתֵירָא קָנֵיס, עַל נְקוּדָה דָא.</p>"],[9514014107,"<p>בְּגִין נְקוּדָה דָא, אַפְסֵיד שְׁלֹמֹה מַלְכָּא מַלְכוּתֵיהּ, וְאִתְקְרַע, וְאִתְיְהַב לְאָחֳרָנִין. וְאַף עַל גַּב דְּאִיהִי זְעֵירָא מִכָּל אַתְוָון, וְאִיהִי נְקוּדָה חָדָא בִּלְחוֹדָאָה.</p>"],[9514014108,"<p>דְּהָא בְּהַהִיא שַׁעֲתָא סָלֵיק י' קַמֵּי מַלְכָּא קַדִּישָׁא, אָמְרָה קַמֵּיהּ, הָא שְׁלמֹה מַלְכָּא עֲבַד לִי פַּלְסְתֵּר. מַאן י'. י' (דברים י״ז:י״ז) דְּלֹא יַ\"רְבֶּה לוֹ סוּסִים. וְלֹא יַ\"רְבֶּה לוֹ נָשִׁים. וְכֶסֶף וְזָהָב לֹא יַ\"רְבֶּה לוֹ מְאֹד. אֲמַר לָהּ קוּדְשָׁא בְּרִיךְ הוּא, שְׁלֹמֹה יִתְאֲבֵד, וְאֶלֶף אָחֳרָנִין, וְאַתְּ לָא תִתְעַקַּר מִגּוֹ אַתְרָךְ.</p>"],[9514014109,"<p>בְּהַהִיא שַׁעֲתָא, נָפְקַת קוּף מִקַּמֵּי קוּדְשָׁא בְּרִיךְ הוּא, וְתָרֵיךְ לֵיהּ מִמַּלְכוּתֵיהּ, וַאֲזַל הֶדְיוֹטָא בְּעָלְמָא, וְהוּא אַכְרֵיז וַאֲמַר בְּאָת ק', (קהלת א׳:י״ב) אֲנִי קֹהֶלֶת הָיִיתִי מֶלֶךְ עַל יִשְׂרָאֵל בִּירוּשָׁלָיִם.</p>"],[9514014110,"<p>וְעַל דָּא (שם ט) וּבָנָה עָלֶי\"הָ מְצוֹדִים גְּדוֹלִים, לְאִתָּפְסָא בְּגִינָ\"הּ בְּנֵי עָלְמָא בְּחוֹבֵיהוֹן. וְאִם לִשְׁלֹמֹה מַלְכָּא הֲוָה הָכֵי, וְאִתְפַּס בְּאִינוּן מְצוֹדִין, כּ\"ש וְכָל שֶׁכֵּן שְׁאָר בְּנֵי נָשָׁא. וּבְגִין כָּךְ אִיהִי אָמְרַת, שְׁחוֹרָה אֲנִי, כְּמָה דְאִתְּמָר. וְעַל דָּא, אַל תִּרְאוּנִי, לָא תֵיכְלוּן לְאִסְתַּכָּלָא בִּי וּלְעָאֳלָא בְּגַוָּואי, בְּגִין שֶׁאֲנִי שְׁחַרְחוֹרֶת, כֹּלָּא כְּמָה דְאִתְּמָר.</p>"],[9514014111,"<p>(שיר השירים א׳:ו׳) בְּנֵי אִמִּי נִחֲרוּ בִי, אָעִיקוּ לִי בְּהַאי נְקוּדָה, דְּלָא לְאַעֳלָא אָחֳרָא בְּגַוָּואי. אִינוּן אִתְפְּשִׁיטוּ וְאִתְתַּקְּנוּ בְּתִיקּוּנֵיהוֹן כִּדְקָא יָאוֹת. אִתְתַּקָּנוּ וְאִתְפַּשְׁטוּ בְּאָת ו', דְּנָפְקָא מִגּוֹ נְקוּדָּה עִילָּאָה, וְאִתְתַּקָּנוּ בְּתִקּוּנֵיהוֹן כִּדְקָא יָאוֹת. אִתְתַּקָּנוּ וְאִתְפַּשְּׁטוּ וְאִתְגְּלִיפוּ בְּאָת ש', דְּנָפְקָא מִתַּמָּן.</p>"],[9514014112,"<p>אִתְתַּקָּנוּ וְאִתְגְּלִיפוּ וְאִתְפַּשְּׁטוּ, בְּאָת ן'. אִתְתַּקָּנוּ וְאִתְגְּלִיפוּ וְאִתְפַּשְּׁטוּ בְּאָת צ'. וַאֲנָא לֵית לִי פְּשִׁיטוּ לְסִטְרָא בְּעָלְמָא, וְלָא שַׁבְקוּ לִי אֲתַר אָחֳרָא לְאַכְלָלָא לְכוֹ.</p>"],[9514014113,"<p>שָׂמוּנִי נוֹטֵרָה אֶת הַכְּרָמִים, דַּאֲנָא נְקוּדָה חַד, דְּנָטֵיר לִשְׁאָר אַתְוָון דְּאִתְנְקִידוּ בִי, וְאַנְטַרְנָא לוֹן, דְּהָא אֲנָא אָזֵיל בְּכָל אַתְוָון, וְאִתְפַּשְׁטוּ בִי, כּוּלְהוּ בִּי אִתְפַּשְּׁטוּ.</p>"],[9514014114,"<p>כַרְמִי שֶׁלִּי לֹא נָטָרְתִּי, דַּאֲנָא לֵית לִי פְּשִׁיטוּ, וְלָא עֲנָפָא, לְסִטְרָא דָא, וְלָא לְסִטְרָא דָא. דְּאִלְמָלֵי פָּשִׁיטְנָא עַנְפִין, כָּלֵילְנָא לְכוֹן בְּגַוָּאי. אֲבָל לֹא נָטָרְתִּי, לָא אוֹשִׁיטְנָא עַנְפִין לְסִטְרָא בְּעָלְמָא. נָטָרְתִּי, נָטַר עַנְפָא.</p>"],[9514014115,"<p>אָת דָּא, בֵּית יִשְׂרָאֵל אִיהִי, דְּיָרֵית לָהּ מִגּוֹ נְקוּדָה עִילָּאָה. דִּכְתִיב, (ישעיהו ה׳:ז׳) כִּי כֶּרֶם ה' צְבָאוֹת בֵּית יִשְׂרָאֵל. וְעַל דָּא, כַּרְמִי שֶׁלִּי לֹא נָטָרְתִּי, דְּלָא אוֹשִׁיטְנָא עַנְפִין לְסִטְרָא בְּעַלְמָא, לְאַחֲדָא לְכוֹ.</p>"],[9514014116,"<p>וַאֲנָא נוֹטֵרָה אֶת הַכְּרָמִים, מְשַׁלַּח וּפַשֵּׁיט עַנְפִין לְכָל אַתְוָון, וּמִגַּוָּואי אִתְתַּקָּנוֹ. וְאוֹת שֶׁלִּי לָא אוֹשִׁיטְנָא בֵּיהּ עַנְפִין, וּבְגִין כָּךְ אַל תִּרְאוּנִי, לָא תוּכְלוּן לְאִסְתַּכָּלָא בִּי, וּלְאַעֳלָא בְּגַוָּאי.</p>"],[9514014117,"<p>וְכָל דָּא, בְּגִין דְּאִיהִי ה\"א אִתְכְּלִילָא בְּיִיחוּדָהָא לְסַלְקָא לְעֵילָא, וְלָא אִצְטְרִיכָא לְאַעֳלָא בְּגַוָּהּ.</p>"],[9514014118,"<p>בַּר אִיהִי בְּיִיחוּדָא דִילָהּ, נְקוּדָה פְּנִימָאָה גוֹ אוּכְלוּסָהָא. וְכָל אוּכְלוּסָהָא בְּתֵיאוּבְתָּא לְאִתְקְרָבָא לְגַבָּהּ. וְכֵיוָן דְּאִיהִי אָמְרַת דָּא, אִיהִי סָלְקָא וְאִתְטַמְּרָא מִנַּיְיהוּ, לְאִשְׁתַּעְשְׁעָא לְעֵילָא. כֵּיוָן דְּסָלְקָא, וְשָׁבְקוּ לָהּ אוּכְלוּסָהָא.</p>"],[9514014119,"<p>דְּהָא דָּא קַשְׁיָא לָהּ, בְּגִין דְּלָא שָׁבְקוּ לָהּ אוּכְלוּסָהָא, וַאֲפִילּוּ רִגְעָא חָדָא. וְכַד אִיהִי בְּאָת דָּא, אִתְכְּלִילַת בְּגַוָּהּ בְּיִיחוּדָא, וַאֲמָרַת דָּא, כְּדֵין אוּכְלוּסָהָא שַׁבְקִין לָהּ בְּעַל כָּרְחַיְיהוּ, וְאִיהוּ אִשְׁתְּמִיטַת מִנַּיְיהוּ, וְסָלְקָא לְעֵילָא. כֵּיוָן דְּסָלְקָא לְעֵילָא, אָמְרַת לְגַבֵּי רְחִימָהּ, (שיר השירים א׳:ז׳) הַגִּידָה לִי שֶׁאָהֲבָה נַפְשִׁי וְגו'.</p>"],[9514014120,"<p>חָדֵי רַבִּי שִׁמְעוֹן, אֲמַר אִי נִיחָא לֵיהּ לְמַר, מַאן דְּשָׁרֵי מִלָּה, לִיסַיֵּים. דְּהוֹאִיל וְחֶדְוָה דִילִי בְּמִלִּין דְּמַר, בְּמַאי דְּשָׁרֵי לִיסַיֵּים. אָמַר לֵיהּ, ר', מִלֶּיךָ דְּמִתְחַקְּקִין וּמִתְגַּלְּפִין לְעֵילָא, הֱוֵי אֵימָא בְּקַדְמִיתָא. מִילַי דְּמִתְחַקְּקִין וּמִתְגַּלְּפִין לְתַתָּא, אֵימָא לְבָתַר, וְאַתְּ פְּתַח פּוּמָךְ וְיִנְהֲרוּן מִילָךְ.</p>"],[9514014121,"<p>פְּתַח רַבִּי שִׁמְעוֹן וַאֲמַר, הַגִּידָה לִי שֶׁאָהֲבָה נַפְשִׁי וְגו'. הָא אִתְעַרְנָא, בְּכָל אֲתַר דִּכְתִיב הַגֵּד, הִגִּיד, וַיַּגֵּד, כּוּלְהוּ מִלֵּי דְּאַגָּדָה אִינוּן, וְאִית לְאִסְתַּכָּלָא בְּהוּ. וְהָכָא כְּתִיב הַגִּידָה לִי, רָזָא דְּחָכְמְתָא אִיהוּ.</p>"],[9514014122,"<p>וְאִם תֹּאמַר הָא סַגִּיאִין אִינוּן בְּאוֹרַיְיתָא, דְּלֵית בְּהוּ רָזָא דְחָכְמְתָא, כְּגַוְונָא דִכְתִיב, (שמואל א י׳:ט״ז) הַגֵּד הִגִּיד לָנוּ כִּי נִמְצְאוּ הָאֲתוֹנוֹת וְאֶת דְּבַר הַמְּלוּכָה לֹא הִגִּיד לוֹ. אֲפִילּוּ הַנֵּי בְּרָזָא דְחָכְמְתָא הֲווֹ, דְּאִלְּמָלֵא הֲווֹ בְּרָזָא דְחָכְמְתָא, מְנָא יָדַע שְׁמוּאֵל אִי אִשְׁתַּכְּחָן אִי לָא. דְּבַר הַמְּלוּכָה, חָכְמְתָא עִילָּאָה הִיא לְעֵילָא וְתַתָּא, רָזִין דְּקוּדְשָׁא בְּרִיךְ הוּא.</p>"],[9514014123,"<p>הַגִּידָה לִי שֶׁאָהֲבָה נַפְשִׁי. כְּתִיב, (בראשית א׳:ט׳) וַיֹּאמֶר אֱלֹהִים יִקָּווּ הַמַּיִם מִתַּחַת הַשָּׁמַיִם וכו', כַּד סָלֵיק בִּרְעוּתָא דְּקוּדְשָׁא בְּרִיךְ הוּא לְמִבְרָא אַרְעָא, נְטֵיל מִתַּלְגָא דִּתְחוֹת כּוּרְסְיָיא יְקָרָא, וַאֲרָמֵיהּ לְגוֹ מַיָא, וְאַקְפְּיֵיהּ תַּמָּן, וַהֲוַת אַרְעָא גְלִידָא גּוֹ מַיָא, וְאִתְטַמְּרַת תַּמָּן, וַהֲוַת גּוֹ חֲשׁוֹכָא בְּקַדְרָא.</p>"],[9514014124,"<p>בְּשַׁעֲתָא דַּאֲמַר יִקָּווּ הַמַּיִם מִתַּחַת הַשָּׁמַיִם אֶל מָקוֹם אֶחָד, דְּהָא אִינוּן מְקוֹרִין אוֹשִׁיטוּ וְאַנְגִידוּ מַיִין מֵעֵילָא, לַאֲתַר דִּיסוֹדָא דְמַלְכָּא עִילָּאָה. כְּדֵין אַרְעָא דַּהֲוַות טְמִירָא גוֹ תַּתָּא, אִתְקַשְּׁטַת וְאִתְתַּקָּנַת לְאִתְחֲזָאָה. דְּאִי לָא אִתְתַּקַּן הַאי אֲתַר, אַרְעָא לָא אִתְחֲזִיאַת. דְּהַאי אֲתַר לָא אִתְתַּקַּן בִּנְגִידוּ דְמַיִּין עִילָּאִין, בַּר לְמִיתַּן לְנוּקְבָא.</p>"],[9514014125,"<p>וְכַד אִיהוּ אִתְתַּקַּן לְגַבָּהּ, כְּדֵין וְתֵרָאֶה הַיַּבָּשָׁה, וְתֵרָאֶה בְּקַשִּׁיטָהָא. מִכָּאן דְּלָא תִתְחֲזֵי אִתְּתָא בְּקוֹשִׁיטָהָא וּבְתִיקוּנָהָא, בַּר כַּד אִיהִי בְּבַעֲלָהּ, אֲזַי תֵרָאֶה וְתִתְתַּקַּן כִּדְקָא יָאוֹת.</p>"],[9514014126,"<p>כְדֵין (שם) וַיִּקְרָא אֱלֹהִים לַיַּבָּשָׁה אֶרֶץ, יַבָּשָׁה הֲוָה בְּקַדְמִיתָא, דְּלֵית לָהּ חֵיזוּ וּדְיוֹקְנָא לְמֶעְבַּד פֵּירִין וְאִיבִּין, כֵּיוָן דְּאִתְתַּקָּנַת בְּבַעֲלָהּ, מִיָּד נִקְרֵאת אֶרֶץ, אֲתַר מִתְתַּקְּנַת לְמֶעְבַּד פֵּירֵי וְאִיבִּין.</p>"],[9514014127,"<p>בְּשַׁעֲתָא דַּאֲמַר יִקָּווּ הַמַּיִם מִתַּחַת הַשָּׁמַיִם אֶל מָקוֹם אֶחָד וַדַּאי, כְּדֵין כָּל חֶדְוָה וְכָל חֵידוּ וְכָל תִּיקּוּנָא אִתְתַּקַּן. כֵּיוָן דְּכָל תִּיקּוּנָא אִתְתַּקַּן, כְּדֵין סָלְקָא לְגַבֵי דְכוּרָא, וְאִיהִי אָמְרַת הַגִּידָה לִי שֶׁאָהֲבָה נַפְשִׁי אֵיכָה תִרְעֶה אֵיכָה תַרְבִּיץ בַּצָּהֳרָיִם. אֵיכָה אֵיכָה תְּרֵין זִמְנִין, רֶמֶז עַל שְׁנֵי חֻרְבָּנִין, חֻרְבַּן בַּיִת רִאשׁוֹן וְחֻרְבַּן בַּיִת שֵׁנִי.</p>"],[9514014128,"<p>וּבְגִין כָּךְ, אֵיכָה תִרְעֶה, בְּחֻרְבַּן קַדְמָאָה. אֵיכָה תַרְבִּיץ, בְּחֻרְבַּן תִּנְיָינָא. דְּהָא חֶדְוָה דִילָן טַב וְיָאוֹת, וּבְגוֹ חֶדְוָה דָא אִית לִי לְבָכְיָיא עַל תְּרֵי מִקְדְּשֵׁי, חַד מִקְדְּשָׁא עִלָּאָה, וְחַד מִקְדְּשָׁא תַּתָּאָה.</p>"],[9514014129,"<p>(שיר השירים א׳:ז׳) שַׁלָּמָה אֶהְיֶה כְּעֹטְיָה, אִי לָאו הַנֵּי תְּרֵי זִמְנֵי דַּאֲנָא זְמִינָא לְמִקְרֵי אֵיכָה. שַׁלָּמָה אֶהְיֶה, בִּשְׁלָם אֱהֵא בְּלָא גָלוּתָא כְּלָל. בִּשְׁלָם עַל בָּנַי לְתַתָּא. כְּעֹטְיָה, כְּמָה דְאַתְּ אָמֵר, (שמואל א כ״ח:י״ד) וְהוּא עֹטֶה מְעִיל. אֱהֵא אִתְעַטְפָא בְּעִיטוּפָא דְקוּדְשָׁא עִילָּאָה, דְּאִיהוּ שְׁמָא קַדִּישָׁא י\"ה. שַׁלָּמָה אֶהְיֶה, בִּשְׁלָם אֱהֵא בְּכָל שְׁלִימוּ דִּלְעֵילָא. כְּעֹטְיָה: כְּעוֹטֶה יָ\"ה, לְמֶהֱוֵי בְּכָל שְׁלִימוּ עִילָּאָה. עַל עֶדְרֵי חֲבֵרֶיךָ, אִלֵּין דַּרְגִּין קַדִּישִׁין דְּכוּלְהוּ, כְּגַוְונָא דִלְעֵילָא.</p>"],[9514014130,"<p>כְדֵין אִיהוּ אָתֵיב לְגַבָּהּ, וְשָׁרֵי מִן מִלָּה דָא, דְּאִיהוּ בַּתְרָאָה מִן הַאי שִׁבְחָא, וְאָמַר, אִם לֹא תֵדְעִי לָךְ הַיָּפָה בַּנָּשִׁים, אִם אַתְּ לָא יָדַעְתְּ תְּרֵין אֵיכָה אֵיכָה לְמַאי נִינְהוּ. צְאִי לָךְ, פּוּקִי וַחֲמִי בְּעִקְבֵי הַצֹּאן, עַל מָה יְהֵא חוּרְבַּן בַּיִת רִאשׁוֹן וּבַיִת שֵׁנִי. תִּנְדַע עַל מַה. עַל מִשְׁכְּנוֹת הָרוֹעִים, דְּהָא זְמִינִין לְבַטָלָא אוֹרַיְיתָא, בְּבַיִת רִאשׁוֹן וּבְבַיִת שֵׁנִי.</p>"],[9514014131,"<p>הַגִּידָה לִי שֶׁאָהֲבָה נַפְשִׁי, אַתְּ רְחִימָא דְנַפְשָׁאי, הַגִּידָה לִי בְּרָזָא דְחָכְמְתָא, אֵיכָה תִרְעֶה, אִי כְּדֵין תִּרְעִי אַנְתְּ לְקִבְלִי, לְמֶהֱוֵי אֲנָא גַבָּךְ בְּחֶדְוָה, וּלְמֶהֱוֵי עִמָּךְ. דְּהָא בְּזִמְנָא דֶּאֱהֵא עִמָּךְ, שַׁלָּמָה אֶהְיֶה, בִּשְׁלָם אֱהֵא, כְּמוֹחָא דֶּאֱגוֹזָא, דְּאִיהִי מִתְעַטְפָא עַל כָּל אִינוּן הֵיכָלִין דִּבְגַוָּוהּ, דִּכְתִיב, (דברים ד׳:ל״ט) וְיָדַעְתָּ הַיּוֹם וַהֲשֵׁבוֹתָ אֶל לְבָבֶךָ כִּי ה' הוּא הָאֱלֹהִים בַּשָּׁמַיִם מִמַּעַל וְעַל הָאָרֶץ מִתָּחַת אֵין עוֹד.</p>"],[9514014132,"<p>זַכָאִין כָּל אִינוּן דְּמִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא, לְמִנְדַע בְּחָכְמְתָא דְמָארֵיהוֹן, וְאִינוּן יָדְעֵי וּמִסְתַּכְּלִין בְּרָזִין עִילָּאִין. בְּגִין דְּכַד בַּר נָשׁ נָפֵיק מֵהַאי עָלְמָא, בְּהָא אִסְתַּלְּקוּ מִנֵּיהּ כָּל דִּינִין דְּעָלְמָא. וְלָא עוֹד, אֶלָּא דְּפָתְחִין לֵיהּ תְּלֵיסַר תַּרְעֵי דְרָזֵי דַּאֲפַרְסְמוֹנָא דַכְיָא, דְּחָכְמְתָא עִילָּאָה תַּלְיָיא בְּהוּ.</p>"],[9514014133,"<p>וְלָא עוֹד, אֶלָּא דְקוּדְשָׁא בְּרִיךְ הוּא חָקוּק לֵיהּ בְּהַהוּא פּוּרְפִּירָא, דְּכָל דְּיוֹקְנִין גְּלִיפִין תַּמָּן. וְקוּדְשָׁא בְּרִיךְ הוּא אִשְׁתַּעְשְׁעָא בֵּיהּ בַּגַּן עֵדֶן, וְאַחְסֵין תְּרֵין עָלְמִין, עַלְמָא דָא וְעַלְמָא דְאָתֵי.</p>"],[9514014134,"<p>חָכְמְתָא דְאִצְטְרִיךְ לֵיהּ לְבַר נָשׁ. חַד, לְמִנְדַע לְאִסְתַּכָּלָא בְּרָזָא דְמָארֵיהּ. וְחַד, לְמִנְדַע לֵיהּ לְגוּפֵיהּ, וּלְאִשְׁתְּמוֹדָע מֵאָן אִיהוּ. וְאֵיךְ אִתְבְּרֵי, וּמֵאָן אָתֵי. וּלְאָן יְהַךְ. וְתִיקּוּנָא דְגוּפָא, הֵיאַךְ אִתְתַּקַּן. וְהֵיאַךְ אִיהוּ זַמִּין לְמֵיעַל בְּדִינָא קַמֵּי מַלְכָּא דְכוֹלָּא.</p>"],[9514014135,"<p>וְחַד, לְמִנְדַע וּלְאִסְתַּכָּלָא בְּרָזִין דְּנִשְׁמָתֵיהּ. מַאי הִיא הַאי נֶפֶשׁ דְּבֵיהּ, וּמֵאָן אַתְיָא, וְעַל מָה אָתֵי בְּהַאי גוּפָא טִפָּה סְרוּחָה, דְּהַיּוֹם כָּאן וּמָחָר בַּקֶּבֶר. וְחַד לְאִסְתַּכָּלָא בְּהַאי עָלְמָא, וּלְמִנְדַע עַלְמָא דְּאִיהוּ בֵּיהּ, וְעַל מַה יִתְתַּקַּן. וּלְבָתַר, בְּרָזִין עִילָּאִין דְּעָלְמָא דִלְעֵילָא, לְאִשְׁתְּמוֹדָעָא לְמָארֵיהּ. וְכָל דָּא יִסְתַּכַּל בַּר נָשׁ מִגּוֹ רָזִין דְּאוֹרַיְיתָא.</p>"],[9514014136,"<p>תָּא חֲזֵי, כָּל מַאן דְּאָזֵיל לְהַהוּא עָלְמָא בְּלָא יְדִיעָה, אֲפִילּוּ אִית בֵּיהּ עוֹבָדִין טָבִין סַגִּיאִין, מַפְקִין לֵיהּ מִכָּל תַּרְעֵי דְּהַהוּא עָלְמָא.</p>"],[9514014137,"<p>פּוּק חֲמֵי מַאי כְּתִיב הָכָא, הַגִּידָה לִי, אֵימָא לִי רָזִין דְּחָכְמְתָא עִילָּאָה, אֵיךְ אַנְתְּ רָעֵי וְאַנְהֵיגַת בְּהַהוּא עָלְמָא עִילָּאָה. אוֹלִיף לִי רָזִין דְּחָכְמְתָא, דְּלָא יָדַעְנָא, וְלָא אוֹלִיפְנָא עַד הָכָא. בְּגִין דְּלָא אֶהֱוֵי בְּכִיסּוּפָא, בְּגוֹ אִינוּן דַּרְגִּין עִילָּאִין, דַּאֲנָא עָאל בֵּינַיְיהוּ, דְּהָא עַד הָכָא לָא אִסְתַּכַּלְנָא בְּהוּ.</p>"],[9514014138,"<p>תָּא חֲזֵי, מַאי כְּתִיב, (שיר השירים א׳:ח׳) אִם לֹא תֵדְעִי לָךְ הַיָּפָה בַּנָּשִׁים, אִם אַנְתְּ אַתְיָא בְּלָא יְדִיעָה, וְלָא אִסְתַּכְּלַת בְּחָכְמְתָא, עַד דְּלָא תֵיעוֹל הָכָא, וְלָא יְדַעְתְּ בְּרָזִין דְעַלְמָא עִילָּאָה, צְאִי לָךְ, לֵית אַנְתְּ כְּדַי לְמֵיעַל הָכָא בְּלָא יְדִיעָה, צְאִי לָךְ בְּעִקְּבֵי הַצֹּאן, וֶהֱוֵי יְדַעְתְּ גּוֹ אִינוּן עִקְּבֵי הַצֹּאן, אִלֵּין אִינוּן דִּבְנֵי נָשָׁא דְּדָשִׁין לוֹ בְּעָקֵב, וְיָדְעִין רָזִין עִילָּאִין דְּמָארֵיהוֹן, וּבְהוֹ תִנְדַע לְאִסְתַּכָּלָא וּלְמִנְדַע.</p>"],[9514014139,"<p>וּרְעִי אֶת גְּדִיּוֹתַיִךְ, אִלֵּין אִינוּן תִּינוֹקוֹת שֶׁל בֵּית רַבָּן. יְנוּקֵי דְּאִינוּן בְּבֵי מִדְרְשָׁא, וְאוֹלְפִין אוֹרַיְיתָא. עַל מִשְׁכְּנוֹת הָרוֹעִים, עַל אִינוּן בָּתֵּי כְנֵסִיּוֹת וּבָתֵּי מִדְרָשׁוֹת, דְּתַמָּן אוֹלְפִין חָכְמְתָא עִילָּאָה. אַף עַל גַּב דְּאִינוּן לָא יָדְעֵי, אַנְתְּ תִּנְדַע מִגּוֹ אִלֵּין מִלִּין דְּחָכְמְתָא דְקָאַמְרֵי.</p>"],[9514014140,"<p>כְתִיב, וַיִּבְרָא אֱלֹהִים אֶת שְׁנֵי הַמְּאֹרֹת הַגְּדֹלִים וכו', וַיִּבְרָא אֱלֹהִים, בְּקַדְמִיתָא תְּרֵין נְהוֹרִין הֲווֹ שְׁקוּלִין דָּא לָקֳבֵיל דָּא, כְּמָא דְאוֹקְמוּהָ חֲבֵרִין. וְאוֹקִימְנָא, דְּאִינוּן תְּרֵין נְהוֹרִין הֲווֹ בְּרָזָא חָדָא, דְּבוּקִים כַּחֲדָא, וַהֲווּ בְּשִׁיקּוּלָא חָדָא, לְאִתְקְרֵי תַּרְוַויְיהוּ גְּדוֹלִים, כְּמָה דְאוֹקִימְנָא.</p>"],[9514014141,"<p>לַאו דַּהֲוַת סִיהֲרָא בְּקַדְמִיתָא רַב וְעִילָּאָה, אֶלָּא דִּבְכָל זִימְנָא דְסִיהֲרָא קָיְימַת בְּשִׁמְשָׁא בְּרָזָא חָדָא, בְּגִינֵיהּ, אִיהִי אִתְקְרִיאַת בַּהֲדֵיהּ גְּדוֹלִים. זְנָבָא דְּאַרְיָה, אַרְיֵה אִיהוּ, וְאַרְיֵה אִתְקְרֵי.</p>"],[9514014142,"<p>אָמְרָה סִיהֲרָא קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, אֶפְשָׁר לְמַלְכָּא חָדָא דְּלִשְׁתַּמֵּשׁ בִּתְרֵין כִּתְרִין כַּחֲדָא. אֶלָּא דָא בִּלְחוֹדוֹהִי, וְדָא בִּלְחוֹדוֹהִי.</p>"],[9514014143,"<p>אֲמַר לָהּ, חָמֵינָא בָּךְ, דִּרְעוּתָךְ לְמֶהֱוֵי רֹאשׁ לְשׁוּעָלִים. זִילִי וְאַזְעֵירִי גַרְמֵיךְ, דְּהָא אַף עַל גַּב דְּאַתְּ תֶּהֱוֵי רֵישָׁא לְהוֹן, אַזְעִירוּ אִית לָךְ מִכְּמָה דַּהֲוֵית.</p>"],[9514014144,"<p>וְהָא אִיהוּ דַּאֲמָרַת סִיהֲרָא, (שיר השירים א׳:ז׳) הַגִּידָה לִי שֶׁאָהֲבָה נַפְשִׁי אֵיכָה תִרְעֶה, אֵיכְדֵין אֶפְשָׁר לָךְ לְאַנְהָגָא עָלְמָא, בִּתְרֵין כִּתְרִין כַּחֲדָא. אֵיכָה תַרְבִּיץ בַּצָּהֳרָיִם, דְּהָא סִיהֲרָא לֵית הִיא כְּדַאי לְאַנְהָרָא, וְאִי אֶפְשָׁר לָךְ לְאַנְהָגָא בִּתְרֵין כִּתְרִין כַּחֲדָא, בְּשִׁמְשָׁא וּבְסִיהֲרָא, דְּהָא סִיהֲרָא מַה נְּהוֹרָא אִית לָהּ בַּצָּהֳרָיִם. בְּגִין כָּךְ, אִי אֶפְשָׁר לָךְ לְאִשְׁתַּמְּשָׁא בִּתְרֵין כִּתְרִין כַּ חֲדָא.</p>"],[9514014145,"<p>שַׁלָּמָה אֶהְיֶה כְּעֹטְיָה, אֵכְדֵין אֱהֵא אֲנָא מִתְעַטְפָא בַּצָּהֳרָיִם, כַּד נְהִירוּ וְתוֹקְפָא דְשִׁמְשָׁא לֶהֱוֵי אָזֵיל וְאַתְקֵיף. הָא אֲנָא מִתְעַטְפָא בְּכִיסּוּפָא קַמֵּיהּ, וְלָא אֵיכוּל לְשַׁמְּשָׁא קַמָּךְ. וְאַנְתְּ אֵיךְ תֵּיכוּל לְאַנְהָגָא וּלְאִשְׁתַּמְּשָׁא בִּתְרֵין כִּתְרִין כַּחֲדָא.</p>"],[9514014146,"<p>אֲמַר לָהּ קוּדְשָׁא בְּרִיךְ הוּא, הָא יְדַעְנָא בִּיךְ, זִילִי וְאַזְעֵירִי גַרְמֵיךְ. (שם) אִם לֹא תֵדְעִי לָךְ הַיָּפָה בַּנָּשִׁים, דַּאֲמַרְתְּ, דְּאִי אֶפְשָׁר לִי לְאַנְהָגָא עַלְמָא בִּתְרֵין כִּתְרִין כַּחֲדָא, זִילִי וְאַזְעֵירִי גַּרְמֵיךָ, וְתֶיהֱוִי רֵישָׁא לְשׁוּעָלִים.</p>"],[9514014147,"<p>צְאִי לָךְ בְּעִקְּבֵי הַצֹּאן, פּוּקִי וַהֲוִי רֵישָׁא לְאִינוּן אוּכְלוּסִין וַחֲיָילִין דִּלְתַתָּא. וּרְעִי לוֹן, וְאַנְהִיגִי לוֹן, וֶהֱוִי מַלְכָּא דְּכוּלְהוּ תַתָּאֵי, וְאַנְהִיגִי לְכָל חַד וְחַד כִּדְקָא חָזֵי לֵיהּ. וֶהֱוִי שָׁלְטָא בְּלֵילְיָא. וַדַּאי פּוּקִי, וְאַזְעֵירִי גַרְמֵיךְ, וְהָכֵי אִתְחֲזֵי לָךְ.</p>"],[9514014148,"<p>אֲמַר לֵיהּ אֵלִיָּהוּ, רַבִּי, זַכָּאָה חוּלָקָךְ, דְּסִתְרִין דְּמָארָךְ נְהִירִין קַמָּךְ כִּנְהוֹרָא דְשִׁמְשָׁא. וּבְגִין כָּךְ, כָּל אִינוּן מִילִין דְּפוּמָךְ, כָּלְהוֹ חֲקִיקִין לְעֵילָא. וְחָדֵינָא דַּאֲנָא שְׁמַעְנָא לוֹן מִפּוּמָךְ. זַכָּאָה אַנְתְּ בְּהַאי עָלְמָא, וְזַכָּאָה אַנְתְּ בְּעַלְמָא דְאָתֵי. מִלָּה דָא הֲוָה תַּלְיָא קַמֵי מַלְכָּא קַדִּישָׁא, דְּלָא אִתְגְּלֵי לְכָל חֲיָילִין דִּלְעֵילָא. מַאן אִיהוּ דְּגָלֵי לֵיהּ בְּהַאי קְרָא הַשְׁתָּא, אַנְתְּ הוּא, דְּזַכָּאָה חוּלָקָךְ בְּעַלְמָא דֵין וּבְעַלְמָא דְאָתֵי.</p>"],[9514014149,"<p>עַל פּוּמָא דְּאֵלִיָּהוּ אִתְגְּזַר, (שה\"ש א) הַגִּידָה לִי שֶׁאָהֲבָה נַפְשִׁי, כֵּיוָן דְּאִיהִי סָלְקַת לְעֵילָא, וְאִשְׁתְּמִיטַת מִגּוֹ חֵילָהָא, וְכָל אִינוּן אוּכְלוּסָהָא, בְּרָזָא דְאָת י', אִיהִי אָמְרַת, הַגִּידָה לִי שֶׁאָהֲבָה נַפְשִׁי, אַנְתְּ דְּאִיהִי רְחִימָא דְּנַפְשָׁאי, אֵיכָה תִרְעֶה, הוֹאִיל וַאֲנָא נְקוּדָה חָדָא בְּלא פְּשִׁיטוּ כְּלַל, דְּהָא אֲנָא כְּלִילָא בְּגַרְמָאי, וְלָא יָכֵילְנָא לְמִלְקַט וּלְמֵיהַב.</p>"],[9514014150,"<p>וְהָא אִיהִי אָמְרָה לְגַבֵּי רְחִימָה, בְּגִין דְּאִיהִי יָתְבָא קְמוּטָא בְּגַרְמָהּ, בִּנְקוּדָה חָדָא, וְאִיהִי בָּעָאת לְאָעֳלָא אִיהוּ בְּגַוָּהּ. כְּמָה דְאַתְּ אָמֵר, וּבָא אֵלֶיהָ מֶלֶךְ גָּדוֹל, אַף עַל גַּב דְּאִיהִי אָת זְעֵירָא, מִכָּל אַתְוָון.</p>"],[9514014151,"<p>וְעַל דָּא, מִיּוֹמָא דְּאִתְחֲרֵיב בֵּי מַקְדְּשָׁא, אוֹמֵי קוּדְשָׁא בְּרִיךְ הוּא, דְּלָא יֵיעוֹל לְגַבָּהּ לְעֵילָא, עַד דְּיֵיעֲלוּן יִשְׂרָאֵל לְתַתָּא. דִּכְתִיב (הושע יא) בְּקִרְבְּךָ קָדוֹשׁ וְלֹא אָבוֹא בְּעִיר. כְּתִיב הָכָא בְּעִיר, וּכְתִיב הָתָם (קהלת ט) עִיר קְטַנָּה. דְּהָא אִיהִי אָת י' זְעֵירָא מִכָּלְהוֹ.</p>"],[9514014152,"<p>שַׁלָּמָה אֶהְיֶה כְּעֹטְיָה, כְּלִילָא בְּגַוָּאי, דְּלֵית לִי פְּשִׁיטוּ מִכָּל סִטְרִין כְּלַל. בְּגִין דְּאִיהוּ סְתִימָא מִכָּל סִטְרִין יַתִּיר מִכָּל שְׁאָר אַתְוָון.</p>"],[9514014153,"<p>אִם לֹא תֵדְעִי לָךְ וְגו', צְאִי לָךְ, פְּשִׁיטִי גַּרְמֵיךְ בְּכָל סִטְרִין, וּלְקִיטִי עִדּוּנִין וְכִיסוּפִין, בְּהַהוּא פְּשִׁיטוּ. וּמַאי אִיהוּ הַהוּא פְּשִׁיטוּ. דְּאִתְעֲבֵיד כְּחַד סֻכָּה דְּאִינוּן נְטוּרֵי עֶדְרֵי דְעָנָא. וְדָא אִיהוּ אָת ה'.</p>"],[9514014154,"<p>וְהָא אִיהִי צְאִי לָךְ. צְאִי לָא כְתִיב, אֶלָּא צְאִי לָךְ, כְּמָה דְאַתְּ אָמֵר (ישעיה נד) הַרְחִיבִי מְקוֹם אָהֳלֵךְ וִירִיעוֹת מִשְׁכְּנוֹתַיִךְ וכו'. דְּהָא בְּקַדְמִיתָא לָא הֲוֵית אֶלָא נְקוּדָה חָדָא שְׁחוֹרָה, דְּלֵית בָּהּ אֲתַר אָחֳרָא, אֶלָּא אִיהִי סְתִימָא בְּגַוָּוהּ, הַשְׁתָּא דְּסָלְקָא וְאִיהִי מִתְחַבְּרָא בְּבַעֲלָהּ, אִיהוּ אֲמַר לָהּ, צְאִי לָךְ. הַרְחִיבִי מְקוֹם אָהֳלֵךְ, פְּשִׁיטִי גַרְמֵיךְ, וּכְדֵין וּרְעִי אֶת גְּדִיּוֹתַיִךְ, תּוּכְלִי לְמִלְקַט עִדּוּנִין וְכִיסּוּפִין.</p>"],[9514014155,"<p>דְּהָא בְּשַׁעֲתָא דְאִיהִי נְקוּדָה חָדָא, וְסַלְקָא לְעֵילָא, וְהַהוּא מַלְכָּא עִילָּאָה נָחֵית לְגַבָּהּ לְמֵיעַל בָּהּ, בָּטַשׁ בְּהַהוּא נְקוּדָה, וְאִתְפַּשַּׁט בְּכָל סִטְרִין, וְאִתְעֲבֵיד הַהוּא נְקוּדָה אָת ה', וְאִשְׁתְּלֵימַת מִכָּל סִטְרִין, וְלָקְטָא עִדּוּנִין וְכִיסּוּפִין. כְּדֵין אֲמַר לָהּ, וּרְעִי אֶת גְּדִיּוֹתַיִךְ, זִילִי, וֶהֱוֵי זָן וּמְפַרְנֵס לְכָל אוּכְלוּסַיִךְ, זְעֵירִין וְרַבְרְבִין.</p>"],[9514014156,"<p>הַיָּפָה בַּנָּשִׁים, נְקוּדָה חָדָא גּוֹ אַתְוָון, לֵית שַׁפִּירוּ לְכָל אַתְוָון בַּר אָת י'. בִּנְקוּדָה דָא מִתְתַּקְנָן כָּל אַתְוָון, וְאִיהִי שַׁפִּירָא דְּכָלְהוֹ, וְלֵית אָת דְּאָזֵיל בְּלָא נְקוּדָה דָא. הִיא בְּכָלְהוֹ, וְכָלְהוֹ בָּהּ. וְהִיא יָפָה וְשַׁפִּירוּ דְּכוֹלָּא, דְּהָא מֵאֲתַר סְתִימָא עִילָּאָה קָא אָתַת, רֵישׁ כָּל דַּרְגִּין עִילָּאִין. וּבָהּ אִיהוּ רֵישׁ כָּל דַּרְגִּין תַּתָּאִין דִּלְתַתָּא. בְּגִין כָּךְ הַיָּפָה בַּנָּשִׁים, שַׁפִּירוּ דְּכֹלָּא.</p>"],[9514014157,"<p>וְתוּ הַיָּפָה בַּנָּשִׁים, כְּתִיב בַּנָּשִׁים, בְּאִינוּן אַתְוָון דְּאִינוּן נוּקְבֵי. וּמַאי אִיהוּ. אָת ה'. דְּהָא כְּדֵין אִיהִי פְּשִׁיטוּ, וְשַׁפִּירוּ דְּכוֹלָּא, לְמִרְעֵי, וּלְמִפְלְגָא חוּלָּקִין לְכָל אוּכְלוּסִין עִילָּאִין דִּילָהּ. וְעַל דָּא, צְאִי לָךְ מֵהַאי סְתִימוּ, דְאָת כְּלִילָא וּסְתִימָא בְּגַוָּוךְ. לָךְ, לְגַרְמָךְ וּלְתוֹעַלְתָּךְ. וְכוֹלָּא בְּרָזָא דְאַתְוָון אִיהוּ.</p>"],[9514014158,"<p>כְתִיב, (תהילים מ״ח:ד׳) אֱלֹהִים בְּאַרְמְנוֹתֶיהָ נוֹדַע לְמִשְׂגָּב. דְּהָא בְּשַׁעֲתָא דְּהַהוּא מֶלֶךְ גָּדוֹל אָתֵי לְגַבָּהּ, וְאַמְשִׁיךְ לָהּ לְעֵילָא לְמֵיעַל בָּהּ, וּבָטַשׁ בָּהּ בְּהַהוּא נְקוּדָה. כֵּיוָן דְּבָטַשׁ בְּהַהוּא נְקוּדָה, אִתְפַּשְׁטַת וְאִתְפַּתְּחַת לְכָל סִטְרִין, וְאִתְעֲבֵידַת אָת ה', פִּתְחָא דְּהֵכָלִין לְכָל סְטַר, לְמֵיעַל הַהוּא מֶלֶךְ גָּדוֹל, וּכְדֵין אֱלֹהִים בְּאַרְמְנוֹתֶיהָ בְּאִינוּן פְּתִיחוּ דְהֵיכָלִין, בְּאָת ה' אִשְׁתְּמוֹדָע.</p>"],[9514014159,"<p>הַהוּא אֱלֹהִים חַיִּים, נָטְלָא הַהוּא שְׁמָא, לְמֵיזַן וּלְמִפְלְגָא חוּלָקִין לְכוֹלָּא. וּכְדֵין נוֹדַע לְמִשְׂגָּב, לְמֶהֱוֵי מִשְׂגָּב לְתַתָּאי, וְלַאֲרָקָא בִּרְכָאן לְכוֹלָּא, כְּגַוְונָא דִלְעֵילָא.</p>"],[9514014160,"<p>בְּשַׁעֲתָא דְּבָעָא קוּדְשָׁא בְּרִיךְ הוּא לְמִבְרֵי עָלְמָא, סְלִיקוּ כָּל מִלִּין דְּעָלְמָא, וְכָל דַּרְגִּין עִילָּאִין וְתַתָּאִין, כָּלְהוֹ בְּמַחֲשָׁבָה. אַמַּאי אִקְרֵי מַחֲשָׁבָה. אֶלָּא דָא אִיהִי נְקוּדָה חָדָא סְתִימָא, דְּקָיְימָא בְּמַחֲשָׁבָה. דְּהָא נְקוּדָה חָדָא, לָא אִתְיְדַע לְאָן אֲתַר אִתְפַּשְׁטַת, וּמַה יֶּהֱוֵי מִינָהּ, וּלְאָן אֲתַר יִסְטֵי אוֹרְחָא. וּנְקוּדָה דָא, אִיהִי רֵישָׁא דְּכָל רְעוּתִין וְכָל מַחְשָׁבִין דְּעָלְמָא.</p>"],[9514014161,"<p>וַהֲוָה כֹּלָּא סָתִים בְּגַוָּוהּ, וְלָא אִתְיְדִיעַ, עַד דְּאִתְפַּשַּׁט הַאי מַחֲשָׁבָה, וְאִתְעֲבֵיד חַד פְּשִׁיטוּ, לְסִטְרָא דָא וּלְסִטְרָא דָא. כֵּיוָן דְּהַאי נְקוּדָה אִתְפַּשַּׁט בְּהַאי פְּשִׁיטוּ, אִתְגְּלֵי יַתִּיר כָּל מַה דְּהֲוָה סָתִים.</p>"],[9514014162,"<p>לָא דְּאִתְגְּלֵי לְמִנְדַע, אֶלָּא אִתְגְּלֵי הַהוּא סְתִימוּ, לְאָן אֲתַר סָטֵי אוֹרְחָא. וְנָפְקָא מֵרָזָא דְמַחֲשָׁבָה, דְּהָא לָא קָיְימָא בַּמַּחֲשָׁבָה, וְלָא סָלְקָא בִּשְׁמָא דָא, אֶלָּא קָיְימָא בִּשְׁמָא לְאִתְגַּלְּיָיא. וְאִתְעֲבֵיד חַד קוֹל בְּלַחַשׁ, וּמַאי אִיהוּ. דָּא אָת ה'. דְּהוּא מַנּוֹ לַאֲפָקָא כָּל אִינוּן מִלִּין סְתִימִין דַּהֲווֹ גּוֹ מַחֲשָׁבָה.</p>"],[9514014163,"<p>הָכָא אִיהוּ בְּהִיפוּכָא מִגַּוְּונָא דִלְתַתָּא. לְתַתָּא, מַאן דְבָטַשׁ בְּהַהִיא נְקוּדָה דִלְתַתָּא, כַּד אִיהִי סְתִימָא, וְאָתֵי לְגַבָּהּ הַהוּא מֶלֶךְ גָדוֹל, דְּאִיהוּ בְּרָזָא דְּאָת ו' דְּנָפֵיק מֵהַהוּא ה' עִילָּאָה. הַהוּא ו' דְּנָחֵית מִגַּוֵּיהּ, בָּטַשׁ בְּהַאי נְקוּדָה, וְאַפֵּיק מִגַּוָּוהּ כָּל מַה דְּלָקֵיט מִלְּעֵילָא, וְאִתְפַּשְּׁטַת וְאִתְפַּתְּחַת לְכָל סִטְרִין, וְאִתְעֲבֵיד אָת ה'.</p>"],[9514014164,"<p>לְעֵילָא, מַאן דְּבָטַשׁ בְּאָת ה' עִילָּאָה, אִיהִי נְקוּדָה חָדָא עִילָּאָה סְתִימָא, כֵּיוָן דְּבָטַשׁ בָּהּ, אַפֵּיק לְבַר, וְאִתְגַּלְּיָין כָּל אִינוּן מִלִּין סְתִימִין דַּהֲווֹ תַּמָּן, וְנָפְקֵי לְבַר, הָא אִתְיְידַע הַהוּא מַחֲשָׁבָה דְּהֲוָה סָתִים וְלָא יְדִיעַ.</p>"],[9514014165,"<p>כְגַוְונָא דָא, כַּד בָּטַשׁ ו' בִּנְקוּדָה דָא לְתַתָּא, כְּדֵין אַפֵּיק מִגַּוָּוהּ, כָּל אִינוּן חַיָּילִין וּמַשִּׁרְיָין וְאוּכְלוּסִין וּנְהוֹרִין וְנָחֲלִין עֲמִיקִין דִּלְעֵילָא.</p>"],[9514014166,"<p>וּכְדֵין אָמְרֵי לָהּ, (שיר השירים א׳:ח׳) וּרְעִי אֶת גְּדִיּוֹתַיִךְ עַל מִשְׁכְּנוֹת הָרוֹעִים. טוֹל נְהוֹרִין וּמְזוֹנִין, וּפַלְגֵי לְכָל אִינוּן חַיָּילִין וְהָבֵי לוֹן. עַל מִשְׁכְּנוֹת הָרוֹעִים, אִינוּן רוֹעִים דְּהֵן מְנַהֲגֵי עָלְמָא, לְמֵיהַב לוֹן שׁוּלְטָנוֹ וְתוֹקְפָא, כָּל חַד וְחַד כִּדְקָא חָזֵי לֵיהּ. וְכָל דָּא, בְּאִתְפַּשְּׁטוּ דְּהַהִיא נְקוּדָא דַּהֲוַת סְתִימָא מִן קַדְמַת דְּנָא.</p>"],[9514014167,"<p>חָדֵי רַבִּי שִׁמְעוֹן, וַאֲמַר, בְּקַדְמִיתָא עַד לָא אִתְאֲמַר וְלָא אִתְגְּלֵי מִלִּין אִלֵּין דְּשִׁיר הַשִּׁירִים, בְּכֵינָא וַעֲצֵיבְנָא. וְהַשְׁתָּא דְּמִלִּין אִלֵּין אִתְגַּלְּיָין, חָדֵינָא, וַאֲמֵינָא, דְּזַכָּאָה חוּלָקִי דַּהֲוֵינָא בְּדָא. וְתוּ, דְּמִלִּין עִילָּאִין דִּלְעֵילָא, אִתְגַּלְּיָין הָכָא עַל יְדָא דְמַר.</p>"],[9514014168,"<p>(שה\"ש א) לְסוּסָתִי בְּרִכְבֵי פַרְעֹה דִּמִּיתִיךְ רַעְיָתִי, רַבִּי שִׁמְעוֹן פָּתַח וְאָמַר, (שמות יד) וַיִּקַּח שֵׁשׁ מֵאוֹת רֶכֶב בָּחוּר וכו', תָּא חֲזֵי, חָכְמְתָא דְמִצְרַיִם, דְּכָל מַה דַּעֲבָדוּ, לְגַבֵּי רָזָא דְחָכְמְתָא דִלְעֵילָא עֲבָדוּ. וּפַרְעֹה חַכִּים הֲוָה יַתִּיר, דְּהָא לָא מוֹקְמֵי מַלְכָּא בְּמִצְרַיִם אִי לָא יְהֵא חַכִּים מִכָּלְהוֹ.</p>"],[9514014169,"<p>וְעַל דָּא כְּתִיב וַיִּקַּח, אִיהוּ נְטֵיל כּוֹלָּא בְּחָכְמָה, נְטֵיל עֵיטָא דְחָכְמְתָא לְגַבֵּיהּ. אֲמַר, עַמָּא דָא שֵׁשׁ מֵאוֹת אֶלֶף אִינוּן, עָאל לְאִידְרוֹי, וַהֲפַךְ בְּכָל זִינֵי חֲרָשִׁין דִּילֵיהּ, וַעֲבַד סְגִימִין פְּסִיסִין, וַחֲרַשׁ חֲרָשִׁין, וּנְטֵיל שִׁית מְאָה רֶכֶב בְּרִירָן. בָּחוּר: בְּרִירָן בַּחֲרָשִׁין, טְעוּנִין בְּכָל זִינֵי קִסְמִין וַחֲרָשִׁין כְּרָזָא דִלְעֵילָא, דְּהַהוּא מְמַנָּא דְּאִתְמַנָּא עֲלַיְיהוּ.</p>"],[9514014170,"<p>וַהֲוָה נְטֵיל טָעִין בְּקִסְמִין וַחֲרָשִׁין, שֵׁשׁ מֵאוֹת רֶכֶב בָּחוּר, דַּהֲווֹ בְּרִירָן לְקִבְלַיְיהוּ דְיִשְׂרָאֵל. וְכֹל רֶכֶב מִצְרַיִם, כָּל חַד וְחַד טָעִין בְּחַרְשׁוֹי וְקוֹסְמוֹי. לָא הֲווֹ חַכִּימִין בְּמִצְרַיִם, דְּלָא טָעִין טְעוּנִין דְּקִסְמִין וַחֲרָשִׁין.</p>"],[9514014171,"<p>וְשָׁלִישִׁים עַל כֻּלּוֹ, מַאי וְשָׁלִישִׁים. אֶלָּא זִינִין דַּחֲרָשִׁין לֵיהּ גְּלִיפָן בִּתְלַת תְּלַת. וּשְׁמָהָן דִּמְסָאֲבוֹ הֲווֹ בְּאַתְוָון דִּתְלַת תְּלַת. כָּלְהוֹ גְּלִיפֵי בִּקְסִירִין מְזַיְינָן, כְּגַוְונָא דִלְעֵילָא, לְמֶהֱוֵי לֵיהּ זִייוּנִין קַסִּירִין לְגַבַּיְיהוּ דְיִשְׂרָאֵל.</p>"],[9514014172,"<p>עַל כַּלָּה כְּתִיב, דְּהָא עֵיטָא נָטַל עַל כַּלָּה, וּבְגִין לְשֵׁיצָאָה לוֹן לְיִשְׂרָאֵל. וְכָלְהוֹ הֲווֹ זִינֵי מַשִּׁרְיָין עַל כַּלָּה, דַּהֲוַת נָטְלָא קַמַּיְיהוּ דְיִשְׂרָאֵל.</p>"],[9514014173,"<p>מִיָּד (שמות י״ד:ח׳) וַיְחַזֵּק ה' אֶת לֵב פַּרְעֹה וַיִּרְדֹּף אַחֲרֵי בְּנֵי יִשְׂרָאֵל וּבְנֵי יִשְׂרָאֵל יוֹצְאִים בְּיָד רָמָה. מִיָּד רָמָה לָא כְתִיב, אֶלָּא בְּיָד רָמָה. אִיהִי יָד דִּכְתִיב בֵּיהּ, (שם) וַיַּרְא יִשְׂרָאֵל אֶת הַיָּד הַגְּדוֹלָה, הַהִיא יָד הַגְּדוֹלָה אִיהִי יָד רָמָה.</p>"],[9514014174,"<p>בְּהַהִיא שַׁעֲתָא, חָקֵיק קוּדְשָׁא בְּרִיךְ הוּא בְּהַאי יָד, כָּל דְּיוֹקְנִין, וְכָל חַיָּילִין וְתוֹקְפִין דְּמִצְרָאֵי, כְּגַוְונָא דְּאִינוּן חֳרָשִׁין וְקִסְמִין דַּעֲבָדוֹ, בְּשַׁעֲתָא דַּהֲווֹ אַתְיָין בַּחֲרָשָׁא דָא. הַהִיא יַד, הֲוָה חָקֵיק בֵּיהּ לְקִבְלֵיהּ דְּהַהוּא חָרָשָׁאֵי, וְאִתַּבְרַת קַמֵּיהּ דְּהַהוּא דִּיוּקְנָא דְּהֲוָה חָקֵיק בְּהַהוּא יָד. הֲדָא הוּא דִכְתִיב, (שם טו) יְמִינְךָ יְיָ' נֶאְדָּרִי בַּכֹּחַ יְמִינְךָ יְיָ' תִּרְעַץ אוֹיֵב. וּבְגִין הַאי דִּמִּיתִיךְ, דְּיוֹקְנִין וְצִיּוּרִין חֲקֵיקְנָא בִּיךְ, כְּגַוְונָא דְּסוּסְוָותָא דְּפַרְעֹה. עַד הָכָא.</p>"],[9514014175,"<p>אֲבָל בְּקִישּׁוּרָא דְּמִלִּין, לָא אִתְקַשְׁרוּ. דְּאִי הָכֵי, מַאי הַאי לְגַבֵּי קְרָא דִלְעֵילָא, וּבְרָזָא דִּרְחִימוּ וְחֶדְוָה דְתֻשְׁבַּחְתָּא דָא. מַאי בָּעָאן הָכָא רְתִיכִין דְּפַרְעֹה. וּמַאי קָא אָתֵיב לְגַבָּהּ.</p>"],[9514014176,"<p>אֶלָּא וַדַּאי כּוֹלָּא בְּקִישּׁוּרָא דְרָזָא חָדָא אִיהוּ. לְסוּסָתִי בְּרִכְבֵי פַרְעֹה. אַהֲדַרְנָא לְמִלָּה קַדְמָאָה. דְּכַד קוּדְשָׁא בְּרִיךְ הוּא מַנֵּי לָהּ עַל כָּל אִינוּן אוּכְלֻסִּין וּמַשִּׁירְיָין דִּלְתַתָּא לְמֶהֱוֵי רֵישָׁא דִלְהוֹן. מֵהַהוּא זִמְנָא אִיהִי מְשַׁבַּחַת תָּדִיר, וְלָא שְׁכֵיכַת, וְכָל אוּכְלוּסִין דִּילָהּ מְשַׁבְּחָן תָּדִיר, וְלָא שְׁכִיכוּ לְעָלְמִין.</p>"],[9514014177,"<p>וְתוּשְׁבַּחְתָּא דִּרְחִימוּ דָא, הֲוֵי שֵׁירוּתָא, כַּד נָפְקַת מִמִּצְרַיִם, וְכָל אוּכְלוּסִין דִּלְעֵילָא וְתַתָּא הֲווֹ קַמָּהּ, וּכְדֵין שְׁרִיאַת רְחִימוּ דְּתוּשְׁבַּחְתָּא לְגַבֵּי עֵילָּא. וְסוּסָוָון דְּפַרְעֹה וּרְתִיכוֹי הֲווֹ נָטְלָן אֲבַתְרַיְיהוּ דְיִשְׂרָאֵל, אִיהִי שְׁרִיאַת בְּתוּשְׁבַּחְתָּא דִּרְחִימוּ לְגַבֵּי עֵילָּא.</p>"],[9514014178,"<p>וְקוּדְשָׁא בְּרִיךְ הוּא לָא בָּעֵי בְּתוּשְׁבַּחְתָּא בְּהַהוּא זִמְנָא, כְּמָא דְתָנִינָן דִּכְתִיב (שמות י״ד:כ׳) וְלֹא קָרַב זֶה אֶל זֶה כָּל הַלַּיְלָה. וְאִיהוּ אִשְׁתִּיק לָהּ מִגּוֹ תּוּשְׁבַּחְתָּא דִּרְחִימוּ דְּשָׁרֵיאַת.</p>"],[9514014179,"<p>פּוּק חֲזֵי, כַּלָּה דְּקָיְימָא בִּרְחִימוּ לְמֶחֱמֵי לְבַעֲלָהּ, כַּד חָמַאת לֵיהּ, אִתְעָרַת רְחִימוּ לְגַבֵּיהּ, וְשָׁרֵיאַת לְשַׁבְּחָא לְגַבֵּיהּ. וְאִי אִיהוּ לָא בָעֵי בְּתוּשְׁבַּחְתָּא, מְשַׁתְּקָהּ בִּשְׁתִיקוּ מֵאִתְעָרוּתָא דִּרְחִימוּ דְּשָׁרֵיאַת. אֵיךְ שָׁכֵיךְ לִבָּהּ וּרְעוּתָהּ.</p>"],[9514014180,"<p>כֵיוָן דְּטָבְעֵי כָּל אִינוּן סוּסָוָון וּרְתִיכִין דְּפַרְעֹה בְּיַמָּא, וְחָמוֹ יִשְׂרָאֵל כָּל אִינוּן גְּבוּרָאן וְנִיסִּין דַּעֲבַד לוֹן קוּדְשָׁא בְּרִיךְ הוּא, שַׁבְּחוּ יִשְׂרָאֵל בְּאַרְעָא תּוּשְׁבַּחְתָּא בְּגִינָהּ, וְקַבֵּיל לוֹן קוּדְשָׁא בְּרִיךְ הוּא, דִּכְתִיב, (שמות ט״ו:א׳) אָז יָשִׁיר משֶׁה וּבְנֵי יִשְׂרָאֵל אֶת הַשִּׁירָה הַזֹּאת לַייָ'. לְבָתַר כַּד אַהֲדַר בֵּירָא, שַׁבְּחוּ יִשְׂרָאֵל תּוּשְׁבַּחְתָּא בְּגִינָהּ. דִּכְתִיב, אָז יָשִׁיר יִשְׂרָאֵל אֶת הַשִּׁירָה הַזֹּאת. אֲתָא יְהוֹשֻׁעַ וְשַׁבַּח תּוּשְׁבַּחְתָּא בְּגִינָהּ. אֲתוֹ דְּבוֹרָה וּבָרָק וְשַׁבַּחוּ תּוּשְׁבַּחְתָּא בְּגִינָהּ.</p>"],[9514014181,"<p>כֵיוָן דְּבָנָה שְׁלמֹה בֵּי מַקְדְּשָׁא, וְעָלְמִין הֲווֹ כָּלְהוֹ בְּשִׁיקּוּלָא חָדָא, כְּדֵין אִיהִי אִתְעָרַת רְחִימוּ וְתוּשְׁבַּחְתָּא עִילָּאָה, וַאֲמָרַת מִילִין עִילָּאִין אִילֵּין דְּתוּשְׁבַּחְתָּא וּרְחִימוּ לְגַבֵּיהּ.</p>"],[9514014182,"<p>כְדֵין אִיהוּ, מִגּוֹ רְחִימוּ וְתֵיאוּבְתָּא דְכַלָּה, בָּעָא לְאַדְכּוּרֵי לָהּ הַהוּא שְׁתִיקוּ דַּעֲבַד לָהּ לְמִשְׁתַּק, וְלָא בָעָא בְּתוּשְׁבַּחְתָּא, פָּתַח וְאָמַר, (שיר השירים א׳:ט׳) לְסֻסָתִי בְּרִכְבֵי פַרְעֹה, כַּד אִינוּן סוּסָוָון וּרְתִיכִין דְּפַרְעֹה הֲווֹ אַתְיָין וְרָדְפִין אֲבַתְרַיְהוֹן דְּיִשְׂרָאֵל, דִּמִּיתִיךְ רַעֲיָתִי, אַשְׁתֵּיקִית לָךְ בְּאִשְׁתּוֹקָא. דִּמִּיתִיךְ: כְּמָא דְאִתְּמָר, וַיִּדֹּם אַהֲרֹן. שֶׁמֶשׁ בְּגִבְעוֹן דּוֹם.</p>"],[9514014183,"<p>וְעִם כָּל דָּא, הָכֵי אִצְטְרִיךְ, דְּהָא בְּהַהוּא זִמְנָא עַד כְּעָן, בְּנִין וְאֻכְלוּסִין דְּאַרְעָא, וְכָל תִּיקּוּנִין דִּילָךְ, לָא הֲווֹ שְׁלֵמִין כִּדְקָא יָאוֹת, וְאַתְּ לָא הֲוֵית מִתְעַטְרָא בְּהוּ כִּדְקָא יָאוֹת בְּתִיקּוּנַיִךְ.</p>"],[9514014184,"<p>אֲבָל הַשְׁתָּא נָאווּ לְחָיַיִךְ בַּתּוֹרִים, כַּמָּא יָאִין כָּל תִּיקוּנִין דִּילָךְ, וְכַמָּה שַׁפִּירִין אִינוּן בַּתּוֹרִים, דִּכְבָר קַבִּילוּ אוֹרַיְיתָא, תּוֹרָה שֶׁבִּכְתָב וְתוֹרָה שֶׁבְּעַל פֶּה, וְאִתְעַטְרַת בְּהוּ. מַה דְּלָא הֲוֵית מִקַּדְמַת דְּנָא.</p>"],[9514014185,"<p>וּבְגִין כָּךְ דִּמִּיתִיךְ רַעֲיָתִי, וְלָא בָעֵינָא בְּתוּשְׁבַּחְתִּיךְ, וְאִתְעָרוֹ דִּרְחִימוּ דִּילָךְ, בְּגִין דְּאַתְּ עֵרוֹם וְעֶרְיָה, וְלָא הֲוֵית מִתְתַּקְּנָא בְּתִיקּוּנִין. וְהַשְׁתָּא כַּמָּא יָאַיָין תִּיקּוּנִין דִּילָךְ, וּרְעוּתָא דִּילִי בָּךְ, וּבְמִילֵי תּוּשְׁבַּחְתֵּיךְ. צַוָּארֵךְ, הָא אִית לָךְ בֵּי מַקְדְּשָׁא בְּאַרְעָא, בְּגַוְונָא דְּכָלְהוֹ צִיּוּרִין עִילָּאִין וְכַמָּה צַדִּיקִים וַחֲסִידִים עָאלִין בְּגַוֵּיהּ.</p>"],[9514014186,"<p>וְהַשְׁתָּא דְּאַתְּ מִתְעַטְרָא בְּתִיקוּנֵיךְ, וּבִשְׁלִימוּ דִּלְהוֹן, הָא כָּל מְקוֹרִין עִילָּאִין, וְכָל דַּרְגִּין וְשַׁיְיפִין הָא אִינוּן לְגַבָּךְ, לְקַבְּלָא לָךְ, וּלְאַתְקָנָא לָךְ בְּתִיקּוּנִין עִילָּאִין.</p>"],[9514014187,"<p>וְעַל דָּא (שיר השירים א׳:י״א) תּוֹרֵי זָהָב נַעֲשֶׂה לָךְ, נַעֲשֶׂה וַדַּאי, אֶעֱשֶׂה לָא כְתִיב, אֶלָּא נַעֲשֶׂה, מֵרֵישָׁא דִּנְקוּדָה עִילָּאָה, עַד יְסוֹדָא תַּתָּאָה, נְתַקֵּן לָךְ, וְנַעֲבֵיד לָךְ מִסִּטְרָא דְּזָהָב, דְּתַמָּן אִתְעָרוֹ דִּרְחִימוּ. עִם נְקוּדוֹת הַכָּסֶף, מִסִּטְרָא דְּיָמִינָא.</p>"],[9514014188,"<p>לְאַחֲזָאָה, דְּהָא אִתְעָרוֹ דִּלְעֵילָא, לָא אִתְעַר וְלָא אִתְתַּקַּן לְגַבָּהּ, אֶלָּא כַּד אִתְתַּקְּנָא אִיהוּ בְּקַדְמִיתָא בְּתִיקּוּנֵי דְּהַאי עָלְמָא. כֵּיוָן דְּתִיקּוּנִין דְּהַאי עָלְמָא אִתְתַּקְּנוּ בָהּ כִּדְקָא יָאוֹת, כְּדֵין תִּיקּוּנֵי דִּלְעֵילָא מִתְתַּקְּנֵי בָהּ, וְיַהֲבֵי לָהּ תּוֹרֵי זָהָב עִם נְקוּדוֹת הַכָּסֶף. תּוֹרֵי, כְּמָה דְאַתְּ אָמֵר (אסתר ב׳:ט״ו) תּוֹר אֶסְתֵּר בַּת אֲבִיחַיִל.</p>"],[9514014189,"<p>וְעַל דָּא, כַּד רָדְפִין סוּסָוָון דְּרִכְבֵי פַרְעֹה, דִּמִּיתִיךְ, דְּלָא תְשַׁבַּח וְלָא תִתְעָר רְחִימוּ לְגַבָּאי. בְּגִין דְּתִיקּוּנִין דִּילָךְ לְתַתָּא לָא הַוְיָין. וְהַשְׁתָּא יָאוֹת הוּא, דְּהָא נָאווּ לְחָיַיִךְ בַּתּוֹרִים וְגו', וַדַּאי תּוֹרֵי זָהָב נַעֲשֶׂה לָךְ וְגו', וְנִתְתַּקַּן לָךְ כִּדְקָא יָאוֹת. וְכָל חַד וְחַד כְּפוּם אוֹרְחוֹי, וּמִלִּין הָכֵי מִתְקַשְּׁרָן.</p>"],[9514014190,"<p>(שיר השירים א׳:ט׳) לְסֻסָתִי בְּרִכְבֵי פַרְעֹה וְגו', כְּתִיב (שמות י״ג:כ״א) וַה' הוֹלֵךְ לִפְנֵיהֶם יוֹמָם בְּעַמּוּד עָנָן וְגו'. בְּשַׁעֲתָא דַּאֲפֵיק לוֹן קוּדְשָׁא בְּרִיךְ הוּא לְיִשְׂרָאֵל מִמִּצְרַיִם, לָא הֲווֹ בָּעָאן לְמֵיזַל בְּמַדְבְּרָא בְאוֹרַח נְגִיבוּ. דַּהֲווֹ רְגִילִין בְּמִצְרַיִם, דְּהַוְיָא כְּגִנְתָא דְעֵדֶן, כְּמָה דְאַתְּ אָמֵר, כְּגַן ה' כְּאֶרֶץ מִצְרַיִם. דַּהֲווֹ אָזְלִין בַּאֲתַר נְגִיבוּ בְּאוֹרְחָא, בְּחוּרְבָא בְּלָא יִישׁוּבָא.</p>"],[9514014191,"<p>מָה עֲבַד קוּדְשָׁא בְּרִיךְ הוּא, שָׁדַר קֳדָמַיְיהוּ שְׁכִינְתָּא, דַּהֲוַת אָזְלַת בְּכָל גְּוָונִין דְּזָהֲרָא, בְּכָל גְּוָונִין דְּתֵיאוּבְתָּא, וַהֲווּ רְהִיטֵי אֲבַתְרָהּ לְמֶחֱמֵי בְּתֵיאוּבְתָּא. וּבְגִין כָּךְ הֲווֹ רְהִיטִין אֲבַתְרָהּ, וְאָזְלֵי, וְלָא הֲווֹ מִתְעַכְּבֵי. וְקוּדְשָׁא בְּרִיךְ הוּא עֲבֵיד לוֹן הָכֵי, כִּי הֵיכֵי דְּלָא יִתְעַכֵּב קִדּוּשָׁא דִּשְׁמָא עַל יַמָּא, דְּאִיהוּ הֲוָה בָּעֵי לְאִתְיַקְּרָא בְּגוֹ כָּל עַמְּמִין דְּאַרְעָא.</p>"],[9514014192,"<p>כְגַוְונָא דְּאִלֵּין אָזְלִין בִּבְהִילוּ, אוּף הָכֵי עֲבַד פַּרְעֹה בִּרְתִיכוֹי וְסוּסָוָון דִּילֵיהּ, בְּגִין לְמִרְדַּף בִּבְהִילוּ, דְּלָא יִתְעַכְּבוּן רְתִיכוֹי בְּאוֹרְחָא. מָה עֲבַד. נָטַל סוּסָוָון נוּקְבֵי וְסוּסָוָון דְּכוּרֵי, וְשַׁוֵּי נוּקְבֵי לְקַמַּיְיהוּ וּדְכוּרֵי מֵאֲחוֹרָא, דְּכוּרֵי הֲווֹ רָהֲטֵי בָּתַר נוּקְבֵי, וְנוּקְבֵי הֲווֹ רָהֲטֵי מִקַּמֵּי דְכוּרֵי, וְאִלֵּין וְאִלֵּין הֲווֹ רָהֲטֵי בִּבְהִילוּ. וְדָא עֲבַד פַּרְעֹה בְּחָכְמְתָא, לְמִרְדַּף בִּבְהִילוּ אֲבַתְרַיְיהוּ דְיִשְׂרָאֵל.</p>"],[9514014193,"<p>כֵיוָן דְּאַדְבֵּיק לוֹן, וּבְעָא לַאֲגָחָא קְרָבָא בְּיִשְׂרָאֵל, נָטַל נוּקְבֵי וְחָגַר לוֹן לַאֲחוֹרָא, וּדְכוּרֵי לְקַמַּיְיהוּ, בְּגִין לְיַאֲשָׁא רְתִיכוֹי. כָּךְ בְּקַדְמִיתָא כְּתִיב, (שמות) וַה' הוֹלֵךְ לִפְנֵיהֶם יוֹמָם, וּלְבָתַר כְּתִיב, (שם יד) וַיִּסַע מַלְאַךְ הָאֱלֹהִים הַהֹלֵךְ לִפְנֵי מַחֲנֵה יִשְׂרָאֵל וַיֵּלֶךְ מֵאַחֲרֵיהֶם. וַיִּסַּע, בְּגִין דְּיִתְיָיאֲשׁוּן יִשְׂרָאֵל, וִיהוֹן נְטִירִין. וְכָל אִינוּן גִּירִין, וּבְלִסְטְרָאִין, וְאַבְנִין, וְקוֹלְפִין, דַהֲווֹ רָמָאן לְגַבַּיְיהוּ דְּיִשְׂרָאֵל, לָא מָטוֹ לוֹן. וְהַיְינוּ דִּכְתִיב, הִתְיַצְּבוּ וּרְאוּ, וּבְגִין כָּךְ דִּמִּיתִיךְ, בְּהַהוּא גַּוְונָא מַמָּשׁ.</p>"],[9514014194,"<p>כֵיוָן דְּאִינוּן אוּכְלוּסִין אִתְעֲבָרוֹ, וְחָמוֹ כָּל אִינוּן נִסִּין וּגְבוּרָן דַּעֲבַד קוּדְשָׁא בְּרִיךְ הוּא עַל יַמָּא, כְּדֵין נָאווּ לְחָיַיִךְ בַּתּוֹרִים, אִתְתַּקָּנוֹ יִשְׂרָאֵל בְּרָזָא דִמְהֵימְנוּתָא, דִּכְתִיב (שם) וַיַּאֲמִינוּ בַּה' וּבְמשֶׁה עַבְדּוֹ. וְקַבִּילוּ יִשְׂרָאֵל אוֹרַיְיתָא עַל טוּרָא דְסִינַי, תּוֹרָה שֶׁבִּכְתָב וְתוֹרָה שֶׁבְּעַל פֶּה, וּכְדֵין אִתְתְּקָנוּ כּוֹלָא, עֵילָא וְתַתָּא כִּדְקָא יָאוֹת.</p>"],[9514014195,"<p>(שיר השירים א׳:י׳) נָאווּ לְחָיַיִךְ בַּתּוֹרִים, תָּא חֲזֵי, כָּל גְּוָונִין דִּלְגוֹ, וְכָל מַחְשְׁבִין וּרְעוּתִין דְּעָלְמָא דְּאִינוּן גּוֹ לִבָּא, כּוּלְהוּ אִתְחֲזוֹן בְּאַנְפִּין. וּבְאַנְפִּין אִשְׁתְּמוֹדְעָא בַּר נָשׁ מַאן אִיהוּ. אִי עוֹבָדוֹי לְטַב, אִי עוֹבָדוֹי לְבִישׁ. כְּמָה דְאַתְּ אָמֵר, (ישעיהו ג׳:ט׳) הַכָּרַת פְּנֵיהֶם עָנְתָה בָם. וְהַשְׁתָּא דְּתִיקּוּנִין דְּכֹלָּא כָּלְהוֹ כִּדְקָא יָאוֹת, בְּתִיקּוּנִין דְּכָשְׁרָאן, בְּתִיקוּנִין דְּעוֹבָדִין טָבִין, מִיָּד נָאווּ לְחָיַיִךְ בְּלָא כִיסּוּפָא כְּלָל.</p>"],[9514014196,"<p>וְכָל דָּא הֲוֵי בְּזִמְנָא דְּאִתְבְּנֵי בֵּי מַקְדְּשָׁא, וְעָלְמִין כּוּלְהוֹן בְּחֶדְוָא, עֵילָּא וְתַתָּא, וּכְדֵין אִתְתַּקָּנוֹ אַנְפִּין כִּדְקָא חָזֵי. אִתְחַבְּרוּ אַנְפִּין בְּאַנְפִּין כִּדְקָא חָזֵי.</p>"],[9514014197,"<p>לְחָיַיִךָ, וְלָא כְתִיב פָּנַיִךְ, בְּגִין דְּכוֹלָּא חַד, אֲבָל לְחָיַיִם, אִינוּן מְתַקְּנָן צִפְצוּפָא וּמִילּוּלָא לְאִסְתַּכָּלָא בְּהוּ. וּבְגִין כָּךְ, שִׁירָתָא דָא אִתְתַּקְּנָא הַשְׁתָּא, יַתִּיר מִשְּׁאָר זִמְנִין דְּעָלְמָא.</p>"],[9514014198,"<p>כְתִיב, (בראשית ט״ו:ד׳) וְהִנֵּה דְבַר ה' אֵלָיו לֵאמֹר לֹא יִירָשְׁךָ זֶה כִּי אִם אֲשֶׁר יֵצֵא מִמֵּעֶיךָ הוּא יִירָשֶׁךָ. וְכִי אַבְרָהָם דְּהֲוָה אָזֵיל בִּשְׁלִימוּ לְגַבֵּי מַלְכָּא קַדִּישָׁא, אֵיךְ לֹא הֶאֱמִין בְּמַאֲמָר דְּקוּדְשָׁא בְּרִיךְ הוּא, אֲמַר דְּלֶהֱוֵוי לֵיהּ בְּנִין, דִּכְתִיב לְזַרְעֲךָ אֶתֵּן אֶת הָאָרֶץ הַזֹּאת. וּלְבָתַר אִיהוּ אֲמַר, וְהִנֵּה בֶן בֵּיתִי יוֹרֵשׁ אֹתִי.</p>"],[9514014199,"<p>שְׁפִיל לְרֵישֵׁיהּ דִּקְרָא, מַה כְּתִיב, (שם) וְאָנֹכִי הוֹלֵךְ עֲרִירִי. וּכְתִיב (שם) הֵן לִי לֹא נָתַתָּה זֶרַע וְהִנֵּה בֶן בֵּיתִי יוֹרֵשׁ אֹתִי. אֶלָּא בְּקַדְמִיתָא אַבְרָהָם הֲוָה הֵימִין בְּקוּדְשָׁא בְּרִיךְ הוּא, וַהֲוָה מִסְתַּכֵּל בְּכוֹכְבַיָיא וּבְהַנֵּי מַזָּלַיָּיא, וַהֲוָה חָזֵי דְּלָא יְהֵא לֵיהּ בַּר. בְּגִין דְּעַד כְּעָן לָא הֲוָה דָּבֵיק בִּדְבִיקוּ דְּמָארֵיהּ.</p>"],[9514014200,"<p>כֵיוָן דִּכְתִיב וַיּוֹצֵא אֹתוֹ הַחוּצָה, אַפֵּיק לֵיהּ מֵהַהוּא אוֹרַח, וְקָרֵיב לֵיהּ לְגַבֵּיהּ לְפוּלְחָנֵיהּ, לְמִנְדַע אוֹרְחִין אָחֳרָנִין דְּחָכְמְתָא, וְאַפֵּיק לֵיהּ מֵהַהוּא טִיּוּרֵי דְּמַזָּלֵי, וַאֲמַר לֵיהּ, אַבְרָם אֵינוֹ מוֹלִיד, אַבְרָהָם מוֹלִיד. וְדָא (בראשית י״ז:ה׳) וְלֹא יִקָּרֵא עוֹד אֶת שִׁמְךָ אַבְרָם וְהָיָה שִׁמְךָ אַבְרָהָם כִּי אַב הֲמוֹן גּוֹיִם נְתַתִּיךָ.</p>"],[9514014201,"<p>מַאי טַעְמָא, בְּגִין דְּלֵית בְּכָל אַתְוָון אָת דְּמִתְתַּקְּנָא לְאוֹלָדָא, בַּר אָת ה'. הַאי אָת, אִיהִי מִתְתַּקְּנָא לְמֶעְבַּד פֵּירִין וְאִיבִּין יַתִּיר מִכָּל שְׁאָר אַתְוָון. וּבְגִין כָּךְ אִיהִי פְּתִיחָא מִכָּל סִטְרִין.</p>"],[9514014202,"<p>וְאִי תֵימָא, אָת דָּא לָא אִצְטְרִיךְ לֵיהּ לְאַבְרָהָם לְאִתּוֹסְפָא לֵיהּ, דְּהָא לָאו דִּילֵיהּ הוּא, ה' אִיהִי נוּקְבָא בְּכָל אֲתַר, וְתֵינַח לְשָׂרָה לְמֶהֱוֵי אָת דָּא רְשִׁימָא בְּגַוָּוהּ.</p>"],[9514014203,"<p>אֶלָּא תְּרֵי ההי\"ן אִינוּן, חַד עִילָּאָה, וְחַד תַּתָּאָה. חַד עַלְמָא דִדְכוּרָא, וְחַד עַלְמָא תַּתָּאָה, דְּאִיהוּ עַלְמָא דְנוּקְבָא. כֵּיוָן דְּאִתּוֹסַף ה' בְּאַבְרָהָם, אוֹר קַדְמָאָה דְּהֲוָה הַאי ה' מִתְעַטֵף בֵּיהּ, נָפֵיק וַעֲבַד אִיבִּין. וְאִתְרְשִׁים אַבְרָהָם בְּהַהוּא דַרְגָּא עִילָּאָה דִּילֵיהּ, בְּחֵילָא דְּהַאי ה' עִילָּאָה, דְּהָא לֵית חֵילָא וְתוֹקְפָא לְהַהוּא אוֹר קַדְמָאָה, בַּר ה'. וּבְגִין כָּךְ נָטֵיל הַהוּא אוֹר קַדְמָאָה, אָת ה' עִמֵּיהּ, וְאִתְיַשֵּׁב בְּדַרְגֵּיהּ, דְּהָא סָלֵיק לְמֶהֱוֵי עָבִיד תּוֹלָדִין.</p>"],[9514014204,"<p>תְּרֵין אַתְוָון רְשִׁימִין הָכָא, דְּאִינוּן סְלִיקוּ לְעַלְמָא עִילָּאָה, וְאִינוּן ה\"ם. אָת ם' מֵעַלְמָא עִילָּאָה אִיהִי. מַאי בֵּינַיְיהוּ בֵּין אָת ם' וּבֵין אָת ה', דְּהָא תַּרְוַיְיהוּ מֵעַלְמָא עִילָּאָה אִינוּן.</p>"],[9514014205,"<p>אֶלָּא כַּד סָתִים כּוֹלָּא גּוֹ מַחְשָׁבָה עִילָּאָה, וְאִיהִי נְקוּדָה לָא אִתְפַּשְּׁטָא, וְאַסְתֵּים לְגוֹ. כָּל אִינוּן שְׁבִילִין עִילָּאִין, וְאַתְוָון סְתִימִין, אַסְתֵּים כּוֹלָא בְּאָת ם'. וַהֲווּ כָּל אִינוּן שְׁבִילִין וְאַתְוָון עִילָּאִין סְתִימִין כְּלִילָן בְּאָת דָּא. כֵּיוָן דְּסָלֵיק בִּרְעוּ לְאִתְגַּלָּאָה, וְלַאֲפָקָא תּוֹלָדִין, הַאי אָת ם' אִתְפַּתַּח, וְאִתְעֲבֵיד אָת ה'.</p>"],[9514014206,"<p>לָא אִשְׁתַּנּוֹ דָּא מִדָּא, אֶלָּא דְּאִתְפַּתַּח לַאֲפָקָא תּוֹלָדִין וּלְאִתְגַּלְּיָיא בִּלְחִישׁוּ. דְּהָא אָת דָּא לָא אִתְגַּלְּיָיא וְלָא אִדְכַּר. וְאַף עַל גַּב דְּאִיהִי בִּלְחִישׁוּ, הוּא בְּפוּם גַּלֵּי. וּבְגִין כָּךְ, בְּשַׁעֲתָא דְּאִתְגַּלֵּי וְאִתְפַּתַּח, כְּדֵי זַמִּין לְאוֹלָדָא.</p>"],[9514014207,"<p>דְּהָא בְּעוֹד דְּלָא קָיְימָא בִּפְתִיחוּ דְה', כּוֹלָּא סָתֵים בְּגַוָּוהּ בְּאָת ם'. לְבָתַר דְּאִתְפַּתַּח, עֲבֵיד תּוֹלָדִין בְּאוֹת ה'.</p>"],[9514014208,"<p>וְאִינוּן תּוֹלָדִין לָא נַפְקֵי לְבַר, בַּר בְּחַד אֵבָר, שַׁיְיפָא קַדִּישָׁא דְּאִתְתַּקַּן גַבֵּיהּ, וְעָאל בְּאָת ה' בַּתְרַיְיתָא. מֵאֵת ה' נָפֵיק, וּבְאָת ה' עַיִּיל, בְּהַהוּא אֵבָר דְּאִתְתַּקַּן גַּבֵּי ה' בַּתְרַיְיתָא.</p>"],[9514014209,"<p>וּבְשַׁעֲתָא דְּאִתְפַּתַּח, וְאִתּוֹסַף אָת דָּא, ה' עִילָּאָה, כְּדֵין אִתְתַּקַּן בְּתֵיאוּבְתָּא, וְהַאי אֵבָר צַדִּיקָא דְּעַלְמָא אִתְתַּקַּן עֲלֵיהּ. וְעַל דָּא, כַּד אִתְתַּקַּן הַאי אֵבָר בְּתֵיאוּבְתָּא, אִתּוֹסַף בֵּיהּ ה'. וְכַד אֵבָר דָּא לָא הֲוֵי בְּתֵיאוּבְתָּא, וַהֲוָה ם' בִּלְחוֹדוֹי, לְאִתְחֲזָאָה דְּהָא לָא קָיְימָא לְאוֹלָדָא.</p>"],[9514014210,"<p>וְרָזָא דָּא אַבְרָם, אבֶּן רִבִּי ם', דָּא אֵינוֹ מוֹלִיד, דְּהָא ם' סְתִימָא אִיהִי, וְלָא קָיְימָא לְאוֹלָדָא. כַּד אִתּוֹסַף ה', הַהוּא ם' אִתְפַּתַּח, וְאִתּוֹסַף ה', וְקָיְימָא בְּהַהוּא אֵבָר לְמֶעְבַּד תּוֹלָדִין. וְרָזָא דָא אַבְרָהָם, אבֶּן רִבִּי ה\"ם, דָּא, מוֹלִיד וַעֲבֵיד אִיבִּין.</p>"],[9514014211,"<p>וּבְגִין כָּךְ אַבְרָם אֵינוֹ מוֹלִיד, אַבְרָהָם מוֹלִיד. בְּגִין דְּהַהוּא אֵבָר לָא אִתְתַּקַּן עַד דַּאֲתֵי ה'. וּבְכָל אֲתַר ה\"א קָיְימָא לְתּוֹלָדִין וְאִיבִּין, וְעַל דָּא שְׁמָא גָּרִים.</p>"],[9514014212,"<p>וּמְנָא לָן דְּהַהוּא אֵבָר לָא אִתְתַּקַן אֶלָּא בְּגִין ה'. דְּהָא בְּזִמְנָא דְּהֲוָה שְׁמֵיהּ אַבְרָם, לָא אִתְגְּזַר הַהוּא אֵבָר, וְלָא אִתְתַּקַּן. בָּתַר דַּאֲתָא ה', אִתְתַּקַּן הַהוּא אֵבָר, וְאִתְגְּזַר, לְמֶעְבַּד אִיבִּין בְּהַהוּא ה' בַּתְרָאָה. וּבְעוֹד דְּאִיהוּ עַלְמָא עִילָּאָה סָתוּם בְּאָת ם', הַהוּא אֵבָר לָא אִתְתַּקַּן, וְקָיְימָא עָרְלָה בְּלָא גְזִירוּ.</p>"],[9514014213,"<p>וְהַרְגָּא תַּתָּאָה קָיְימָא מִגּוֹ עָרְלָה, בְּאָת ד', גּוֹ מִסְּכֵּנוּ. כַּד עַלְמָא עִילָּאָה גּוֹ סְתִימוּ בְּרָזָא דְאָת מ', עַלְמָא תַּתָּאָה בְּמִסְכֵּנוּ בְּרָזָא דְאָת ד'.</p>"],[9514014214,"<p>כַד אִתְפַּתַּח עַלְמָא עִילָּאָה מֵאָת ם', וְאִתְעֲבֵיד ה', כְּדֵין, אִתְתַּקַּן בְּרִית, וְאִתְעֲבַר עָרְלָה. וְכֵיוָן דְאִתְתַּקַּן הַאי בְּרִית, נָפְקִין אִלֵּין תְּרֵין אַתְוָון, וְעַיְילֵי אַתְוָון אוֹחֳרָנִין. נַפְקִין תְּרֵין אִלֵין ד\"ם.</p>"],[9514014215,"<p>וְכָל גְּזִירוּ דְלָא נָפֵיק מִינֵיהּ דָּם, לָאו אִיהוּ גְּזִירוּ. דְּהָא אִלֵּין מִתְעַבְרָן וְעַיְילִין תְּרֵין אָחֳרָנִין. בַּאֲתַר דְּאָת ם', עַיִּיל ה'. בַּאֲתַר דְּאָת ד', עַיִּיל ה'. כְּדֵין כּוֹלָא קָיְימָא לְאוֹלָדָא.</p>"],[9514014216,"<p>וְרָזָא דָא (ישעיהו ט׳:ו׳) לְםַ\"רְבֵּה הַמִּשְׂרָה וּלְשָׁלוֹם אֵין קֵץ עַל כִּסֵּא דָוִד וְעַל מַמְלַכְתּוֹ לְהָכִין אֹתָהּ וּלְסַעֲדָהּ. ם' רַבָּה, לְמַרְבֵּה. רָזָא דָא, כַּד לְאָת ם' רַבָּה הַמִּשְׂרָה, דְּאַסְגִּיאוּ רְבוּ עִילָּאָה, דְּאִתְפַּתַּח וְאִתְעֲבֵיד ה', כְּדֵין וּלְשָׁלוֹם אֵין קֵץ. מַאי וּלְשָׁלוֹם. אֶלָּא וּלְשָׁלוֹם, דָּא הַהוּא אֵבָר יְסוֹדָא דְּעָלְמָא, דְּאִתְעֲבַר מִנֵּיהּ עָרְלָה, הַהוּא דְּאִקְרֵי קֵץ כָּל בָּשָׂר, וַדַּאי וּלְשָׁלוֹם אֵין קֵץ, דְּהָא אִתְעֲבַר. וִיתֵיב שָׁלוֹם עַל כִּסֵּא דָוִד, וְעַל מַמְלַכְתּוֹ, לְהָכִין אֹתָהּ וּלְסַעֲדָהּ בְּמִשְׁפָּט וּבִצְדָקָה.</p>"],[9514014217,"<p>וְכָל דָּא, כַּד אִתְעֲבַר ם' וְאִתְפַּתַּח, כְּדֵין אִתְעֲבַר עָרְלָה, וְאִתְעֲבַר ד', כְּמָא דְאִתְּמָר. וְרָזָא דָא, (שמות כ״ד:ח׳) הִנֵּה דַם הַבְּרִית אֲשֶׁר כָּרַת ה'. דְּאִצְטְרִיךְ לַאֲפָקָא מִינֵיהּ דַּ\"ם בְּרִית, תְּרֵין אַתְוָון אִלֵּין.</p>"],[9514014218,"<p>וְעַל רָזָא דָא, אַבְרָהָם אֵבָר ה\"ם דְּאִתְפַּתַּח אָת ם', בְּגִין לְשַׁמָּשָׁא הַאי אֵבָר בְּעַלְמָא דִלְתַתָּא. וּבְגִין הַאי, יִצְחָק לָא נָפֵיק, עַד דְּאִתְעֲבַר עָרְלָה מֵהַהוּא אֵבָר קַדִּישָׁא עִילָּאָה. וּבְגִין כָּךְ, קוּדְשָׁא בְּרִיךְ הוּא כָּל מַה דַּעֲבַד בְּאַרְעָא, כּוֹלָּא אִיהוּ בְּרָזָא דְשִׁימּוּשָׁא כְּגַוְונָא עִילָּאָה, לְאַחֲזָאָה דְּהָא אַפֵּיק שְׁמָהָן כּוּלְהוּ בְּחָכְמְתָא עִילָּאָה, כְּגַוְונָא דְרָזָא דִלְעֵילָא, כֹּלָּא כִּדְקָא יָאוֹת.</p>"],[9514014219,"<p>(בראשית ט״ו:ד׳) וְהִנֵּה דְבַר ה' אֵלָיו לֵאמֹר לֹא יִירָשְׁךָ זֶה. מַאי טַעְמָא, בְּגִין דְּהֲוָה עֶבֶד מַשְׂכִּיל. וּכְדֵין אֲמַר, הֵן לִי לֹא נָתַתָּ זֶרַע וְהִנֵּה בֶן בֵּיתִי כו'. בְּגִין דְּהָא אִיהוּ הֲוָה מִסְתַּכֵּל וְחָמֵי בְּטִיּוּרֵי דְּלָא יוֹלִיד. וּבְשַׁעֲתָא דְאִתְגְּזַר אַבְרָהָם, אִשְׁתְּלֵים בְּכוֹלָּא בְּאָת הֵ\"א, דְּאִתְפַּתַּח מֵאָת ם' וְאָת ד' אוּף הָכֵי. כְּדֵין עָאל אַבְרָהָם בְּאוֹרַח דְּחָכְמְתָא, וְאִתְעֲבַר מֵהַהוּא אוֹרְחָא אָחֳרָא דְּכוֹכְבַיָא וּמַזָּלֵי.</p>"],[9514014220,"<p>תָּא חֲזֵי, בְּשַׁעֲתָא דְּהֲוָה בֵּיהּ עָרְלָה, דְּלָא אִתְגְּזַר, קוּדְשָׁא בְּרִיךְ הוּא לָא אִתְגְּלֵי לֵיהּ אֶלָּא בַּמַּחֲזֶה. בְּגִין דְּעַלְמָא עִילָּאָה הֲוָה סָתוּם בְּאָת ם', וְעַלְמָא תַּתָּאָה הֲוָה בְּמִסְכֵּנוּ בְּאָת ד'. כֵּיוָן דְּעַלְמָא עִילָּאָה אִתְפַּתַּח בְּאָת ה', וְאַבְרָהָם אַעֲבַר הַהוּא עָרְלָה, וְאִתְעֲבַר עַלְמָא תַּתָּאָה מֵהַהוּא ד', כְּדֵין כְּתִיב, וַיֵּרָא אֵלָיו ה', כְּדֵין אִתְגְּלֵי כּוֹלָּא, וְאִתְפַּתַּח מַאי דְלָא הֲוָה מִקַּדְמַת דְּנָא כְּדֵין.</p>"],[9514014221,"<p>כְהַאי גַוְונָא מַמָּשׁ, כָּל זִמְנָא דְּצַדִּיקֵי וַחֲסִידֵי אַסְגִּיאוּ בְּעָלְמָא, כְּדֵין כּוֹלָּא אִתְגַּלְּיָא וְאִתְפַּתַּח. בְּזִמְנָא דִּשְׁלֹמֹה מַלְכָּא בָּנָה בֵּי מַקְדְּשָׁא, וַהֲווּ יִשְׂרָאֵל כּוּלְהוּ צַדִּיקֵי וַחֲסִידֵי, שָׁקְטֵי כְּחַמְרָא עַל דּוּרְדַּיָּיה, כְּדֵין אִתְפַּתַּח כּוֹלָּא, וְאִתְגַּלֵּי שִׁירָתָא דָא עֵילָא וְתַתָּא.</p>"],[9514014222,"<p>בְּהַהוּא שַׁעֲתָא כְּתִיב, (שיר השירים א׳:ט׳) לְסֻסָתִי בְּרִכְבֵי פַרְעֹה דִּמִּיתִיךְ רַעְיָתִי. מַה סּוּסְוָותָא דִּרְתִיכִין דְּפַרְעֹה הֲווֹ מְזוּיָנִין בְּכָל זִינֵי קְרָבָא, אוּף הָכֵי אַנְתְּ הֲוֵית מִתְלַבְּשָׁא בְּכַמָּה זִינֵי קְרָבָא, לַאֲגָחָא קְרָבָא. וּמַה סּוּסָוָון דְּפַרְעֹה הֲווֹ טְעוּנִין בְּכַמָּה מָאנֵי זִינֵי קְרָבִין, אַבְנִין, גִּירִין, בְּלִסְטְרָאִין, קִסּוּרִין, כּוּלְהוּ טְעוּנִין לַאֲגָחָא קְרָבָא, אוּף הָכֵי אֲנָא בָךְ טָעֵינְנָא כָּל זִינֵי קְרָבִין, לַאֲגָחָא קְרָבִין, לְאִתְקַדְּשָׁא בָךְ לְעֵינֵיהוֹן דְּכוֹלָּא, וְלַאֲגָחָא קְרָבָא בְּהוֹן.</p>"],[9514014223,"<p>וְהַשְׁתָּא חָמֵינָא לָךְ בְּגַוְונָא אָחֳרָא, בְּכַמָּה תִּיקּוּנִין יָאִין, בְּכַמָּה תִּיקּוּנִין שַׁפִּירִין. נָאווּ לְחָיַיִךְ בַּתּוֹרִים, בִּתְרֵי הֵהִי\"ן, דְּהָא כּוֹלָּא אִתְפַּתַּח לְגַבָּיךְ וְאִתְגַּלְּיָיא. ה' עִילָּאָה חָדֵי בָךְ, וְיָאֵי לְקַבְּלָךְ, וְאִתְפַּתַּח. וְאַתְּ אִתְעֲבָרַת מֵאֵת ד', וְעַיְילַת בְּאָת ה'. וְאִלֵּין תְּרֵין, נָאווּ וְאִתְתַּקָּנוּ לְגַבָּיךְ, דְּאִינוּן תְּרֵין הֵהִי\"ן, אִינוּן תּוֹרִים, תּוֹרָה שֶׁבִּכְתָב וְתוֹרָה שֶׁבְּעַל פֶּה. צַוָּארֵךְ בַּחֲרוּזִים תִּיקּוּנִין עִילָּאִין, דְּכָל מְקוֹרִין דְּאִתְתַּקָּנוּ לְגַבָּךְ.</p>"],[9514014224,"<p>וְהָא אִיהוּ דְּאִיהוּ דְּכֵיר לְגַבָּהּ בַּחֲבִיבוּ וּרְחִימוּ סַגֵּי, בְּגִין דְּתֵיאוּבְתֵּיהּ לְגַבָּהּ, וּלְנַחֲמָהּ וּלְמַלָּלָא עַל לִבָּהּ, וּלְאַחֲזָאָה לָהּ רְחִימוּ סַגֵּי. וְעַל דָּא אֲמַר לְגַבָּהּ, תּוֹרֵי זָהָב וְגו', מִכָּאן וָאֵילָךְ אִית לְאוֹסָפָא לָךְ שַׁפִּירוּ עַל שַׁפִּירוּ, תִּיקּוּנִין עַל תִּיקּוּנִין.</p>"],[9514014225,"<p>כְתִיב, (שמות כ״ד:י״ב) וַיֹּאמֶר ה' אֶל משֶׁה עֲלֵה אֵלַי הָהָרָה וֶהְיֵה שָׁם וְאֶתְּנָה לְךָ אֶת לֻחֹת הָאֶבֶן וְהַתּוֹרָה וְהַמִּצְוָה אֲשֶׁר כָּתַבְתִּי לְהוֹרֹתָם. הַאי קְרָא אוֹקְמוּהָ חַבְרַיָיא. אֲבָל עֲלֵה אֵלַי הָהָרָה, זַכָּאָה חוּלָקָא דְּעַבְדָּא, דְּמָרֵיהּ סָלֵיק לֵיהּ לְגַבֵּיהּ בִּרְתִיכֵיהּ. הֲדָא הוּא דִכְתִיב, עֲלֵה אֵלַי הָהָרָה, הָהָרָה וַדַּאי. דְּהָא הָהָר מִבָּעֵי לֵיהּ.</p>"],[9514014226,"<p>וֶהְיֵ\"ה שָׁם, הָכָא אִתְמְסַר לֵיהּ לְמשֶׁה, מַה דְּלָא אִתְמְסַר לֵיהּ מִקַּדְמַת דְּנָא. דְּהָא הַהוּא שְׁמָא דִּרְתִיכָא קַדִּישָׁא, אִתְמְסַר לֵיהּ בִּידֵיהּ.</p>"],[9514014227,"<p>וְאִם תֹּאמַר הָא כְתִיב (שם ג) שַׁל נְעָלֶיךָ. וַדַּאי פַּקֵּיד לֵיהּ לְאִתְפְּרָשָׁא מֵאִתְּתֵיהּ מִכֹּל וָכֹל, אֲבָל זִוּוגָא אָחֳרָא לָא אִתְמְסַר לֵיהּ עַד הַשְׁתָּא. בְּשַׁעֲתָא דַּאֲמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, וֶהְיֵ\"ה שָׁם, כְּדֵין מְסַר לֵיהּ שְׁמָא גְלִיפָא, וַחֲקֵיק לֵיהּ לְגַבֵּי משֶׁה בְּאַרְעָא.</p>"],[9514014228,"<p>בְּקַדְמִיתָא כַּד הֲוָה בְּמִצְרַיִם, חָקַק בֵּיהּ שְׁמָא דֵּאלֹקִים, דִּכְתִיב (שמות ז׳:א׳) רְאֵה נְתַתִּיךָ אֱלֹהִים לְפַרְעֹה. שְׁמָא דָא וַדַּאי אִתְחֲקַק בֵּיהּ בְּשֵׁירוּתָא דִּנְבִיאוּתֵיהּ. כֵּיוָן דְּאִסְתַּלַּק בְּעִילוּיָיא אָחֳרָא, חֲקֵיק בֵּיהּ קוּדְשָׁא בְּרִיךְ הוּא שְׁמֵיהּ מַמָּשׁ, בְּגִין לְאִסְתַּלָּקָא עַל שְׁמָא דֵּאלֹהִים דְּהֲוָה בֵּיהּ בְּקַדְמִיתָא. וְהַשְׁתָּא חָקִיק בֵּיהּ שְׁמָא קַדִּישָׁא דִילֵיהּ, בְּגִין לְאִזְדַוְוגָא בֵּיהּ בִּשְׁמָא קַדְמָאָה, וּלְמֶהֱוֵי בְּאַרְעָא שְׁמָא שְׁלִים, כְּגַוְונָא דִלְעֵילָא, יהו\"ה אלהי\"ם, דְּהוּא שְׁמָא שְׁלִים.</p>"],[9514014229,"<p>וּשְׁמָא שְׁלִים הֲוָה בְּיוֹמֵי דְמשֶׁה בְּאַרְעָא. אֱלֹקִים, הַהוּא זִוּוּגָא דִילֵיהּ. יהו\"ה, שְׁמָא קַדִּישָׁא בֵּיהּ. וְעַד דְּלָא אִתְגְּלֵיף בֵּיהּ בְּמשֶׁה שְׁמָא דָא, לָא אִזְדַּוַּוג בֵּיהּ שְׁמָא דֵאלֹקִים. כֵּיוָן דִּכְתִיב עֲלֵה אֵלַי הָהָרָה, אִתְיְהֵיב לֵיהּ רְשׁוּ לְמֵיתַב עַל כּוּרְסְיָיא דְמַלְכָּא. כְּדֵין כַּד מַלְכָּא יָהֵיב לֵיהּ כּוּרְסְיֵיהּ, יָהֵיב לֵיהּ שְׁמֵיהּ מַמָּשׁ, דִּכְתִיב וֶהְיֵ\"ה שָׁם, אֲנַח לֵיהּ בְּאַתְרֵיהּ בְּכוֹלָּא.</p>"],[9514014230,"<p>בִּתְרֵין דַּרְגִּין סָלֵיק משֶׁה בְּהַהוּא זִמְנָא, מַה דְּלָא אִסְתַּלֵיק הָכֵי בַּר נָשׁ בְּעָלְמָא. אִתְיְהיב לֵיהּ כּוּרְסְיָיא דְמַלְכָּא, וּמַלְכָּא מְסַר לֵיהּ שְׁמֵיהּ, זַכָּאָה חוּלָקֵיהּ דְּמשֶׁה.</p>"],[9514014231,"<p>וְאֶתְּנָה לְךָ אֶת לֻחוֹ\"ת הָאֶבֶן, וְהָא אוֹקְמוּהָ לֻחוֹת הָאֶבֶן כְּמַשְׁמָעָן. אֶלָּא כָּל מַפְתְּחָן אִתְמָסְרוּ לֵיהּ לְמשֶׁה. מַשְׁמַע דִּכְתִיב וְאֶתְּנָה לְךָ, לְ\"ךָ וַדַּאי. דְּהָא כַּד אִסְתַּלַּק בִּשְׁמָא דָא וֶהְיֵ\"ה שָׁם, וְאִתְמְסַר לֵיהּ כּוּרְסְיָיא דְמַלְכָּא, כְּדֵין אַעֲטַר לֵיהּ בְּכוֹלָּא, לְמֶהֱוֵי תִּיקּוּנָא שְׁלִים, תִּיקּוּנָא עִילָּאָה.</p>"],[9514014232,"<p>וְהַתּוֹרָה וְהַמִּצְוָה, אִלֵּין תְּרֵין דְּרוֹעִין, מִסִּטְרָא דָא, וּמִסִּטְרָא דָא. אֲשֶׁר כָּתַבְתִּי, אִלֵּין תְּרֵין יַרְכִין. לְהוֹרוֹתָם, דָּא אִיהוּ דַּרְגָּא יְסוֹדָא חָדָא, דְּמִינֵיהּ נָפְקִין כָּל טַעֲמִין, לְאַעֲנָאָה לְתַתָּא, וְכֹלָּא אִתְמְסַר לֵיהּ לְמשֶׁה, בְּגִין לְאַעֲטָרָא לֵיהּ בְּרָזָא עִילָּאָה, לְמֶהֱוֵי תְּרֵין שְׁמָהָן גְּלִיפָן, דְּאִינוּן שְׁמָא שְׁלִים בְּאַרְעָא.</p>"],[9514014233,"<p>וְעַל דָּא אֲמַר דָּוִד מַלְכָּא, (תהילים מ״ו:ט׳) לְכוּ חֲזוּ מִפְעֲלוֹת אֱלֹהִים אֲשֶׁר שָׂם שַׁמּוֹת בָּאָרֶץ. אַל תִּקְרֵי שַׁמּוֹת, אֶלָּא שֵׁמוֹת. אִינוּן תְּרֵין שְׁמָהָן, דְּאִינוּן שְׁמָהָן גְּלִיפָן, וְסָלְקָן לִשְׁמָא שְׁלִים, לְמֶהֱוֵי שְׁמָא שְׁלִים בְּאַרְעָא, כְּגַוְונָא דִלְעֵילָא.</p>"],[9514014234,"<p>כֵיוָן דְּאָתָא שְׁלֹמֹה, וְאִתְבְּנֵי בֵּי מַקְדְּשָׁא, מַה כְּתִיב. (דברי הימים א כ״ט:כ״ג) וַיֵּשֶׁב שְׁלֹמֹה עַל כִּסֵּא יהו\"ה לְמֶלֶךְ. כְּדֵין הַאי כִּסֵּא אִתְעַטְרָא עֵילָא וְתַתָּא, וְסָלְקָא בְּתוּשְׁבַּחְתָּא לְגַבֵּי עֵילָא.</p>"],[9514014235,"<p>כֵיוָן דְּסָלְקָא בְּתוּשְׁבַּחְתָּא, אוֹשִׁיט לָהּ מַלְכָּא יָמִינָא, לְקַבְּלָא לָהּ. וְקַבֵּיל לָהּ בֵּין דְּרוֹעוֹי, וַאֲמַר לָהּ מִילֵי דִרְחִימוּ, וּפַקֵּיד לְמֵיהַב לָהּ מַתְּנָן וּנְבַזְבְּזָן וִיקָר סַגֵּי, וַאֲמַר (שיר השירים א׳:י״א) תּוֹרֵי זָהָב נַעֲשֶׂה לָךְ עִם נְקוּדוֹת הַכָּסֶף. תּוֹרֵי זָהָב, אִינוּן פִּסּוּקֵי טַעֲמֵי. בְּגִין דְּאִינוּן אוֹלְפִין אוֹרַח לְאַעֲנָאָה, אִי לְיָמִינָא וְאִי לִשְׂמָאלָא.</p>"],[9514014236,"<p>וְעַל מָה אִקְרוּן תּוֹרֵי. בְּגִין דְּכַד מָטָא תּוֹר וְזִמְנָא דְהַאי דַרְגָּא, לְמֵיהַב לָהּ עַל יְדָא דְהַהוּא יְסוֹדָא. עָבִיד בָּהּ רְשִׁימוּ לְאַעֲנָאָה, וּלְמֵהַךְ בְּהַהוּא אוֹרַח דְּבָעֵי לְמֵהַךְ. וְכֵן כַּד דַּרְגָּא אָחֳרָא, מָטָא תּוֹר וְזִמְנָא לְמֵיהַב בָּהּ, עָבִיד בָּהּ רְשִׁימוּ בְּגַוְונָא אָחֳרָא, לְאַעֲנָאָה וּלְמֵהַךְ בְּהַהוּא אוֹרַח מַמָּשׁ. וְעַל רָזָא דָא, (הושע י״ד:י׳) יְשָׁרִים דַּרְכֵי ה'. אִלֵּין אִינוּן תְּנוּעֵי דְטַעֲמֵי, כָּל חַד וְחַד כִּדְקָא חָזֵי לֵיהּ.</p>"],[9514014237,"<p>תּוֹרֵי זָהָב, בְּגִין דְּטַעֲמֵי הָכֵי תַּלְיָין עַל אַתְוָון, כְּמָא דְתַלְיָין נְזוֹרִין דְּנִזְמִין עַל גַּבֵּי אוּדְנִין. כְּגוֹן תַּלְשָׁא, וּשְׁאָר תְּנוּעֵי דְּאִינוּן נִזְמִין וְנָזוֹרֵי, דְּתִיקּוּנִין דְּאַתְוָון.</p>"],[9514014238,"<p>תֵּיבִין בְּלָא טַעֲמֵי, וְלָא אִית בְּהוּ תְּנוּעֵי, הָכֵי אִינוּן כְּאוּדְנִין דְּכַלָּה, בְּלָא נְזוֹרִין וַעֲגוֹלִין, וּשְׁלִילָא מִתִּקּוּנָא. תֵּיבִין בְּלָא נְקוּדֵי, אִינוּן כְּאִתְּתָא בְּלָא לְבוּשִׁין, דְּלָא יָכְלָא לְמֵיהַךְ לַאֲתַר דְּעָלְמָא. בְּגִין כָּךְ תִּיקּוּנֵי דְּאַתְוָון, אִינוּן טַעֲמֵי וּתְנוּעֵי. אִלֵּין וְאִלֵּין תִּיקּוּנִין וּמַלְבּוּשִׁין אִינוּן לְאַתְוָון. וְעַל דָּא תּוֹרֵי זָהָב, אִינוּן תְּנוּעֵי דְּטַעֲמֵי.</p>"],[9514014239,"<p>וּמַה דַּאֲמַר זָהָב, בְּגִין דְּאִינוּן אַתְיָין מֵרֵישָׁא דְמַלְכָּא, לְמֵיהַב דַּעְתָּא וְסֻכְלְתָנוּ לְאַתְוָון כָּלְהוֹ. בְּגִין כָּךְ כּוּלְהוּ בְּרָזָא חָדָא קָיְימִין.</p>"],[9514014240,"<p>נְקוּהֵי וְטַעֲמֵי, תְּרֵין דַּרְגִּין אִינוּן, אִלֵּין וְאִלֵּין אִצְטְרִיכוּ לְאִתְתַּקְּנָא בְּהוּ אַתְוָון. אַתְוָון אִינוּן רְשִׁימִין בְּרָזִין עִילָּאִין, דְּהָא כּוּלְהוּ נַפְקָן מֵרָזָא דְּחָכְמְתָא עִילָּאָה, בְּאִינוּן תְּלָתִין וּתְרֵין שְׁבִילִין דְּנָפְקָא מֵחָכְמְתָא.</p>"],[9514014241,"<p>וְאַתְוָון כּוּלְהוּ חֲקִיקִין לְתַתָּא, וְיָרְתָא לוֹן תּוֹרָה שֶׁבְּעַל פֶּה. וְכַד כּוּלְהוּ אַתְיָין לְאִתַּקְנָא לָהּ בְּרָזָא דְּאִינוּן אַתְוָון, עַבְדֵּי בָהּ נְקוּדֵי וְטַעֲמֵי, כְּמָה דְּאִתְּמָר. וְעַל דָּא תּוֹרֵי זָהָב וכו'.</p>"],[9514014242,"<p>וְהָכָא רָזִין עִילָּאִין, לְאִינוּן דְּיָדְעֵי מִדִּין. אַתְוָון כּוּלְהוּ רְשִׁימִין בְּרָזָא, וְאִקְרוּן גּוּפֵּי תּוֹרָה, דְּקָיְימִין לְמֵילַף וּלְמִנְדַע בְּרָזִין עִילָּאִין.</p>"],[9514014243,"<p>נְקוּהִין אִינוּן נָפְקִין מֵרָזָא דְּמוֹחָא, לְקָיְימָא אַתְוָון עַל תִּיקּוּנַיְיהוּ, וּבִנְקוּדָה חָדָא אִשְׁתַּנֵּי תֵּיבָה, וְאַעֲבַר לְהַהִיא תֵּיבָה מִקִּיּוּמָהּ, בְּגַוְונָא אָחֳרָא.</p>"],[9514014244,"<p>בּוּצִינָא דְּקַרְדִינוּתָא, כַּד בָּטַשׁ הַהוּא אֲוִירָא דַּכְיָא בְּמוֹחָא, בָּטַשׁ וְלָא בָּטַשׁ, מָטָא לְגַבֵּיהּ דְּהַהוּא מוֹחָא, וְאִסְתַּלֵּיק מִנֵּיהּ, מָטָא וְלָא מָטָא. כְּדֵין הַהוּא בְּטִישׁוּ נָפֵיק לְגַבֵּי אַתְוָון מִגּוֹ מוֹחָא, וְאַתְוָון אִתְנְקִידוּ.</p>"],[9514014245,"<p>וְאִם תֹּאמַר, נְקוּדֵי תִּיקּוּן סוֹפְרִים הוּא. חַס וְשָׁלוֹם. דְּאֲפִילּוּ כָּל נְבִיאֵי דְּעָלְמָא יְהוֹן כְּמשֶׁה, דְּקַבֵּיל אוֹרַיְיתָא מִטוּרָא דְסִינַי, לֵית לוֹן רְשׁוּ לְחַדְתָּא אֲפִילּוּ חָדָא נְקוּדָה זְעֵירָא בְּאָת חַד, אֲפִילּוּ אָת זְעֵירָא דְּאוֹרַיְיתָא.</p>"],[9514014246,"<p>כֵיוָן דְּהַהוּא בְּטִישׁוּ אִתְיַישֵׁב בְּמוֹחָא, מִגּוֹ אֲוִירָא דַכְיָא דְּאִתְּפַס, בְּגִין דְּאִית אֲוִירָא דַכְיָא דְּלָא אִתְּפַס כְּלָל. וְהַאי דְּאִתְּפַס כַּד אִתְיַישֵׁב בְּהַאי מוֹחָא, הַהוּא בְּטִישׁוּ עִילָּאָה. כְּדֵין נָפְקֵי כָּל תְּנוּעֵי דְטַעֲמֵי, וְאִינוּן טַעֲמֵי כְּמֶתֶג לְסוּסְיָא, לְמֵהַךְ בְּאוֹרַח מֵישַׁר, לְיָמִינָא, וְלִשְׂמָאלָא, לְכָל רְעוּתָא דְּטַעֲמֵי אָזְלֵי, וּפָסְקֵי, וְתָבֵי, וּמְרַהֲטֵי, אָזְלֵי בְּגַאֲוָתָא, וּבְשִׁפְלֵי, וְלֵית רְשׁוּ לְכָל אַתְוָון לְמֵהַךְ לְסִטְרָא דָא וּלְסִטְרָא דָא, בַּר בִּרְשׁוּ, כְּמָה דְטַעֲמֵי מְדַבְּרֵי לוֹן. וּמִלָּה בְּגִינֵהוֹן אִשְׁתְּמַע, בְּגִין לְמֵהַךְ בְּאוֹרַח מֵישַׁר.</p>"],[9514014247,"<p>וְעַל דָּא, אַתְוָון כָּלְהוֹ אַתְיָין לְמֵיהַךְ בְּרָזָא דְהַנֵּי תְּרֵין. בִּנְקוּדֵי וְטַעֲמֵי כַּחֲדָא. וְרָזָא דָא, (משלי כ״ה:י״א-י״ב) תַּפּוּחֵי זָהָב בְּמַשְׂכִּיּוֹת כָּסֶף דָּבָר דָּבֻר עַל אָפְנָיו. תַּפּוּחֵי זָהָב, אִינוּן טַעֲמֵי וּתְנוּעֵי. בְּמַשְׂכִּיּוֹת כָּסֶף, אִלֵּין נְקוּדֵי. דָּבָר דָּבֻר עַל אָפְנָיו, דְּהָא לֵית מִלָּה כִּדְקָא יָאוֹת, לְבַר בִּתְרֵין אִלֵּין. וּבְגִין כָּךְ, תּוֹרֵי זָהָב נַעֲשֶׂה לָךְ.</p>"],[9514014248,"<p>כְתִיב (בראשית א) וַיֹּאמֶר אֱלֹהִים נַעֲשֶׂה אָדָם בְּצַלְמֵנוּ כִּדְמוּתֵנוּ וְיִרְדּוּ וְגו'. הַאי קְרָא אִתְעָרוֹ בֵּיהּ חַבְרַיָּיא, וַדַּאי קוּדְשָׁא בְּרִיךְ הוּא אֲמַר דָּא, לְמַשִּׁרְיָין עִילָּאִין, וְאִתְיְיעֵט בְּהוּ לְמִבְרֵי אָדָם כְּמַלְכָּא גּוֹ חֵילוֹי.</p>"],[9514014249,"<p>אֲבָל אִית לְאִסְתַּכָּלָא, אִי בְּרָזָא דִלְעֵילָא הֲוָה, דְּהַאי אֱלֹהִים אִיהוּ אֱלֹהִים חַיִּים, רָזָא דְעָלְמָא עִילָּאָה. וְאִי אִיהוּ אֱלֹהִים רָזָא דְעַלְמָא תַּתָּאָה. אֵיךְ אִתְתַּקַּן נַעֲשֶׂה לְהַאי סִטְרָא וּלְהַאי סִטְרָא.</p>"],[9514014250,"<p>אֶלָּא וַדַּאי, כּוֹלָּא אִיהוּ כְּגַוְונָא חָדָא, וּבְרָזָא חָדָא. אָדָם כָּלֵיל בְּכָל סִטְרִין, רָזָא דִילֵיהּ אִיהוּ בְּכוֹלָא, וּמֵרָזָא דֵּאלֹהִים אִשְׁתַּכַּח אָדָם. וְלָא אִשְׁתַּכַּח מֵרָזָא דִּשְׁאָר שְׁמָהָן. הֲדָא הוּא דִכְתִיב, (בראשית א) וַיִּבְרָא אֱלֹהִים אֶת הָאָדָם בְּצַלְמוֹ בְּצֶלֶם אֱלֹהִים. בְּצַלְמוֹ בְּצֶלֶם, תְּרֵין צַלְמִין אַמַּאי אִינוּן. אֶלָּא חַד לִדְכוּרָא, וְחַד לְנוּקְבָא.</p>"],[9514014251,"<p>תְּרֵין אֱלֹהִים הָכָא, חַד דְּכַר, וְחַד נוּקְבָא. בְּצַלְמוֹ, דְּכַר. בְּצֶלֶם אֱלֹהִים, נוּקְבָא. וְעַל דָּא וַיִּבְרָא אֱלֹהִים אֶת הָאָדָם בְּצַלְמוֹ, דָּא עַלְמָא עִילָּאָה. בְּצֶלֶם אֱלֹהִים, דָּא עַלְמָא תַּתָּאָה. וְרָזָא דָא נַעֲשֶׂה, כְּלָלָא חָדָא. כִּדְקָא אֲמָרָן.</p>"],[9514014252,"<p>בְּשַׁעֲתָא דְאִתְבְּרֵי אָדָם, אַתְוָון כָּלְהוֹ אִתְבְּרִיאוּ, אִתְגְּלִימוּ, וְאִצְטַיְירוּ. בְּשַׁעֲתָא דְּאִתְנְשֵׁיב בֵּיהּ רוּחָא, נָפְקוּ נְקוּדֵי וְאִתְיַישְׁבוּ בְּאַתְוָון. בְּשַׁעֲתָא דְּאִתְתַּקַּן בְּסוּכְלְתָנוּ וּבְמַדָּע, נָפְקוּ תְּנוּעֵי דְּטַעֲמֵי וְאִתְיַישְׁבוּ עַל נְקוּדֵי וְאַתְוָון. וְכָל תִּיקּוּנָא דְּרָזָא דְאָדָם הָכֵי אִיהוּ, בְּכָל סִטְרִין דְּעָלְמָא. בְּרָזָא דְאָדָם, אִתְיַישֵׁב כּוֹלָּא כְּמָא דְּאִתְּמָר. וְלֵית אָדָם, בַּר בְּכָל הַנֵּי תִּיקּוּנִין.</p>"],[9514014253,"<p>אָמַר לֵיהּ אֵלִיָּהוּ, ר', אַפְתַּח פּוּמָךְ, וִינַהֲרָן מִילָךְ. דִּרְשׁוּ דִלְעֵילָא אִתְמְסַר בִּידָךְ. פָּתַח וְאָמַר, (בראשית א) בְּרֵאשִׁית בָּרָא אֱלֹהִים. הַאי קְרָא אוֹקִימְנָא לֵיהּ בְּכַמָּה דוּכְתֵּי. אֲבָל תָּא חֲזֵי, עַל רָזָא דְּעִיקָּרָא דָא כִּדְקָא אֲמָרָן, דְּהָא אִי יֵיתוּן כָּל נְבִיאֵי מְהֵימְנֵי דְּעָלְמָא, וְיִסְתַּלְּקוּן בִּנְבוּאַתְהוֹן בִּסְלִיקוּ דִּנְבוּאָה דְמשֶׁה, לָא יָכְלִין לְחַדְתָּא אֲפִילּוּ חָדָא נְקוּדָה דְּאוֹרַיְיתָא.</p>"],[9514014254,"<p>מַאי טַעְמָא, בְּגִין דְּאַתְוָון כּוּלְהוּ לָא נָפְקוּ אֶלָּא מִגּוֹ נְקוּדָה זְעֵירָא, וְאַתְוָון אִינוּן כְּלָלָא דְאוֹרַיְיתָא. וְהָא לֵית לְכָל אַתְוָון רְשׁוּ לְנַטְלָא לְהַאי סִטְרָא וּלְהַאי סִטְרָא, בַּר בִּנְקוּדֵי.</p>"],[9514014255,"<p>אַתְוָון כּוּלְהוּ, כְּגוּפָא בְּלָא נַפְשָׁא. כַּד אַתְיָין נְקוּדֵי, הָא גוּפָא אִתְקַיַּים בְּקִיּוּמֵיהּ, וּכְדֵין (בראשית ב׳:ז׳) וַיְהִי הָאָדָם לְנֶפֶשׁ חַיָּה כְּתִיב. וְכָלְהוֹ מֵרָזָא דְּחַד נְקוּדָה נָפְקֵי.</p>"],[9514014256,"<p>בְּשַׁעֲתָא דְּאַתְוָון נָפְקוּ מִגּוֹ עַלְמָא דְאָתֵי, כּוּלְהוּ אַגְלִימוּ בְּרָזָא דְאָדָם, וַהֲווּ גוּפָא בְּלָא נַפְשָׁא.</p>"],[9514014257,"<p>עַד דְּאִתְעַר הַאי נְקוּדָה עִילָּאָה, וְעָאל בִּטְמִירוּ גּוֹ עַלְמָא דְאָתֵי. וְנָפְקוּ נְקוּדֵי כּוּלְהוּ, מִגּוֹ הַאי נְקוּדָה, לְקַיְימָא אַתְוָון עַל קִיּוּמַיְיהוּ. וְדָא אִיהוּ בְּרֵאשִׁית בָּרָא אֱלֹהִים, רֵאשִׁית דָּא נְקוּדָה עִילָּאָה, דְּבָהּ בָּרָא אֱלֹהִים, וְאַתְקֵין כָּל נְקוּדֵי תִּיקּוּנֵי דְאַתְוָון, דְּאִינוּן רָזָא דְּשָׁמַיִם וָאָרֶץ. וְאִי לָא הַאי רֵאשִׁית, רָזָא דִּנְקוּדָה עִילָּאָה, לָא אִתְנְקִידוּ אַתְוָון, וְלָא הֲוָה בְּהוּ קִיּוּמָא.</p>"],[9514014258,"<p>דָּבָר אַחֵר בְּרֵאשִׁית, בְּהַאי רֵאשִׁית רָזָא דִּנְקוּדָא עִילָּאָה, בָּרָא אֱלֹהִים, בְּחֵילָא דְהַאי נְקוּדָה, נָפְקוּ אַתְוָון, וְאִצְטַיְירוּ בְּתִיקּוּנַיְיהוּ, לְמֶהֱוֵי רָזָא דְגוּפָא בְּשַׁיְיפִין יְדִיעָן, בְּלָא נַפְשָׁא. וּבְגִין כָּךְ כְּתִיב בָּרָא, בְּגִין דְּלָא נָפַק נַפְשָׁא לְגוּפָא לְקָיְימָא בְּקִיּוּמֵיהּ.</p>"],[9514014259,"<p>כֵיוָן דְּאִתְעַר נְקוּדָה עִילָּאָה, גּוֹ עַלְמָא דְאָתֵי, לַאֲפָקָא נְקוּדֵי נַפְשָׁא, כְּדֵין כְּתִיב, (בראשית א׳:ג׳) וַיֹּאמֶר אֱלֹהִים יְהִי אוֹר, אִתְנְהִירוּ אַתְוָון בִּנְקוּדֵי, דְּאִינוּן נַפְשָׁא.</p>"],[9514014260,"<p>אוֹר, דָּא נְקוּדָה קַדְמָאָה, דְּנָהֵיר מִגּוֹ הַהִיא נְקוּדָה עִילָּאָה סְתִימָא, דְּסָתִים וְלָא יְדִיעַ. נְקוּדָה דָא, דְּנָהֵיר מִגּוֹ הַהִיא סְתִימָא דָא, נְקוּדָה דְאִיקְרֵי חוֹלָם, דְּנָהֵיר לְעֵילָא עַל כָּל אַתְוָון, בְּגִין יְקָרָא דִּנְקוּדָה סְתִימָא.</p>"],[9514014261,"<p>וּבְגִין דְּאַתְוָון כּוּלְהוּ, אִתְכְּנָשׁוּ בַּחֲמֵשׁ מְאָה פַּרְסֵי דְעַלְמָא דְאָתֵי, נָהֵיר נְקוּדָה דָא חָמֵשׁ זִמְנִין. וְרָזָא דָא, וַיֹּאמֶר אֱלֹהִים יְהִי אוֹר. וַיְהִי אוֹר. וַיַּרְא אֱלֹהִים אֶת הָאוֹר כִּי טוֹב. וַיַּבְדֵּל אֱלֹהִים בֵּין הָאוֹר וּבֵין הַחשֶׁךְ. וַיִּקְרָא אֱלֹהִים לָאוֹר יוֹם.</p>"],[9514014262,"<p>יְהִי אוֹר דָּא נְקוּדָה חוֹלָם. וַיְהִי אוֹר, דָּא נְקוּדָה אָחֳרָא דְּאִקְרֵי שֻׁרֻק. בְּגִין דִּנְקוּדָה קַדְמָאָה דְאִיקְרֵי חֹלָם, נָהֵיר לְעֵילָא, וְעַד דְּלָא אִתְמְשַׁךְ לְאַנְהָרָא לְתַתָּא, הֲוָה סָתִים. כֵּיון דְּאִתְמְשַׁךְ נָהֵיר גּוֹ אֶמְצָעִיתָא, בְּרָזָא דְּשֻׁרֻק. (בראשית א׳:ד׳) וַיַּרְא אֱלֹהִים אֶת הָאוֹר כִּי טוֹב, דָּא חִרִק. כַּד נָהֵיר לְתַתָּא.</p>"],[9514014263,"<p>בְּזִמְנָא דְּנָפְקוּ נְקוּדִין לְאַנְהָרָא לְגוּפָא, אוֹר קַדְמָאָה דְּאִיהוּ חֹלָם, נָהֵיר לְעֵילָא, וְאִתְיַישֵׁב בְּרֵישָׁא דְגוּפָּא, וְיָהֵיב נְהִירוּ לְכָל רֵישָׁא: לְאַנְפִּין. לְעַיְינִין. לִנְהִירוּ דְרֵישָׁא, לְכָל תִּיקּוּנֵי רֵישָׁא.</p>"],[9514014264,"<p>וְשֻׁרֻק שָׁארֵי בְּאֶמְצָעִיתָא, וְזָהֵיר נָהִירוּ לְקִיּוּמָא דְגוּפָא מִמַּרְאֶה מָתְנָיו וּלְמַעְלָה, בְּכָל רָזִין דִּילֵיהּ.</p>"],[9514014265,"<p>חִרִק שָׁארֵי לְתַתָּא, וְיָהֵיב נְהִירוּ וְקִיּוּמָא מִמַּרְאֶה מָתְנָיו וּלְמַטָה, בְּכָל תִּיקּוּנִין וְרָזִין דִּילֵיהּ. כְּדֵין וַיַּרְא אֱלֹהִים אֶת הָאוֹר כִּי טוֹב.</p>"],[9514014266,"<p>כַד אִתְתַּקַּן גּוּפָא דְּאַתְוָון בְּאִלֵּין נְקוּדִין, כְּדֵין כְּתִיב, (בראשית א׳:ד׳) וַיַּבְדֵּל אֱלֹהִים בֵּין הָאוֹר וּבֵין הַחשֶׁךְ. לְעוֹלָם הַבְדָּלָה בִּדְרוֹעָא דִשְׂמָאלָא, דְּאִית בֵּיהּ חשֶׁךְ. וְאַנְהֵיר בִּנְקוּדַת סֶגוֹל, לְאַנְהָרָא מִגּוֹ חֲשׁוֹכָא וְלוּאֵי.</p>"],[9514014267,"<p>וַיִּקְרָא אֱלֹהִים לָאוֹר יוֹם, דָּא נְקוּדַת צֵרֵי, דְּאַנְהֵיר וְאִתְיַשֵּׁב בִּדְרוֹעָא יָמִינָא, וְאַתְקֵין לֵיהּ בְּכָל תִּיקּוּנוֹי.</p>"],[9514014268,"<p>וְכַד נוּקְבָא אִתְדַּבְּקַת בְּיָמִינָא וּשְׂמָאלָא, וְאִתְיְהֵיבַת בֵּינַיְיהוּ, אִתְדַּבְּקוּ בָּהּ תְּרֵין נְקוּדִין אִלֵּין צֵרֵ\"י וְסֶגוֹל. בְּקִיּוּמָא וְהִפּוּכָא אָחֳרָא, דְּלָא מִתְיַישְׁבָן בָּהּ הָכֵי. צֵרֵי אִתְהַפֵּךְ וְאַנְהֵיר בָּהּ בִּדְיוֹקְנָא אָחֳרָא, בְּלָא יִישׁוּבָא כִּדְכוּרָא, וְאִיהוּ שְׁבָא. וְסֶגוֹל אִתְהַפַּךְ וְאַנְהֵיר בָּהּ בִּדְיוֹקְנָא אָחֳרָא, וְאִיהוּ שֻׁרֻק דִּתְלַת נְקוּדִין. וּלְאַחֲזָאָה חֲבִיבוּ דִדְכוּרָא לְגַבֵּי נוּקְבָא, אִיהוּ וְאִיהִי כּוֹלָּא חַד, לְזִמְנִין דְּאַנְהֵיר בְּהוּ דְכוּרָא. מֵהָכָא אִתְפַּשְּׁטוּ נְקוּדֵי לְכָל שְׁאָר שַׁיְיפִין דְּאַתְוָון בְּגוּפָא.</p>"],[9514014269,"<p>(בראשית א׳:ו׳) וַיֹּאמֶר אֱלֹהִים יְהִי רָקִיעַ בְּתוֹךְ הַמָּיִם, דָּא נְקוּדָה פַּתָּח. פְּשִׁיטוּ דִּנְהִירוּ דְּאַנְהֵיר בְּסִטְרָא דִדְכוּרָא, בִּסְטַר שְׂמָאלָא, וְאַנְהֵיר לְהַהוּא סִטְרָא, וְהַשְׁתָּא אִתְחֲלִיפוּ, וְאִתְכְּלִלוּ יָמִינָא בִּשְׂמָאלָא, וּשְׂמָאלָא בְּיָמִינָא.</p>"],[9514014270,"<p>מַיִם אִיהוּ לְיָמִינָא, בְּרָזָא דְהַהִיא נְקוּדָה דְּאַנְהֵיר בָּהּ צֵרֵי, בְּסִטְרָא דָא דְּיָמִינָא, אִתְפְּלִיגוּ תְּרֵין מִיָּמִין, וְהָא אוֹקִימְנָא. וּבְגִין כָּךְ, צֵרֵי, תְּרֵין נְקוּדִין מִתְיַישְׁבָן מִיָּמִין, לָקֳבֵיל תְּרֵין, חַד לְעֵילָא וְחַד לְתַתָּא, כְּמָה דְּאִתְחֲזֵי בִּנְקוּדַת שְׁבָ\"א.</p>"],[9514014271,"<p>לְבָתַר, כֵּיוָן דְּאִתְנְהֵיר הַאי רָקִיעַ, דְּאִיהוּ נְקוּדָה דְּאִיקְרֵי פַּתָּח, עָאל הַאי נְקוּדָה בֵּין נְקוּדָה לִנְקוּדָה דְּצֵרֵי, בֵּין מַיִם לָמָיִם, וְאַפְרֵישׁ בֵּינַיְיהוּ, וְנָטֵיל לוֹן לְגַבֵּיהּ. וּכְדֵין מַיִם לִסְטַר שְׂמָאלָא בִּנְקוּדַת פַּתָּח. וְעַל רָזָא דָא, (דברים כ״ח:י״ב) יִפְתַּח ה' לְךָ אֶת אוֹצָרוֹ הַטוֹב וכו', לָתֵת מְטַר וכו', דְּהָא מַיִם מִסִּטְרָא דְּפַתָּח אִינוּן.</p>"],[9514014272,"<p>תּוּ אִתְפַּשַּׁט רָקִיעַ מִסִּטְרָא דְיָמִינָא, וְעָאל בִּסְטַר שְׂמָאלָא, בֵּין נְקוּדַת סֶגוֹל וְאִתְעֲבֵיד קָמַץ. וְעָאל כְּדֵין שְׂמָאלָא בְּיָמִינָא, וְאִתְכְּלֵיל דָּא בְּדָא, יָמִינָא בִּשְׂמָאלָא וּשְׂמָאלָא בְּיָמִינָא.</p>"],[9514014273,"<p>(בראשית א׳:ט׳) וַיֹּאמֶר אֱלֹהִים יִקָּווּ הַמַּיִם, לְעֵילָא כְּתִיב מַיִם חָמֵשׁ זִמְנִין. (שם) יְהִי רָקִיעַ בְּתוֹךְ הַמָּיִם. וִיהִי מַבְדִּיל בֵּין מַיִם לָמָּיִם. וַיַּבְדֵּל בֵּין הַמַּיִם כו'. וּבֵין הַמַּיִם. הָא חָמֵשׁ זִמְנִין מַיִם, לָקֳבֵיל תְּרֵין נְקוּדִין דְּאִינוּן חָמֵשׁ, צֵרֵי וְסֶגוֹל. צֵרֵי תְּרֵין, וְסֶגוֹל תְּלָתָא, הָא חָמֵשׁ אִלֵּין מִתְיַישְׁבָן בְּיָמִינָא וּשְׂמָאלָא.</p>"],[9514014274,"<p>נוּקְבָא עָאלַת בֵּין יָמִינָא וּשְׂמָאלָא, וּמְקַבְּלָא לְאִלֵּין נְקוּדִין, לְמֵיהַב לָהּ דַּעְתָּא בִּשְׁלִימוּ. וְלָא מִתְיַישְׁבָן בֵּיהּ הָכֵי, וּמִתְהַפְּכָן בֵּיהּ בְּאֹרַח קָלִיל. צֵרֵי, אִתְהַפַּךְ בָּהּ לִנְקוּדָה שְׁבָא, בְּאוֹרַח קָלִיל. סֶגוֹל, אִתְהַפַּךְ בָּהּ לִנְקוּדָה שׁוּרֻק בְּאוֹרַח קָלִיל.</p>"],[9514014275,"<p>וּלְעוֹלָם אִתְּתָא דַעְתָּהּ קָלִיל עֲלָהּ, דְּהָא לָא יָכִילוּ לְאִתְיַשְּׁבָא בָּהּ לְמֶהֱוֵי בָּהּ דַּעְתָּהּ שְׁלִים, כְּמָה דְאִינוּן לְעֵילָא. אֶלָּא אַהֲדָרוּ בָהּ בְּאוֹרַח קָלִיל, וְאִשְׁתְּכַח דַּעְתָּהּ קַלָּה עֲלָהּ. כְּמָה דְאִינוּן תְּרֵין נְקוּדֵי צֵרֵי סֶגוֹל אִינוּן חָמֵשׁ, אוּף הָכֵי בָהּ שְׁבָא שֻׁרֻק אִינוּן חָמֵשׁ, אֲבָל בְּלָא יִישׁוּבָא כְּלָל.</p>"],[9514014276,"<p>יִקָּווּ הַמַּיִם, אִינוּן חָמֵשׁ כּוּלְהוּ, לִנְקוּדָה חָדָא, דְּאִיהִי נְקוּדַת שׁוּרֻק, דְּקָיְימָא תְּחוֹת רָקִיעַ, קָמַץ. כָּל אִינוּן מַיִין דְּהַאי סִטְרָא, וְהַאי סִטְרָא, כָּל אִינוּן חָמֵשׁ נְקוּדִין מִתְיַישְׁבָן בְּהַאי נְקוּדָה. וְדָא אִתְיַישְׁבַת, וְנָהֵיר לִבְרִית קַדִּישָׁא דְּבִדְּכוּרָא. וְכָל נְהוֹרָא דַּחֲמֵשׁ נְקוּדִין כּוּלְהוּ יָרִית דָּא.</p>"],[9514014277,"<p>כֵיוָן דְּהַאי יָרִית כּוּלְהוּ, כְּדֵין אִתְנְהִירַת נוּקְבָא, לְמֶעְבַּד פֵּירִין וְאִיבִּין. דִּכְתִיב, (בראשית) תַּדְשֵׁא הָאָרֶץ דֶּשֶׁא וְגו'. בְּחֵילָא דְהַאי נְקוּדָה דְּקָיְימָא לְתַתָּא, דְּעָבִיד בָּהּ פֵּירִין וְאִ יבִּין.</p>"],[9514014278,"<p>(שם א) וַיֹּאמֶר אֱלֹהִים יְהִי מְאֹרֹת בִּרְקִיעַ הַשָּׁמַיִם, דָּא נְקוּדַת חֲטָף קָמַץ, דְּנָהֵיר נְהִירוּ, כְּגַוְונָא דְהַהוּא אוֹר קַדְמָאָה, נְקוּדַת חֹלָם. וְעַל דְּלָא אַנְהֵיר בְּיִשּׁוּבָא, כְּגַוְונָא דִילֵיהּ, אִיהוּ מְאֹרֹת חָסֵר, דְּלָא נָהֵיר בְּיִשּׁוּבָא, כְּגַוְונָא דְחֹלָם אַף עַל גַּב דְּקָיְימָא בְּגַוְונָא דִילֵיהּ.</p>"],[9514014279,"<p>(שם) וַיֹּאמֶר אֱלֹהִים יִשְׁרְצוּ הַמַּיִם שֶׁרֶץ נֶפֶשׁ חַיָּה, דָּא אִיהוּ, בְּרָזָא דִּנְקוּדַת שְׁבָ\"א סֶגוֹ\"ל. דְּהָא סֶגוֹ\"ל אִתְכְּלֵיל מַיִין בְּאֶשָׁא. רַחֲשִׁין רְחִישׁוּ דְּהַהוּא נֶפֶשׁ חַיָּה, הַהוּא דַעְתָּא דְּאִתְיְהֵיב לָהּ מִתְּרֵין סִטְרִין, אִיהוּ קַלָּה עֲלָהּ, וְדָא אִקְרֵי שֶׁרֶץ דְּנֶפֶשׁ חַיָּה, רְחִישׁוּ דְּרָחֵישׁ וְנָפֵיק וְאָזֵיל בְּכָל נְקוּדֵי.</p>"],[9514014280,"<p>וְתָא חֲזֵי, שְׁבָ\"א אִיקְרֵי מָהִיר צֶדֶק, וְהָכֵי אִיהו. וּבְגִין כָּךְ אִיקְרֵי נֶפֶשׁ דְּהַהִיא חַיָּה, שֻׁרֻק דִּתְלַת נְקוּדִין. בְּשַׁעֲתָא דְּאָת ו' אִסְתַּלַּק מִינָהּ, אֲפֵיקַת דַעְתָּא הַהִיא דְּנָטְלָה מִגּוֹ עֵילָא, כְּמָא דְאִתְּמָר, וּבְאַתְרֵיהּ דְּאָת ו', אַפֵּיק שֻׁרֻק, וְהָכֵי אִיהוּ בְּכָל אֲתַר.</p>"],[9514014281,"<p>וְעַל דָּא, נְקוּדֵי כּוּלְהוּ קָיְימִין לְאַנְהָרָא לְאַתְוָון, כְּעוֹבָדָא דִשְׁמַיָא וְאַרְעָא וְכָל עָלְמִין כּוּלְהוּ. וְלֵית קִיּוּמָא וּנְהִירוּ לְכָל אַתְוָון, בַּר בִּנְהִירוּ דִּנְקוּדֵי, וְכוֹלָּא אִתְמְסַר בְּרָזָא דְאוֹרַיְיתָא בְּסִינַי. וְהָכֵי אִיהוּ בְּרָזָא דִלְעֵילָא, וְכֹלָּא תִּיקּוּנָא דְאָדָם, כְּמָה דְאִתְּמָר.</p>"],[9514014282,"<p>(בראשית א׳:כ״ו) וַיֹּאמֶר אֱלֹהִים נַעֲשֶׂה אָדָם בְּצַלְמֵנוּ כִּדְמוּתֵנוּ, כְּתִיב (תהילים ל״ז:כ״ג) מֵה' מִצְעֲדֵי גֶבֶר כּוֹנָנוּ וְדַרְכּוֹ יֶחְפָּץ. תָּא חֲזֵי, כַּד בְּרָא קוּדְשָׁא בְּרִיךְ הוּא עַלְמָא עִילָּאָה וְעַלְמָא תַּתָּאָה, כּוֹלָּא בִּדְיוֹקְנָא חָדָא הֲוָה, לְמֶהֱוֵי דָא כְּגַוְונָא דְדָא. בְּשַׁעֲתָא דְּבָעָא קוּדְשָׁא בְּרִיךְ הוּא לְמִבְרֵי אָדָם לְתַתָּא, בָּעָא לְמֶעְבַּד לֵיהּ כְּגַוְונָא דִתְרֵין עָלְמִין.</p>"],[9514014283,"<p>וְכָל רָזִין דִּלְעֵילָא וְתַתָּא, כֹּלָּא אִיהוּ בְּאָדָם. גּוּלְגַּלְתָּא דְּרֵישָׁא דְּקָיְימָא עַל גּוּפָא, אִיהוּ בְּרָזָא דְעַלְמָא עִילָּאָה, בְּאִינוּן תִּיקּוּנִין דְּרֵישָׁא. גּוּפָא אִיהוּ בְּרָזָא דְגוּפָא, דְּקָיְימִין דַּרְגִּין בְּשַׁיְיפִין יְדִיעָן תְּחוֹת הַאי רֵישָׁא. יַרְכִין וְרַגְלִין, כּוֹלָא בְּדַרְגִּין דִּלְתַתָּא, כִּדְקָא חָזֵי לֵיהּ לְמֶהֱוֵי כְּגַוְונָא דִלְעֵילָא. כָּל דְּיוֹקְנִין עִילָּאִין וְתַתָּאִין, כּוּלְהוּ חֲקֵיק קוּדְשָׁא בְּרִיךְ הוּא בָּאָדָם, לְמֶהֱוֵי אִיהוּ שְׁלִים בְּכוֹלָא.</p>"],[9514014284,"<p>תָּא חֲזֵי, מֵה' מִצְעֲדֵי גֶבֶר כּוֹנָנוּ, כַּד קוּדְשָׁא בְּרִיךְ הוּא אִתְרְעֵי בֵּיהּ בְּבַר נַשׁ, כָּל צַעֲדוֹי וְכָל אוֹרְחוֹי אִינְהוּ מִתְתַּקְנָן קַמֵּיהּ, וְאִיהוּ מְתַקֵּן לְהוֹ כָּל חַד וְחַד כִּדְקָא יָאוֹת. וְדַרְכּוֹ יֶחְפָּץ, אֲפִילּוּ בְּמִילֵי דְעָלְמָא.</p>"],[9514014285,"<p>תּוּ. מֵה' מִצְעֲדֵי גֶבֶר כּוֹנָנוּ, אִי בַּר נַשׁ יְשַׁוֵּי דַעְתֵּיהּ וּרְעוּתֵיהּ וְלִבֵּיהּ לְגַבֵּי מַלְכָּא קַדִּישָׁא, לְמֵהַךְ בָּתַר אוֹרְחֵיהּ דְּאִיהוּ עָבִיד. קוּדְשָׁא בְּרִיךְ הוּא אִתְרְעֵי בֵּיהּ, כְּאִילּוּ הוּא דִילֵיהּ מַמָּשׁ.</p>"],[9514014286,"<p>בְּשַׁעֲתָא דְּנָפְקוּ אַתְוָון מִגּוֹ רָזָא עִילָּאָה, כְּמָא דְאִתְּמָר, וְאִתְגְּלִימוּ, וְאִצְטַיְירוּ בִּדְיוֹקְנָא דְאָדָם. לְבָתַר נָפְקוּ נְקוּדֵי, וְאַנְשֵׁיב בְּהוּ רוּחָא דְחַיֵּי, וְאִתְקַיְימוּ אַתְוָון, כְּבַר נָשׁ דְּקָאִים עַל רַגְלוֹי בְּקִיּוּמָא דְרוּחָא.</p>"],[9514014287,"<p>לְבָתַר דִּנְקוּדֵי אִתְקַיְּימוּ עַל אַתְוָון, וְיָהֲבוּ בְהוֹ נַפְשָׁא, אִצְטְרִיךְ לְמֶהֱוֵי בְּדַעְתָּא וְסוּכְלְתָנוּ, וּלְנַטְלָא בְּמַטְלָנוֹי, וּלְמֵיהַב מְזוֹנָא וְתוֹקְפָא לְאַחֲרָא. וְדָא אִיהִי בְּצַלְמֵנוּ כִּדְמוּתֵנוּ. כְּמָא דְאוֹקִימְנָא, בְּצַלְמֵנוּ דָא רָזָא דְעַלְמָא עִילָּאָה. כִּדְמוּתֵנוּ דָּא רָזָא דְעַלְמָא תַּתָּאָה.</p>"],[9514014288,"<p>דָּבָר אַחֵר, בְּצַלְמֵנוּ: אִלֵּין תְּנוּעֵי דְטַעֲמֵי, דְּאִינוּן תִּיקּוּנָא וּשְׁלִימוּ, בְּדַעְתָּא וְסוּכְלְתָנוּ, לְמִנְדַע יְדִיעָה לְאִסְתַּכְּלָא לְעֵילָא, כְּמָה דְאִיהוּ סָתִים וְלָא אִתְגַלְּיָיא.</p>"],[9514014289,"<p>כְמַלְכָא דְּאִיהוּ חַכִּים בְּסוּכְלְתָנוּ בְּחָכְמְתָא, וְלָא נָטֵיל לְסִטְרָא דָא אוֹ לְסִטְרָא דָא, בַּר בְּחָכְמְתָא וּבְסוּכְלְתָנוּ וּבְמִנְדַע. אוּף הָכֵי, כְּגַוְונָא דָא, תְּנוּעֵי דְטַעֲמֵי, כּוּלְהוּ מַטְלָנֵיהוֹן בְּחָכְמְתָא וּבְסֻכְלְתָנוּ וּבְמִנְדַע, כְּמָה דְאִתְחֲזֵי. וְדָא אִיהוּ בְּצַלְמֵנוּ.</p>"],[9514014290,"<p>כִדְמוּתֵנוּ, אִלֵּין רָזִין דִּנְקוּדֵי, דְּאִינוּן נָפְקוּ מִגּוֹ דִּיוּקְנָא חָדָא דִנְקוּדָה עִילָּאָה, מֵהַהוּא דִּיוּקְנָא סְתִימָא דְּלָא אִתְחֲזֵי, וּמִגּוֹ דְּנָפְקֵי מִגּוֹ נְקוּדָה חָדָא אִקְרוּן נְקוּדֵי דְמוּת, דִּיוּקְנָא דִּנְקוּדָה עִילָּאָה.</p>"],[9514014291,"<p>דְּאִי תֵימָא אַתְוָון. לָאו הָכֵי, דְּהָא דְיוֹקְנָא, לָאו אִיהוּ לְעֵילָא, וְלָא תַּלְיָיא תַּמָּן דִּיוּקְנָא, דְּהָא לְבָתַר דְּנָפְקֵי מֵרָזָא דְעַלְמָא עִילָּאָה, אַגְלִימוּ וְאִצְטַיְירוּ כּוּלְהוּ, מַה דְּלָא הֲוַת מִקַּדְמַת דְּנָא, דְּלָאו אִית דִּיוּקְנָא וְצִיּוּרָא לְעֵילָא כְּלַל, וְעַל דָּא לָא יְדִיעַ, וְלֵית מַאן דְּיָדַע בֵּיהּ כְּלוּם.</p>"],[9514014292,"<p>רֵאשִׁיתָא סְתִימָא דְאִתְגַלְּיָיא, וְלָא יְדִיעַ, חַד נְקוּדָה סְתִימָא אִיהוּ. וְהַהוּא נְקוּדָה, לָא יְדִיעַ, וְלָא אִתְגַּלְּיָא, וְלֵית מַאן דְּיָדַע בָּהּ. אֲבָל אַתְוָון, לָא בָהּ אִתְצַיְירָן, וְלָא תַּלְיָין לְעֵילָא, דְּהָא לֵית תַּמָּן דִּיוּקְנָא כְּלַל. וְעַל דָּא, כִּדְמוּתֵנוּ אִלֵּין נְקוּדֵי. בְּצַלְמֵינוּ, אִלֵּין תְּנוּעֵי, דְּאִיהוּ שְׁלִימוּ דְּכֹלָּא.</p>"],[9514014293,"<p>רָזָא הָכָא לְיָדְעֵי מִדִּין. תְּנוּעֵי דְאִיהוּ שְׁלִימוּ דְּכֹלָּא, אָן אִינוּן בְּבַר נָשׁ. אֶלָּא רָזָא דָּא בְּצַלְמֵנוּ, הָא אִיהוּ צוּלְמֵי דְבַר נַשׁ מִלְּגוֹ וּלְבַר. לְגוֹ, סוּכְלְתָנוּ וּמַדַּע וְחָכְמָה. לְבַר, הַהוּא צוּלְמָא דְאָזְלָא עֲלֵיהּ, וּמְדַבְּרָא לֵיהּ לְבַר נַשׁ בִּנְטִירוּ, לְמֶהֱוֵי נָטֵיר מִכֹּלָּא. בְּעוֹד דְּהַנֵּי תְּנוּעֵי אִינוּן בְּבַר נָשׁ, בַּר נָשׁ אִיהוּ שְׁלִים בְּכֹלָּא. כְּגַוְונָא דָא בְּכָל אִינוּן רָזִין עִילָּאִין דִּלְעֵילָא.</p>"],[9514014294,"<p>וְרָזָא דָא, מֵה' מִצְעֲדֵי גֶבֶר כּוֹנָנוּ, לְמֵיטַל בְּמַטְלָנוֹי, בְּאִינוּן תְּנוּעִין דְּטַעֲמֵי. וְדַרְכּוֹ יֶחְפָּץ, בְּאִינוּן נְקוּדֵי. מֵה', מִינֵיהּ אִתְנְטֵיל רָזָא דָא, לְמֶהֱוֵי לְתַתָּא כֹּלָּא כְּגַוְּונָא חָדָא וְרָזָא חָדָא.</p>"],[9514014295,"<p>מֵה' מִצְעֲדֵי גֶבֶר כּוֹנָנוּ, כְּגוֹן אַזְלָא מַקְפָא שׁוֹפָר הוֹלֵךְ, דְּאִינוּן מִצְעֲדֵי גֶבֶר, דְּמִתְתַּקְּנָן כָּל חַד וְחַד כִּדְקָא חָזֵי לֵיהּ, וְדָא אִיהוּ כּוֹנָנוּ. וּשְׁאָר תְּנוּעֵי, אִינוּן דִּכְתִיב, וְדַרְכּוֹ יֶחְפָּץ, הֵן בִּזְקִיפוּ, הֵן לְמֵיזַל, הֵן לְמִיפְסַק, הֵן לְנַגְנָא בְּחֶדְוָוא, הֵן לְמִשְׁתַּק, הֵן לְמֵיהַב דִּינָא. כֹּלָּא אִיהוּ מִנְדַע וְסוּכְלְתָנוּ לְמֵיטַל בְּמַטְלָנוֹי כִּדְקָא יָאוֹת.</p>"],[9514014296,"<p>זַרְקָא, דָּא אִיהוּ נִיגוּנָא בְּחֶדְוָה, כַּד אָתֵי בּוּצִינָא דְקַרְדִינוּתָא, בְּהַהוּא בְּטִישׁוּ דְּגוֹ אֲוִירָא דַכְיָא דְּלָא אִתְפַּס, יָהֵיב חֲדוּ וְחֶדְוָה, וְזָרֵיק מֵרָחוֹק, לְנַגְנָא בְּחֶדְוָה, לְמַאן דְּלָא יְדִיעַ וְלָא אִתְפַּס כְּלָל, וְקָאִים בְּקִיּוּמֵיהּ, וְלָא אִתְיַשֵּׁב לְמִנְדַע, עַד דְּקָרֵיב בְּסֻכְלְתָנוּ יַתִּיר. וְכֵן תְּנוּעֵי כּוּלְהוּ, כָּל חַד וְחַד כִּדְקָא יָאוֹת.</p>"],[9514014297,"<p>וְעַד לָא מָטוֹ אִלֵּין תְּנוּעֵי, כָּל אִינוּן שַׁיְיפִין דְּגוּפָא, לָא יָכְלִין לְנַטְלָא בְּמַטְלָנִין. דְּהָא כָּל שַׁיְיפִין דְּגוּפָא אִתְפַּלְּגוּ בְּאַתְוָון, דְּאִינוּן עֶשְׂרִין וּתְרֵין אַתְוָון, דְּאִתְגָּלְמוּ בְּפִרְקִין וְשַׁיְיפִין.</p>"],[9514014298,"<p>תְּרֵיסַר שַׁיְיפִין, אִינוּן פָּרְקִין דְּנָטְלִין. וְאִלֵּין תְּרֵיסַר לָא נָטְלִין בְּמַטְלָנִין כִּדְקָא יָאוֹת, בַּר בְּרָזָא דִתְרֵיסַר תְּנוּעֵי, דְּכוּלְהוּ עָבְדִין לְהַנֵּי פִּרְקִין לְנַטְלָא לוֹן. וְאִית תְּנוּעֵי אָחֳרָנִין, לְמֵיהַב סוּכְלְתָנוּ וְחָכְמָה וּמַדָּע לְכָל גּוּפָא, וּלְנַטְלָא כָּל גּוּפָא, וּלְמֵיהַב חֶדְוָה לְעֵילָא וְתַתָּא כּוֹלָּא כִּדְקָא חָזֵי.</p>"],[9514014299,"<p>עֶשְׂרִין וּתְרֵין אַתְוָון, אִינוּן כְּלָלָא דְרָזָא דְגוּפָא. וְכָלְהוֹ אִתְפַּלְּגוּ בְּשַׁיְיפִין דְּגוּפָא. וּמֵרָזָא דְאַתְוָון, גּוּפָא אִשְׁתְּלִים. אִשְׁתָּאֲרוּ אַתְוָון אָחֳרָנִין, דְּאִינוּן עֶשֶׂר. תְּרֵיסַר אַתְוָון אִינוּן קַדְמָאֵי, דְּאִינוּן שַׁיְיפִין קִיּוּמָא דְּכָל גּוּפָא, לְמֶהֱוֵי כָּל שַׁיְיפָא וְשַׁיְיפָא עַל תִּיקוּנֵיהּ.</p>"],[9514014300,"<p>וְאַף עַל גַּב דְּאִית בְּהוּ בְּאַתְוָון, אַתְוָון דְּאִתְחֲזוּן בִּדְכוּרָא, וְאַתְוָון דְּאִתְחֲזוּן בְּנוּקְבָא. כְּגוֹן א' דְּכוּרָא, ב' נוּקְבָא. ג' דְּכוּרָא, ד' נוּקְבָא. ה' נוּקְבָא, ו' דְּכוּרָא. וְכֵן אַתְוָון כּוּלְהוּ אָחֳרָנִין, מִנְּהוֹן כְּלִילָן בִּדְכוּרָא, וּמִנְהוֹן כְּלִילָן בְּנוּקְבָא. וְאִי תֵימָא, אִי הָכֵי, אֵיךְ אִתְבְּנֵי אָדָם בְּרָזָא דְּעֶשְׂרִין וּתְרֵין אַתְוָון, דְּהָא כַּד אִסְתַּכְּלָן, וְאִתְבְּרִירוּ אַתְוָון דְּאִצְטְרִיכוּ וְאִתְחֲזוּן לִדְכוּרָא, לֵית בַּר תְּרֵיסַר, לָקֳבֵיל תְּרֵיסַר שַׁיְיפִין.</p>"],[9514014301,"<p>אֶלָּא וַדַּאי, אַתְוָון כּוּלְהוּ כְּלִילָן בְּרָזָא דִדְכוּרָא, וְאִינוּן עֶשְׂרִין וּתְרֵין אַתְוָון, אַתְוָון דְּכוּרֵי וְאַתְוָון נוּקְבֵי. בְּגִין דְּשַׁיְיפִין כּוּלְהוּ, אִית שַׁיְיפָא בְּאִינוּן פִּרְקִין, דְּאִינוּן כְּלִילָן דָּא בְּדָא, וְעַיִּיל דָּא בְּדָא. מַאן דְּעַיִּיל אִיהוּ דְּכַר, הַהוּא דִמְקַבֵּל לֵיהּ בְּגַוֵּיהּ, אִיהִי נוּקְבָא.</p>"],[9514014302,"<p>בְּכָל שַׁיְיפִין אִית דְּכַר וְנוּקְבָא. וְעַיִּיל דָּא בְּדָא, כִּדְכוּרָא בְּנוּקְבָא. וּבְגִין כָּךְ, כָּלְהוֹ אַתְוָון סָלְקִין בְּרָזָא דִדְכוּרָא וְנוּקְבָא. וְאַתְוָון כּוּלְהוּ אִצְטְרִיךְ אִלֵּין לְאִלֵּין, וּלְאִתְחַבְּרָא אִלֵּין בְּאִלֵּין. אָעֵיל דָּא בְּדָא, כִּדְכוּרָא בְּנוּקְבָא.</p>"],[9514014303,"<p>כ\"ב אַתְוָון אָחֳרָנִין כְּלִילָן בְּנוּקְבָא לְתַתָּא, וְאִינוּן אַתְוָון זְעֵירִין. דְּהָא כַּד אִתְחַבַּר דְּכַר בְּנוּקְבָא, בְּתֵיאוּבְתָּא דִּבְכָל אַתְוָון דְּשַׁיְיפִין כּוּלְהוּ, לְגַבֵּי נוּקְבָא, אַטֵיל בָּהּ רָזָא דְּאַתְוָון, בְּאִינוּן מַיִין דִּילָהּ, וּלְבָתַר אַקְרִימוּ שָׁמַיִם דְּאַגְלִימוּ אַתְוָון, וְנָפְקֵי אַתְוָון אָחֳרָנִין כְּגַוְונָא דְאִלֵּין. וְעַל דָּא אִית אַלְפָא בֵיתָא דְּאַתְוָון עִילָּאִין רַבְרְבִין. וְאִית אַלְפָא בֵיתָא דְּאַתְוָון דַּקִּיקִין.</p>"],[9514014304,"<p>א' אִיהוּ חַד, וְרָזָא דְחַד, נָפֵיק וְאַגְלִים בְּרָזָא דִלְתַתָּא, שַׁיְיפִין עִילָּאִין דְּאִתְחַבְּרָן בְּחַד, וְאִינוּן חַד. וְעִם כָּל דָּא, לָאו אִיהוּ אֶלָּא שַׁיְיפָא חָד.</p>"],[9514014305,"<p>בְּגִין דְּכַד נָפְקָא א', וְאִתְיְהֵיבַת בָּרֹאשׁ, נָפְקָא בְּהַהוּא דְיוֹקְנָא דְּהַנְהוּ אָחֳרָנִין דְּאִצְטְרִיכוּ לְאִתְחַבְּרָא בַּהֲדֵיהּ, וְכַד נָפַק א', אַחֲזֵי לִתְרֵין דַּרְגִּין אָחֳרָנִין, דְּאִצְטְרִיכוּ לְאִתְחַבְּרָא בַּהֲדֵיהּ, דְּאִינוּן שְׂמָאלָא וְאֶמְצָעִיתָא, וְכוּלְהוּ אִתְאֲחָדוּ כַּחֲדָא, וְאִתְחֲזוּן בִּדְיוֹקְנָא דִילֵיהּ. כֵּיוָן דְּאִשְׁתַּכָּחוּ וְאִתְיַישְׁבוּ בְּדוּכְתַּיְיהוּ אִינוּן תְּרֵין שַׁיְיפִין אָחֳרָנִין, אִתְהֲדַר א' וְאִתְיַישֵׁב בְּדוּכְתֵּיהּ בָּרֹאשׁ, בְּסִטְרָא דְּיָמִינָא.</p>"],[9514014306,"<p>הֵיךָ עֲבַד קוּדְשָׁא בְּרִיךְ הוּא. כַּד אַתְוָון נָפְקוּ, אָת קַדְמָאָה דְּנָפֵיק, רֵישׁ לְכָל אַתְוָון, אִיהִי א'. מָה עֲבַד קוּדְשָׁא בְּרִיךְ הוּא. אִתְעַטַף בְּהַהוּא אָת, וּבְרָא שָׁמַיִם. וְאָת דָּא בְּרָא בֵּיהּ קוּדְשָׁא בְּרִיךְ הוּא, רָזָא דְיִיחוּדָא, דְּאִינוּן תְּלַת דַּרְגִּין, וְאִינוּן שָׁמַיִם, רָזָא חַד. כְּמָא דְאוֹקִימְנָא, וְהָא אִתְּמָר. כֵּיוָן דְּאִתְבְּרוּ שָׁמַיִם בְּרָזָא דָא, עַד לָא הֲווֹ קְרִישׁוּ וְלָא גְלִידוּ שָׁמַיִם, דְּהָא טְמִירִין הֲווֹ גּוֹ מַיָיא, רָזָא דְאָת א', דְּאִיהוּ לְיָמִינָא.</p>"],[9514014307,"<p>לְבָתַר דְּאַקְרִישׁוּ מִגּוֹ מַיָיא, נָפְקַת אָת ו', מִתְצַיְירָא בְּצִיּוּרָא, דִּגְלִימוּ בִּדְיוֹקְנָא דְאָדָם. וְעִם כָּל דָּא לָא חָסַר מֵהַהוּא דִּיוּקְנָא דְּאָת א' כְּלוּם, וְאִתְהַדַּר וְאִתְיַישֵׁב בְּדוּכְתֵּיהּ.</p>"],[9514014308,"<p>שָׁארֵי נְהִירוּ דְהַאי אָת לְאַנְהָרָא מֵרֵישָׁא דְעַלְמָא לִסְיָיפֵי עַלְמָא. גָּנֵיז לֵיהּ נְהוֹרֵיהּ בְּאָת אָחֳרָא, וַעֲבֵיד לְהַאי אָת בַּיִ\"ת חָד, לְאַגְנָזָא נְהוֹרֵיהּ בְּגַוֵּיהּ, וְאִתְגְּנֵיז הַהוּא אוֹר בְּגַוֵּיהּ.</p>"],[9514014309,"<p>וּמֵהַהִיא שַׁעֲתָא, אִתְגְּנֵיז וְאִיטְמַר, וְלָא נָפֵיק לְעָלְמָא, בַּר בְּחַד שְׁבִיל דַּקִּיק, דְּאִמְשַׁךְ חַד חוּטָא מִינֵיהּ, וּמִינֵיהּ אִתְּזָן עָלְמָא, וְקָאִים בְּקִיּוּמֵיהּ.</p>"],[9514014310,"<p>מֵהַאי אָת אִתְבְּנֵי כּוֹלָּא. מֵהַאי אָת אִתְּזַן כּוֹלָּא. בְּאָת דָּא נָטֵיר לוֹן קוּדְשָׁא בְּרִיךְ הוּא לְיִשְׂרָאֵל, וְאִתְּבַר שַׂנְאֵיהוֹן קַמַּיְיהוּ. הֲדָא הוּא דִכְתִיב, (שמות ט״ו:ו׳) יְמִינְךָ ה' נֶאְדָּרִי בַּכֹּחַ יְמִינְךָ ה' תִּרְעַץ אוֹיֵב. בְּשַׁעֲתָא דְּגָרְמוּ חוֹבִין, מַה כְּתִיב. (איכה ב׳:ג׳) הֵשִׁיב אָחוֹר יְמִינוֹ. כְּדֵין בְּהַהוּא זִמְנָא אִתְגְּלוּן יִשְׂרָאֵל מֵאַרְעָא, וְשָׁלְטוּ בְּהוֹן שׂוֹנְאֵיהוֹן.</p>"],[9514014311,"<p>א' אִתְיַישֵׁב בִּדְרוֹעָא, בְּרָזָא וְתוּקְפָא וְחֵילָא, דְּאִינוּן תְּרֵין סִטְרִין אָחֳרָנִין דְּאִתְתַּקְפוּ בֵּיהּ, וְאִיהוּ דְרוֹעָא דְיָמִינָא. ב' אִתְכְּלֵיל בְּגַוָּוהּ, וְכָנֵישׁ לֵיהּ לְקִבְלֵיהּ, כְּנוּקְבָא דְּעַיִּיל בְּגַוָּהּ דְּכוּרָא. בְּגִין כָּךְ אַתְוָון כּוּלְהוּ, חַד דְּכַר, וְחַד נוּקְבָא.</p>"],[9514014312,"<p>א', אִתְפַּשַּׁט לְאַתְוָון אָחֳרָנִין, וְאִשְׁתְּלִימוּ בִּשְׁלִימוּ, לְנַטְלָא תְּרֵין דַּרְגִּין אָחֳרָנִין אָלֶף, לְמֶהֱוֵי שְׁלִימוּ דִילֵיהּ. וְרָזָא דָא וְהַחוֹנִים עָלָיו מַטֵה פְּלוֹנִי. וְהַחוֹנִים עָלָיו, תְּרֵי דַרְגִּין בְּחַד.</p>"],[9514014313,"<p>עַד דְּסָלְקִין אַתְוָון, לְשִׁתִּין רִבּוֹא, כְּחוּשְׁבַּן שִׁבְטֵיהוֹן דְּיִשְׂרָאֵל, דְּאִינוּן תְּרֵיסַר, וְסָלְקִין לְשִׁתִּין רִבּוֹא. אוּף הָכֵי אַתְוָון, כַּד אִתְמָלוֹ סָלְקִין לְשִׁתִּין. אָלֶף בֵּית גִּימְל דָּלֶת הֵא וָו זָיִן חֵית טֵת יוּד כָּף לָמֶד מֶם נוּן סָמֶךְ עַיִן פֵּא צַדִּי קוּף רֵישׁ שִׁין תָּו. אִלֵּין אִינוּן סְלִיקוּ דְּאַתְוָון, לְשִׁיתִּין רִבּוֹא. בְּגִין לְמֶהֱוֵי שְׁלִימוּ בְּרָזָא דְּאַתְוָון, בְּשַׁיְיפֵי כּוּלְהוּ.</p>"],[9514014314,"<p>אִשְׁתָּאֲרוּ תוּ אַתְוָון, וְאִינוּן תְּרֵיסַר. מֶם סְתִימָא, צַדִי אֲרִיכָא, נוּן, פֵּא, כָּף, וְאִינוּן אַתְוָון אָחֳרָנִין כְּפוּלִים, מנצפ\"ך. וְאִינוּן סָלְקֵי לִתְרֵיסַר אַתְוָון. וְכַד אַתְוָון כּוּלְהוּ אִשְׁתַּלִּימוּ, סָלְקִין לְע\"ב אַתְוָון, רָזָא דִשְׁמָא קַדִּישָׁא דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְקְרֵי בְּהוּ.</p>"],[9514014315,"<p>חוּשְׁבַּן יִשְׂרָאֵל שִׁבְעִים נֶפֶשׁ, וּתְרֵין אַתְוָון דְּאִינוּן סָהֲדֵי בְּגַוַּיְיהוּ, וְאִתְכְּלִילוּ בְּהוּ, וְאִינוּן י\"ה. דִּכְתִיב, (תהילים קכ״ב:ד׳) שֶׁשָּׁם עָלוּ שְׁבָטִים שִׁבְטֵי יָ\"ה עֵדוּת לְיִשְׂרָאֵל. וְעַל רָזָא דָא, הָראוּבֵנִי הַשִּׁמְעוֹנִי. וְהָא אוֹקְמוּהָ, וְכָלְהוֹ סָלְקוֹ לְע\"ב.</p>"],[9514014316,"<p>כְגַוְונָא דָא אַלְפָ\"א בֵיתָ\"א, דְּסָלְקָא אַתְוָון כּוּלְהוּ לְרָזָא דְּע\"ב אַתְוָון, לְמֶהֱוֵי כֹּלָּא רָזָא דְּגוּפָא שְׁלִים, רָזָא דְּאָדָם. רָזָא דִּרְתִיכָא עִילָּאָה. רָזָא דִּשְׁמָא קַדִּישָׁא גְּלִיפָא.</p>"],[9514014317,"<p>בְּגִין כַּךְ אַתְוָון כָּלְהוֹ סָלְקִין בִּסְלִיקוּ דִּרְתִיכָא עִילָּאָה, בִּדְיוֹקְנַיְיהוּ וְגוּפַיְיהוּ, לְמֶהֱוֵי כּוֹלָּא רָזָא חָדָא כִּדְקָא יָאוֹת. אַתְוָון כּוּלְהוּ, כַּד מִתְחַבְּרָן וְאִתְגְּלִיפוּ בְּגִלּוּפַיְיהוּ, בְּרָזָא דְּע\"ב אַתְוָון גְּלִיפִין, אִתְעֲבִידוּ כָּלְהוֹ גּוּפָא חָדָא.</p>"],[9514014318,"<p>(רות א׳:א׳) וַיְהִי בִּימֵי שְׁפֹט הַשֹׁפְטִים. רַבָּנָן פָּתְרֵי קְרָא דִּכְתִיב, (איוב ל״ח:ז׳) בְּרָן יַחַד כּוֹכְבֵי בֹקֶר וַיָּרִיעוּ כָּל בְּנֵי אֱלֹהִים. מַאן כּוֹכְבֵי בֹקֶר. אִינוּן מַלְאָכִין קַדִּישִׁין דְּשָׁלְטִין בִּימָמָא. מַאן בְּנֵי אֱלֹהִים. אִינוּן מַלְאָכִין קַדִּישִׁין דְּשָׁלְטִין בְּלֵילְיָא.</p>"],[9514014319,"<p>בֹּא וּרְאֵה, כָּל מַה שֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא בְּעוֹלָמוֹ, לֹא בָּרָא אֶלָּא לִיקָרָא דִילֵיהּ. שֶׁנֶּאֱמַר, (ישעיהו מ״ג:ז׳) כָּל הַנִּקְרָא בִּשְׁמִי וְלִכְבוֹדִי בְּרָאתִיו יְצַרְתִּיו אַף עֲשִׂיתִיו. הַקָּדוֹשׁ בָּרוּךְ הוּא בָּרָא בַּר נָשׁ בְּעַלְמָא, וְיָהֵיב בֵּיהּ שְׁמֵיהּ יהו\"ה. ה', נֶפֶשׁ. ו', רוּחַ. ה', נִקְרֵאת נִשְׁמָתָא. י', נִשְׁמָתָא לְנִשְׁמָתָא. וּקְרָאָם, י\"ה, אָב וָאֵם. ו\"ה, בֵּן וּבַת.</p>"],[9514014320,"<p>דּוּגְמָא דְּבָרָא רוּחַ וְנַפְשָׁא דְּקַדִּישָׁא, כָּךְ בָּרָא רוּחַ וְנַפְשָׁא מִסִּטְרָא דִּשְׂמָאלָא. וּבְדוּגְמָא דְּהוּא הַיַּיִן עַל שְׁמָרָיו, כָּךְ הוּא הָרוּחַ וְהַנֶּפֶשׁ הַשִּׂכְלִית, עַל רוּחַ וְנֶפֶשׁ הַבַּהֲמִית. וְלָמָּה נִקְרֵאת בַּהֲמִית. שֶׁהוּא מִסִּטְרָא דִּסמאל וְנָחָשׁ, דְּאִינוּן דְּכַר וְנוּקְבָא. וְעַל דָּא אֲמַר שְׁלֹמֹה הַמֶּלֶךְ בְּחָכְמָתוֹ, (קהלת ג׳:כ״א) מִי יוֹדֵעַ רוּחַ בְּנֵי הָאָדָם הָעוֹלָה הִיא לְמַעְלָה וְרוּחַ הַבְּהֵמָה הַיּוֹרֶדֶת הִיא לְמַטָה לָאָרֶץ.</p>"],[9514014321,"<p>וּלְסִטְרָא דִּמְסָאֲבוּ, לָא יְהֵיב קוּדְשָׁא בְּרִיךְ הוּא שְׁמָא דִילֵיהּ. שֶׁנֶּאֱמַר, (ישעיהו מ״ב:ח׳) אֲנִי יְיָ' הוּא שְׁמִי וּכְבוֹדִי לְאַחֵר לֹא אֶתֵּן וּתְהִלָּתִי לַפְּסִילִים. אֲנִי, רֶמֶז (ויקרא כ״ו:כ״ח) וְיִסַּרְתִּי אֶתְכֶם אַף אָנִי. ה', רֶמֶז לְמִדַּת הָרַחֲמִים. לְאַחֵר לֹא אֶתֵּן, רֶמֶז לְאֵל אַחֵר, שֶׁנֶּאֱמַר לֹא תִשְׁתַּחֲוֶה לְאֵל אַחֵר, דְּהוּא בְּסִטְרָא דִּמְסָאֲבָא.</p>"],[9514014322,"<p>פָּתַח רַבִּי וְאָמַר, בְּרָזָא דְּידוד. י' אִקְרֵי בְּדוּגְמָא, דָּא אֱלִימֶלֶךְ. ה' אִתְקְרֵי בְּדוּגְמָא, דָּא נָעֳמִי. וְלָמָּה נִקְרֵאת שְׁמָהּ נָעֳמִי, שֶׁנֶּאֱמַר וִיהִי נֹעַם ה' אֱלֹהֵינוּ עָלֵינוּ וְגו'. ו\"ה דּוּגְמָא, דָּא רוּת וּבַעֲלָהּ.</p>"],[9514014323,"<p>רוּת הָפְכָה לִשְׁמָהּ תּוֹר. שֶׁנֶּאֱמַר, (בראשית ט״ו:ט׳) וְתוֹר וְגוֹזָל. (שיר השירים ב׳:י״ד) יוֹנָתִי בְּחַגְוֵי הַסֶּלַע בְּסֵתֶר הַמַּדְרֵגָה הַרְאִינִי אֶת מַרְאֲיִךְ הַשְׁמִיעִינִי אֶת קוֹלֵךְ כִּי קוֹלֵךְ עָרֵב וּמַרְאֵךְ נָאוֶה.</p>"],[9514014324,"<p>פָּתַח וְאָמַר, וּמַה וּמַעֲשֵׂה יָדֵינוּ כּוֹנְנָה עָלֵינוּ. דָּא עוֹבָדָא דִּיעֲבַד בַּר נָשׁ. אִי אִינוּן עוֹבָדִין טָבִין, יִשְׁכּוֹן עֲלֵיהּ הויה. וְאִי לָא, יִסְתַּלַּק מִינָהּ. שֶׁנֶּאֱמַר, (משלי י״ד:א׳) חַכְמוֹת נָשִׁים בָּנְתָה בֵיתָהּ וְאִוֶּלֶת בְּיָדֶיהָ תֶהֶרְסֶנּוּ. חַכְמוֹת נָשִׁים: דָּא נִשְׁמָתָא וְנַפְשָׁא. וְאִוֶּלֶת, דָּא נֶפֶשׁ דִּשְׂמָאלָא שֶׁנִּקְרֵאת עָרְפָּה.</p>"],[9514014325,"<p>פָּתַח וְאָמַר, מַה הוּא דְּאָמַר, (שיר השירים ב׳:י״ד) הַרְאִינִי אֶת מַרְאַיִךְ. כַּד יִתְעֲבֵיד בַּר נַשׁ מִטִיפָּה, בְּשִׁלְיָיתָא דְאִמֵּיהּ, כְּמָה דְּאִתְרַבֵּי, אָעֵיל בֵּיהּ הַקָּדוֹשׁ בָּרוּךְ הוּא זְעֵיר זְעֵיר רוּחָא וְנַפְשָׁא. וְנֵר יְהֵיבַת עַל רֵישֵׁיהּ בְּלֵילְיָא. שֶׁנֶּאֱמַר, (איוב כ״ט:ג׳) בְּהִלּוֹ נֵרוֹ עֲלֵי רֹאשִׁי. וְעַמּוּדָא דִנְהוֹרָא בִּימָמָא, שֶׁנֶּאֱמַר ק (שמות י״ד:י״ט) וַיִּסַּע עַמּוּד הֶעָנָן וְגו', וְלַיְלָה בְּעַמּוּד אֵשׁ כו' לָלֶכֶת יוֹמָם וָלָיְלָה. וְנֶאֱמַר, (משלי ו׳:כ״ג) כִּי נֵר מִצְוָה וְתוֹרָה אוֹר.</p>"],[9514014326,"<p>וְאוֹלְפֵי לֵיהּ כָּל אוֹרַיְיתָא. וְאוֹלְפֵי לֵיהּ כָּל פִּיקוּדֵי. וְיֵמְרוּן לֵיהּ, חֲזֵי, דְּדֵין הוּא דֶּרֶךְ עֲקַלָּתוֹן, דְּאִיתְקְרֵי לַיְלָה. וּבְאַתְרָא הָדֵין יַעֲלוּן כָּל נַפְשָׁתָא דְּאֶינָשָׁא. שֶׁנֶּאֱמַר, (איוב ג׳:י״ט) קָטָן וְגָדוֹל שָׁם הוּא וְעֶבֶד חָפְשִׁי מֵאֲדוֹנָיו.</p>"],[9514014327,"<p>וְאַחְזְיָין לֵיהּ, בְּעַמּוּדָא דְּאֵישָׁתָא, דְּהִיא עַל רֵישֵׁיהּ, כַּמָּה דוּבִּין וּנְמֵרִין וַאֲרָיָין וּמַלְאֲכֵי חַבָּלָה דְּיָתְבִין תַּמָּן. וְכַלְבָּא תַּמָּן, וְעַל דָּא אֲמַר דָּוִד, (תהילים כ״ב:כ״א) הַצִּילָה מֵחֶרֶב נַפְשִׁי מִיַּד כֶּלֶב יְחִידָתִי. וְדֵין אַתְרָא הוּא חֹשֶׁךְ, וּמַלְאֲכֵי חַבָּלָה קָרוֹן לְהוֹן לֵילוֹת. וְעַל דָּא אֲמַר, מִפַחַד בַּלֵּילוֹת. לֵילוֹת מַמָּשׁ אִקְרוּן.</p>"],[9514014328,"<p>וְיֵמְרוּן לֵיהּ, אִם תִּזְכֶּה לְמִצְוֹת, כָּל מִצְוָה וּמִצְוָה, יַעַבְדוּן לָךְ מִינָהּ מַלְאַךְ טוֹב. וּבְעִידָן דְּתֵיעוֹל בְּאַתְרָא הָדֵין, וְתִזְכֶּה לְמִצְוֹת, יֵימְרוּן, סוֹלוּ סוֹלוּ פַּנּוּ דֶרֶךְ הָרִימוּ מִכְשׁוֹל מִדֶּרֶךְ פְּלוֹנִי דָּא, וְלָא יִשְׁלְטוּן עָלֶיךָ מַלְאֲכֵי חַבָּלָה.</p>"],[9514014329,"<p>וּבְדוּגְמָא דָא בִּימָמָא, יֵימְרוּן, אִם תִּזְכֶּה בְּאוֹרַיְיתָא, כָּל אוֹת וְאוֹת יִהְיֶה מַלְאָךְ, דְּיַעֲזְרֶךָ בְּאַתְרָא הָדֵין. וְאוֹרַיְיתָא דְאִקְרֵי אוֹרְחָא, יְהַךְ בְּאוֹרְחָא הָדֵין, דְּלָא יִשְׁלְטוּן עֲלָךְ. וְעַל דָּא אֲמַר, לַנְחוֹתָם הַדֶּרֶךְ. וּבָתַר דֵּין יַחֲזוּן לֵיהּ גִּינְתָא דְעֵדֶן, וְכָל חֵלֶק וְחֵלֶק שֶׁיֵּשׁ לַצַּדִּיק בִּפְנֵי עַצְמוֹ. וּמַשְׁבִּיעִין לֵיהּ שֶׁיְקַיִּים כָּל הַתּוֹרָה.</p>"],[9514014330,"<p>וּבָתַר כֵּן יֵימְרוּן לֵיהּ, (בראשית י״ב:א׳) וַיֹּאמֶר ה' אֶל אַבְרָם לֶךְ לְךָ וְגו' (שם) וְאֶעֶשְׂךָ לְגוֹי גָדוֹל וְגו'. וַיֹּאמֶר ה' אֶל אַבְרָם, דָּא נִשְׁמָתָא, דְּהִיא אָב לַרוּחַ, וְרָם לַגּוּף. לֶךְ לְךָ מֵאַרְצְךָ, דָּא גִנְתָא דְעֵדֶן. וּמִמּוֹלַדְתְּךָ, דָּא בֶּטֶן דְּאִימָּא, שֶׁל בָּשָׂר וָדָם. וּמִבֵּית, דָּא שְׁכִינְתָא. אָבִיךָ, דָּא הַקָדוֹשׁ בָּרוּךְ הוּא. שֶׁאֵין אָבִיו, אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא. וְאֵין אִמּוֹ, אֶלָּא כְּנֶסֶת יִשְׂרָאֵל. אֶל הָאָרֶץ, זֶה הָעוֹלָם הַשָּׁפֵל. וְיַהֲבוּ לֵיהּ ז' בִּרְכָאן דַּאֲמִירָן לְעֵיל, מִוְּאֶעֶשְׂךָ וְגו' עַד כָּל מִשְׁפְּחוֹת הָאֲדָמָה וְגו'.</p>"],[9514014331,"<p>אִם בַּר נַשׁ יִזְכֶּה, וְיִהְיֶה צַדִּיק, וְהוּא יָדַע שְׁמָא דְּהַקָדוֹשׁ בָּרוּךְ הוּא, מַה יֵּימְרוּן לֵיהּ כַּד אִסְתַּלַּק מֵעָלְמָא. (תהילים צ״א:י״ב) לֹא תִירָא מִפַּחַד לָיְלָה וְגו', (שם) עַל כַּפַּיִם יִשָּׂאוּנְךָ פֶּן תִּגּוֹף בָּאֶבֶן. מִן הָאֶבֶן שֶׁל דֶּרֶךְ עֲקַלָּתוֹן, רַגְלֶךָ כו' עַד כִּי יָדַע שְׁמִי.</p>"],[9514014332,"<p>וְאִם בַּר נָשׁ לָא יִזְכֶּה בְּאוֹרַיְיתָא, וּלְעוֹבָדִין טָבָן, כַּד יִסְתַּלַּק מֵעָלְמָא, יֵעוֹל בְּאוֹרְחָא חֲשׁוֹכָא דַּאֲמַרְנָא, וְאִזְדַּעְזְעוּ כָּל מַאן דְּאִית בְּהַהוּא אֲתַר, וְיֵימְרוּן הַזֹּאת נָעֳמִי, דְּאָזְלַת בְּאַתְרָא הָדֵין מַלְיָיא כָּל טוּבָא, מַלְיָיא מֵאוֹרַיְיתָא. עַמּוּד הֶעָנָן דְּנָהַר לָהּ בְּאַתְרָא הָדֵין לְמֵיהַךְ בִּימָמָא. וְעַמּוּדָא דְאֵישָׁתָא לְאַנְהָרָא לָהּ לְמֵיזַל בְּאַתְרָא הָדֵין בְּלֵילְיָא. וְעִם בַּעֲלָהּ נִשְׁמָתָא לְנִשְׁמְתָא.</p>"],[9514014333,"<p>אֲתִיבָא אִיהִי וְאָמְרָה, (רות א׳:כ׳) אַל תִּקְרֶאנָה לִי נָעֳמִי קְרֶאןָֹ לִי מָרָא כִּי הֵמַר שַׁדַּי לִי מְאֹד. דְּהַנְעֵל לִי בְּגוּפָא בִּישָׁא. אֲנִי מְלֵאָה הָלַכְתִּי בְּאַתְרָא הָדֵין, וְרֵיקָם הֱשִׁיבַנִי ה'. בְּהַהִיא שַׁעֲתָא אָמְרָה, שֹׁבְנָה בְנֹתַי וְגו'. שֶׁנֶּאֱמַר, (שם) וַתֹּאמֶר נָעֳמִי לְכַלֹּתֶיהָ שֹׁבְנָה בְנֹתַי. אֲתֵיבַת רוּת נַפְשָׁתָא קַדִּישָׁא וַאֲמָרַת, אַל תִּפְגְּעִי בִי לְעָזְבֵךְ לָשׁוּב מֵאַחֲרָיִךְ כִּי בַאֲשֶׁר תֵּלְכִי אֵלֵךְ וּבַאֲשֶׁר תָּלִינִי אָלִין וכו'.</p>"],[9514014334,"<p>אֲבָל עָרְפָּה, נַפְשָׁתָא דְּהִיא סִטְרָא דִשְׂמָאלָא, אָזְלָא לְגוּפָא, וְאִתְאַבָּלַת עָלֶיהָ. שֶׁנֶּאֱמַר, (איוב י״ד:כ״ב) אַךְ בְּשָׂרוֹ עָלָיו יִכְאָב וְנַפְשׁוֹ עָלָיו תֶּאֱבָל. וְכָל זְמַן דְּאִתְאַבָּל עֲלֵיהּ, אָמַר הַגּוּף לַנֶּפֶשׁ הַבַּהֲמִית, בִּשְׁבִיל הָאֲכִילָה וְהַשְּׁתִיָּה שֶׁנָּתַתָּ לִי, הַנְּשָׁמָה בְּצַעַר גָּדוֹל, וּבְלֹא תוֹרָה וּבְלֹא מִצְוֹת. טוֹל מַה שֶּׁנָּתַתָּ לִי. וְנִבְקַע הַגּוּף.</p>"],[9514014335,"<p>אָמַר רַבִּי, כְּתִיב (תהילים מ״א:ב׳) אַשְׁרֵי מַשְׂכִּיל אֶל דָּל וְגו'. מַהוּ דָּל. אִישׁ נִסְתָּר. וַיֹּאמֶר מַה תִּתֶּן לִי, וְכִי יוֹתֵר רָשָׁע אֲנִי מִכָּל הָאָדָם שֶׁבָּעוֹלָם. וְיַעֲשֶׂה מְרִיבָה עִם הַקָדוֹשׁ בָּרוּךְ הוּא. אַשְׁרָיו מַאן דְּמַשְכִּיל לֵיהּ. דִּכְתִיב, (ישעיהו כ״ז:ה׳) אוֹ יַחֲזֵק בְּמָעֻזִּי יַעֲשֶׂה שָׁלוֹם לִי שָׁלוֹם יַעֲשֶׂה לִי.</p>"],[9514014336,"<p>דְּאָמַר רַבִּי נְהוֹרָאי, מַהוּ דִּכְתִּיב אוֹ יַחֲזֵק בְּמָעֻזִּי וְגו'. וְכִי הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהוּא בַּעַל הַשָּׁלוֹם, עוֹשֶׂה שָׁלוֹם בִּמְרוֹמָיו, צָרִיךְ לְמִי שֶׁיַּעֲשֶׂה לוֹ שָׁלוֹם, וַהֲלֹא הַשָּׁלוֹם שֶׁלּוֹ.</p>"],[9514014337,"<p>אֶלָּא, הֶעָנִי בְּשָׁעָה שֶׁרוֹאֶה אֶת עַצְמוֹ בְּדוֹחַק, הוּא עוֹשֶׂה מְרִיבָה כְּלַפֵּי מַעְלָה. וְהַמַּחֲזִיק בְּיָדוֹ שֶׁל עָנִי, וְעוֹשֶׂה עִמּוֹ צְדָקָה, כִּבְיָכוֹל, עִם הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה שָׁלוֹם. לְפִי שֶׁגּוֹרֵם לֶעָנִי, שֶׁמְבַקֵּשׁ מְחִילָה מִלְּפָנָיו יִתְבָּרַךְ, עַל שֶׁהֵטִיחַ דְּבָרִים כְּלַפֵּי מַעְלָה, וְאָז עוֹשֶׂה שָׁלוֹם בֵּינוֹ לְבֵין קוֹנוֹ. מִי גָרַם לוֹ לַעֲשׂוֹת שָׁלוֹם. זֶה הַנּוֹתֵן צְדָקָה לֶעָנִי, וְהֶחֱזִיק בְּיָדוֹ, דִּכְתִיב אוֹ יַחֲזֵק בְּמָעֻזִּי וְגו', וְזֶהוּ הַדַּל. וְהַקָּדוֹשׁ בָּרוּךְ הוּא מַהוּ אוֹמֵר. אֵין דָּנִין אֶת הָאָדָם לְפִי צַעֲרוֹ.</p>"],[9514014338,"<p>וְהָכִי נָמֵי בְּאִיּוֹב, דְּאָמַר רַבִּי תַּנְחוּם, אָמַר אִיּוֹב לְהַקָּדוֹשׁ בָּרוּךְ הוּא, (איוב כג) מִי יִתֵּן יָדַעְתִּי וְאֶמְצָאֵהוּ כו' אֶעֶרְכָה לְפָנָיו מִשְׁפָּט. עַד שֶׁהֵטִיחַ אִיּוֹב דְּבָרִים כְּלַפֵּי מַעְלָה.</p>"],[9514014339,"<p>וְתוּ לֹא. וַהֲלֹא בְּכַמָּה מְקוֹמוֹת כָּפַר בִּתְחִיַּית הַמֵּתִים, וְהֵטִיחַ דְּבָרִים כְּלַפֵּי מַעְלָה, וְסָקַל אִיקוּנִין שֶׁל מֶלֶךְ.</p>"],[9514014340,"<p>אֶלָא אָמַר רַבִּי נְהוֹרָאי, בְּהַהִיא שַׁעֲתָא אָמַר הַמְקַטְרֵג לְהַקָּדוֹשׁ בָּרוּךְ הוּא, אִיּוֹב שֶׁאָמַרְתָּ עָלָיו אִישׁ תָּם וְיָשָׁר וִירֵא אֱלֹהִים וְסָר מֵרָע, הֲרֵי כָּפַר בִּתְחִיַּית הַמֵּתִים, וְהֵטִיחַ דְּבָרִים, וְסָקַל אִיקּוּנִין שֶׁל מֶלֶךְ. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, אִיּוֹב לֹא בְדַעַת יְדַבֵּר.</p>"],[9514014341,"<p>בְּשָׁעָה שֶׁנִּתְוַוכֵּחַ אִיּוֹב עִם הַקָּדוֹשׁ בָּרוּךְ הוּא, מַה הוּא אוֹמֵר, ש (איוב י) הֲטוֹב לְךָ כִּי תַעֲשֹׁק כִּי תִמְאַס יְגִיעַ כַּפֶּיךָ וְגו'. וְכִי הוּא טוֹב זֶה הָעוֹשֶׁק שֶׁתַּעֲשֶׂה לִי, אָבִי וְאִמִּי עָשׂוּ לִי הַגּוּף, וְאַתְּ אִתְעֲבֵידַת אָרִיס עִמְּהוֹן, וִיהַבְתְּ בִּי נִשְׁמָתָא. וַאֲמַרְתְּ לַמְּקַטְרֵג, אַךְ אֶת נַפְשׁוֹ שְׁמֹר. מַה דִּידָךְ נָטַרְתְּ, מַה דְּאָבִי וְאִמִּי, אֲמַרְתְּ הִנּוֹ בְיָדְךָ. וְכִי הוּא טוֹב זֶה הָעוֹשֶׁק שֶׁתַּעֲשֶׂה לִי, כִּי תִמְאָס יְגִיעַ כַּפֶּיךָ. שֶׁהַנֶּפֶשׁ מְאוּסָה מִצַּד יִסּוּרֵי הַגּוּף. וְעַל עֲצַת רְשָׁעִים הוֹפָעְתָּ, סָקַל אִיקוּנִין שֶׁל מֶלֶךְ.</p>"],[9514014342,"<p>וְהַמְקַטְרֵג קִטְרֵג עַל כָּל זֶה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. אָמַר לֵיהּ הַקָּדוֹשׁ בָּרוּךְ הוּא, אִיּוֹב לֹא בְדַעַת יְדַבֵּר, וְאֵינוֹ נִתְפַּס עַל צַעֲרוֹ. וְכֵיוָן שֶׁבָּא הַקָּדוֹשׁ בָּרוּךְ הוּא וְנִתְוַוכֵּחַ עִמּוֹ, חָזַר בּוֹ וְאָמַר, (שם מ) אַחַת דִּבַּרְתִּי וְלֹא אֶעֱנֶה וּשְׁתַּיִם וְלֹא אוֹסִיף, אַסְכַּר פּוּמֵיהּ קַמֵּי דַּיָּינָא.</p>"],[9514014343,"<p>רַבִּי פְּדָת אָמַר, כִּי לֹא דִּבַרְתֶּם נְכוֹנָה בְּעַבְדִי אִיּוֹב לֹא כְתִיב, אֶלָּא (שם מב) כִּי לֹא דִּבַּרְתֶּם אֵלַי נְכוֹנָה. אֵלַי לֹא דִבַּרְתֶּם נְכוֹנָה, הוּא עָמַד וְהִצְדִיק אֶת הַדִּין, וּבִקֵּשׁ עַל עַצְמוֹ עַל מַה שֶּׁאָמַר. וְהֵם לֹא בִּקְּשׁוּ עַל עַצְמָם, עַל מַה שֶׁהִטְעוּהוּ בְּמַעֲנֶה לְשׁוֹנָם.</p>"],[9514014344,"<p>רַבִּי יְהוֹשֻׁעַ דְּסִכְנִין בְּשֵׁם רַבִּי יוּדָא אָמַר, כָּל הַחוֹשֵׁד בִּכְשֵׁרִים, רָאוּי לִלְקוֹת בְּצָרַעַת. דִּכְתִיב, (במדבר יב) אֲשֶׁר נוֹאַלְנוּ וַאֲשֶׁר חָטָאנוּ. וּכְתִיב, (שם) אַל נָא תְהִי כַּמֵּת. חֲבֵרָיו שֶׁל אִיּוֹב חַשָׁדוּהוּ בַּמֶּה שֶׁלֹּא הָיָה בוֹ, וְלֹא בִּקְשׁוּ מִמֶּנּוּ מְחִילָה, וְלֹא בִקְּשׁוּ עַל נַפְשָׁם, עַד שֶׁבִּיקֵּשׁ אִיּוֹב עֲלֵיהֶם רַחֲמִים. וְהַקָּדוֹשׁ בָּרוּךְ הוּא הוֹדִיעַ לָהֶם, שֶׁחָטְאוּ בַּמֶּה שֶׁחֲשָׁדוּהוּ. וּלְפִיכָךְ, וְעַבְדִי אִיּוֹב יִתְפַּלֵּל בַּעַדְכֶם.</p>"],[9514014345,"<p>וְאָמַר רַבִּי יוֹסֵי בֶּן קִסְמָא, מַהוּ דִּכְתִּיב, (איוב מב) כִּי אִם פָּנָיו אֶשָּׂא לְבִלְתִּי עֲשׂוֹת עִמָּכֶם נְבָלָה. מַאי נְבָלָה, זוֹ צָרַעַת. דִּכְתִיב, (במדבר יב) וְאָבִיהָ יָרֹק יָרַק בְּפָנֶיהָ, וְתִרְגֵּם רַבִּי יוֹסֵי וְאָבִיהָ מְנַבֵּל יְנַבֵּל בְּאַפֶּיהָ.</p>"],[9514014346,"<p>בֹּא וּרְאֵה, כְּשֶׁנִּגְלָה הַקָּדוֹשׁ בָּרוּךְ הוּא אֶל אִיּוֹב, מַה כְּתִיב. (איוב לח) וַיַּעַן ה' אֶת אִיּוֹב מִן הַסְעָרָה וַיֹּאמֶר. רַבִּי יוֹסֵי בַּר חֲלַפְתָּא אָמַר, הֵשִׁיב לוֹ עַל מַה שֶּׁאָמַר, (שם ט) אֲשֶׁר בִּסְעָרָה יְשׁוּפֵנִי, אָמַר אִיּוֹב, רִבּוֹנוֹ שֶׁל עוֹלָם, שֶׁמָּא רוּחַ סְעָרָה עָבְרָה לְפָנָיו, וְנִתְחַלֵּף לְךָ שְׁמִי אִיּוֹב, בְּאוֹיֵב. הֲדָא הוּא דִכְתִיב, (שם יג) וַתַּחְשְׁבֵנִי לְאוֹיֵב לָךְ. לְפִיכָךְ הֵשִׁיבוֹ מִן הַסְּעָרָה.</p>"],[9514014347,"<p>רַבָּנָן אָמְרֵי, סְעָרָה שֶׁל שָׂטָן, שֶׁהִסְעִיר גּוּפוֹ שֶׁל אִיּוֹב. וּמְנָלָן דְּאִיקְרֵי סְעָרָה. דִּכְתִיב, (תהילים קמ״ח:ח׳) רוּחַ סְעָרָה עוֹשָׂה דְבָרוֹ. שֶׁאֵין לוֹ רְשׁוּת לַעֲשׂוֹת שׁוּם דָּבָר, אֶלָּא בְּמַאֲמָרוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>"],[9514014348,"<p>רַבִּי בּוֹן אוֹמֵר, כְּתִיב בְּשִׂי\"ן, דִּכְתִיב אֲשֶׁר בִּשְׂעָרָה יְשׁוּפֵנִי. וּכְתִיב בְּסַמַךְ, דִּכְתִיב מִן הַסְּעָרָה. כְּתִיב הָכָא אֲשֶׁר בִּשְׂעָרָה, וּכְתִיב הָתָם (ויקרא י״ז:ז׳) לַשְּׂעִירִים אֲשֶׁר הֵם זוֹנִים אַחֲרֵיהֶם.</p>"],[9514014349,"<p>וְהַאי דִכְתִיב בִּשְׂעָרָה. רַבִּי רְחוּמָאי אָמַר, פַּעַם אַחַת זָכָר, וּפַעַם אַחַת נְקֵבָה. פַּעַם אַחַת זָכָר, דִּכְתִיב (ויקרא ט״ז:כ״ב) וְנָשָׂא הַשָּׂעִיר עָלָיו. וּכְתִיב, (בראשית כ״ז:י״א) הֵן עֵשָׂו אָחִי אִישׁ שָׂעִיר. פַּעַם אַחַת נְקֵבָה, דִּכְתִיב (שם לג) וַיָּשָׁב בַּיּוֹם הַהוּא עֵשָׂו לְדַרְכּוֹ שֵׂעִירָה, וּכְתִיב בְּסַמַךְ דִּכְתִיב מִן הַסְּעָרָה. מַאי טַעְמָא. שֶׁמַּסְעִיר גּוּפוֹ שֶׁל אָדָם.</p>"],[9514014350,"<p>וְהָא כְתִיב, (מלכים ב ב׳:י״א) וַיַּעַל אֵלִיָּהוּ בִּסְעָרָה הַשָּׁמַיִם. רַבִּי נְחֶמְיָה וְרַבִּי יְהוּדָה אָמְרֵי, כְּשֶׁהֶעֱלָה הַקָּדוֹשׁ בָּרוּךְ הוּא אֵלִיָּהוּ לָרָקִיעַ, עָמַד מַלְאַךְ הַמָּוֶת כְּנֶגְדוֹ.</p>"],[9514014351,"<p>אָמַר לֵיהּ הַקָּדוֹשׁ בָּרוּךְ הוּא, עַל מְנָת כָּךְ בָּרָאתִי שָׁמַיִם, שֶׁיַּעֲלֶה אֵלִיָּהוּ לְשָׁם. אָמַר לֵיהּ מַלְאַךְ הַמָּוֶת, רִבּוֹנוֹ שֶׁל עוֹלָם, עַכְשָׁיו יִהְיֶה פִּתְחוֹן פֶּה לַבְּרִיּוֹת. אָמַר לֵיהּ הַקָּדוֹשׁ בָּרוּךְ הוּא, אֵין זֶה כִּשְׁאָר בְּרִיּוֹת, וְיָכוֹל הוּא לְהַעֲבִיר אוֹתְךָ מִן הָעוֹלָם, וְאֵינְךָ יוֹדֵעַ כֹּחוֹ. אָמַר לֵיהּ, רִבּוֹנוֹ שֶׁל עוֹלָם, תֵּן לִי רְשׁוּת, וְאֵרֵד אֵלָיו. אָמַר לֵיהּ רֵד, מִיָּד יָרַד. כֵּיוָן שֶׁרָאָה אוֹתוֹ אֵלִיָּהוּ, הִכְרִיחוֹ תַּחַת רַגְלָיו, וּבִקֵּשׁ לְהַעֲבִירוֹ מִן הָעוֹלָם, וְלֹא נָתַן לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא רְשׁוּת. מִיָּד כָּפַף אוֹתוֹ תַּחְתָּיו, וְעָלָה לַשָּׁמַיִם. דִּכְתִיב (שם) וַיַּעַל אֵלִיָּהוּ בִּסְעָרָה הַשָּׁמַיִם.</p>"],[9514014352,"<p>כֵיוָן שֶׁנִּגְלָה הַקָּדוֹשׁ בָּרוּךְ הוּא לְאִיּוֹב, בְּהַהוּא סְעָרָה נִגְלָה אֵלָיו. דִּכְתִיב, מִן הַסְּעָרָה, הַנו\"ן כְּפוּפָה, וְלֹא פְשׁוּטָה. כָּפַף אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא כְּנָחָשׁ הוֹלֵךְ עַל גָּחוֹן, וְדִבֵּר עִמּוֹ. מַה אָמַר לֵיהּ לְאִיּוֹב. (איוב ל״ח:ד׳) אֵיפֹה הָיִיתָ בְּיָסְדִי אָרֶץ. מִיָּד שָׁתַק, וְלֹא יָכוֹל לַעֲמוֹד בְּתוֹכַחְתּוֹ. לְהוֹרוֹת שֶׁמַּעֲשָׂיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא בֶּאֱמֶת.</p>"],[9514014353,"<p>רַבִּי אֲלֶכְּסַנְדְּרִי פָּתַח וְאָמַר, (שם) בְּרָן יַחַד כּוֹכְבֵי בֹקֶר, כּוֹכָבִים שֶׁבַּמָּרוֹם שׁוֹלְטִים בַּלַּיְלָה, חוּץ מֵאוֹתָן שֶׁשּׁוֹלְטִין בַּבֹּקֶר. וְכֻלָּן מְשַׁבְּחִין וּמְפָאֲרִין וּמְיַיחֲדִין שְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. הֲדָא הוּא דִכְתִיב, בְּרָן יַחַד כּוֹכְבֵי בֹקֶר, וְלֹא כוֹכְבֵי לַיְלָה אַף עַל פִּי שֶׁמֶּמְשַׁלְתָּן כְּרֶגַע.</p>"],[9514014354,"<p>(שם) וַיָּרִיעוּ כָּל בְּנֵי אֱלֹהִים, אַמַּאי וַיָּרִיעוּ, אָמַר רַבִּי אֲלֶכְּסַנְדְּרִי, בְּשָׁעָה שֶׁעוֹלֶה עַמּוּד הַשַּׁחַר, אוֹתָן בְּנֵי אֱלֹהִים מְרִיעִין בִּתְרוּעָה, וְכָל אוֹתָן הַמַּלְאָכִים וְהַכּוֹכָבִים הַמְמוּנִים בַּלַּיְלָה, מַעֲבִירִין אוֹתָם מִמְּקוֹמָם, וְשׁוֹלְטִים מַלְאָכִים אֲחֵרִים בִּמְקוֹמָם, לִהְיוֹתָם מְמוּנִּים בַּיּוֹם.</p>"],[9514014355,"<p>רַבִּי חִסְדָאי אוֹמֵר, כּוֹכָב אֶחָד יֵשׁ בַּמָּרוֹם, וְהַקָדוֹשׁ בָּרוּךְ הוּא מוֹצִיאוֹ מִמְקוֹמוֹ, וִילוֹן שְׁמוֹ. וְהוּא מְמוּנֶּה לְהַכְנִיס וּלְהוֹצִיא שְׁאָר הַכּוֹכָבִים, וּמְשַׁמֵּשׁ כָּל הַלַּיְלָה, כֵּיוָן שֶׁאוֹתָן כּוֹכְבֵי בוֹקֶר שׁוֹלְטִין, נִגְנַז וְנִבְלַע בִּמְקוֹמוֹ.</p>"],[9514014356,"<p>אָמַר רַבִּי שְׁמוּאֵל, כְּתִיב (שם ט) הַמַּרְגִּיז אֶרֶץ מִמְּקוֹמָהּ וְעַמּוּדֶיהָ יִתְפַּלָּצוּן. כַּד הַקָּדוֹשׁ בָּרוּךְ הוּא בָּעֵי לְמִירְגַּז כָּל עָלְמָא, וּלְאַרְגָּשָׁא וּלְאַרְעָשָׁא סַמְכוֹהִי, לָא אַרְעֵישׁ לֵיהּ אֶלָּא מִמְקוֹמוֹ. מַאן מְקוֹמוֹ. דָּא נְקוּדָה דְצִיּוֹן.</p>"],[9514014357,"<p>רַבִּי רְחוּמָאי אוֹמֵר, מִצִּיּוֹן הוּשְׁתַּת הָעוֹלָם. דִּכְתִיב, מִזְמוֹר לְאָסָף אֵל אֱלֹהִים ה' דִּבֶּר וַיִּקְרָא אֶרֶץ מִמִּזְרַח שֶׁמֶשׁ עַד מְבוֹאוֹ. וּכְתִיב בַּתְרֵיהּ, (תהלים נ) מִצִּיּוֹן מִכְלַל יוֹפִי אֱלֹהִים הוֹפִיעַ.</p>"],[9514014358,"<p>וְאָמַר רַבִּי שִׁמְלָאי, כַּד בָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת עָלְמָא, אָעֵיל נְהוֹרָא בִּנְהוֹרָא, וְאַלְבֵּישׁ דָּא בְדָא, וּבָרָא שָׁמַיִם. דִּכְתִיב, (שם קד) עוֹטֶה אוֹר כַּשַּׂלְמָה נוֹטָה שָׁמַיִם כַּיְרִיעָה.</p>"],[9514014359,"<p>וְהַאי אוֹר, אִקְרֵי אוֹר לְבוּשׁוֹ. אוֹר קַדְמָאָה, דְּאִתְלַבֵּשׁ בֵּיהּ הַקָּדוֹשׁ בָּרוּךְ הוּא. וְהַהוּא אוֹר אִתְפַּשַּׁט בְּהוֹד וְהָדָר, וְאִיבְרֵי עָלְמָא. דִּכְתִיב, הוֹד וְהָדָר לָבָשְׁתָּ כו' נוֹטֶה שָׁמַיִם כַּיְרִיעָה.</p>"],[9514014360,"<p>רַבִּי חִזְקִיָּה אָמַר, כְּשֶׁנָּטַל הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הַשֶּׁלֶג, וְזָרַק לְתוֹךְ הַמַּיִם, מִתַּחַת כִּסֵּא כְבוֹדוֹ, נָטַל כְּשִׁיעוּר שָׁעֳלוֹ, דִּכְתִיב, מִי מָדַד בְּשָׁעֳלוֹ מַיִם.</p>"],[9514014361,"<p>רַבִּי יוּדָאי אָמַר, כְּשִׁיעוּר שְׁלִישׁ זֶרֶת נָטַל, וְזָרַק לְתוֹךְ הַמַּיִם. דִּכְתִיב, (ישעיה מ) וְכָל בַּשָּׁלִשׁ עֲפַר הָאָרֶץ. וּכְתִיב, (איוב לז) כִּי לַשֶּׁלֶג יֹאמַר הֱוֵא אָרֶץ.</p>"],[9514014362,"<p>וּמִתַּחַת הַמַּיִם, נִקְפָּא מָקוֹם אֶחָד בַּתְּחִילָה, בְּאֶמְצַע הַתְּהוֹם, וְנַעֲשֵׂית מִשָּׁם אֶבֶן אַחַת מְשׁוּקַעַת בְּאֶמְצַע תְּהוֹם, וְעָלְתָה לְמַעְלָה וְנִרְאֵית בְּצִיּוֹן. וְהִיא נְקוּדַת הָעוֹלָם.</p>"],[9514014363,"<p>רַבִּי יוֹסֵי אוֹמֵר, סְגַלְגַּל וּסְגוֹלְגַּלְתָּא לָא מִתְמוֹקְמֵי, אֶלָּא מִגּוֹ חַד נְקוּדָה, בָּאֶמְצַע, וְהַהִיא נְקוּדָה אִיהִי מְקוֹמוֹ שֶׁל עוֹלָם, וּמִשָּׁם נִתְפַּשְּׁטָה הָאָרֶץ לְכָל רוּחוֹתֶיהָ. רַבִּי חִזְקִיָה אָמַר, כְּעֵין בְּרִיָּיתוֹ שֶׁל אָדָם.</p>"],[9514014364,"<p>בְּשָׁעָה שֶׁנִּקְפְּאָה הָאָרֶץ מִתַּחַת הַמַּיִם, מַה כְּתִיב, (בראשית א) יִקָּווּ הַמַּיִם מִתַּחַת הַשָּׁמַיִם אֶל מָקוֹם אֶחָד וְתֵרָאֶה הַיַּבָּשָׁה. כֵּיוָן שֶׁרָאוּ הַמַּיִם הַיַּבָּשָׁה, הָיוּ עוֹלִים וְנִגְבָּהִים לְכַסוֹתָהּ כְּבָרִאשׁוֹנָה, עַד שֶׁגָּעַר בָּהֶם הַקָדוֹשׁ בָּרוּךְ הוּא וְנָסוּ, דִּכְתִיב (תהלים קד) מִן גַּעֲרָתְךָ יְנוּסוּן.</p>"],[9514014365,"<p>וְאַף עַל פִּי שֶׁהָיוּ נָסִין, לֹא הָיוּ מִשְׁתַּכְּכִין. מַאי טַעְמָא. מִפְּנֵי שֶׁהָיוּ מְכַסִּין עָלֶיהָ בַּתְּחִילָּה, וְעַכְשָׁיו נָסִין מִפָּנֶיהָ. מֶה עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא. נָטַל כְּמִין צְרוֹר שֶׁל חֶרֶשׂ, וְחָקַק בּוֹ שְׁמוֹ שֶׁל ע\"ב שֵׁמוֹת, וְהִשְׁלִיךְ לְתוֹךְ הַמַּיִם, וְעָמְדוּ מִיָּד, וְנִשְׁתַּכְּכוּ.</p>"],[9514014366,"<p>ובְאֵיזֶה מָקוֹם עָמְדוּ. בְּצִיּוֹן. דִּכְתִיב, (שם נ) מִצִּיּוֹן מִכְלַל יוֹפִי, זֶה שְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. וּכְשֶׁהָאָרֶץ מִתְמוֹטֶטֶת, אֵינָהּ מִתְמוֹטֶטֶת אֶלָּא מִמָּקוֹם זֶה, שֶׁהוּא מְקוֹם הָעוֹלָם.</p>"],[9514014367,"<p>רַבִּי פְּדָת אוֹמֵר, הַנִּשְׁבַּע בֶּאֱמֶת בִּשְׁמוֹ שֶׁל הַקָדוֹשׁ בָּרוּךְ הוּא, צְרוֹר זֶה שֶׁחָתוּם בּוֹ שְׁמוֹ, מִסְתַּלֵּק לְמַעְלָה בְּחֶדְוָה, וּמִתְקַיִּים בּוֹ, וְהָעוֹלָם מִתְקַיֵּים. וְהַנִּשְׁבַּע לַשֶּׁקֶר, אוֹתוֹ צְרוֹר עוֹלֶה וּמִסְתַּלֵּק, וְרוֹאֶה שֶׁהוּא שָׁוְא, וְאָז הָעוֹלָם מִתְמוֹטֵט, וְרוֹצֶה לַחֲזוֹר לְתוֹהוּ וָבוֹהוּ. שֶׁאֵין הָעוֹלָם מִתְקַיֵּים, אֶלָּא עַל שְׁמוֹ הַחָתוּם בֶּאֱמֶת. וְעַל דָּא כְתִיב, (שמות כ׳:ז׳) לֹא תִשָּׂא אֶת שֵׁם ה' אֱלֹהֶיךָ לַשָּׁוְא.</p>"],[9514014368,"<p>רַבִּי חִזְקִיָּה אוֹמֵר, מְקוֹם כָּל הָעוֹלָם כֻּלּוֹ, הִיא נְקוּדָה אַחַת, אֲשֶׁר עָלֶיהָ עוֹמֵד הַכֹּל. וְהַכָּבוֹד אֵינוֹ בָּרוּךְ אֶלָּא מִמְקוֹמוֹ. דִּכְתִיב, (יחזקאל ג׳:י״ב) בָּרוּךְ כְּבוֹד ה' מִמְקוֹמוֹ.</p>"],[9514014369,"<p>מַאי (איוב ט׳:ו׳) וְעַמּוּדֶיהָ יִתְפַּלָּצוּן. רַבִּי פְּרַחְיָא אוֹמֵר, אֵלּוּ עַמּוּדִים סַמְכִין יְסוֹדָא, וְקִיּוּמָא דְעַלְמָא עֲלַיְיהוּ. וְכַמָּה אִינוּן. ז'. דִּכְתִיב, (משלי ט׳:א׳) חָצְבָה עַמּוּדֶיהָ שִׁבְעָה. יְסוֹד דְּאִינוּן סָמְכִין, צַדִּיק אֶחָד. דִּכְתִיב, (שם י) וְצַדִּיק יְסוֹד עוֹלָם. עַמּוּד לָא כְתִיב, אֶלָּא יְסוֹד, יְסוֹדָא דְכוֹלָּא קָיְימִין עֲלֵיהּ.</p>"],[9514014370,"<p>כְנֶגֶה זֶה, שִׁבְעָה רְקִיעִין הֵן. וְשִׁבְעָה כּוֹכָבִים רָצִין וְחוֹזְרִין הֵן. שִׁבְעָה אֲרָצוֹת. שִׁבְעָה יַמִּים. שִׁבְעָה תְּהוֹמוֹת. וְכוּלָּם תְּלוּיִם בַּמַּאֲמָר הַהוּא. שֶׁנֶּאֱמַר, הַבּוֹנֶה בַּשָּׁמַיִם מַעֲלוֹתָיו. הֵם ז' סְפִירוֹת, מַעֲלוֹת גְּדוֹלוֹת, עַמּוּדִים חֲקוּקִים בִּשְׁמוֹ הַגָּדוֹל, וְכֻלָּם תְּלוּיִם בְּמַאֲמָר אֶחָד, וְהֵם שָׁמַיִם הָעֶלְיוֹנִים.</p>"],[9514014371,"<p>וְשֶׁבַע אֲרָצוֹת קְדוֹשׁוֹת, שֶׁמִּזְדַּוְוגִין עִמָּהֶן. וְלָא אִית בְּהוֹן פֵּירוּדָא. שֶׁנֶּאֱמַר, (בראשית א׳:ה׳) וַיְהִי עֶרֶב וַיְהִי בֹקֶר יוֹם אֶחָד. יוֹם שֵׁנִי, יוֹם שְׁלִישִׁי. יוֹם רְבִיעִי. יוֹם חֲמִישִׁי. יוֹם הַשִּׁשִּׁי. עַד יוֹם הַשְּׁבִיעִי. א (שמות כ׳:י״א) כִּי שֵׁשֶׁת יָמִים עָשָׂה ה'.</p>"],[9514014372,"<p>וּכְנֶגְהָם שִׁבְעָה עַמּוּדִים חֲקוּקִים, שֶׁהֵם תְּלוּיִם בַּשָּׁמַיִם. וְאִינוּן שְׁנֵי עָשָׂר שְׁבָטִים, דְּאִינוּן תְּלוּיִין בְּמִדַּת יַעֲקֹב, הַנִּקְרָא שָׁמָיִם. שֶׁנֶּאֱמַר, (מלכים א ח׳:ל״ט) וְאַתָּה תִשְׁמַע הַשָּׁמַיִם מְכוֹן שִׁבְתֶּךָ, וּכְתִיב (דברים ו) שְׁמַע יִשְׂרָאֵל וְגו'.</p>"],[9514014373,"<p>רַבִּי רְחוּמָאי אוֹמֵר, הַשִּׁבְעָה עֶלְיוֹנִים, הֵם שְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. (עמוס ט) וַאֲגְדָּתוֹ, מַאי אֲגֻדָּתוֹ. הֵם שֶׁבַע מַעֲלוֹת לְמַטָה מֵהֶם, שֶׁעוֹמְדִים עַל הָעוֹלָם, וּמַנְהִיגִים אוֹתָהּ. עַל אֶרֶץ, זוֹ אֶרֶץ הַתַּחְתּוֹנָה. יְסָדָהּ, זוֹ אֶרֶץ הָעֶלְיוֹנָה הַנִּקְרֵאת בִּינָה, וְהִיא תְּלוּיָה בְּחָכְמָה. וּמַאי אִיהוּ, תֵּבֵל. שֶׁנֶּאֱמַר, (ירמיהו י׳:י״ב) מֵכֵין תֵּבֵל בְּחָכְמָתוֹ.</p>"],[9514014374,"<p>(עמוס ט׳:ו׳) הַקּוֹרֵא לְמֵי הַיָּם, יָם אֶחָד, וְהֵן שִׁבְעָה. רַבִּי כְּרוּסְפְּדָאי אוֹמֵר, הֲלֹא יַם אֶחָד בָּעוֹלָם הוּא. אָמַר רִבִּי רְחוּמָאי, יַמִּים כְּתִיב. דִּכְתִיב, וּלְמִקְוֵה הַמַּיִם קָרָא יַמִּים.</p>"],[9514014375,"<p>וְכוּלָּן נִכְנָסִין לַיַּם הַגָּדוֹל, וְהֵם שִׁבְעָה, וְכֻלָּם נִכְנָסִים בּוֹ, זֶה לְמַטָה מִזֶּה, עַד הַתְּהוֹם, עַד שֶׁתִּמְצָא יַם הַגָּדוֹל שִׁבְעָה זֶה עַל זֶה, וְכוּלָּם תְּלוּיִם בְּמַאֲמַר אֶחָד.</p>"],[9514014376,"<p>אָמַר רַבִּי שִׁמְלָאי, אֵימָתַי הָעוֹלָם מִתְמוֹטֵט. בְּשָׁעָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מַבִּיט וְרוֹאֶה בּוֹ. שֶׁנֶּאֱמַר, (תהילים י״ד:ב׳) ה' מִשָּׁמַיִם הִשְׁקִיף עַל בְּנֵי אָדָם וְגו'.</p>"],[9514014377,"<p>רַבִּי נְהוֹרָאי וְרַבִּי יִצְחָק קָמוּ בִּנְהוֹרָא, כַּד נְהַר יְמָמָא, לְמֵיהַךְ בְּאוֹרְחָא. עַד לָא נָפְקֵי, זְקַף עֵינוֹהִי רַבִּי נְהוֹרָאי, חָמָא בְּכוֹכְבֵי בֹקֶר דְּקָא מְרַתְּתֵי. אֲמַר ר' יִצְחָק, חֲזֵי אִינוּן כּוֹכְבַיָא דְּקָא מְרַתְּתֵי בִּדְחִילָא דְמָרֵיהוֹן, הַשְׁתָּא מָטֵי זִמְנַיְיהוּ לְזַמְּרָא.</p>"],[9514014378,"<p>בְּגִין, דְּאִינוּן בְּנֵי אֱלֹהִים, קַיְימוּ עֲלַיְיהוּ. וְכַד מְסַיְימוּ שְׁאָר חַיָּילִין דְּקָא מְשַׁבְּחִין בְּלֵילְיָא, אִינוּן בְּנֵי אֱלֹהִים תּוֹקְעִין תְּרוּעָה, וּמִתְכַּנְסִין כָּל מַשִּׁרְיָין דְּשָׁלְטִין בְּלֵילְיָא לְאַתְרַיְיהוּ.</p>"],[9514014379,"<p>כְדֵין אִינוּן כּוֹכְבַיָא דְּשָׁלְטִין בִּיְמָמָא, בְּצַפְרָא, מְרַתְּתִין וְדָחֲלֵי וְסָלְקֵי שִׁירָתָא. וְהַשְׁתָּא מָטָא זִמְנַיְיהוּ, לְשַׁבְּחָא לְמָרַיְיהוּ, בְּזִמְנָא דָא דְּשָׁמְעִין הַהִיא תְּרוּעָה. דִּכְתִיב, (איוב ל״ח:ז׳) בְּרָן יַחַד כּוֹכְבֵי בֹקֶר וַיָּרִיעוּ כָּל בְּנֵי אֱלֹהִים.</p>"],[9514014380,"<p>אַקְדימוּ וַאֲזָלוּ, וַהֲוָה נָהֵיר יְמָמָא. כַּד נְפַק שִׁמְשָׁא וְאִתְגְּלֵי לְעַלְמָא, אֲמַר לֵיהּ רַבִּי יִצְחָק לְרַבִּי נְהוֹרָאי, תְּוַוהְנָא כַּד אִסְתַּכַּלְנָא בְּשִׁמְשָׁא, דְּכִי נָפַק, נָפֵיק סוּמְקָא, וּלְבָתַר הָכֵי אִתְהַדַּר חִוְּורָא. אַמַּאי.</p>"],[9514014381,"<p>וַדַּאי אִדְכַּרְנָא מִלָּה, דַּאֲמַר רַבִּי יוֹסֵי בֶּן שָׁלוֹם, אֲמַר רַבִּי יִצְחָק בֶּן יְהוּדָא, שִׁמְשָׁא כַּד נָפֵיק, נָפֵיק בְּתוֹקְפָא, כִּגְבַר תַּקִּיף. ובָקַע תְּלֵיסַר מַשְׁקוֹפֵי חַלּוֹנֵי דִרְקִיעָא.</p>"],[9514014382,"<p>וְלֵית בְּכָל אִינוּן כּוֹכְבֵי שְׁמַיָא וּמַזָּלֵי דְּאִיקְּרֵי גִבּוֹר, בַּר מִשִּׁמְשָׁא. מַה גְּבוּרָה עָבִיד. אֶלָּא כַּד אִסְתַּיֵּים יְמָמָא וְעָאל לֵילְיָא, אִסְתַּתְּמָן כָּל אִינוּן כֵּוִין וּמַשְׁקוֹפִין דִּרְקִיעָא. בְּשַׁעֲתָא דְּאָתֵי יְמָמָא וְשִׁמְשָׁא נְפַק, אִתְעַטַר וְאִתְגְּלֵיף בְּאַתְוָון דְּרָזָא דִּשְׁמָא קַדִּישָׁא, וּבְתוֹקְפָא וּבְחֵילָא דִּילֵיהּ, כָּנֵיס בְּכָל אִינוּן רְקִיעִין, וּבָקַע בְּכָל אִינוּן חַלּוֹנִין, וְאִתּוֹקְדוּן בְּשַׁלְהוֹבוֹי, וּפְתַח לוֹן וּנְפַק לְבַר.</p>"],[9514014383,"<p>וּמְנָא לָן דְּאִתְקְרֵי גִבּוֹר. דִּכְתִיב, (תהילים י״ט:ו׳) יָשִׂישׂ כְּגִבּוֹר לָרוּץ אוֹרַח. וּכְתִיב, (שופטים ה׳:ל״א) כְּצֵאת הַשֶּׁמֶשׁ בִּגְבוּרָתוֹ. כְּגִבּוֹר שֶׁנִּכְנַס לַמִּלְחָמָה וְנוֹצֵחַ, הוּא אָדוֹם. כְּשֶׁנִּצַּח חוֹזֵר לִגְוָונוֹ הָרִאשׁוֹן. כָּךְ הַשֶּׁמֶשׁ, כְּשֶׁיּוֹצֵא, נִדְלָקִים בּוֹ שַׁלְהָבוֹתָיו, וְהוּא אָדוֹם מֵרוֹב גְּבוּרָתוֹ, וְאַחַר כָּךְ חוֹזֵר לַגַּוָּון הָרִאשׁוֹן.</p>"],[9514014384,"<p>אֲזָלוּ, כַּד מָטוּ בֵּי חֲקַל, אֲמַר רַבִּי יִצְחָק, לֵימָא מַר מֵאִינוּן מִילִין דְּמַעַלְיָיתָא דְּבִקְרִיאַת שְׁמַע. פָּתַח וְאָמַר, (דברים ו׳:ד׳) שְׁמַע יִשְׂרָאֵל ה' אֱלֹהֵינוּ ה' אֶחָד. הַאי קְרָא, תֵּינַח בְּשַׁעֲתָא דַּאֲמָרוּ בְּנִין דְּיַעֲקֹב לַאֲבוּהוֹן, אוֹ משֶׁה לְיִשְׂרָאֵל, אֲבָל הַשְׁתָּא, כֻּלָּא עַלְמָא אָמְרֵי שְׁמַע יִשְׂרָאֵל, לְמַאן יִשְׂרָאֵל אָמְרִין.</p>"],[9514014385,"<p>אֶלָא הָא תָּנִינָא, יַעֲקֹב אָבִינוּ לֹא מֵת, וְהַקָדוֹשׁ בָּרוּךְ הוּא חָתִים לֵיהּ גּוֹ כּוּרְסָא יְקָרֵיהּ, לְמֶהֱוֵי תָּדִיר סַהֲדָא עַל בְּנוֹי, דְּקָא מְיַחֲדֵי שְׁמֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא כִּדְחָזֵי, בְּכָל יוֹמָא תְּרֵין זִמְנֵי, וְכַד אִינוּן מְיַחֲדִין שְׁמֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא, אָמְרֵי שְׁמַע יִשְׂרָאֵל, הֲוֵי סָהֵיד עֲלָן, דַּאֲנַן מְיַחֲדֵי שְׁמֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא כִּדְקָא חָזֵי.</p>"],[9514014386,"<p>בְּהַהוּא שַׁעֲתָא, נָטְלֵי לֵיהּ לְיַעֲקֹב בְּאַרְבַּע גַּדְפִין, פְּרִישָׂן לְאַרְבַּע סִיטְרֵי עָלְמָא, וְסָלְקֵי לֵיהּ לְקַמֵּי קַדִּישָׁא עִילָּאָה, וּמְבָרַךְ לֵיהּ בְּשֶׁבַע בִּרְכָאן. פְּתַח הַקָּדוֹשׁ בָּרוּךְ הוּא וַאֲמַר, זַכָּאָה אִיהוּ אַבָּא, דְּזַרְעָא דָּא אוֹלִיד בְּאַרְעָא. זַכָּאִין אִינוּן בְּנִין, דְּקָא מְעַטְרִין לַאֲבוּהוֹן הָכֵי. בְּהַהִיא שַׁעֲתָא, כָּל אִינוּן חֵילֵי דִשְׁמַיָא, פָּתְחֵי וְאָמְרֵי בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד.</p>"],[9514014387,"<p>וְיַעֲקֹב מִתְעַטֵר בִּתְלֵיסַר נַהֲרָא אֲפַרְסְמוֹנָא דַכְיָא, וְקָאִים תָּדִיר כְּקַרְתָּא מֻקָּפָא שׁוּר עַל בְּנוֹי קַמֵּיהּ דְקוּדְשָׁא בְּרִיךְ הוּא, וְלָא שָׁבַק דִּינָא תַּקִּיפָא לְשַׁלְטָא עֲלַיְיהוּ, וְכָל בְּנֵי עַלְמָא לָא יָכְלִין לְשֵׁצָאָה לְהוֹן. הֲדָא הוּא דִכְתִיב, (ישעיה מד) אַל תִּירָא עַבְדִּי יַעֲקֹב.</p>"],[9514014388,"<p>פְּתַח רַבִּי יְהוּדָאי וַאֲמַר, בְּדוּגְמָא דְּאִית י\"ב שְׁבָטִים לְתַתָּא, דְּאִינוּן בְּנֵי יַעֲקֹב, כָּךְ אִיתָא יַעֲקֹב עִילָּאָה בִּשְׁמַיָא, וּתְרֵי עֲשַׂר שְׁבָטִין עִילָּאִין. וּבְדוּגְמָא דִּמְיַיחֲדֵי שְׁמֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא יִשְׂרָאֵל לְתַתָּא, כָּךְ מְיַיחֲדֵי מַלְאֲכֵי קַדִּישִׁין לְעֵילָא. וְכוֹלָּא בְּגַוְונָא דִלְעֵילָא.</p>"],[9514014389,"<p>פָּתַח רַבִּי נְהוֹרָאי וְאָמַר, (ישעיה כט) לָכֵן כֹּה אָמַר ה' אֶל בֵּית יַעֲקֹב אֲשֶׁר פָּדָה אֶת אַבְרָהָם לֹא עַתָּה יֵבוֹשׁ יַעֲקֹב וְלֹא עַתָּה פָּנָיו יֶחֱוָרוּ. וְכִי יַעֲקֹב פָּדָה אֶת אַבְרָהָם, וְיַעֲקֹב לָא אִבְרֵי בְּעָלְמָא.</p>"],[9514014390,"<p>אֶלָּא תָּא חֲזֵי, בְּשַׁעֲתָא דַּהֲווֹ מַפְּלֵי לְאַבְרָהָם בְּאוּר כַּשְׂדִּים, הַקָּדוֹשׁ בָּרוּךְ הוּא אַכְנֵישׁ לְפַמַּלְיָא דִילֵיהּ, וַאֲמַר שְׁזִיבוּ לְאַבְרָהָם מִגּוֹ יְקִידָא דִילֵיהּ, דְּאִיהוּ רְחִימָאי.</p>"],[9514014391,"<p>אֲמָרוּ לְהַקָּדוֹשׁ בָּרוּךְ הוּא, הָא יִפּוֹק מִינֵיהּ יִשְׁמָעֵאל. אֲמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, הָא יִפּוֹק מִינֵיהּ יִצְחָק. אֲמָרוּ לְהַקָּדוֹשׁ בָּרוּךְ הוּא, הָא יִפּוֹק מִינֵּיהּ עֵשָׂו. אֲמַר הַקָדוֹשׁ בָּרוּךְ הוּא, הָא יִפּוֹק מִינֵיהּ יַעֲקֹב. אֲמָרוּ, הָא וַדַּאי בִּזְכוּת יַעֲקֹב יִשְׁתְּזֵיב. וְעַל דָּא אֲמַר, אֲשֶׁר פָּדָה אֶת אַבְרָהָם, דְבִזְכוּתֵיהּ אִישְׁתְּזֵיב אַבְרָהָם.</p>"],[9514014392,"<p>אֲמַר רַבִּי, בְּשָׁעָה דִּכְפִיתוּ לַחֲנַנְיָה מִישָׁאֵל וַעֲזַרְיָה, דְּיִפְּלוּן לוֹן בְּגוֹ אַתּוּן נוּרָא יְקֵידְתָּא. חֲנַנְיָה אֲמַר, (תהילים קי״ח:ו׳) ה' לִי לֹא אִירָא מַה יַּעֲשֶׂה לִי אָדָם. מִישָׁאֵל אֲמַר, (ירמיה כז) וְאַתָּה אַל תִּירָא עַבְדִּי יַעֲקֹב וְאַל תֵּחַת יִשְׂרָאֵל כִּי אִתְּךָ אָנִי נְאֻם ה'. עֲזַרְיָה אֲמַר, שְׁמַע יִשְׂרָאֵל וְגו'.</p>"],[9514014393,"<p>אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, (ישעיהו מ״ד:ה׳) זֶה יֹאמַר לַה' אָנִי, זֶה חֲנַנְיָה, שֶׁאָמַר ה' לִי לֹא אִירָא. וְזֶה יִקְרָא בְּשֵׁם יַעֲקֹב, זֶה מִישָׁאֵל, שֶׁאָמַר וְאַתָּה אַל תִּירָא עַבְדִּי יַעֲקֹב. וּבְשֵׁם יִשְׂרָאֵל יְכַנֶּה, זֶה עֲזַרְיָה, שֶׁאָמַר שְׁמַע יִשְׂרָאֵל וכו'. לֹא עַתָּה יֵבוֹשׁ יַעֲקֹב וְלֹא עַתָּה פָּנָיו יֶחֱוָרוּ.</p>"],[9514014394,"<p>וְלָמָּה לָא הֲוָה דָנִיֵּאל בְּהוֹן. אֶלָּא דָּנִיֵּאל אֲמַר, אֲנִי נִקְרָא בֵּלְטְשַׁצַר, כְּשֵׁם אֱלִיל שֶׁלּוֹ. שֶׁנֶּאֱמַר, א (דניאל ד׳:ה׳) בֵּלְטְשַׁאצַּר כְּשֻׁם אֱלָהִי כו', וּכְתִיב, (שם ב) בֵּאדַיִן מַלְכָּא נְבוּכַדְנֶצַּר נְפַל עַל אַנְפּוֹהִי וּלְדָנִיֵּאל סְגִד. וְהַקָדוֹשׁ בָּרוּךְ הוּא אָמַר, פְּסִילֵי אֱלֹהֵיהֶם תִּשְׂרְפוּן בָּאֵשׁ, אֲזַל וְלָא הֲוָה עִמְּהוֹן.</p>"],[9514014395,"<p>מָה רָאוּ חֲנַנְיָה מִישָׁאֵל וַעֲזַרְיָה דְּנָפְלוּ בְּנוּרָא. אֶלָּא אֲמָרוּ, צְפַרְדְּעִים מַפְּלִין גּוּפְהוֹן בְּנוּרָא, בִּשְׁבִיל לְאַבְאֵישׁ לְמִצְרָאֵי, בְּמַאֲמָר דְּקוּדְשָׁא בְּרִיךְ הוּא. אֲנַחְנָא עַל אַחַת כַּמָּה וְכַמָּה בִּשְׁבִיל יְקָרָא דְּמָארָנָא.</p>"],[9514014396,"<p>אֲזָלוּ וְאִתְעַסְּקוּ בְּאוֹרַיְיתָא, אַדְּהָכֵי רָמַשׁ שִׁמְשָׁא. אֲמַר רַבִּי נְהוֹרָאי, נְעִבַר מֵאָרְחָא, וּנְסַלַק לְטוּרָא, וְנִשְׁתַּדֵּל בְּאוֹרַיְיתָא, וְלָא נִדְמוּךְ.</p>"],[9514014397,"<p>עַד דַּהֲווֹ יַתְבֵי וּמִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא דָא עִם דָּא, שְׁמָעוּ חַד קָלָא דְּהֲוָה אֲמַר, עִילָּאִין קוּמוּ. תַּתָּאִין דְּמִיכִין, דְּשִׁנְתָא בְּחוֹרֵיהוֹן, אִיתְעָרוֹ. הָא הַקָּדוֹשׁ בָּרוּךְ הוּא בָּעֵי לְמִרְגַּז עָלְמָא, וְאִינוּן סָמְכִין קַיָּימִין, דְּעַלְמָא סָמֵיךְ עֲלֵיהוֹן, מְרַתְּתֵי. קָל בִּכְיָיא, דְּחַד אוּזִילָא דְּאַיַּלְתָּא, דְּקָא בָּכְיָיא עַל חַד אִרְיָיא, דְּאִיתְרְשֵׁים תְּדִירָא בְּכוּרְסְיָיא קַדִּישָׁא.</p>"],[9514014398,"<p>אֲמַר רַבִּי נְהוֹרָאי לְרַבִּי יִצְחָק, שָׁמְעֵת מִידֵי. אֲמַר לֵיהּ, שְׁמַעְנָא, וְעַל דָּא אֲמִינָא, (לא ידוע) שָׁמַעְתִּי וַתִּרְגַּז בִּטְנִי. אֲמַר ר' נְהוֹרָאי, וַדַּאי הַקָּדוֹשׁ בָּרוּךְ הוּא בָּעֵי לְמֵידַן עַלְמָא דִּילֵיהּ, וְעַד לָא יִתְעֲבֵד דִּינָא, הָא קָלָא אִיתְעַר, וְאַכְרֵיז תָּדִיר בְּעַלְמָא. וַדַּאי רָמֵי דְרָמִין יִסְתַּלְקוּן הַשְׁתָּא בְּעַלְמָא. וְכוֹלָּא בָּרֵיר לָן, בַּר הַאי דַּאֲמַר, קָל בִּכְיָיא דְּחַד אוּזִילָא דְּאַיַּלְתָּא, דְּקָא בָּכֵי עַל חַד אִרְיָיא, לָא יָדַעְנָא מַאי אִיהוּ.</p>"],[9514014399,"<p>אֲמַר רַבִּי נְחֶמְיָה, לָא יָדְעוּ בְּהַאי לְפוּם שַׁעֲתָא, לְיוֹמִין זְעִירִין אִיתְגְּלֵי בְּעָלְמָא, וּמַאי אִיהוּ בִּכְיָיא. דָּא בִּכְיָיא דְּרַבִּי יִשְׁמָעֵאל בֶּן אֱלִישָׁע כֹּהֵן גָּדוֹל, דִּבְכָה עַל רֵישֵׁיהּ דְּרַבָּן שִׁמְעוֹן בֶּן גַּמְלִיאֵל. דְּהַהִיא בִּכְיָיא לָא אִתְעֲבַר מִכּוּרְסָא דְמַלְכָּא, עַד דְּיַעֲבֵיד הַקָּדוֹשׁ בָּרוּךְ הוּא נוּקְמִין בִּשְּׁאָר עַמִּין.</p>"],[9514014400,"<p>אֲמַר רַבִּי רְחוּמָאי, בֹּא וּרְאֵה, בְּשָׁעָה שֶׁהַקָדוֹשׁ בָּרוּךְ הוּא דָּן אֶת הָעוֹלָם, לְמִי דָן תְּחִלָּה, לִגְדוֹלֵי הַדּוֹר דָּן תְּחִלָּה, וְאַחַר כַּךְ דָּן אֶת הָעוֹלָם. מְנָלָן. מֵהָכָא, דִּכְתִיב, וַיְהִי בִּימֵי שְׁפֹט הַשֹׁפְטִים, שְׁפֹט הַשֹׁפְטִים תְּחִלָּה, וְאַחַר כַּךְ וַיְהִי רָעָב בָּאָרֶץ. רַבִּי יוֹסֵי בַּר יְהוּדָה אָמַר, מֵהָכָא, (מלכים א ח׳:נ״ט) לַעֲשׂוֹת מִשְׁפַּט עַבְדּוֹ וּמִשְׁפַּט עַמּוֹ יִשְׂרָאֵל. מִשְׁפַּט עַבְדּוֹ תְּחִלָּה, וְאַחַר כָּךְ מִשְׁפַּט עַמּוֹ יִשְׂרָאֵל.</p>"],[9514014401,"<p>(רות א׳:א׳) וַיֵּלֶךְ אִישׁ מִבֵּית לֶחֶם יְהוּדָה. רַבִּי יְהוּדָה וְרַבָּנָן דְּאָמְרֵי, בִּזְּמַן שֶׁהַדִּין בָּא לָעִיר, יְסַלֵּק אָדָם עַצְמוֹ מֵאוֹתָהּ עִיר, שֶׁכֵּיוָן שֶׁנִּיתַּן רְשׁוּת לְמַלְאַךְ הַמָּוֶת, אֵינוֹ חוֹשֵׁשׁ לְכָל אָדָם, וְאִישׁ שֶׁפָּגַע בּוֹ, יֵשׁ לוֹ רְשׁוּת לְהַזִּיקוֹ.</p>"],[9514014402,"<p>כֵיוָן שֶׁרָאָה אֱלִימֶלֶךְ, שֶׁהַדִּין בָּא לָעוֹלָם, מִיָּד בָּרַח לְהִסְתַּלֵּק מִן הַדִּין, וְעִם כָּל דָּא לֹא בָּרַח מִמֶּנּוּ. רַבָּנָן דְּקֵיסָרִין אָמְרֵי, אֱלִימֶלֶךְ גְּדוֹל הַדּוֹר הָיָה, וְהָיָה נִיכָּר לְמַעְלָה, וְכָל מִי שֶׁהוּא נִיכָּר לְמַעְלָה, הוּא נִתְּפַס תְּחִלָּה.</p>"],[9514014403,"<p>רַבִּי יְהוֹשֻׁעַ אָמַר, מַה כְּתִיב בַּשּׁוּנַמִּית. (מלכים ב ד׳:י״ג) וַתֹּאמֶר בְּתוֹךְ עַמִּי אָנֹכִי יוֹשָׁבֶת. מִכָּאן, שֶׁצָּרִיךְ לְהַכְנִיס רֹאשׁוֹ לְתוֹךְ רַבִּים, וְלֹא יְהֵא נִרְשַׁם לְבַד.</p>"],[9514014404,"<p>מַה כְּתִיב בַּתְּחִלָּה. וַיֵּלֶךְ אִישׁ סְתָם, רָצָה לְהַחְבִּיא וּלְהַסְתִּיר עַצְמוֹ שֶׁלֹּא יַכִּירוּ בוֹ. מִי הִכִּירוּ. מִדַּת הַדִּין. וְאָמַר, וְשֵׁם הָאִישׁ אֱלִימֶלֶךְ, אָדָם נִיכָּר וְנִרְשָׁם הוּא, לְהִסָּתֵר אֵינוֹ רָאוּי, וְלֹא לְהַחְבִּיא. וְלָא אִיהוּ דָא אֱלִימֶלֶךְ, פַּרְנָסָא דְעַמָּא. וְלָא אִיהוּ דָא אֱלִימֶלֶךְ, דְּהֲוָה סְתִים עֵינוֹי מֵעוֹבָדֵי עַמָּא.</p>"],[9514014405,"<p>רַבִּי פְּרַחְיָא אָמַר, בְּאוֹתָהּ שָׁעָה הָיָה הַקָּדוֹשׁ בָּרוּךְ הוּא דָּן אֶת הָעוֹלָם, וּבֵית דִּין שֶׁלְּמַעְלָה עוֹמֵד, וְהַקָדוֹשׁ בָּרוּךְ הוּא הָיָה מַסְתִּירוֹ וְאוֹמֵר, וַיֵּלֶךְ אִישׁ סְתָם. עָמְדָה מִדַּת הַדִּין וְהִזְכִּירוֹ, וְשֵׁם הָאִישׁ אֱלִימֶלֶךְ. מִיָּד נִגְזַר עָלָיו הַדִּין, וְעַל בָּנָיו. כְּדִכְתִיב, וַיָּמָת אֱלִימֶלֶךְ וְגו'.</p>"],[9514014406,"<p>רַבִּי יְהוּדָה אָמַר, אֱלִימֶלֶךְ, מִי לָא הֲוָה יָדַע דְּהוּא אֱלִימֶלֶךְ דָּא. אֶלָּא כֵּיוָן שֶׁרָאָה שֶׁהַדּוֹר מְבַזִּין בִּגְדוֹלִים, אָמַר וַדַּאי אֵלֵךְ מִכָּאן, וְלֹא אֶהְיֶה נִתְּפַס בְּתוֹכָם. וֶאֱלִימֶלֶךְ גְּדוֹל הַדּוֹר הָיָה, וְהָיָה יְכוֹלֶת בְּיָדוֹ לִמְחוֹת, וְלֹא מִיחָה. וְהָלַךְ מִשָּׁם וּבָרַח, וּלְפִיכָךְ נִזְכָּר שְׁמוֹ וְנֶעֱנָשׁ.</p>"],[9514014407,"<p>(רות א) וַיְהִי בִּימֵי שְׁפֹט הַשֹׁפְטִים. רַבִּי יְהוֹשֻׁעַ אָמַר, כָּל מָקוֹם שֶׁנֶּאֱמַר וַיְהִי בִּימֵי, לָשׁוֹן צַעַר הוּא. אֱלִימֶלֶךְ, הוּא הָיָה כְּדוּגְמַת מֶלֶךְ. כֵּיוָן שֶׁהִכִּיר בַּדָּבָר, הִשְׁמִיט עַצְמוֹ מִיִּשְׂרָאֵל, וְהָלַךְ לָּגוּר בֵּין הָאוּמּוֹת, דְּסָבַר שֶׁלֹּא יְהֵא נִידּוֹן בֵּינֵיהוֹן. עָמְדָה מִדַּת הַדִּין וְהִזְכִּירוֹ, וְנִתְּפַשׂ.</p>"],[9514014408,"<p>וַיְהִי בִּימֵי שְׁפֹט הַשֹׁפְטִים, רַבִּי חִלְקְיָה בַּר אֱלִיעֶזְר פָּתַח קְרָא דִּכְתִיב, (ירמיה לא) מֵרָחוֹק ה' נִרְאָה לִי וְגו'. כְּשֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מְדַבֵּר עִם הַנְּבִיאִים, אֵינוֹ נִגְלָה אֲלֵיהֶם אֶלָּא מֵרָחוֹק. וְעַל כֵּן רוֹאִים דְּמוּת דְּבָרִים, כְּאָדָם הָעוֹמֵד מִמֶּרְחָק, חוּץ מִמּשֶׁה.</p>"],[9514014409,"<p>דְּאָמַר רַבִּי אֶלְעָזָר אָמַר רַבִּי חֲנִינָא, כָּל הַנְּבִיאִים כּוּלָּם לֹא נִתְנַבְּאוּ אֶלָּא מִתּוֹךְ אַסְפַּקְלַרְיָא שֶׁאֵינָהּ מְאִירָה, משֶׁה מִתּוֹךְ אַסְפַּקְלַרְיָא הַמְאִירָה. שְׁאָר הַנְּבִיאִים מֵרָחוֹק, וּמשֶׁה מִקָּרוֹב. שֶׁנֶּאֱמַר, (במדבר יב) לֹא כֵן עַבְדִּי משֶׁה בְּכָל בֵּיתִי נֶאֱמָן הוּא. מְהֵימְנָא בְּבֵית מַלְכָּא, קָרֵיב הוּא לְמַלְכָּא.</p>"],[9514014410,"<p>וְאִי תֵימָא, כֵּיוָן דְּכָל הַנְּבִיאִים נִתְנַבְּאוּ מֵרָחוֹק, אֵין אַהֲבָתוֹ שֶׁל מָקוֹם עֲלֵיהֶם. כְּתִיב, ק (ירמיה לא) מֵרָחוֹק ה' נִרְאָה לִי וְאַהֲבַת עוֹלָם אֲהַבְתִּיךְ עַל כֵּן מְשַׁכְתִּיךְ חָסֶד.</p>"],[9514014411,"<p>אָמַר רַבִּי חֲנִינָא, יֵשׁ רָחוֹק וְנִתְקָרֵב, וְקָרוֹב וְנִתְרַחֵק. יֵשׁ רָחוֹק וְנִתְקָרֵב, דִּכְתִיב, (משלי לא) מִמֶרְחָק תָּבִיא לַחְמָהּ. קָרוֹב וְנִתְרַחֵק, דִּכְתִיב, מֵרָחוֹק ה' נִרְאָה לִי. זֶה קָרוֹב לַנְּבִיאִים. וְזֶה רָחוֹק לַמַּלְכוּת. רַבִּי אֶלְעָזָר אוֹמֵר, אִיפְכָא, קָרוֹב לַמַּלְכוּת. וְרָחוֹק לַנְּבִיאִים. שֶׁרוֹאִין דִּמְיוֹנוֹת שֶׁל מַעְלָה כְּמִין גּוּף.</p>"],[9514014412,"<p>רַבִּי חִלְקְיָה אָמַר, כְּשֶׁרוֹאִין הַנְּבִיאִים בְּצִיחְצוּחַ, בְּיָדוּעַ שֶׁהָעוֹלָם נִידּוֹן לְמֵיטַב. וּכְשֶׁרוֹאִים בַּחֲשֵׁיכָה, נִידּוֹן לְפֻרְעָנֻיּוֹת. וַאֲזַי פָּתַח קְרָא, וַיְהִי בִּימֵי שְׁפֹט הַשֹׁפְטִים וְגו'.</p>"],[9514014413,"<p>וַיְהִי בִּימֵי. רַבִּי בּוֹן, כָּל יוֹמוֹי הֲוָה בְּקֵסָרִין, יוֹמָא חַד חָמָא עַמָּא דְסָרְחֵי, דַּהֲווֹ מִסְכְּנֵי אָזְלוֹ, וְלָא מַשְׁגִּיחִין עֲלַיְיהוּ. אֲמַר, וַדַּאי דִינָא אִתְחֲזֵי הָכָא, קָם וַאֲזֵיל לֵיהּ.</p>"],[9514014414,"<p>יוֹמָא חַד חָלִישׁ דַּעְתֵּיהּ, פָּגַע בִּכְפַר סִיכְנִין בְּרִמּוֹן, וְאַדְמוּךְ. שָׁמַע חַד קָלָא, לְחַד תַּנָּא דְּלָעֵי בִּרְנָנָא דְאוֹרַיְיתָא דַּאֲמַר, (דברים כב) כִּי יִקָּרֵא קַן צִפוֹר לְפָנֶיךָ וכו'. קַן, זֶה תְּשׁוּבָה. בַּדֶּרֶךְ, זֶה רָחֵל. שֶׁנֶּאֱמַר, (משלי ד) וְאֹרַח צַדִּיקִים כְּאוֹר נֹגַהּ הוֹלֵךְ וְאוֹר עַד נְכוֹן הַיּוֹם. וְצַדִּיקִים, תְּרֵין בְּנִין, יוֹסֵף וּבִנְיָמִין. וְהִיא נִקְרֵאת לְבָנָה, הוֹלֶכֶת כָּל הַלַּיְלָה, וּמֵאִיר לָהֶם, עַד נְכוֹן הַיּוֹם, שֶׁהוּא יַעֲקֹב.</p>"],[9514014415,"<p>בְּכָל עֵץ, כָּל, דָּא צַדִּיק חַי הָעוֹלָמִים. עֵץ, דָּא שְׁכִינָה. שֶׁנֶּאֱמַר, עֵץ חַיִּים הִיא לַמַּחֲזִיקִים בָּהּ. עַל הָאָרֶץ, דָּא אֶרֶץ הַתַּחְתּוֹנָה. אֶפְרוֹחִים, דָּא שְׁנֵים עָשָׂר שְׁבָטִים דִּלְעֵילָא. אוֹ בֵּצִים, דָּא יִשְׂרָאֵל דִּלְתַתָּא, דְּאִינוּן כְּמַלְבּוּשָׁא דְגוּפָא. וְהָאֵם רוֹבֶצֶת עַל הָאֶפְרוֹחִים וכו', שַׁלֵּחַ תְּשַׁלַּח אֶת הָאֵם, שֶׁנֶּאֱמַר, (ישעיה נ) וּבְפִשְׁעֲכֶם שֻׁלְחָה אִמְּכֶם.</p>"],[9514014416,"<p>וְאֶת הַבָּנִים תִּקַּח לָךְ. אַרְכִין רַבִּי בּוֹן אוּדְנוֹי, וּשְׁמַע הַהוּא קָלָא דַּאֲמַר, חָס עַל דָּא, לָא אֲמַר וְלָא כְלוּם. מַאן דְּחָס, שְׁבַק אִימָּא וּבְנָהָא וְאָזֵיל לֵיהּ. וּמַה דְּאִימָּא מִתָּרְכָא מִן הַקַּן, מַה הִיא אוֹמֶרֶת. אוֹי שֶׁהֶחֱרַבְתִּי אֶת בֵּיתִי, וְשָׂרַפְתִּי אֶת הֵיכָלִי, וְהִגְלֵיתִי בָּנַי לְבֵין הָאוּמּוֹת. וְעַל דָּא יְרַחֵם הַקָּדוֹשׁ בָּרוּךְ הוּא, דְּהָא רַחֲמָנָא לָא אִשְׁתַּכַּח אֶלָא הָכֵי.</p>"],[9514014417,"<p>וְעַל דָּא שְׁכִינָה צוֹעֶקֶת עַל בָּנֶיהָ. הָא כְתִיב, שַׁלֵּחַ תְּשַׁלַּח, תְּרֵין שִׁלּוּחִין, דְּאִינוּן בַּיִת רִאשׁוֹן וּבַיִת שֵׁנִי. שַׁלֵּחַ תְּשַׁלַּח אֲפִילּוּ ק' זִימְנִין דְּאִי אַהֲדַר עַל גּוֹזָלֵיהּ גּוֹ רְחִימוּ דִּבְנָהָא, שַׁלֵּחַ אֲפִילּוּ כַּמָּה זִמְנִין, עַד דַּאֲזַל לֵיהּ וְסָתַר קַן שֶׁלָּהּ, וְיִטוֹל בְּנִין טְמִירִין דְּקוּנְטְרָא, לְמֵיטַל אִגְרָא, הָא רַחֲמָנָא לָא אִשְׁתְּכַח אֶלָּא הָכֵי. וְהַאֲרַכְתָּ יָמִים, שֶׁיַּאֲרִיךְ רוֹגֶז מִן שֵׁשֶׁת יָמִים, שֶׁנִּקְרְאוּ אֶרֶךְ אַפַּיִם. ה' ה' אֵל רַחוּם וְחַנּוּן אֶרֶךְ אַפַּיִם וְגו'.</p>"],[9514014418,"<p>אָמַר רִבִּי חִזְקְיָה אֲמַר רַבִּי יוֹסֵי בֶּן קִיסְמָא אָמַר רַבִּי שְׁמוּאֵל, כַּד בְּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא עָלְמָא, בְּרָא לֵיהּ בִּתְלַת קִיטְרִין, וְאִינוּן חָכְמָה וּתְבוּנָה וָדָעַת. דִּכְתִיב, (משלי ג׳:י״ט-כ׳) ה' בְּחָכְמָה יָסַד אָרֶץ כּוֹנֵן שָׁמַיִם בִּתְבוּנָה בְּדַעְתּוֹ תְּהוֹמוֹת נִבְקָעוּ.</p>"],[9514014419,"<p>וְכָלְהוֹ קִיטְרִין בְּבַר נָשׁ. וְקִיטְרָא דִּתְבוּנָה דְּפָקַע מִינַיְיהוּ, אִתְפַּשַּׁט בִּשְׁאָר בִּרְיָין וּבְכוּלְהוֹ אִית סוּכְלְתָנוּ לְפוּם אוֹרְחֵיהּ.</p>"],[9514014420,"<p>הַאי עוֹפָא כַּד פָּרַח מִגּוֹזָלֵיהּ, וְאִשְׁתַּלַּח מֵעַל בְּנָהָא, מְצַפְצְפָא וְאָזְלָא, וְלָא יָדְעָה לְאָן אֲתַר אָזְלָא, מְנַדְּרָא לְמֵיבַד גַּרְמָהּ. הַקָּדוֹשׁ בָּרוּךְ הוּא דִּכְתִיב בֵּיהּ (תהילים קמ״ה:ט׳) וְרַחֲמָיו עַל כָּל מַעֲשָׂיו, אֲפִילּוּ עַל יִתּוּשָׁא זְעֵירָא בְּעָלְמָא, רַחֲמִין דִּילֵיהּ עַל כֹּלָּא. הַהוּא דִּמְמַנָּא עַל עוֹפָּא, אִיתְעַר לְגַבֵּי הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>"],[9514014421,"<p>וְהַקָּדוֹשׁ בָּרוּךְ הוּא אִתְעַר עַל בְּנוֹי, כְּדֵין קָלָא נָפְקָא קַמֵּיהּ, וְאָמְרָה, (משלי כ״ז:ח׳) כְּצִפּוֹר נוֹדֶדֶת מִן קִנָּהּ כֵּן אִישׁ נוֹדֵד מִמְקוֹמוֹ. כְּדֵין אִיהוּ אִתְעַר רַחֲמֵי, עַל כָּל אִינוּן דְּאָזְלֵי מְנַדְּדֵי מֵאֲתַר לַאֲתַר, וּמִדוּךְ לְדוּךְ אָחֳרָא. תְּבִירֵי לִבָּא, תְּבִירֵי חֵילֵי. וְאִיתְעַר רַחֲמֵי עַל כָּל עָלְמִין, וְחָס עֲלַיְיהוּ, וְשָׁבֵיק חוֹבֵי דִּמְנַדְּדָן מֵאַתְרַיְיהוּ, וְחָס עֲלַיְיהוּ וְעַל כָּל עַלְמָא.</p>"],[9514014422,"<p>וְעַל דָּא אֲמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, אַשְׁרֵי צִפּוֹרָא לְבַר, וְהִיא אִיתְעָרַת רַחֲמִין עַל כָּל עָלְמָא, מַאן גָּרִים לְמֵיחַס עַל עַלְמָא וּלְאִיתְעַר רַחֲמִין עֲלַיְיהוּ. הַהוּא בַּר נָשׁ דְּשָׁלַח הַהוּא צִיפּוֹר לְצַעֲרָהּ בִּתְרֵין גְּוָונִין, הָכֵי אִתְעַר הַקָּדוֹשׁ בָּרוּךְ הוּא, וְאִתְמְלֵי רַחֲמִין עַל כָּל אִינוּן מָארֵי דְּצַעֲרָא, וְעַל כָּל אִינוּן דִּמְנַדְּדֵי מִדּוּכְתַּיְיהוּ. וּבְגִין כָּךְ, אַגְרֵיהּ דְּהַאי בַּר נָשׁ, מַה כְּתִיב בֵּיהּ. (דברים כ״ב:ז׳) לְמַעַן יִיטַב לָךְ וְהַאֲרַכְתָּ יָמִים.</p>"],[9514014423,"<p>קָם ר' בּוֹן עַל רַגְלוֹהִי, וְחָדֵי, וַאֲמַר, בְּרִיךְ רַחֲמָנָא דְּשָׁמַעְנָא לְהַאי קָלָא, וְאִלְמָלֵא לָא אֲתֵינָא לְעַלְמָא אֶלָּא לְמִשְׁמַע דָּא, דַּיִּי.</p>"],[9514014424,"<p>אַהֲהַר הַהוּא קָלָא כְּמִלְּקַדְּמִין, פָּתַח וְאָמַר, (תהילים ק״ד:כ״ד) מָה רַבּוּ מַעֲשֶׂיךָ ה' כֻּלָּם בְּחָכְמָה עָשִׂיתָ וְגו'. כָּל עַלְמָא לָא אִיתוֹן אֶלָּא בְּחָכְמָה. וּבַר נַשׁ אִתְמְלֵי בְּכוֹלָּא. שְׁאָר בְּרִיָּין, בְּתוֹסֶפְתָּא דְּחָכְמְתָא, דְּאִשְׁתָּאַר בְּבַר נָשׁ.</p>"],[9514014425,"<p>וְאַף עַל גַּב דְּכוּלְהוֹ בְּרִיָּין הָכֵי, לָא הֲוָה בְּרִיָּה קָלֵיל לְמִירְדַּף בָּתַר עוֹבָדָא דְּבַר נָשׁ, כְּעוֹפָא. בַּר נָשׁ בָּנֵי בִּנְיָין לְדִיּוּרֵיהּ, עוֹפָא בְּנֵי בִּנְיָין לְדִיּוּרֵיהּ. בַּר נָשׁ אַתְיָא מְזוֹנֵי לִבְרֵיהּ, עוֹפָא אַתְיָא מְזוֹנֵי לְבָנֶיהָ. בַּר נָשׁ אַסֵּי לְמַרְעִין בְּעִשְׂבָא, עוֹפָא בְּעִשְׂבָא מַסֵּי לְמַרְעִין. בַּר נָשׁ אוּמָנָא וְעָבִיד אַרְבִין בְּיַמָּא, עוֹפָא נָטַל גּוֹזָלֵיהּ וְאַתְקֵין לֵיהּ עַל כֵּיף יַמָּא.</p>"],[9514014426,"<p>בַּר נָשׁ מְשַׁבַּח וּמְרוֹמֵם לְמַלְכָּא עִילָּאָה, עוֹפָא מְצַפְצְפָא וּמְשַׁבְּחָא לְמָרֵיהּ, דְּהוּא אֱלָהָא עִילָּאָה. וּבְגִין כָּךְ, לְמַעַן יִיטַב לָךְ, אֵטִיב לָךְ לָא כְתִיב, אֶלָּא יִיטַב לָךְ. הַהוּא שִׁלּוּחָא דְּצִיפּוֹרָא דִּמְשַׁלַח, דְּאִתְעַר עַל עַלְמָא לְאוֹטִיב לָךְ.</p>"],[9514014427,"<p>רַבִּי בּוֹן קָם וַאֲזֵיל גַּבֵּיהּ, וְאַשְׁכַּח דְּהוּא רַבִּי יַנַּאי סָבָא, מִן חַבְרַיָיא. עָאל גַּבּוֹי, וּנְשֵׁיק לֵיהּ בְּרֵישָׁא. אֲמַר, כְּמָה דִּמְנַחַמְתְּ לִבָּאי, כָּךְ יְנַחֵם הַקָּדוֹשׁ בָּרוּךְ הוּא לָךְ. יְתִיבוּ כַּחֲדָא.</p>"],[9514014428,"<p>פָּתַח הַהוּא סָבָא וְאָמַר, (רות א׳:א׳) וַיְהִי בִּימֵי שְׁפֹט הַשֹׁפְטִים וַיְהִי רָעָב בָּאָרֶץ. בִּזְּמַן שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא דָּן אֶת הָעוֹלָם, לְמִי הוּא דָן תְּחִלָּה. לְאוֹתָם שֶׁהֵם דָּנִין אֶת הָעוֹלָם, הֵם דָּנִין אֶת הָעוֹלָם, מִי דָן אוֹתָם. הַקָדוֹשׁ בָּרוּךְ הוּא. מִפְּנֵי קִלְקוּל הַדִּין, רָעָב בָּא לָעוֹלָם.</p>"],[9514014429,"<p>בְּכָל זְמַן אֵינוֹ בָּא, אֶלָּא בַּעֲוֹן רָאשֵׁי הָעָם. כִּי הָא דְּאָמַר רַבִּי יוּדָאי, מַאי דִכְתִיב, (משלי י״ג:כ״ג) רָב אֹכֶל נִיר רָאשִׁים וְיֵשׁ נִסְפֶּה בְּלֹא מִשְׁפָּט. כְּשֶׁיֵּשׁ סִיפּוּק אוֹכֶל בָּעוֹלָם, נִיר רָאשִׁים, הֵם זוֹרְעִים וְאוֹכְלִים לָשׂוֹבַע. וּכְשֶׁאֵין אוֹכֶל בָּעוֹלָם, יֵשׁ נִסְפֶּה בְּלֹא מִשְׁפָּט, יֵשׁ מִי שֶׁעוֹמֵד בְּשַׁלְוָה, וְנִסְפֶּה מִן הָעוֹלָם. עַל אֵיזֶה עָוֹן. עַל עָוֹן שֶׁמְקַלְקְלִים אֶת הַדִּין וְאֶת הַמִּשְׁפָּט, וּמְעַוְּותִין אוֹתוֹ.</p>"],[9514014430,"<p>וְאִי תֵימָא, אִם הַגְּדוֹלִים חוֹטְאִים בְּלֹא מִשְׁפָּט, שֶׁלֹּא עָשׂוּ מִשְׁפָּט בָּעוֹלָם, הַקָּדוֹשׁ בָּרוּךְ הוּא בָּא לַהֲרוֹג הָעֲנִיִּים בִּשְׁבִילָם. אֶלָּא, הָעֲנִיִּים הֵם כֵּלָיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, וְהֵם קְרוֹבִים אֵלָיו, וּכְשֶׁהָרָעָב בָּא לָעוֹלָם, הֵם צוֹעֲקִים אֵלָיו, וְהַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹמֵעַ לָהֶם, וּמְעַיֵּין עַל הָעוֹלָם, וְדָן לְאוֹתָן שֶׁגָּרְמוּ צַעַר זֶה עַל הָעֲנִיִּים, וְנִסְפִּים מִן הָעוֹלָם קוֹדֶם זְמַנָּם. כְּדִכְתִיב, (שמות כ״ב:כ״ו) אִם צָעֹק יִצְעַק אֵלָי וְגו' וְשָׁמַעְתִּי כִּי חַנּוּן אָנִי. וְאוֹמֵר, (שם) וְחָרָה אַפִּי וְהָרַגְתִּי אֶתְכֶם בֶּחָרֶב וְגו'.</p>"],[9514014431,"<p>בְּוַדַּאי, בְּאוֹתוֹ זְמַן, יֵשׁ נִסְפֶּה וּמִסְתַּלֵּק מִן הָעוֹלָם, קוֹדֶם זְמַנּוֹ, בְּלֹא מִשְׁפָּט, עַל שֶׁלֹּא הוֹצִיאוּ הַמִּשְׁפָּט לְאוֹרָה, וְעַל שֶׁעִוְּותוּ וְקִילְקְלוּ הַמִּשְׁפָּט. דְּאָמַר רַבִּי יוֹסֵי, כָּל דַּיָּין שֶׁאֵינוֹ מַחְמִיץ אֶת הַדִּין, אֵין מַחְמִיצִין דִּינוֹ מִלְּמַעְלָה, וּמִסְתַּלֵּק מִן הָעוֹלָם קוֹדֶם זְמַנּוֹ. הֲדָא הוּא דִכְתִיב, (משלי י״ג:כ״ג) יֵשׁ נִסְפֶּה בְּלֹא מִשְׁפָּט.</p>"],[9514014432,"<p>יֵשׁ מִי שֶׁדָּן אֶת הַדִּין לַאֲמִיתּוֹ, וּמְקַבֵּל שָׂכָר עָלָיו מֵאֵת הַקָּדוֹשׁ בָּרוּךְ הוּא. וְיֵשׁ מִי שֶׁדָּן דִּין אֱמֶת לַאֲמִיתּוֹ, וְנִתְּפַשׂ. כְּגוֹן דַּיָּין שֶׁמְדַקְדֵּק דִּקְדּוּקִים לְזַכּוֹת לְרָשָׁע, וְאֵינוֹ מַעֲנִישׁ אֶלָּא בְּדִין אֱמֶת. דְּתַנְיָא, בֵּית דִּין מַכִּין וְעוֹנְשִׁין שֶׁלֹּא מִן הַתּוֹרָה, כְּדֵי לַעֲשׂוֹת סְיָיג לַתּוֹרָה. אוֹ מִפְּנֵי שֶׁהַזְּמַן גּוֹרֵם, וְהַדַּיָּין מְסַלֵּק עַצְמוֹ מִן הַדִּין, וּמִלְּהַעֲנִישׁוֹ, וּמְדַקְדֵּק בְּעִנְיַן הַדִּין, לִמְצוֹא פֶּתַח לְזַכּוֹת אוֹתוֹ מִן הַדִּין מַמָּשׁ, וְהוּא דִין אֱמֶת, אֲפִילּוּ הָכִי כְּשֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא דָּן אֶת הָעוֹלָם, אוֹתוֹ הַדַּיָּין נִתְּפַס עָלָיו, וּמִסְתַּלֵּק מִן הָעוֹלָם קוֹדֶם זְמַנּוֹ. וְאִם לָאו, עָלָיו הַכָּתוּב אוֹמֵר, (איוב י״ח:י״ט) לֹא נִין לוֹ וְלֹא נֶכֶד בְּעַמּוֹ. כְּשֶׁעַצְמוֹ אֵינוֹ נִתְּפַס, נִתְּפַס זַרְעוֹ.</p>"],[9514014433,"<p>יֵשׁ מִי שֶׁאֵינוֹ דָּן אֶת הַדִּין לַאֲמִתּוֹ, וּמְקַבֵּל עָלָיו שָׂכָר. כְּגוֹן אַבָּא, שֶׁרָאָה אֶחָד מְחַבֵּק לְאֵשֶׁת אִישׁ, וּמְנַשְׁקָהּ, אַפֵּיק לוֹן לְקוֹלְפִין, וְקָטֵיל לוֹן. לָאו דִּבְנֵי הֲרִיגָה נִינְהוּ, אֶלָּא לַעֲשׂוֹת סְיָיג לַתּוֹרָה, דְּלָא יֵימְרוּן, דַּיָּינָא אַפֵּיק לוֹן מִדִּין תּוֹרָה, דְּלָא מִתְחַיְיבֵי קְטוֹל, אֶלָּא וַעֲשׂוּ סְיָיג לַתּוֹרָה. וְדַיָּינָא דְּלָא עָבִיד סְיָיג לַתּוֹרָה, לֵית לֵיהּ סְיָיג בְּעַלְמָא דֵין, שֶׁל נִין וְנֶכֶד עָצוּר וְעָזוּב. וּבָעוֹלָם הַבָּא מַעֲבִירִין מִמֶּנּוּ אוֹתָם מַעֲשִׂים טוֹבִים, שֶׁהֵם סְיָיג לָאָדָם לָעוֹלָם הַבָּא. כִּי הָא דְּאָמַר רַבִּי נוּרִי, עֲשׂוּ סְיָיג לַתּוֹרָה, בְּגִין דְּתוֹרְכוּן חַיִּים בְּהַאי עַלְמָא וּבְעַלְמָא דְאָתֵי.</p>"],[9514014434,"<p>וַיֵּלֶךָ אִישׁ, בְּכָל מָקוֹם שֶׁנֶּאֱמַר אִישׁ, צַדִּיק גָּדוֹל הוּא בְּדוֹרוֹ, שֶׁיּוּכַל לַעֲמוֹד עַל עַצְמוֹ, וְעַל אֲחֵרִים. כְּעִנְיַן זֶה לִגְנַאי, אִישׁ יוֹדֵעַ צַיִד אִישׁ שָׂדֶה, רָשָׁע בְּרִשְׁעוֹ קָטִיל, וּמְקַפֵּחַ בְּנֵי נָשָׁא וְלָא דָחִיל.</p>"],[9514014435,"<p>אֱלִימֶלֶךָ גָּדוֹל בְּדוֹרוֹ, רָאוּי לַעֲמוֹד עַל עַצְמוֹ, וְעַל אֲחֵרִים. כֵּיוָן שֶׁרָאָה הָרָעָב, מִיָּד בָּרַח. לְפִיכָךְ נֶעֱנָשׁ. מִבֵּית לֶחֶם יְהוּדָה, מִמָּקוֹם סַנְהֶדְּרֵי גְדוֹלָה, מִנְּבִיעוּ דְּאוֹרַיְיתָא דְּתַמָּן. כְּמָה דְאַתְּ אָמֵר, (שמואל ב כ״ג:ט״ו) מִי יַשְׁקֵנִי מַיִם מִבּוֹר בֵּית לֶחֶם אֲשֶׁר בַּשָּׁעַר.</p>"],[9514014436,"<p>וְהָא עָקַר רַגְלוֹי מִנְּבִיעוּ דְּאוֹרַיְיתָא דְּבֵית לֶחֶם יְהוּדָה, לָגוּר בִּשְׂדֵי מוֹאָב, וּבְגִין כָּךְ אִתְעֲנָשׁוּ. וְאַנְתְּ רַבִּי, גִּלִּית גַּרְמָךְ בַּאֲתַר דְּנָבְעִין חַבְרַיָּיא מַבּוּעֵי דְאוֹרַיְיתָא הָכָא. אֲמַר, בְּרִיךְ רַחֲמָנָא דְּשַׁדְּרַנִּי הָכָא, לְמִשְׁמַע מִילָךְ.</p>"],[9514014437,"<p>רַבִּי בּוֹן, הֲוָה אָזֵיל יוֹמָא חַד בְּאוֹרְחָא, פָּגַע בֵּיהּ חַד יְנוּקָא. אָמַר לֵיהּ, רַבִּי, תִּבָּעֵי דְּאֵיהַךְ עִמָּךְ בְּאוֹרְחָךְ, וַאֲשַׁמֵּשׁ קַמָּךְ בְּהַאי אוֹרְחָא. אָמַר לֵיהּ, זִיל. אֲזַל אֲבַתְרֵיהּ.</p>"],[9514014438,"<p>עַד דְּהֲוָה אָזֵיל, פָּגְעָן בֵּיהּ, ר' חִיָּיא וְרַבִּי אַבָּא וְרַבִּי יוּדָא וְר' יוֹסֵי, אֲמָרוּ לֵיהּ, אַתְּ בִּלְחוֹדָךְ, וְלֵית מַאן דְטָעִין בַּתְרָךְ. אֲמַר לוֹן, חַד יְנוּקָא הָכָא דְּאָזֵיל אֲבַתְרָאי. אֲמַר רַבִּי חִיָּיא, כְּדַאי הֲוֵית לָחוֹב בְּעַצְמָךְ, דְּלֵית עִמָּךְ עִם מַאן דְּתִשְׁתָּעֵי בְּמִילֵי דְאוֹרַיְיתָא. יָתְבֵי בְּחַקְלָא תְּחוֹת אִילָן חַד.</p>"],[9514014439,"<p>פָּתַח ר' חִיָּיא וְאָמַר, (משלי ד) וְאֹרַח צַדִּיקִים כְּאוֹר נֹגַהּ הוֹלֵךְ וָאוֹר עַד נְכוֹן הַיּוֹם. הַהוֹלֵךְ בַּדֶּרֶךְ צָרִיךְ לִהְיוֹת עִמּוֹ, מִי שֶׁיְדַבֵּר עִמּוֹ בְּדִבְרֵי תוֹרָה. וְכָךְ דַּרְכָּן שֶׁל צַדִּיקִים, הוֹלֵךְ וָאוֹר, הוֹלֵךְ, וְעִמּוֹ דִּבְרֵי תוֹרָה. דִּכְתִיב, (משלי ו) וְתוֹרָה אוֹר. עַד נְכוֹ\"ן הַיּוֹם, עַד שֶׁתִּשְׁתַּתֵּף עִמּוֹ הַשְּׁכִינָה, וְלֹא תָזוּז מִמֶּנּוּ. דְּתָנִינָן, בְּכָל מָקוֹם שֶׁיֵּשׁ דִּבְרֵי תוֹרָה, שְׁכִינָה שָׁם. שֶׁנֶּאֱמַר, (שמות כ) בְּכָל מָקוֹם אֲשֶׁר אַזְכִּיר אֶת שְׁמִי וכו'.</p>"],[9514014440,"<p>פָּתַח רַבִּי יְהוּדָה וְאָמַר, (משלי ג׳:ח׳) רִפְאוּת תְּהִי לְשָׁרֶךָ וְגו'. הַתּוֹרָה הִיא רְפוּאָה לָאָדָם, לַגּוּף וְלָעֲצָמוֹת, בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. דְּאָמַר רַבִּי נְחֶמְיָה אָמַר רִבִּי נְהוֹרָאי, אַסְוָותָא לְבַר נָשׁ בְּהַאי עַלְמָא בְּכָל יוֹמָא, מַאן דְּקָרֵי קְרִיאַת שְׁמַע עַל תִּיקּוּנֵיהּ.</p>"],[9514014441,"<p>וְאָמַר רַבִּי נְהוֹרָאי, בִּקְרִיאַת שְׁמַע יֵשׁ רמ\"ח תֵּיבוֹת, כְּמִנְיַן רמ\"ח אֵבָרִים שֶׁל אָדָם. וְהַקּוֹרֵא קְרִיאַת שְׁמַע כְּתִיקוּנָהּ, כָּל אֵבָר וְאֵבָר נוֹטֵל תֵּיבָה אַחַת לְעַצְמוֹ, וּמִתְרַפֵּא בּוֹ. וְדָא אִיהוּ רִפְאוּת תְּהִי לְשָׁרֶךָ וְשִׁיקּוּי לְעַצְמוֹתֶיךָ.</p>"],[9514014442,"<p>אַדְהָכֵי, מָטָא הַהוּא יְנוּקָא, לָאֵי מֵאוֹרְחָא, וִיתֵיב קַמַּיְיהוּ. שָׁמַע אִלֵּין מִלִּין, קָם עַל רַגְלוֹהִי וַאֲמַר, וַהֲלֹא בִּקְרִיאַת שְׁמַע אֵין שָׁם אֶלָּא רמ\"ה תֵּיבוֹת. אֲמַר לֵיהּ רַבִּי חִיָּיא, תִּיב בְּנִי, יְתִיב, אֲמַר, בְּנִי שָׁמַעְתְּ בְּהַאי מִידֵי.</p>"],[9514014443,"<p>אָמַר לֵיהּ, כָּךְ שָׁמַעְתִּי מֵאַבָּא, דְּבִקְרִיאַת שְׁמַע יֵשׁ רמ\"ח תֵּיבוֹת חָסֵר תְּלַת, לְמִנְיַן אֵיבָרָיו שֶׁל אָדָם. מַאי תַּקַנְתֵּיהּ. תְּקִינוּ, דִּשְׁלִיחַ צִבּוּר חוֹזֵר שְׁלשָׁה תֵּיבוֹת אֵלוּ. וּמַאי נִינְהוּ. ה' אֱלֹהֵיכֶם אֱמֶת. כְּדֵי לְהַשְׁלִים רמ\"ח תֵּיבוֹת עַל הַקָּהָל. וּכְדֵי שֶׁלֹּא יַפְסִיק לֶאֱמֶת, לֹא פָּחוֹת מִשְׁלשָׁה, וְלֹא יוֹתֵר מִשְׁלשָׁה.</p>"],[9514014444,"<p>אַדְהָכֵי אָתֵי רַבִּי יוּדָא בְּרֵיהּ דְּר' פִּנְחָס, וִיתֵיב לְגַבַּיְיהוּ, וַאֲמַר לְהוֹ, בְּמַאי עַסְקִיתוּ. אֲמָרוּ לֵיהּ, בְּמִילֵי דִּקְרִיאַת שְׁמַע, וְהָכֵי אֲמַר הַאי יְנוּקָא. אֲמַר, וַדַאי הָכִי הוּא, וְהָכֵי אֲמַר ר' יוֹחָנָן בֶּן נוּרִי אָמַר רַבִּי יוֹסֵי בֶּן דּוּרְמַסְקִית, מִשְׁמֵיהּ דְּר' עֲקִיבָא, חֲסִידִים הָרִאשׁוֹנִים תִּקְּנוּ קְרִיאַת שְׁמַע כְּנֶגֶד עֲשֶׂרֶת הַדִּבְּרוֹת. וּכְנֶגֶד מִנְיַן אֵיבָרָיו שֶׁל אָדָם. וְהָא חָסְרוּ מֵהֶם שְׁלשָׁה. תִּקְּנוּ שֶׁיְהֵא שְׁלִיחַ צִבּוּר חוֹזֵר וּמַשְׁלִים אוֹתָם. וּמַאי נִינְהוּ. ה' אֱלֹהֵיכֶם אֱמֶת.</p>"],[9514014445,"<p>בִּתְפִלָּה תִּקְּנוּ, ג' בְּרָכוֹת רִאשׁוֹנוֹת, וְג' בְּרָכוֹת אַחֲרוֹנוֹת. בִּקְרִיאַת שְׁמַע, ג' שֵׁמוֹת בָּרִאשׁוֹנָה, ה' אֱלֹהֵינוּ ה', וּשְׁלשָׁה שֵׁמוֹת בָּאַחֲרוֹנָה, ה' אֱלֹהֵיכֶם אֱמֶת. וְכָל הַקּוֹרֵא קְרִיאַת שְׁמַע כְּהַאי גַוְונָא, בְּיָדוּעַ שֶׁאֵינוֹ נִיזּוֹק בְּאוֹתוֹ יוֹם.</p>"],[9514014446,"<p>וְכָל הָאוֹמֵר קְרִיאַת שְׁמַע שֶׁלֹּא עִם הַצִּבּוּר אֵינוֹ מַשְׁלִים אֵיבָרָיו, מִפְּנֵי שֶׁחִיסֵר הַשְּׁלשָׁה תֵּיבוֹת שֶׁשְׁלִיחַ צִבּוּר חוֹזֵר. מַאי תַּקְנְתֵּיהּ. יְכַוֵּון בְּט\"ו וָוי\"ן דֶּאֱמֶת וְיַצִּיב.</p>"],[9514014447,"<p>וְעִם כָּל זֶה הָיָה קוֹרֵא עָלָיו אַבָּא, (קהלת א׳:ט״ו) מְעֻוָּת לֹא יוּכַל לִתְקֹן וְגו'. אוֹתָן שְׁלשָׁה תֵּיבוֹת שֶׁבִּקְרִיאַת שְׁמַע, שֶׁשְׁלִיחַ צִבּוּר חוֹזֵר אוֹתָם, לֹא יָכוֹל לְהִימָּנוֹת אוֹתָם לְתַשְׁלוּם רמ\"ח כִּשְּׁאָר הַצִּיבּוּר. אָמַר לְהַהוּא יְנוּקָא, אֵימָא קְרָאָךְ. פָּתַח וְאָמַר, (שם ט) עִיר קְטַנָה וַאֲנָשִׁים בָּהּ מְעָט.</p>"],[9514014448,"<p>רַבִּי בּוֹן, טָעֵין יוֹמָא חַד, אֲבַתְרוֹי דְּרַבִּי שִׁמְעוֹן בֶּן יוֹחָאי, בִּסְלִיקוּ דְּחַד טִינָרָא, בְּרָמָאָה דְטוּרָא, חָמוּ חַד צִפּוֹרָא מְנַדְּדָא מִגּוֹזָלָא, וְאַתְיָין אָחֳרָנִין, וְאִמְרְטוּן אַגְפָהָא, וַאֲמַר הַאי קְרָא עֲלָהּ, (משלי כ״ז:ח׳) כְּצִפּוֹר נוֹדֶדֶת מִן קִנָּהּ כֵּן אִישׁ נוֹדֵד מִמְּקוֹמוֹ.</p>"],[9514014449,"<p>עַד דַּהֲווֹ אָזְלוּ, חָמוּ חַד חִוְּויָא, דְּקָטֵיל בַּר נַשׁ, וַאֲזֵיל לֵיהּ. וְחָמוּ אַרְיָא, דְּטָרִיף אוּדְנָא, וְאָכִיל. אֲמַר רַבִּי שִׁמְעוֹן, מַאי אַהֲנֵי לְהַאי חִיוְיָא, דְּטָרִיף לְמַגָּנָא.</p>"],[9514014450,"<p>פָּתַח וְאָמַר, (איוב ט׳:י״ז) אֲשֶׁר בִּשְׂעָרָה יְשׁוּפֵנִי וְהִרְבָּה פְצָעַי חִנָּם. אֲשֶׁר בִּשְׂעָרָה, דָּא שָׂטָן, דְּאוֹרְחֵיהּ כְּחִיוְויָא, טָרִיף וְקָטֵיל לְמַגָּנָא, וְלָא אִתְהַנֵּי מִינֵיהּ. יְשׁוּפֵנִי, כְּתִיב הָכָא יְשׁוּפֵנִי, וּכְתִיב הָתָם הוּא יְשׁוּפְךָ רֹאשׁ. וּבְגִין דְּבִשְׂעָרָה יְשׁוּפֵנִי, הִרְבָּה פְצָעַי חִנָם, דְּאוֹרְחֵיהּ לְאַבְאָשָׁא חִנָם, וְטָרַף טַרְפָּא לְמַגָּנָא.</p>"],[9514014451,"<p>וְאִי תֵימָא בְּלָא רְשׁוּת קָא עָבִיד. וְהָכְתִיב, רוּחַ סְעָרָה עוֹשָׂה דְבָרוֹ. וּכְתִיב, (קהלת י׳:י״א) אִם יִשֹׁךְ הַנָּחָשׁ בְּלָא לָחַשׁ. חִיוְיָא לָא נָשַׁךְ, עַד דְּלָחֲשִׁין לֵיהּ מִלְעֵילָא. דַּאֲמַר רַבִּי שִׁמְעוֹן, אִית דְּלָחֲשִׁין לֵיהּ מִלְּעֵילָא, וְלָא אִשְׁתְּמוֹדַע לְגַבֵּיהּ הַהוּא חִוְיָא, וְקָטֵיל לֵיהּ לְאַחֲרָא. זַכָּאָה מַאן דְּלָא אִשְׁתְּמוֹדַע גַּבֵּיהּ, וְלָא אִתְרְשִׁים קַמֵּיהּ.</p>"],[9514014452,"<p>מַה כְּתִיב בֶּאֱלִימֶלֶךְ. (רות א׳:ב׳) וְשֵׁם הָאִישׁ אֱלִימֶלֶךְ, כֵּיוָן דְּאִתְרְשִׁים לְגַבֵּיהּ, אַסְטִין בְּדִינָא עֲלוֹהִי, עַד דְּקָטַל לֵיהּ. דִּכְתִיב, וַיָּמָת אֱלִימֶלֶךְ. כֵּיוָן דְּשָׁרֵי בֵיהּ שָׁארֵי בִּבְנוֹי וְכוֹלָּא בְּעוֹנָשָׁא דְּדַיָּינָא, דְּלֵית עָנְשָׁא כְּעֳנָשָׁא דְּדִינָא. דִּי לָא יֵימָא דַיָּינָא דְּאִיהוּ אִתְעֲנַשׁ בִּלְחוֹדוֹי, אֶלָּא אִיהוּ וּבְנוֹי וְכָל בֵּיְיתֵיהּ יִתָּפְסוּן בְּחוֹבָא דְדִינָא.</p>"],[9514014453,"<p>דַּיָּינָא, אִית לֵיהּ לְמִירְדַּף וּלְמֵדַע בָּתַר עוֹבָדֵי דִבְנֵי מָתָא, דְּאִיהוּ אִיתְפַּס בְּחוֹבַיְיהוּ. דְּלָא יֵימָא דַיָּינָא, אֲנָא לְמֵידַן דִּינָא בֵּין גַּבְרָא לְחַבְרֵיהּ, וְלָא יַתִּיר. אֶלָּא כָּל עוֹבָדֵי מָתָא תְּלוּיִין עַל קוֹדְלֵיהּ. וְאִי אָטִים עֵינוֹי מֵעוֹבָדֵי מָתָא, אִיהוּ אִתְּפִיס בְּחוֹבַיְיהוּ.</p>"],[9514014454,"<p>אֱלִימֶלֶךָ יָכֵיל הֲוֵי לְמֵיקַם וּלְמִיגָנָא עַל דָּרֵיהּ, וְזַכָּאָה הֲוָה. בְּשַׁעֲתָא דְּאִיתְעַר הַקָּדוֹשׁ בָּרוּךְ הוּא בְּדִינָא עַל עַלְמָא, אַשְׁגַּח בְּרָאשֵׁיהֶן דְּעַמָּא, וּבָעָא לְחַפְיָא עַל אֱלִימֶלֶךְ. בְּקַדְמִיתָא מַה כְּתִיב. אִישׁ סְתָם, וְלָא כְתִיב מַאן הוּא. מִיָּד קָם מְקַטְרְגָא וַאֲמַר, וְשֵׁם הָאִישׁ אֱלִימֶלֶךְ, דְּאִתְרְשִׁים אִיהוּ וְאִשְׁתְּמוֹדַע הוּא וְכָל בֵּיְיתֵיהּ.</p>"],[9514014455,"<p>מִכָאן אוֹלִיפְנָא, דְּלֵית דַּיָּינָא בְּכָל דָּרָא וְדָרָא, דְּלָא אִתְרְשִׁים וְאִשְׁתְּמוֹדַע לְגַבֵּיהּ עֵילָּא. וּבְשַׁעֲתָא דְּאִתְעַר דִּינָא עַל עַלְמָא, אִיהִי אִיתְדָן בְּקַדְמִיתָא, דִּכְתִיב שְׁפֹט הַשֹׁפְטִים.</p>"],[9514014456,"<p>וְשֵׁם שְׁנֵי בָנָיו מַחְלוֹן וְכִלְיוֹן. רַבִּי פְּדָת וְרַבִּי פְּרַחְיָא אָמְרוּ, מַחְלוֹן: שֶׁמָּחַל לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא לְאַחַר זְמַן, עַל שֶׁהָיָה מוֹחֶה בְּיָדוֹ שֶׁל אָבִיו, וּמִשְׁתַּדֵּל בּוֹ עַל הַמִּשְׁפָּטִים. כִּלְיוֹן: עַל שֶׁנִּכְלָה מִן הָעוֹלָם.</p>"],[9514014457,"<p>ר' יוֹסֵי בֶּן קִיסְמָא אָמַר, כְּשֵׁם שֶׁהָיוּ הֵם, כָּךְ הָיוּ נְשׁוֹתֵיהֶם. עָרְפָּה, עַל שְׁמָהּ נִידוֹנֶת, קְשַׁת קְדַל, דְּלָא בָּעַאת לְמֵיהֱוֵי לָהּ חוּלָקָא עִם יִשְׂרָאֵל. כְּמוֹ דְאַתְּ אָמֵר, כִּי פָנוּ אֵלַי עוֹרֶף וְלָא פָנִים. רַבָּנָן אָמְרֵי, לְפִי שֶׁהֶחֱזִירָה עוֹרֶף לַחֲמוֹתָהּ.</p>"],[9514014458,"<p>רוּת: עַל שֵׁם תּוֹר, שֶׁהוּא כָּשֵׁר עַל הַמִּזְבֵּחַ. כָּךְ רוּת, כְּשֵׁירָה לָבֹא בַּקָּהָל, שֶׁעָלֶיהָ נִתְקַיְימָה הֲלָכָה, עַמּוֹנִי וְלֹא עַמּוֹנִית, מוֹאָבִי וְלֹא מוֹאָבִית. רוּת: שֶׁיָּצָא מִמֶּנָּהּ בֵּן, שֶׁרִיוָּוה לְהַקָּדוֹשׁ בָּרוּךְ הוּא בְּשִׁירוֹת וְתִשְׁבָּחוֹת.</p>"],[9514014459,"<p>רוּת אֵשֶׁת מַחְלוֹן, בָּאתָה בַּקָּהָל. מַחְלוֹן, שֶׁמָּחַל לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, לִהְיוֹת שְׁמוֹ נִזְכָּר. עָרְפָּה אֵשֶׁת כִּלְיוֹן, לֹא בָאתָה בַּקָּהָל, שֶׁכִּילָּה אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא, כִּלְיוֹן לֹא נִזְכַּר שְׁמוֹ בְּיִשְׂרָאֵל.</p>"],[9514014460,"<p>וְעַל תִּיקּוּנָא דָא. נָעֳמִי, נְשָׁמָה. אֱלִימֶלֶךְ, נִשְׁמָתָא לְנִשְׁמָתָא. מַחְלוֹן, רוּחַ הַשִּׂכְלִית. רוּת, נֶפֶשׁ הַשִּׂכְלִית. כִּלְיוֹן, רוּחַ הַבַּהֲמִיּוּת. וְעַל דָּא אֲמַר שְׁלמֹה, (קהלת ג׳:כ״א) וּמִי יוֹדֵעַ רוּחַ בְּנֵי הָאָדָם הָעוֹלָה הִיא לְמַעְלָה וְרוּחַ הַבְּהֵמָה הַיּוֹרֶדֶת הִיא לְמַטָה לָאָרֶץ. רוּחַ הָאָדָם, דָּא מַחְלוֹן. רוּחַ הַבְּהֵמָה, דָּא כִּלְיוֹן, שֶׁהוּא מִסִּטְרָא דִשְׂמָאלָא. נֶפֶשׁ הַבַּהֲמִית, דָּא עָרְפָּה, שֶׁהִיא מַקְשַׁת קְדַל, וְהִיא מִסִּיטְרָא דִשְׂמָאלָא. וְעַל דָּא, כִּלְיוֹן לֹא נִזְכַּר שְׁמוֹ בְּיִשְׂרָאֵל.</p>"],[9514014461,"<p>וַיִּקְחוּ לָהֶם נָשִׁים מוֹאֲבִיוֹת, אָמַר רִבִּי רְחוּמָאי, בְּנוֹת עֶגְלוֹן מֶלֶךְ מוֹאָב הָיוּ. וּמִפְּנֵי מָה זָכָה עֶגְלוֹן לְכָךְ. אָמַר רִבִּי רְחוּמָאי, כְּשֶׁבָּא אֵהוּד וְאָמַר, (שופטים ג׳:כ׳) דְּבַר אֱלֹהִים לִי אֵלֶיךָ וַיָּקָם מֵעַל הַכִּסֵּא. אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, אַתָּה קַמְתָּ מִכִּסְאֲךָ בִּשְׁבִיל כְּבוֹדִי, חַיֶּיךָ, מִמְּךָ יֵצֵא מִי שֶׁיֵּשֵׁב עַל כִּסְאִי. שֶׁנֶּאֱמַר, (דברי הימים א כ״ט:כ״ג) וַיֵּשֶׁב שְׁלֹמֹה עַל כִּסֵּא ה'.</p>"],[9514014462,"<p>רַבִּי בּוֹן אָמַר, אִלְמָלֵא הֲוֵינָא הָתָם, כַּד אִתְקַיְימָא הֲלָכָה, מוֹאָבִי וְלֹא מוֹאָבִית, פַּלִּיגְנָא עָלָיו, וַאֲמִינָא, מוֹאָבִית וְלֹא מוֹאָבִי. דִּכְתִיב בְּהוּ, (במדבר כה) וַיָּחֶל הָעָם לִזְנוֹת אֶל בְּנוֹת מוֹאָב וַתִּקְרֶאנָה לָעָם לְזִבְחֵי אֱלֹהֵיהֶן. וּכְתִיב, (במדבר לא) הֵן הֵנָּה הָיוּ לִבְנֵי יִשְׂרָאֵל בִּדְבַר בִּלְעָם וַתְּהִי הַמַּגֵּפָה בַּעֲדַת ה'. אִינוּן גָּרְמִין כּוּלֵי הַאי, וְגוּבְרִין אֲסִירֵי וְאִינוּן שָׁרְיָין.</p>"],[9514014463,"<p>וּמִיָּד אָמַר, הַדְרֵי בִי. וּמַה, משֶׁה וְאֶלְעָזָר קִבְּלוּן. דִּכְתִיב, (שם) אֲשֶׁר לֹא יָדְעוּ מִשְׁכַּב זָכָר הַחֲיוּ לָכֶם. מַאי טַעְמָא. דִּבְהֶכְרַח עָמְדוּ בְּנוֹת מוֹאָב בְּאוֹתוֹ מַעֲשֶׂה, דְּאָמַר רִבִּי חִלְקִיָּה אָמַר רַבִּי אַסְיָא בֶּן גּוּרְיוֹן, הָאֲנָשִׁים בָּאִין וּמְבִיאִין אוֹתָן בְּעַל כָּרְחָן, וְהַהִיא שֶׁלֹּא קִבְּלָהּ, הוֹרְגִין אוֹתָהּ. עַד שֶׁנִּמְצְאוּ מוֹאֲבִיּוֹת כּוּלָּן שָׁם בְּהֶכְרַח. וְעַל דָּא וַדַּאי הָאֲנָשִׁים אֲסוּרִים, וְהַנָּשִׁים מוּתָּרוֹת. וְעוֹד, כְּתִיב בְּאוֹרַיְיתָא תְּרֵי טַעֲמֵי, עַל דְּבַר אֲשֶׁר לֹא קִדְמוּ אֶתְכֶם בַּלֶּחֶם וּבַמַּיִם, וַאֲשֶׁר שָׂכַר עָלֶיךָ בִּלְעָם, עִיקָּרָא דְּמִילְתָא גּוּבְרִין הֲווֹ.</p>"],[9514014464,"<p>אֲמַר רַבִּי חִיסְדָּאי, וְהָא תָּנִינָן, דְּנַחַל שִׁיטִים מְגַדֵּל הַנִּיאוּף דְּנָשִׁים הוּא, וְאַתְּ אֲמַרְתְּ בְּעַל כָּרְחָן עָמְדוּ שָׁם. וְאָמַר רַבִּי אוֹשְׁעְיָא, מַאי דִכְתִיב, (יואל ד׳:י״ח) וּמַעְיָן מִבֵּית ה' יֵצֵא וְהִשְׁקָה אֶת נַחַל הַשִּׁטִים, שֶׁבְּאוֹתוֹ זְמַן, עָתִיד הַקָדוֹשׁ בָּרוּךְ הוּא לְרַפְּאוֹת אֶת כָּל הָעוֹלָם, וּמִפְּנֵי שֶׁנַּחַל שִׁטִים מַרְבֶּה נִיאוּף, יֵצֵא מַעְיָן מִבֵּית ה' לְרַפְּאוֹת אוֹתוֹ הַנַּחַל. אִם כֵּן הֲרֵי לְךָ כִּי בִּשְׁבִיל הַנִּיאוּף הֵן בָּאוֹת מֵעַצְמָן.</p>"],[9514014465,"<p>אָמַר רִבִּי מְנַסְיָא, חַס וְשָׁלוֹם. גָּלוּי וְיָדוּעַ, דִּבְמָקוֹם שֶׁבַּעֲלֵיהֶם וַאֲבִיהֶם שָׁם, שֶׁאֵינָן בָּאוֹת מֵעַצְמָן בְּפַרְהֶסְיָא, אֶלָּא הֵם הִפְקִירוּ אוֹתָן בְּעַל כָּרְחָן בַּעֲצַת בִּלְעָם.</p>"],[9514014466,"<p>אָמַר רִבִּי יוֹסֵי בֶּן קִסְמָא, תָּמֵיהַּ אֲנִי, אִם מְגִילָה זוֹ לֹא בָאָה אֶלָּא כְּדֵי לְיַחֵס זֶרַע דָּוִד, שֶׁבָּא מֵרוּת הַמּוֹאֲבִיָּה, לֹא יְסַפֵּר יוֹתֵר, וְלָמָּה לִי כּוּלֵי הַאי, לִיכְתּוֹב יוֹחֲסָא מִבּוֹעַז, כְּשֶׁנָּשָׂא אֶת רוּת, וְיֹאמַר אֵלֶּה תּוֹלְדוֹת פֶּרֶץ, עַד וְיִשַׁי הוֹלִיד אֶת דָּוִד. אֶלָּא כּוֹלָּא אִיצְטְרִיךְ, בְּגִין צַדֶּקֶת זוֹ, שֶׁבָּאָה לְהִתְגַּיֵּיר, וְלַחֲסוֹת תַּחַת כַּנְפֵי הַשְּׁכִינָה, וּלְהוֹדִיעַ עִנְוְתָנוּתָהּ וּצְנִיעוּת שֶׁבָּהּ וְצִדְקוּתָהּ.</p>"],[9514014467,"<p>רַבִּי אֶלְעָזָר בְּר' יוֹסֵי אָמַר, לְהוֹדִיעַ זֶרַע דָּוִד, שֶׁהוּא (תהילים י״ב:ז׳) כֶּסֶף צָרוּף בַּעֲלִיל לָאָרֶץ. דְּהָא פֶּרֶץ וְעוֹבֵד כֶּסֶף צָרוּף הוּא, כְּכֶסֶף זֶה שֶׁנִּצְרַף פַּעַם וּשְׁתַּיִם.</p>"],[9514014468,"<p>וְאִם תֹּאמַר, מִפְּנֵי מָה בָּאוּ מִן הָאִמָּהוֹת בְּעִנְיַן זֶה. אֶלָּא כֶּסֶף מְזוּקָק מִתּוֹךְ סִגִּים שֶׁבָּהּ. וְזֶרַע דָּוִד צָרוּף מִצַּד זֶה וּמִצַּד זֶה. דִּכְתִיב, (דברים ו) וְאָהַבְתָּ אֵת ה' אֱלֹהֶיךָ בְּכָל לְבָבְךָ וְגו', בִּשְׁנֵי יְצָרֶיךָ, בְּיֵצֶר הַטוֹב וּבְיֵצֶר הָרָע. הַכֹּל צָרִיךְ כְּאֶחָד. וְזֶרַע דָּוִד אִיצְטְרִיךְ הָכֵי.</p>"],[9514014469,"<p>פְּתַח רַבִּי וַאֲמַר, הָכֵי אָדָם הָרִאשׁוֹן, נִשְׁמָתָא לְנִשְׁמָתָא. חַוָּה, נִשְׁמָתָא. קַיִן וְהֶבֶל, הֶבֶל, מִזִּינָא חָדָא עִם אָדָם וְחַוָּה, וְאִתְקְרֵי רוּחַ דְּקוּדְשָׁא. קַיִן, רוּחַ דְּטוּמְאָה דִשְׂמָאלָא, אִתְקְרֵי כִּלְאַיִם. וַהֲוֵי עִירְבּוּבְיָא, דְלָא אִצְטְרִיךְ. סִטְרָא אָחֳרָא, דְּלָא מִזִּינָא דְּאָדָם וְחַוָּה. וְעַל דָּא, לֹא תַחֲרשׁ בְּשׁוֹר וּבַחֲמוֹר יַחְדָּיו. וְעַל דָּא, לֹא תֵיעוֹל בְּרִית דְּקוּדְשָׁא בִּרְשׁוּת אַחֲרִיתֵּי, לֹא יִהְיֶה לְךָ אֱלֹהִים אֲחֵרִים עַל פָּנָי.</p>"],[9514014470,"<p>וְאָדָם הוּא דוּגְמָא שֶׁל מַעְלָה. אֱלֹהִים אֲחֵרִים, דָּא חֲמוֹר וְאַתְוָן. זָכָר וּנְקֵבָה. וְעַל דָּא, מַאן דְּעָאֵיל בְּרִית קַדִּישָׁא בִּרְשׁוּת אָחֳרָא, כְּתִיב בֵּיהּ, (הושע ה׳:ז׳) בַּה' בָּגָדוּ כִּי בָּנִים זָרִים יָלָדוּ. וְלֵית קִנְאָה לְהַקָּדוֹשׁ בָּרוּךְ הוּא, בַּר מִן דָּא דִּבְרִית קַדִּישָׁא.</p>"],[9514014471,"<p>בָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא בְּאֵינַשׁ י\"ה ו\"ה, דְּהוּא שְׁמָא קַדִּישָׁא דִילֵיהּ, נִשְׁמָתָא לְנִשְׁמָתָא, וְדָא נִקְרֵאת אָדָם, וּמִתְפַּשְׁטִין נְהוֹרִין בְּתִשְׁעָה נְהוֹרִין, וְהֵם מִשְׁתַּלְּשְׁלִין מִן י', וְהוּא אוֹר אֶחָד בְּלָא פֵּירוּדָא. וְעַל דָּא, גּוּפָא דְּאֵינַשׁ, אִתְקְרֵי לְבוּשָׁא דְאָדָם.</p>"],[9514014472,"<p>ה' נִקְרֵאת נְשָׁמָה, וְתִזְדַּוֵּוג עִם י', וְאִתְפַּשֵּׁיט לְכַמָּה נְהוֹרִין, וְהוּא חַד. י\"ה בְּלִי פֵּירוּדָא. וְעַל דָּא, וַיִּבְרָא אֱלֹהִים אֶת הָאָדָם בְּצַלְמוֹ בְּצֶלֶם אֱלֹהִים בָּרָא אֹתוֹ, זָכָר וּנְקֵבָה בְּרָאָם כו', וַיִּקְרָא אֶת שְׁמָם אָדָם.</p>"],[9514014473,"<p>ו' נִקְרֵאת רוּחַ, וְאִתְקְרֵי בֶּן י\"ה. ה', אִתְקְרִיאַת נַפְשָׁא, וְאִתְקְרִיאַת בַּת. וְעַל דָּא, אָב וָאֵם בֵּן וּבַת. וְרָזָא דְמִלָּה יו\"ד ה\"א וא\"ו ה\"א, אִיקְרֵי אָדָ\"ם. וְאִתְפַּשַּׁט נְהוֹרָא דִילֵיהּ, לַחֲמִשָּׁה וְאַרְבָּעִים נְהוֹרִין, וְדָא הוּא חוּשְׁבַּן אָדָם מ\"ה.</p>"],[9514014474,"<p>וְהַשֵּׁם יו\"ד ה\"א וא\"ו ה\"א, זָכָר וּנְקֵבָה בְּרָאָם כו'. וַיִּקְרָא אֶת שְׁמָם אָדָם. וְאַחַר כַּךְ יָצַר הַגּוּף, דִּכְתִיב (בראשית ב׳:ז׳) וַיִּיצֶר ה' אֱלֹהִים אֶת הָאָדָם עָפָר מִן הָאֲדָמָה וַיִּפַּח בְּאַפָּיו נִשְׁמַת חַיִּים.</p>"],[9514014475,"<p>מַאי אִית בֵּין אָדָם לְאָדָם, הֲרֵי יהו\"ה נִקְרָא אָדָם, וְגוּפָא נִקְרָא אָדָם, מַאי בֵּין הַאי לְהַאי. אֶלָּא, בַּאֲתַר דְּאִקְרֵי (שם א) וַיִּבְרָא אֱלֹהִּים אֶת הָאָדָם בְּצַלְמוֹ, הוּא ידו\"ד. וּבַאֲתַר דְּלָא אִקְרֵי בְּצַלְמוֹ הוּא גּוּף.</p>"],[9514014476,"<p>וּבָתַר דַּאֲמַר וַיִּיצֶר ה' אֱלֹהִים. שֶׁיָּצַר לָאָדָם, עֲשָׂאוֹ. דִּכְתִיב (שם ג) וַיַּעַשׂ ה' אֱלֹהִים לְאָדָם וּלְאִשְׁתּוֹ כָּתְנוֹת עוֹר וַיַּלְבִּישֵׁם. בָּרִאשׁוֹנָה כָּתְנוֹת אוֹר, בְּדוּגְמָא שֶׁל מַעְלָה, וּבָתַר דְחָבוּ כָּתְנוֹת עוֹר.</p>"],[9514014477,"<p>וְעַל דָּא אֲמַר, (ישעיהו מ״ג:ז׳) כָּל הַנִּקְרָא בִּשְׁמִי וְלִכְבוֹדִי בְּרָאתִיו יְצַרְתִּיו אַף עֲשִׂיתִיו. בְּרָאתִיו, דָּא יו\"ד ה\"א וא\"ו ה\"א. יְצַרְתִּיו, דָּא כָּתְנוֹת אוֹר. אַ\"ף עֲשִׂיתִיו, דָּא כָּתְנוֹת עוֹר. מִשּׁוּם דְּהָאַף סִבֵּב זֶה.</p>"],[9514014478,"<p>וּלְמַאן יִתְקְרֵי רָע. דָּא יֵצֶר הָרָע, וְדָא נָחָשׁ, דַּעֲבַד וְסִבֵּב דְּאִתְגְּזַר עַל אָדָם וְחַוָּה מוֹתָא, וְעַל כָּל אֵינַשׁ.</p>"],[9514014479,"<p>וּבְדוּגְמָא דְּאִיתָא שֵׁם דְּקוּדְשָׁא, הָכֵי אִית שֵׁם דִּמְסָאֲבוּ, שֶׁהוּא טָמֵא. וְעַל דָּא, לֹא יִהְיֶה לְךָ אֱלֹהִים אֲחֵרִים עַל פָּנָי. וְכָל הַפּוֹגֵם אֶחָד מֵאֵיבָרָיו מִלְּמַטָה, כְּאִלּוּ פּוֹגֵם מִלְּמַעְלָה.</p>"],[9514014480,"<p>וְעַל דָּא, חֶרֶב בָּא לָעוֹלָם, וְכַפְנָא וּמוֹתָא אָתֵי לְעָלְמָא. וְעַל דָּא (שמות כ״ב:כ״ג) וְהָיוּ נְשֵׁיכֶם אַלְמָנוֹת וְגו'. לְמַאן דְּעָאֵיל בְּרִית קַדִּישָׁא בִּרְשׁוּ אָחֳרָא. וְעַל דָּא, (ויקרא י״ט:י״ט) שַׁעַטְנֵז לֹא יַעֲלֶה עָלֶיךָ. (דברים כ״ב:י׳) לֹא תַחֲרשׁ בְּשׁוֹר וּבַחֲמוֹר יַחְדָּו. וְעַל דָּא אֲמַר, (שם כז) אָרוּר שׁוֹכֵב עִם כָּל בְּהֵמָה. מַאן הִיא בְּהֵמָה. דָּא כּוּתִית. גּוּף שֶׁהִיא מִסִּטְרָא דִּבְהֵמָה אָחֳרָא דִלְעֵילָא, מְסָאֲבָא.</p>"]]});
